	{
		loader::Library lib(testlibname);
		REQUIRE(lib.loaded() == true);
		WHEN("symbol is loaded successfully")
		{
			auto testfunc = lib.func<int(int)>("test");
			THEN("function pointed by symbol is called successfully")
			{
				REQUIRE(testfunc(3) == 3);
			}
		}
	}
