using namespace std;
enum
{
  ksetled
};
int main(int argc, char *argv[])
{
  if(argc == 2){
    char op;
    cmd::CmdMessenger arduino(argv[1], 115200);
    cmd::Cmd led(ksetled);
    cmd::Timeout timeout = cmd::Timeout::simpleTimeout(1000);
    arduino.setTimeout(timeout);
    while(true)
    {
      cout << "'1' turns on, '0' turns off, 'q' quits: ";
      cin >> op;
      cout << endl;
      switch(op)
      {
        case '1':
          led << true << CmdEnd();
          arduino.send(led);
          cout << led.getNumArgs() << endl;
          led.clear();
          break;
        case '0':
          led << false << CmdEnd();
          arduino.send(led);
          led.clear();
          break;
        case 'q':
          break;
      }
      if(op == 'q') break;
      cout << "feeding in serial data\n";
      arduino.feedInSerialData();
    }
  }
  else
  {
    cout << "Usage: led 'port_name'\n";
  }
  return 0;
}

#include "memory.h"
namespace EPITOME
{
	template <typename T>
	Room<T>::Room() {}
	template <typename T>
	Room<T>::~Room()
	{
		Empty();
	}
	template <typename T>
	Room<T>::Room(Room&& other)
	{
		items = other.items;
		other.items.clear();
	}
	template<typename T>
	void Room<T>::Add(T* item)
	{
		items.push_back(item);
	}
	template <typename T>
	void Room<T>::Empty()
	{
		for (T* a : items)
		{
			a->Dispose();
			delete a;
		}
		items.clear();
	}
	template <typename T>
	Disposable<T>::Disposable(T item)
	{
		this->item = item;
	}
	template <typename T>
	void Disposable<T>::Dispose() {}
}

