#include "loadresources.h"
#include <qglobal.h>
using namespace OCC;
void static load_rc()
{
    Q_INIT_RESOURCE(OpenCloudResources_translations);
    Q_INIT_RESOURCE(client);
    Q_INIT_RESOURCE(core_theme);
#ifdef BRANDING_AVAILABLE
    Q_INIT_RESOURCE(theme);
#endif
}
void static unload_rc()
{
    Q_CLEANUP_RESOURCE(OpenCloudResources_translations);
    Q_CLEANUP_RESOURCE(client);
    Q_CLEANUP_RESOURCE(core_theme);
#ifdef BRANDING_AVAILABLE
    Q_CLEANUP_RESOURCE(theme);
#endif
}
ResourcesLoader::ResourcesLoader()
{
    // Q_INIT_RESOURCE must not be called in a namespace
    ::load_rc();
}
ResourcesLoader::~ResourcesLoader()
{
    // Q_CLEANUP_RESOURCE must not be called in a namespace
    ::unload_rc();
}

#include <stdlib.h>
#include <stdio.h>
#include "../include/blasfeo_target.h"
#include "../include/blasfeo_common.h"
#include "../include/blasfeo_d_aux.h"
#include "../include/blasfeo_d_kernel.h"
#include "../include/blasfeo_d_blas.h"
#if defined(FORTRAN_BLAS_API)
#define blas_dsyrk dsyrk_
#endif
static void blasfeo_dsyrk3(char uplo, char ta, int m, int k, double alpha, double *A, int lda, double beta, double *C, int ldc, double *D, int ldd)
	{
#if defined(PRINT_NAME)
	printf("\nblasfeo_dsyrk3 %c %c %d %d %f %p %d %f %p %d %p %d\n", uplo, ta, m, k, alpha, A, lda, beta, C, ldc, D, ldd);
#endif
	if(m<=0)
		return;
	int ii, jj;
	int bs = 4;
	void *mem;
	char *mem_align;
	double *pU;
	int sdu;
	struct blasfeo_dmat sA;
	int sA_size;
	int m1, k1;
	// stack memory allocation
// TODO visual studio alignment
#if defined(TARGET_X64_INTEL_HASWELL) | defined(TARGET_ARMV8A_ARM_CORTEX_A53)
	ALIGNED( double pU0[3*4*K_MAX_STACK], 64 );
//	ALIGNED( double pD0[4*16], 64 );
#elif defined(TARGET_X64_INTEL_SANDY_BRIDGE) | defined(TARGET_ARMV8A_ARM_CORTEX_A57)
	ALIGNED( double pU0[2*4*K_MAX_STACK], 64 );
//	ALIGNED( double pD0[2*16], 64 );
#elif defined(TARGET_GENERIC)
	double pU0[1*4*K_MAX_STACK];
//	double pD0[1*16];
#else
	ALIGNED( double pU0[1*4*K_MAX_STACK], 64 );
//	ALIGNED( double pD0[1*16], 64 );
#endif
	int sdu0 = (k+3)/4*4;
	sdu0 = sdu0<K_MAX_STACK ? sdu0 : K_MAX_STACK;
	// select algorithm
	if(uplo=='l' | uplo=='L')
		{
		if(ta=='n' | ta=='N')
			{
			goto ln;
			}
		else if(ta=='t' | ta=='T' | ta=='c' | ta=='C')
			{
			goto lt;
			}
		else
			{
			printf("\nBLASFEO: dsyrk: wrong value for ta\n");
			return;
			}
		}
	else if(uplo=='u' | uplo=='U')
		{
		if(ta=='n' | ta=='N')
			{
			goto un;
			}
		else if(ta=='t' | ta=='T' | ta=='c' | ta=='C')
			{
			goto ut;
			}
		else
			{
			printf("\nBLASFEO: dsyrk: wrong value for ta\n");
			return;
			}
		}
	else
		{
		printf("\nBLASFEO: dsyrk: wrong value for uplo\n");
		return;
		}
/************************************************
* ln
************************************************/
ln:
#if defined(TARGET_X64_INTEL_HASWELL)
	if(m>=200 | k>=200 | k>K_MAX_STACK)
#elif defined(TARGET_X64_INTEL_SANDY_BRIDGE)
	if(m>=64 | k>=64 | k>K_MAX_STACK)
#elif defined(TARGET_ARMV8A_ARM_CORTEX_A57)
	if(m>=32 | k>=32 | k>K_MAX_STACK)
#elif defined(TARGET_ARMV8A_ARM_CORTEX_A53)
	if(m>16 | k>16 | k>K_MAX_STACK)
#else
	if(m>=12 | k>=12 | k>K_MAX_STACK)
#endif
		{
		goto lx_1;
		}
	else
		{
		goto ln_0;
		}
