        PS_CHECK(ps, "some", "usual", "path");
        UNIT_ASSERT_EQUAL(ps.IsAbsolute, false);
        ps = PSUF(TPathSplit)();
        ps.ParseFirstPart("/some/usual/path");
        PS_CHECK(ps, "some", "usual", "path");
        UNIT_ASSERT_EQUAL(ps.IsAbsolute, true);
    }
    Y_UNIT_TEST(ParsePart) {
