        ps = PSUF(TPathSplit)("some/usual/path");
        ps.ParsePart("/sub/path");
        PS_CHECK(ps, "some", "usual", "path", "sub", "path");
        UNIT_ASSERT_EQUAL(ps.IsAbsolute, false);
    }
