        UNIT_ASSERT_STRINGS_EQUAL(ps.Reconstruct(), "");
    }
    Y_UNIT_TEST(OutIn) {
        PSUF(TPathSplit)
        ps("../path");
        PS_CHECK(ps, "..", "path");
    #ifdef _win_
        UNIT_ASSERT_STRINGS_EQUAL(ps.Reconstruct(), "..\\path");
    #else
        UNIT_ASSERT_STRINGS_EQUAL(ps.Reconstruct(), "../path");
    #endif
    }
