{
  __asm__ __volatile__( 
    FUNCTION_MARKER
    "mov x3, 0xdead\n" 
    "movk x3, 0xbeef, lsl 16\n"  
    "movk x3, 0xbeef, lsl 32\n"  
    "str x30, [sp, #-16]!\n"
    "blr x3\n" 
    "ldr x30, [sp], #16\n"
    FUNCTION_MARKER
   :: );
}
