namespace {

// Function address for GetTechUseErrorMessage
const u32 Func_GetTechUseErrorMessage = 0x00491E80;

// Wrapper function to intercept and modify behavior
void __declspec(naked) getTechUseErrorMessageWrapper()
{
    static CUnit *target;
    static u8 castingPlayer;
    static u16 techId;
    static u16 errorMessage;

    __asm {
        PUSHAD
        MOV EBP, ESP
        MOV target, EAX
        MOV castingPlayer, BL
        MOV EAX, [ESP + 36]   ;// (PUSHAD saves 32) + (CALL saves 4) == 36
        MOV techId, AX
    }

    // Call the hook function
    errorMessage = hooks::getTechUseErrorMessageHook(target, castingPlayer, techId);

    __asm {
        POPAD
        MOV AX, errorMessage
        RETN 4
    }
}

} // Unnamed namespace

namespace hooks {

// Inject the hook patch
void injectTechTargetCheckHooks()
{
    jmpPatch(getTechUseErrorMessageWrapper, Func_GetTechUseErrorMessage);
}

// Hooked implementation of getTechUseErrorMessage
u16 getTechUseErrorMessage(const CUnit *target, s8 castingPlayer, u16 techId)
{
    u32 techId_ = techId;
    static u16 errorMessage;

    __asm {
        PUSHAD
        PUSH techId_
        MOV BL, castingPlayer
        MOV EAX, target
        CALL Func_GetTechUseErrorMessage
        MOV errorMessage, AX
        POPAD
    }

    return errorMessage;
}

} // hooks

