// Prints the elements of a range
template<typename IteratorT>
void print(const range<IteratorT>& r)
{
    for (auto x : r)
        std::cout << x << " ";
    std::cout << std::endl;
}

// Returns the size of a range
template<typename IteratorT>
size_t size(const range<IteratorT>& r)
{
    return std::distance(r.begin(), r.end());
}

int main()
{
    // Initialize a list with some integers
    std::list<int> v{ 3, 1, 4, 22, 31 };

    // Create a range from the list
    auto range = make_range(v.begin(), v.end());

    // Print and measure the first range
    print(range);
    std::cout << "Size : " << size(range) << std::endl;

    // Copy list contents to vector
    std::vector<int> w;
    std::copy(v.begin(), v.end(), std::back_inserter(w));

    // Create a second range covering first 4 elements of vector
    auto range2 = make_range(w.begin(), std::next(w.begin(), 4));

    // Print and measure the second range
    print(range2);
    std::cout << "Size : " << size(range2) << std::endl;

    // Shuffle the second range using random utilities
    randomize();
    std::shuffle(range2.begin(), range2.end(), global_urng());

    // Output shuffled range2 elements
    std::copy(range2.begin(), range2.end(), std::ostream_iterator<int>(std::cout, " "));
    std::cout << std::endl;

    // Output original range elements
    std::copy(range.begin(), range.end(), std::ostream_iterator<int>(std::cout, " "));
    std::cout << std::endl;

    return 0;
}

#include "ros/ros.h"
