// Main function entry point
int main(int argc, char* argv[])
{
    ros::init(argc, argv, "pattern_posture_generator");
    ros::NodeHandle nh;
    PatternPostureGenerator ppg(nh);
    ros::spin();
    return 0;
}

// Default constructor
PatternPostureGenerator::PatternPostureGenerator() {}

// Constructor with NodeHandle initialization
PatternPostureGenerator::PatternPostureGenerator(ros::NodeHandle& nh)
{
    // Retrieve pattern names from parameter server
    if (!nh.getParam("pattern", pattern_names)) return;

    // Process each pattern and load corresponding posture data
    for (std::map<std::string, std::string>::iterator it = pattern_names.begin();
         it != pattern_names.end();
         it++)
    {
        std::vector<double> posture;
        // Load posture data for current pattern
        if (!nh.getParam(std::string("pattern/").append(it->second), posture)) return;
        // Copy posture data into internal storage
        std::copy(posture.begin(), posture.end(),
                  std::back_inserter(posture_datas[it->second]));
    }

    // Advertise the service for posture key retrieval
    key_srv = nh.advertiseService("getPostureKey",
                                  &PatternPostureGenerator::getPostureKey,
                                  this);
}

// Service callback to retrieve posture by name
bool PatternPostureGenerator::getPostureKey(
    pattern_posture_generator::PatternKeyPosture::Request& req,
    pattern_posture_generator::PatternKeyPosture::Response& res)
{
    // Copy requested posture data to response
    std::copy(posture_datas[req.name].begin(),
              posture_datas[req.name].end(),
              std::back_inserter(res.posture));
    return true;
}

