    : message(message) { }

// Add a key-function mapping to the prefix handler
void prefix::push_back(char ch, std::function<void(contents&, boost::optional<int>)> fun) {
    this->map[ch] = fun;
}

// Main operator() implementation for handling input
void prefix::operator()(contents& cont, boost::optional<int> op) {
    show_message(message + "-");
    char ch = getch();
    auto it = map.find(ch);
    if(it == map.end()) {
        show_message(std::string("Didn't recognize key sequence: '")
                     + message + '-' + ch + '\'');
    } else {
        it->second(cont, op);
        showing_message = false;
    }
}

