prefix::operator std::function < void ( contents&,
                                        boost::optional<int> ) > () {
    return std::function < void ( contents&,
                                  boost::optional<int> ) >
        ([this] (contents& cont, boost::optional<int> op)
         {
             (*this)(cont,op);
         });
}

