#include "threadpool.h"

// ThreadPool constructor
ThreadPool::ThreadPool(size_t size)
{
    // Create worker threads
    for (size_t i = 0; i < size; ++i)
    {
        workers.emplace_back([this] {
            // Infinite loop to process tasks
            for (;;)
            {
                std::unique_lock<std::mutex> lock(this->queue_mutex);
                // Wait until there's a task or stop is signaled
                while (!this->m_stop && this->tasks.empty())
                    this->condition.wait(lock);
                // Exit if stopped and no tasks left
                if (this->m_stop && this->tasks.empty())
                    return;
                // Get and execute the next task
                std::function<void()> task(this->tasks.front());
                this->tasks.pop();
                lock.unlock();
                task();
            }
        });
    }
}

// ThreadPool destructor
ThreadPool::~ThreadPool()
{
    {
        std::unique_lock<std::mutex> lock(queue_mutex);
        m_stop = true;
    }
    // Wake up all waiting threads
    condition.notify_all();
    // Join all worker threads
    for (auto i = 0; i < workers.size(); ++i)
        workers[i].join();
}

