// Process the queue using the provided callback
void processQueue(ByteQueue* queue, bool (*callback)(uint8_t*))
{
    // Create a snapshot of the current queue contents
    uint8_t snapshot[queue_length(queue)];
    queue_snapshot(queue, snapshot);

    // Check if callback is NULL
    if(callback == NULL)
    {
        debug("Callback is NULL (%p) -- unable to handle queue at %p\r\n",
                callback, queue);
        return;
    }

    // Execute callback and handle results
    if(callback(snapshot))
    {
        queue_init(queue);
    }
    else if(queue_full(queue))
    {
        debug("Incoming write is too long\r\n");
        queue_init(queue);
    }
    else if(strnchr((char*)snapshot, queue_length(queue) - 1, '\0') != NULL)
    {
        debug("Incoming buffered write corrupted (%s) -- clearing buffer\r\n",
                snapshot);
        queue_init(queue);
    }
}

