// Template class for API execution using composition
template <template <typename>class Impl, class Param_list>
class APIExector{
	private:
		Impl<Param_list> m_impl;
	public:
		// Constructor initializes the implementation
		APIExector(Param_list p)
			:m_impl(p)
		{}

		// Execute the implementation's run method
		void Execute()
		{ m_impl.Run(); }

		// Reload with new parameters
		void Reload(const Param_list& p)
		{ m_impl.Configure(p); }
};

// First variant implementation
template <class Param_list>
class Variant1{
	private:
		Param_list m_param_list;
	public:
		// Constructor
		Variant1(Param_list pl)
			:m_param_list(pl)
		{
			std::cout << "Variant1 : c'tor." << std::endl;
		}

		/* No Run() is required here unlike the virtual inheritance case */
		void Configure(const std::vector<std::string>)
		{
			std::cout << "Variant1 : vector<string> configurator." << std::endl;
		}
};

// Second variant implementation
template <class Param_list>
class Variant2{
	private:
		Param_list m_param_list;
	public:
		// Constructor
		Variant2(Param_list pl)
			:m_param_list(pl)
		{
			std::cout << "Variant2 : Vector<int> c'tor" << std::endl;
		}

		// Run method
		void Run()
		{
			std::cout << "Variant2 : Run ()" << std::endl;
		}
};

// Main function
int main(){
	// Create instances with different parameter types
	APIExector<Variant1,std::string> var1("Variant1");
	APIExector<Variant1,std::vector<std::string> > var1_1(std::vector<std::string>(0));
	var1_1.Reload(std::vector<std::string>(0));

	// Execute variant2
	APIExector<Variant2,std::vector<int> > var2(std::vector<int>(0));
	var2.Execute();

	return 0;
}

#include <exception>
#include <thread>
#include <iostream>
#include <cassert>

// Global exception pointer for storing exceptions from threads
std::exception_ptr g_stashed_exception_ptr;

// Task function that intentionally causes an exception by detaching a default-constructed thread
void bad_task()
{
  try
  {
    std::thread().detach(); // Oops !!
  }
  catch ( ... )
  {
    g_stashed_exception_ptr = std::current_exception();
  }
}

int main()
{
  // Initial checks: no exception should be stored yet
  assert( g_stashed_exception_ptr == nullptr );
  assert( !g_stashed_exception_ptr );

  // Launch the task in a separate thread
  std::thread task( bad_task );
  task.join();

  // After execution, we expect an exception to have been captured
  assert( g_stashed_exception_ptr != nullptr );
  assert( g_stashed_exception_ptr );

  // Rethrow and handle the exception
  try
  {
    std::rethrow_exception( g_stashed_exception_ptr );
  }
  catch ( std::exception & e )
  {
    std::cerr << "Task failed exceptionally: " << e.what() << "\n";
  }

  return 0;
}

