LCD5110 myGLCD;

// Initialize LCD
void LCD_init(void)
{
    /* Set MOSI and SCK output */
    DDRB |= (1<<PB3)|(1<<PB5);

    /* Enable SPI, Master, CPOL=1, CPHA=1 */
    /* Also: MSB first, clock=fosc/4 */
    SPCR = (1<<SPE)|(1<<MSTR)|(1<<CPOL)|(1<<CPHA) | (1<<SPR0);

    /* Set the pins for DC, RST and CS to output */
    DDRB |= (1<<PB0) | (1<<PB2);
    DDRC |= (1<<PC0);

    myGLCD.InitLCD(0x46);
}

