// Define size constant
#define SIZE 60

QPieKey::QPieKey(QWidget *parent) : QWidget(parent)
{
    // Initialize bitmap and painter
    bitmap = new QBitmap(SIZE*2, SIZE*2);
    QPainter painter(bitmap);

    // Set fixed size and clear bitmap
    setFixedSize(SIZE*2, SIZE*2);
    bitmap->clear();

    // Draw outer ellipse
    painter.setBrush(Qt::color1);
    painter.drawEllipse(1, 1, SIZE*2-2, SIZE*2-2);

    // Draw inner ellipse
    painter.setBrush(Qt::color0);
    painter.drawEllipse(SIZE/2, SIZE/2, SIZE, SIZE);

    // Apply mask and hide initially
    setMask(*bitmap);
    hide();
}

QPieKey::~QPieKey()
{
    // Destructor implementation
}

void QPieKey::paintEvent(QPaintEvent *event)
{
    // Paint event handler
    QPainter painter(this);
    painter.setBrush(QColor(128, 128, 128));
    painter.drawRect(event->rect());
}

