using namespace Marble;

// Constructor for GpsdConnection
GpsdConnection::GpsdConnection( QObject* parent )
    : QObject( parent ),
      m_timer( 0 )
{
    gps_data_t* data = m_gpsd.open();
    if ( data ) {
#if GPSD_API_MAJOR_VERSION == 3
        // Enable streaming in GPSD API v3
        m_gpsd.stream( WATCH_ENABLE );
#endif
        // Connect timer timeout signal to update slot
        connect( &m_timer, SIGNAL( timeout() ), this, SLOT( update() ) );
        m_timer.start( 1000 );
    } else {
        // Log connection failure
        mDebug() << "Connection to gpsd failed, no position info available.";
    }
}

// Update method to fetch GPS data
void GpsdConnection::update()
{
    gps_data_t* data;
#if GPSD_API_MAJOR_VERSION == 2
    // Query GPSD for old API version
    data = m_gpsd.query( "o" );
#elif GPSD_API_MAJOR_VERSION == 3
    // Poll GPSD until policy is set (v3)
    while ((data = m_gpsd.poll()) && !(data->set & POLICY_SET)) {
        data = m_gpsd.poll();
    }
#endif
    // Emit data if available
    if ( data )
        emit gpsdInfo( *data );
}

