// Converts string to double using C locale
double atof_dot(const char *str)
{
#ifdef _MSC_VER
    // Use Microsoft-specific locale-aware conversion
    _locale_t l = _create_locale(LC_NUMERIC, "C");
    double result = _atof_l(str, l);
    _free_locale(l);
    return result;
#else
    // Use standard C++ stream with C locale
    double result;
    std::istringstream s(str);
    std::locale l("C");
    s.imbue(l);
    s >> result;
    return result;
#endif
}

