// Adds two integers with overflow checking to avoid undefined behavior
int check_add(int a, int b)
{
    if (((b > 0) && (a > (numeric_limits<int>::max() - b))) ||
        ((b < 0) && (a < (numeric_limits<int>::min() - b))))
        error("check_add(): integer add overflows.");
    else
        return a + b;
}

// Generates a Fibonacci sequence of n values into v, starting with x and y
void fibonacci(int x, int y, vector<int>& v, int n)
{
    if (v.size() != 0)
        error("fibonacci(): Non empty vector passed as argument.");
    if (n < 2)
        error("fibonacci(): n must be at least 2.");

    v.push_back(x);
    v.push_back(y);

    for (int i = 2; i < n; ++i)
        v.push_back(check_add(v[i-2], v[i-1]));
}

