using namespace std;

class CCipher {
public:
  // Decodes the cipher text by shifting letters backward
  string decode(string cipherText, int shift) {
    string orig;
    for (char c : cipherText) {
      // Calculate original character with wrap-around
      orig += 'A' + (c - 'A' - shift + 26) % 26;
    }
    return orig;
  }
};

int main() {
  CCipher cc;
  // Test case: shift by 10 positions
  assert(cc.decode("ABCDEFGHIJKLMNOPQRSTUVWXYZ", 10) == "QRSTUVWXYZABCDEFGHIJKLMNOP");
}

