#include "SimpleString.h"
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

// Default constructor: initializes an empty string
SimpleString::SimpleString()
    : buffer(new char[1])
{
    buffer[0] = '\0';
}

// Constructor from C-string
SimpleString::SimpleString(const char *otherBuffer)
    : buffer(new char[strlen(otherBuffer) + 1])
{
    strcpy(buffer, otherBuffer);
}

// Copy constructor
SimpleString::SimpleString(const SimpleString& other)
{
    buffer = new char[other.size() + 1];
    strcpy(buffer, other.buffer);
}

// Assignment operator
SimpleString &SimpleString::operator=(const SimpleString& other)
{
    delete []buffer;
    buffer = new char[other.size() + 1];
    strcpy(buffer, other.buffer);
    return *this;
}

// Returns the underlying C-string
char *SimpleString::asCharString() const
{
    return buffer;
}

// Returns the length of the string
int SimpleString::size() const
{
    return strlen(buffer);
}

// Destructor
SimpleString::~SimpleString()
{
    delete [] buffer;
}

// Equality operator for two SimpleString objects
bool operator==(const SimpleString& left, const SimpleString& right)
{
    return !strcmp(left.asCharString(), right.asCharString());
}

