// External ThreadSanitizer API declarations
extern "C" {
void *__tsan_external_register_tag(const char *object_type);
void *__tsan_external_assign_tag(void *addr, void *tag);
void __tsan_external_read(void *addr, void *caller_pc, void *tag);
void __tsan_external_write(void *addr, void *caller_pc, void *tag);
void __tsan_write8(void *addr);
}

// Global tag for external memory operations
void *tag;

// Function to perform external write with ThreadSanitizer annotation
__attribute__((no_sanitize("thread")))
void ExternalWrite(void *addr) {
  __tsan_external_write(addr, __builtin_return_address(0), tag);
}

int main(int argc, char *argv[]) {
  // Initialize barrier for thread synchronization
  barrier_init(&barrier, 2);

  // Register custom object type with ThreadSanitizer
  tag = __tsan_external_register_tag("HelloWorld");

  fprintf(stderr, "Start.\n");
  // CHECK: Start.

  // First loop: Create and run test threads
  for (int i = 0; i < 4; i++) {
    void *opaque_object = malloc(16);

    std::thread t1([opaque_object] {
      ExternalWrite(opaque_object);
      barrier_wait(&barrier);
    });

    std::thread t2([opaque_object] {
      barrier_wait(&barrier);
      ExternalWrite(opaque_object);
    });

    // CHECK: WARNING: ThreadSanitizer: race on a library object
    t1.join();
    t2.join();
  }

  fprintf(stderr, "First phase done.\n");
  // CHECK: First phase done.

  // Second loop: Repeat the same pattern
  for (int i = 0; i < 4; i++) {
    void *opaque_object = malloc(16);

    std::thread t1([opaque_object] {
      ExternalWrite(opaque_object);
      barrier_wait(&barrier);
    });

    std::thread t2([opaque_object] {
      barrier_wait(&barrier);
      ExternalWrite(opaque_object);
    });

    // CHECK: WARNING: ThreadSanitizer: race on a library object
    t1.join();
    t2.join();
  }

  fprintf(stderr, "Second phase done.\n");
  // CHECK: Second phase done.

  return 0;
}

