#include <pthread.h>
#include <unistd.h>

// Global read-write lock and shared variable
pthread_rwlock_t rwlock;
int GLOB;

// Thread function that incorrectly writes under a reader lock
void *Thread1(void *p) {
  (void)p;

  // Acquire read lock
  pthread_rwlock_rdlock(&rwlock);

  // Write under reader lock - data race!
  usleep(100);
  GLOB++;

  // Release the lock
  pthread_rwlock_unlock(&rwlock);

  return 0;
}

int main(int argc, char *argv[]) {
  // Initialize the read-write lock
  pthread_rwlock_init(&rwlock, NULL);

  // Main thread acquires read lock
  pthread_rwlock_rdlock(&rwlock);

  // Create worker thread
  pthread_t t;
  pthread_create(&t, 0, Thread1, 0);

  // Read the shared variable while holding the lock
  volatile int x = GLOB;
  (void)x;

  // Release the lock
  pthread_rwlock_unlock(&rwlock);

  // Wait for thread to complete
  pthread_join(t, 0);

  // Clean up
  pthread_rwlock_destroy(&rwlock);

  return 0;
}

