template <class T> T from_str(const std::string & str)
{
    std::istringstream sin(str);
    T ret;
    sin >> ret;
    return ret;
}

// Print double value with high precision and its bit representation
void print(double a)
{
    printf("%.20f, %llX\n", a, *((unsigned long long *) &a));
}

int main(int argc, char **argv)
{
    double i = from_str<double>(argv[1]);

    // Various operations involving infinity and NaN
    print(sqrt(-1));           // NaN
    print(1.0/i);              // Infinity
    print(-1.0/i);             // Negative infinity
    print(0.0/i);              // Positive zero
    print(-0.0/i);             // Negative zero
    print((1.0/i)/(-1.0/i));   // -1.0
    print((1.0/i) + 3.0);      // Infinity
    print((-1.0/i) + 3.0);     // Negative infinity
    print(3.0/(1.0/i));        // 3.0

    return 0;
}

