// Constructs a Status object from a printf-style format and arguments
Status ToStatusF(Code code, const char* format, ...)
{
    va_list ap;
    va_start(ap, format);
    char* p;
    if (vasprintf(&p, format, ap) < 0)
    {
        abort();
    }
    va_end(ap);
    Status status(code, p);
    free(p);
    return status;
}

