// Handle fatal errors with optional color support
void fatal(const Twine &Msg) 
{
    if (sys::Process::StandardErrHasColors()) 
    {
        errs().changeColor(raw_ostream::RED, /*bold=*/true);
        errs() << "error: ";
        errs().resetColor();
    } 
    else 
    {
        errs() << "error: ";
    }

    // Output the error message
    errs() << Msg << "\n";
    exit(1);
}

