// Converts a program memory string to RAM
char *to_print;

char *pgmStrToRAM(PROGMEM char *theString)
{
    // Free previous allocation
    free(to_print);

    // Allocate memory for the string
    to_print = (char *) malloc(strlen_P(theString) + 1);

    // Copy string from program memory to RAM
    strcpy_P(to_print, theString);

    // Return pointer to the allocated string
    return (to_print);
}

