// Performance test for DFT operation
PERF_TEST_P(Size_MatType, dft, TEST_MATS_DFT)
{
    Size sz = get<0>(GetParam());
    int type = get<1>(GetParam());

    // Allocate input and output matrices
    Mat src(sz, type);
    Mat dst(sz, type);

    // Setup test parameters
    declare.in(src, WARMUP_RNG).time(60);

    // Execute DFT in performance loop
    TEST_CYCLE() dft(src, dst);

    // Validate result with sanity check
    SANITY_CHECK(dst, 1e-5, ERROR_RELATIVE);
}

