using namespace std;

// Template function for general types
template <typename T>
string debug_rep(const T &t) {
    ostringstream ret;
    ret << t;
    return ret.str();
}

// Template function for pointer types
template <typename T>
string debug_rep(T *p) {
    ostringstream ret;
    ret << "pointer: " << p;
    if(p) {
        ret << " content: " << debug_rep(*p);
    } else {
        ret << " null pointer";
    }
    return ret.str();
}

// Specialization for string type
string debug_rep(const string &s) {
    return '"' + s + '"' + "no template";
}

int main() {
    string s("hi");
    // Calls the templated version with T=string, since the string specialization is commented out
    cout << debug_rep(s) << endl;

    // Calls the pointer version with T=string
    cout << debug_rep(&s) << endl;

    const string *sp = &s;
    // Calls the pointer version with T=const string (more specialized)
    cout << debug_rep(sp) << endl;

    // For const char*, calls the pointer version with T=const char
    cout << debug_rep("hi world!") << endl;
}

