// Main message loop
void ImwWindowManagerDX11::InternalRun()
{
    MSG msg;
    if (PeekMessage(&msg, NULL, 0, 0, PM_REMOVE))
    {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }
    else
    {
        Update();
        Sleep(16);
    }
}

