using namespace tiramisu;

// Generates a function with given parameters
void gen(std::string name, int size, int val0, int val1)
{
    // Initialize the Tiramisu function
    tiramisu::init(name);

    // Get the implicit global function
    tiramisu::function *function0 = global::get_implicit_function();

    // Define constant N based on input size
    tiramisu::constant N("N", tiramisu::expr((int32_t) size), p_int32, true, NULL, 0, function0);

    // Declare iteration variables
    tiramisu::var i("i", 0, 10), j("j", 0, 10);
    tiramisu::var i0("i0"), j0("j0"), i1("i1"), j1("j1");

    // Define computation S0 as sum of val0 and val1
    tiramisu::computation S0(tiramisu::expr((uint8_t) (val0 + val1)), i, j);

    // Tile operation commented out
    //S0.tile(i, j, 2, 2, i0, j0, i1, j1);

    // Mark outer loop for parallelization
    S0.tag_parallel_level(i);

    // Define output buffer
    tiramisu::buffer buf0("buf0", {size, size}, tiramisu::p_uint8, a_output, function0);

    // Store result in buffer
    S0.store_in(&buf0, {i ,j});

    // Generate code to object file
    function0->codegen({&buf0}, "build/generated_fct_test_114.o");
}

// Main entry point
int main(int argc, char **argv)
{
    // Call gen with fixed parameters
    gen("func", 10, 3, 4);
    return 0;
}

