using namespace llvm;

namespace {

// Test timer additivity
TEST(Timer, Additivity)
{
    Timer T1("T1");
    EXPECT_TRUE(T1.isInitialized());

    // Start and stop first timing
    T1.startTimer();
    T1.stopTimer();
    auto TR1 = T1.getTotalTime();

    // Start again, sleep, then stop
    T1.startTimer();
    std::this_thread::sleep_for(std::chrono::milliseconds(1));
    T1.stopTimer();
    auto TR2 = T1.getTotalTime();

    // Verify second timing is greater
    EXPECT_TRUE(TR1 < TR2);
}

// Test timer trigger state
TEST(Timer, CheckIfTriggered)
{
    Timer T1("T1");

    // Initially not triggered
    EXPECT_FALSE(T1.hasTriggered());

    // After starting, should be triggered
    T1.startTimer();
    EXPECT_TRUE(T1.hasTriggered());

    // After stopping, still triggered
    T1.stopTimer();
    EXPECT_TRUE(T1.hasTriggered());

    // After clearing, no longer triggered
    T1.clear();
    EXPECT_FALSE(T1.hasTriggered());
}

