// Main function to demonstrate Kronrod quadrature methods
int main()
{
    Array<double,Dynamic,2> ans;
    int n = 10;

    // Compute multi-precision Kronrod nodes and weights using Laurie/Gautschi method
    ans = multiPrecisionKronrod(n);

    cout << "Laurie/Gautschi:" << endl;
    cout << setprecision(15);
    cout << ans << endl;
    cout << endl << endl;

    // Compute standard Kronrod and Gauss nodes/weights using Piessens method
