// Test fixture for SmallVector tests
class SmallVectorTest : public ::testing::Test {
};

// Test push_back and clear operations
TEST_F(SmallVectorTest, PushBackClear)
{
    SmallVector<int, 3> vec;
    vec.push_back(1);
    vec.push_back(2);
    vec.push_back(3);
    vec.push_back(4);
    vec.push_back(5);

    ASSERT_EQ(vec.size(), 5);
    ASSERT_EQ(vec[0], 1);
    ASSERT_EQ(vec[1], 2);
    ASSERT_EQ(vec[2], 3);
    ASSERT_EQ(vec[3], 4);
    ASSERT_EQ(vec[4], 5);

    vec.clear();
    ASSERT_EQ(vec.size(), 0);
}

// Test with small capacity
TEST_F(SmallVectorTest, SmallCapacity)
{
    SmallVector<int, 4> vec;
    vec.push_back(1);
    vec.push_back(2);

    ASSERT_EQ(vec.size(), 2);
    ASSERT_EQ(vec[0], 1);
    ASSERT_EQ(vec[1], 2);
}

// Test empty functionality
TEST_F(SmallVectorTest, Empty)
{
    SmallVector<int, 4> vec;
    ASSERT_TRUE(vec.empty());

    vec.push_back(1);
    ASSERT_FALSE(vec.empty());

    vec.clear();
    ASSERT_TRUE(vec.empty());
}

// Test vector growth beyond initial capacity
TEST_F(SmallVectorTest, Grow)
{
    SmallVector<int, 4> vec;

    vec.push_back(1);
    vec.push_back(2);
    ASSERT_EQ(vec.size(), 2);
    ASSERT_EQ(vec[0], 1);
    ASSERT_EQ(vec[1], 2);

    vec.push_back(3);
    vec.push_back(4);
    vec.push_back(5);
    ASSERT_EQ(vec.size(), 5);
    ASSERT_EQ(vec[0], 1);
    ASSERT_EQ(vec[1], 2);
    ASSERT_EQ(vec[2], 3);
    ASSERT_EQ(vec[3], 4);
    ASSERT_EQ(vec[4], 5);

    vec.clear();
    ASSERT_EQ(vec.size(), 0);

    vec.push_back(6);
    vec.push_back(7);
    vec.push_back(8);
    ASSERT_EQ(vec.size(), 3);
    ASSERT_EQ(vec[0], 6);
    ASSERT_EQ(vec[1], 7);
    ASSERT_EQ(vec[2], 8);

    vec.push_back(9);
    vec.push_back(10);
    vec.push_back(11);
    ASSERT_EQ(vec.size(), 6);
    ASSERT_EQ(vec[0], 6);
    ASSERT_EQ(vec[1], 7);
    ASSERT_EQ(vec[2], 8);
    ASSERT_EQ(vec[3], 9);
    ASSERT_EQ(vec[4], 10);
    ASSERT_EQ(vec[5], 11);

    vec.clear();
    ASSERT_EQ(vec.size(), 0);
}

// Test iterator functionality
TEST_F(SmallVectorTest, Iterator)
{
    constexpr size_t SMALL_CAPACITY = 4;
    std::vector<int> vec;
    SmallVector<int, SMALL_CAPACITY> smallVec;

    // Small case
    for (size_t i = 0; i < SMALL_CAPACITY; ++i) {
        smallVec.push_back(i);
        vec.push_back(i);
    }

    ASSERT_EQ(smallVec.size(), vec.size());
    ASSERT_EQ(smallVec, vec);

    size_t i = 0;
    for (auto it = smallVec.begin(); it != smallVec.end(); ++it, ++i) {
        ASSERT_EQ(*it, vec[i]);
    }

    i = 0;
    for (int x : smallVec) {
        ASSERT_EQ(x, vec[i]);
        ++i;
    }
}

// Test map functionality with large data
TEST_F(SmallVectorTest, Map)
{
    constexpr size_t size = 100000;
    SmallVector<int, 100> smallVec;

    for (size_t i = 0; i < size; ++i) {
        smallVec.push_back(i);
    }

    std::vector<int> vec;
    smallVec.map([&vec](int x) {
        vec.push_back(x);
    });

    ASSERT_EQ(smallVec, vec);
}

#include <karm/test>
import Karm.Core;

namespace Karm::Glob::Tests {

// Test glob matching functionality
test$("glob-match")
{
    // Empty string matches empty string
    expect$(matchGlob("", ""));

    // Single character matches same character
    expect$(matchGlob("a", "a"));

    // Non-empty pattern doesn't match empty string
    expect$(not matchGlob("a", ""));

    // Empty pattern doesn't match non-empty string
    expect$(not matchGlob("", "a"));

    // Exact match with alphanumeric
    expect$(matchGlob("abcABC123", "abcABC123"));

    // Case sensitive: ABCabc123 != abcABC123
    expect$(not matchGlob("ABCabc123", "abcABC123"));

    // Wildcard '?' matches any single character
    expect$(matchGlob("?", "a"));
    expect$(matchGlob("?", "b"));
    expect$(matchGlob("?", "1"));
    expect$(matchGlob("?", "8"));

    // '?' doesn't match empty string
    expect$(not matchGlob("?", ""));

    // Wildcard '*' matches any sequence of characters
    expect$(matchGlob("abcABC*", "abcABC123"));
    expect$(matchGlob("abc*123", "abcABC123"));
    expect$(matchGlob("abc*123", "abc123"));
    expect$(matchGlob("*ABC123", "abcABC123"));

    // Case sensitivity for '*'
    expect$(not matchGlob("abcABC*", "ABCabc123"));
    expect$(not matchGlob("abc*123", "ABCabc123"));
    expect$(not matchGlob("abc*123", "abcABCXYZ"));
    expect$(not matchGlob("*ABC123", "ABCabc123"));

    // Character class [abc] matches a, b, or c
    expect$(matchGlob("[abc]", "a"));
    expect$(matchGlob("[abc]", "b"));
    expect$(matchGlob("[abc]", "c"));
    expect$(not matchGlob("[abc]", "1"));
    expect$(not matchGlob("[abc]", "2"));
    expect$(not matchGlob("[abc]", "3"));

    // Range [a-z] matches lowercase letters
    expect$(matchGlob("[a-z]", "a"));
    expect$(matchGlob("[a-z]", "z"));
    expect$(not matchGlob("[a-z]", "1"));
    expect$(not matchGlob("[a-z]", "9"));

    // Negated range [^a-z] matches non-lowercase
    expect$(not matchGlob("[^a-z]", "a"));
    expect$(not matchGlob("[^a-z]", "z"));
    expect$(matchGlob("[^a-z]", "1"));
    expect$(matchGlob("[^a-z]", "9"));

    // Combined range [a-z0-9] matches lowercase letters or digits
    expect$(matchGlob("[a-z0-9]", "a"));
    expect$(matchGlob("[a-z0-9]", "k"));
    expect$(matchGlob("[a-z0-9]", "1"));
    expect$(matchGlob("[a-z0-9]", "7"));
    expect$(matchGlob("[a-z0-9]", "a"));

    // Uppercase letters not in [a-z0-9]
    expect$(not matchGlob("[a-z0-9]", "A"));
    expect$(not matchGlob("[a-z0-9]", "K"));

    return Ok();
}

} // namespace Karm::Glob::Tests

