        EXPECT_EQ(data, val);
        EXPECT_EQ(sizeof(bool), reader.getBuffer().size() * sizeof(uint8_t));
    }

    template <typename T>
    void checkReadNumber()
    {
        checkBasicRead(T {0});
        checkBasicRead(std::numeric_limits<T>::max());
        checkBasicRead(std::numeric_limits<T>::min());
        checkBasicRead(std::numeric_limits<T>::lowest());
    }
