    checkReadNumber<uint8_t>();
    checkReadNumber<int16_t>();
    checkReadNumber<uint16_t>();
    checkReadNumber<int32_t>();
    checkReadNumber<uint32_t>();
    checkReadNumber<uint64_t>();
    checkReadNumber<int64_t>();
    checkReadNumber<float32_t>();
