void DspCore::initDisplay() 
{
    begin();

    if(DEF_SPI_FREQ > 0) 
        setSPISpeed(DEF_SPI_FREQ);

    invert();
    cp437(true);
    flip();
    setTextWrap(false);
    setTextSize(1);
    fillScreen(0x0000);
}

void DspCore::clearDsp(bool black)
{ 
    fillScreen(black?0:config.theme.background); 
}

void DspCore::flip()
{ 
    if(ROTATE_90) 
        setRotation(config.store.flipscreen?3:1); 
    else 
        setRotation(config.store.flipscreen?2:0); 
}

void DspCore::invert()
{ 
    invertDisplay(!config.store.invertdisplay); 
}

void DspCore::sleep(void)
{ 
    enableSleep(true); 
    delay(150); 
    enableDisplay(false); 
    delay(150); 
}

void DspCore::wake(void)
{ 
    enableDisplay(true); 
    delay(150); 
    enableSleep(false); 
    delay(150); 
}

