#include <ros/ros.h>
#include "init.h"
#include "init_serial.h"

// Main entry point for the linktrack AOA node
int main(int argc, char **argv)
{
    ros::init(argc, argv, "linktrack_aoa");
    ros::NodeHandle nh;

    // Initialize serial communication
    serial::Serial serial;
    initSerial(&serial);

    // Set up protocol extraction and AOA initialization
    NProtocolExtracter protocol_extraction;
    linktrack_aoa::Init aoaInit(&protocol_extraction, &serial);

    // Main loop rate: 1000 Hz
    ros::Rate loop_rate(1000);

    while (ros::ok())
    {
        // Check available bytes in serial buffer
        auto available_bytes = serial.available();
        std::string str_received;

        if (available_bytes)
        {
            serial.read(str_received, available_bytes);
            protocol_extraction.AddNewData(str_received);
        }

        // Process ROS callbacks
        ros::spinOnce();
        loop_rate.sleep();
    }

    return EXIT_SUCCESS;
}

