void uiTabDrivenHandle(InputState& in)
{
    switch(g_app.currentTab)
    {
        case Tab::TAB_SLEEP:
            uiSleepMenuHandle(in);
            return;
        case Tab::TAB_INV:
            uiInventoryHandle(in);
            return;
        case Tab::TAB_SHOP:
