class Solution {
public:
    // Reverse the bits of a 32-bit unsigned integer
    uint32_t reverseBits(uint32_t n)
    {
        uint32_t ans = 0;
        for(int i=0;i<32;++i)
        {
            ans <<= 1;
            ans |= (n & 1);
            n >>= 1;
        }
        // Return the reversed bits
        return ans;
    }
};

