// Get unique ID for a single file using MD5
QByteArray GetFileUniquedId(const QString& fileAbsPath)
{
    return MD5Calculator::GetFileMD5(fileAbsPath, BytesRangeTool::BytesRangeE::SAMPLED_128_KB);
