#include <iostream>
#include <memory>
#include <set>
#include <vector>
#include "iresearch/index/postings.hpp"
#include "iresearch/store/store_utils.hpp"
#include "tests_shared.hpp"

using namespace irs;

namespace {
  constexpr size_t kBlockSize = 32768;
}

namespace tests {
namespace detail {

bytes_view ToBytesView(const std::string& s) {
  return bytes_view(reinterpret_cast<const byte_type*>(s.c_str()), s.size());
}

}  // namespace detail

void InsertFindCore(const std::vector<std::string>& src) {
  SimpleMemoryAccounter memory;
  auto pool =
    std::make_unique<byte_block_pool>(ManagedTypedAllocator<byte_type>{memory});
  byte_block_pool::inserter writer(pool->begin());
  Postings bh(writer);

  for (size_t i = 0; i < src.size(); ++i) {
    const std::string& s = src[i];
    const bytes_view b = detail::ToBytesView(s);
    auto res = bh.emplace(b);
    ASSERT_NE(nullptr, res);
    ASSERT_FALSE(doc_limits::valid(res->doc));
    res->doc = doc_limits::invalid() + 1;
    res = bh.emplace(b);
    ASSERT_NE(nullptr, res);
    ASSERT_TRUE(doc_limits::valid(res->doc));
  }

  ASSERT_GT(memory.Counter(), 0);
  ASSERT_EQ(src.size(), bh.size());
  ASSERT_FALSE(bh.empty());

  // insert long key
  {
    const std::string long_str(kBlockSize - irs::bytes_io<size_t>::vsize(32767),
                               'c');
    auto res = bh.emplace(detail::ToBytesView(long_str));
    ASSERT_FALSE(doc_limits::valid(res->doc));
  }

  // insert long key
  {
    const std::string too_long_str(kBlockSize, 'c');
    auto res = bh.emplace(detail::ToBytesView(too_long_str));
    ASSERT_FALSE(doc_limits::valid(res->doc));
  }

  // insert too long key
  {
    const std::string too_long_str(1 + kBlockSize, 'c');
    auto res = bh.emplace(detail::ToBytesView(too_long_str));
    ASSERT_EQ(nullptr, res);
  }

  ASSERT_GT(memory.Counter(), 0);
  pool.reset();
  ASSERT_EQ(memory.Counter(), 0);
}

}  // namespace tests

TEST(postings_tests, ctor) {
  SimpleMemoryAccounter memory;
  auto pool =
    std::make_unique<byte_block_pool>(ManagedTypedAllocator<byte_type>{memory});
  byte_block_pool::inserter writer(pool->begin());
  Postings bh(writer);

  ASSERT_TRUE(bh.empty());
  ASSERT_EQ(0, bh.size());
  ASSERT_EQ(0, memory.Counter());
}

