    void save_to_file(const std::string& absolute_path, const mesh::load_data& obj)
    {
        std::ofstream stream(absolute_path);
        if(stream.good())
        {
            auto ar = ser20::create_oarchive_associative(stream);
            try_save(ar, ser20::make_nvp("mesh", obj));
        }
    }

