// Computes the absolute value for int64_t, ensuring the result is within int63 range
int64_t Int63Arith::i_abs(const int64_t x)
{
    if ((x < int64_t(0)))
    {
        // Negate and mask to ensure sign bit is cleared (int63 constraint)
        return ((int64_t(0) - x) & 0x7FFFFFFFFFFFFFFFLL);
    }
    else
    {
        return x;
    }
}

