#include "llvm/InitializePasses.h"

using namespace llvm;

/// initializeScalarOptsPasses - Initialize all passes linked into the
/// ScalarOpts library.
void llvm::initializeScalarOpts(PassRegistry &Registry)
{
  // Initialize constant hoisting pass
  initializeConstantHoistingLegacyPassPass(Registry);

  // Initialize dead code elimination pass
  initializeDCELegacyPassPass(Registry);

  // Initialize global value numbering pass
  initializeGVNLegacyPassPass(Registry);

  // Initialize early CSE pass
  initializeEarlyCSELegacyPassPass(Registry);

  // Initialize early CSE with memory SSA pass
  initializeEarlyCSEMemSSALegacyPassPass(Registry);

  // Initialize CFG flattening pass
  initializeFlattenCFGLegacyPassPass(Registry);

  // Initialize address space inference pass
  initializeInferAddressSpacesPass(Registry);

  // Initialize instruction simplification pass
  initializeInstSimplifyLegacyPassPass(Registry);

  // Initialize loop invariant code motion pass
  initializeLegacyLICMPassPass(Registry);

  // Initialize loop data prefetching pass
  initializeLoopDataPrefetchLegacyPassPass(Registry);

  // Initialize loop rotation pass
  initializeLoopRotateLegacyPassPass(Registry);

  // Initialize loop strength reduction pass
  initializeLoopStrengthReducePass(Registry);

  // Initialize loop unrolling pass
  initializeLoopUnrollPass(Registry);

  // Initialize atomic lowering pass
  initializeLowerAtomicLegacyPassPass(Registry);

  // Initialize constant intrinsic lowering pass
  initializeLowerConstantIntrinsicsPass(Registry);

  // Initialize comparison merging pass
  initializeMergeICmpsLegacyPassPass(Registry);

  // Initialize n-ary reassociation pass
  initializeNaryReassociateLegacyPassPass(Registry);

  // Initialize partial inline calls pass
  initializePartiallyInlineLibCallsLegacyPassPass(Registry);

  // Initialize reassociation pass
  initializeReassociateLegacyPassPass(Registry);

  // Initialize masked memory intrinsic scalarization pass
  initializeScalarizeMaskedMemIntrinLegacyPassPass(Registry);

  // Initialize scalar replacement of aggregates pass
  initializeSROALegacyPassPass(Registry);

  // Initialize CFG simplification pass
  initializeCFGSimplifyPassPass(Registry);

  // Initialize CFG structuring pass
  initializeStructurizeCFGLegacyPassPass(Registry);

  // Initialize sinking pass
  initializeSinkingLegacyPassPass(Registry);

  // Initialize tail call elimination pass
  initializeTailCallElimPass(Registry);

  // Initialize TLS variable hoisting pass
  initializeTLSVariableHoistLegacyPassPass(Registry);

  // Initialize separate constant offset from GEP pass
  initializeSeparateConstOffsetFromGEPLegacyPassPass(Registry);

  // Initialize speculative execution pass
  initializeSpeculativeExecutionLegacyPassPass(Registry);

  // Initialize straight line strength reduction pass
  initializeStraightLineStrengthReduceLegacyPassPass(Registry);

  // Initialize backedge safepoint placement pass
  initializePlaceBackedgeSafepointsLegacyPassPass(Registry);
}

