// Function to change ownership of a symbolic link
int lchown(const char *path, uid_t uid, gid_t gid)
{
#ifdef SYS_lchown
	// Use lchown system call if available
	return syscall(SYS_lchown, path, uid, gid);
#else
	// Fallback to fchownat with AT_SYMLINK_NOFOLLOW flag
	return syscall(SYS_fchownat, AT_FDCWD, path, uid, gid, AT_SYMLINK_NOFOLLOW);
#endif
}

