    EXPECT_LT(t1, t2);
    EXPECT_LE(t1, t2);
    EXPECT_GT(t2, t1);
    EXPECT_GE(t2, t1);

    EXPECT_EQ(t1 + d, t2);
    EXPECT_EQ(t2 - d, t1);
    EXPECT_EQ(t1 += d, t2);
    EXPECT_GE(t1, t2);
    EXPECT_LE(t1, t2);
    EXPECT_EQ(Time(100), t1 -= d);
