// Test single environment variable scope
TEST(TScopedEnvironment, SingleValue)
{
    auto before = GetEnv("ARCADIA_SOURCE_ROOT");
    {
        NTesting::TScopedEnvironment guard("ARCADIA_SOURCE_ROOT", "source");
        EXPECT_EQ("source", GetEnv("ARCADIA_SOURCE_ROOT"));
    }
    EXPECT_EQ(before, GetEnv("ARCADIA_SOURCE_ROOT"));
}

// Test multiple environment variables scope
TEST(TScopedEnvironment, MultiValue)
{
    TVector<TString> before{GetEnv("ARCADIA_SOURCE_ROOT"), GetEnv("ARCADIA_BUILD_ROOT")};
    {
        NTesting::TScopedEnvironment guard{{
            {"ARCADIA_SOURCE_ROOT", "source"},
            {"ARCADIA_BUILD_ROOT", "build"},
        }};
        EXPECT_EQ("source", GetEnv("ARCADIA_SOURCE_ROOT"));
        EXPECT_EQ("build", GetEnv("ARCADIA_BUILD_ROOT"));
    }
    TVector<TString> after{GetEnv("ARCADIA_SOURCE_ROOT"), GetEnv("ARCADIA_BUILD_ROOT")};
    EXPECT_EQ(before, after);
}

#include "Misc/AutomationTest.h"

// Spec for System Automation
BEGIN_DEFINE_SPEC(AutomationSpec, "System.Automation.Spec", EAutomationTestFlags::EngineFilter | EAutomationTestFlags::ApplicationContextMask)
	bool Foo;
	FString RunOrder; 
END_DEFINE_SPEC(AutomationSpec)

void AutomationSpec::Define()
{
	// First describe block
	Describe("A Describe 1", [this]()
	{
		It("contains a spec with an expectation", [this]()
		{
			Foo = true;
			TestEqual("Foo", Foo, true);
		});
	});

	// Second describe block with disabled specs
	Describe("A Describe 2", [this]()
	{
		BeforeEach([&]()
		{
			Foo = false;
		});

		xIt("will not run disabled specs", [this]()
		{
			TestEqual("Foo", Foo, true);
		});

		xDescribe("with disabled nested Describes", [this]()
		{
			It("will not run specs within those Describes", [this]()
			{
				TestEqual("Foo", Foo, true);
			});
		});
	});

	// Third describe block - BeforeEach and AfterEach example 1
	Describe("A spec using BeforeEach and AfterEach", [this]()
	{
		BeforeEach([this]()
		{
			RunOrder = TEXT("A");
		});

		It("will run code before each spec in the Describe and after each spec in the Describe", [this]()
		{
			TestEqual("RunOrder", RunOrder, TEXT("A"));
		});

		AfterEach([this]()
		{
			RunOrder += TEXT("Z");
			TestEqual("RunOrder", RunOrder, TEXT("AZ"));
		});
	});

	// Fourth describe block - nested BeforeEach/AfterEach example
	Describe("A spec using BeforeEach and AfterEach", [this]()
	{
		AfterEach([this]()
		{
			RunOrder += TEXT("Z");
			TestEqual("RunOrder", RunOrder, TEXT("ABYZ"));
		});

		Describe("while nested inside another Describe", [this]()
		{
			It("will run all BeforeEach blocks and all AfterEach blocks", [this]()
			{
				TestEqual("RunOrder", RunOrder, TEXT("AB"));
			});

			AfterEach([this]()
			{
				RunOrder += TEXT("Y");
			});

			BeforeEach([this]()
			{
				RunOrder += TEXT("B");
			});
		});

		BeforeEach([this]()
		{
			RunOrder = TEXT("A");
		});
	});

	// Fifth describe block - deeply nested BeforeEach/AfterEach example
	Describe("A spec using BeforeEach and AfterEach", [this]()
	{
		BeforeEach([this]()
		{
			RunOrder = TEXT("A");
		});

		AfterEach([this]()
		{
			RunOrder += TEXT("Z");
			TestEqual("RunOrder", RunOrder, TEXT("ABCDXYZ"));
		});

		BeforeEach([this]()
		{
			RunOrder += TEXT("B");
		});

		Describe("while nested inside another Describe", [this]()
		{
			AfterEach([this]()
			{
				RunOrder += TEXT("Y");
			});

			BeforeEach([this]()
			{
				RunOrder += TEXT("C");
			});

			Describe("while nested inside yet another Describe", [this]()
			{
				It("will run all BeforeEach blocks and all AfterEach blocks", [this]()
				{
					TestEqual("RunOrder", RunOrder, TEXT("ABCD"));
				});

				AfterEach([this]()
				{
					RunOrder += TEXT("X");
				});

				BeforeEach([this]()
				{
					RunOrder += TEXT("D");
				});
			});
		});
	});
}

