        .def_ro("channel_count", &FormatInfo::channel_count, D(FormatInfo, channel_count))
        .def_ro("type", &FormatInfo::type, D(FormatInfo, type))
        .def_ro("is_depth", &FormatInfo::is_depth, D(FormatInfo, is_depth))
