#include <windows.h>
#include "bcrypt.h"
#include <string.h>
#include "dds/ddsrt/random.h"

// Generates a random seed for PRNG
bool ddsrt_prng_makeseed (struct ddsrt_prng_seed *seed)
{
    NTSTATUS res;
    // Initialize seed key to zero
    memset (seed->key, 0, sizeof (seed->key));
    // Generate random bytes using system preferred RNG
    res = BCryptGenRandom (NULL, (PUCHAR) seed->key, (ULONG) sizeof (seed->key), BCRYPT_USE_SYSTEM_PREFERRED_RNG);
    // Return true if successful (NTSTATUS >= 0)
    return (res >= 0);
}

