// Main function to find maximum of three numbers
int main()
{
    int a, b, c, m;
    char ch;

    do
    {
        // Read three integers
        printf("%d %d %d", &a, &b, &c);

        // Calculate maximum using ternary operator
        m = (a > b && a > c ? a : (b < c ? b : c));

        // Print the maximum number
        printf("max num= %d\n", m);

        // Ask user if they want to continue
        printf("like to cont...(y/n)");
        scanf("%c", &ch);
    }
    while(ch == 'y' || ch == 'Y');

    return 0;
}

