class BytesInput : public BytesViewInput {
 public:
  BytesInput() = default;
  BytesInput(BytesInput&& rhs) noexcept;
  BytesInput& operator=(BytesInput&& rhs) noexcept;
  explicit BytesInput(bytes_view data);

 private:
