BytesInput::BytesInput(BytesInput&& other) noexcept
  : _buf{std::move(other._buf)} {
  reset(_buf);
  other.reset({});
}

BytesInput& BytesInput::operator=(BytesInput&& other) noexcept {
  if (this != &other) {
