  return *this;
}

void AvgEncodeDecodeCore(size_t step, size_t count) {
  std::vector<uint64_t> values;
  values.reserve(count);
  for (size_t i = 1; i <= count; ++i) {
    values.push_back(i * step);
  }

  auto encoded = values;
  const auto stats =
    irs::encode::avg::encode(encoded.data(), encoded.data() + encoded.size());

  ASSERT_EQ(values[0], std::get<0>(stats));
  ASSERT_EQ(step, std::get<1>(stats));
  ASSERT_EQ(irs::irstd::AllEqual(std::begin(encoded), std::end(encoded)),
            std::get<2>(stats));
  ASSERT_TRUE(std::all_of(encoded.begin(), encoded.end(),
                          [](uint64_t v) { return 0 == v; }));

  auto success = true;
  auto begin = values.begin();
  irs::encode::avg::visit(std::get<0>(stats), std::get<1>(stats),
                          encoded.data(), encoded.data() + encoded.size(),
                          [&begin, &success](uint64_t value) {
                            success = success && (value == *begin);
                            ++begin;
                          });
  ASSERT_TRUE(success);
  ASSERT_EQ(values.end(), begin);

  auto decoded = encoded;
  irs::encode::avg::decode(std::get<0>(stats), std::get<1>(stats),
                           decoded.data(), decoded.data() + decoded.size());
  ASSERT_EQ(values, decoded);
}

void DeltaEncodeDecodeCore(size_t step, size_t count) {
  std::vector<size_t> values;
  values.reserve(count);
  for (size_t i = 1; i <= count; ++i) {
    values.push_back(i * step);
  }

  auto encoded = values;
  irs::encode::delta::Encode(encoded.begin(), encoded.end());

  ASSERT_TRUE(std::all_of(encoded.begin(), encoded.end(),
                          [step](auto v) { return step == v; }));

  auto decoded = encoded;
  irs::encode::delta::Decode(decoded.begin(), decoded.end());
  ASSERT_EQ(values, decoded);
}

void PackedReadWriteCore(const std::vector<uint32_t>& src) {
  static constexpr size_t kBlockSize = 128;
  uint32_t encoded[kBlockSize];
  const auto blocks = src.size() / kBlockSize;

  SDB_ASSERT(blocks);

  // compress data to stream
  irs::bstring buf;
  irs::BytesOutput out(buf);

  auto pack = [](const uint32_t* decoded, uint32_t* encoded,
                 const uint32_t bits) {
    irs::packed::Pack(decoded, decoded + kBlockSize, encoded, bits);
  };

  auto unpack = [](uint32_t* decoded, const uint32_t* encoded,
                   const uint32_t bits) {
    irs::packed::Unpack(decoded, decoded + kBlockSize, encoded, bits);
  };

  // write first n compressed blocks
  {
    auto begin = src.data();
    for (size_t i = 0; i < blocks; ++i) {
      irs::bitpack::write_block32(pack, out, begin, encoded, kBlockSize);
      begin += kBlockSize;
    }
  }

  // decompress data from stream
  std::vector<uint32_t> read(src.size());
  irs::BytesViewInput in(buf);

  // read first n compressed blocks
  {
    auto begin = read.data();
    for (size_t i = 0; i < blocks; ++i) {
      irs::bitpack::read_block32(unpack, in, encoded, begin, kBlockSize);
      begin += kBlockSize;
    }
  }

  ASSERT_EQ(src, read);
}

void PackedReadWriteBlockCore(const std::vector<uint32_t>& src) {
  static constexpr size_t kBlockSize = 128;
  uint32_t encoded[kBlockSize];

  auto pack = [](const uint32_t* decoded, uint32_t* encoded,
                 const uint32_t bits) {
    irs::packed::Pack(decoded, decoded + kBlockSize, encoded, bits);
  };

  auto unpack = [](uint32_t* decoded, const uint32_t* encoded,
                   const uint32_t bits) {
    irs::packed::Unpack(decoded, decoded + kBlockSize, encoded, bits);
  };

  // compress data to stream
  irs::bstring buf;
  irs::BytesOutput out(buf);
  irs::bitpack::write_block32(pack, out, src.data(), encoded, kBlockSize);

  // decompress data from stream
  std::vector<uint32_t> read(src.size());
  irs::BytesViewInput in(buf);
  irs::bitpack::read_block32(unpack, in, encoded, read.data(), kBlockSize);

  ASSERT_EQ(src, read);
}

using irs::DataInput;
