template<typename T>
void ReadWriteCore(const std::vector<T>& src,
                   const std::function<T(DataInput&)>& reader,
                   const std::function<void(DataOutput&, T)>& writer) {
  irs::bstring buf;
  irs::BytesOutput out(buf);

  std::for_each(src.begin(), src.end(),
                [&out, &writer](const T& v) { writer(out, v); });

  BytesInput in(buf);
  std::for_each(src.begin(), src.end(),
                [&in, &reader](const T& v) { ASSERT_EQ(v, reader(in)); });
}

// Since NaN != NaN according to the ieee754
template<typename T>
void ReadWriteCoreNan(const std::function<T(DataInput&)>& reader,
                      const std::function<void(DataOutput&, T)>& writer) {
  irs::bstring buf;
  irs::BytesOutput out(buf);

  writer(out, std::numeric_limits<T>::quiet_NaN());
  writer(out, std::numeric_limits<T>::signaling_NaN());

  BytesInput in(buf);
  ASSERT_TRUE(std::isnan(reader(in)));
  ASSERT_TRUE(std::isnan(reader(in)));
}

template<typename Cont>
void ReadWriteCoreContainer(
  const Cont& src, const std::function<Cont(DataInput&)>& reader,
  const std::function<DataOutput&(DataOutput&, const Cont&)>& writer) {
  irs::bstring buf;
  irs::BytesOutput out(buf);
  writer(out, src);

  BytesInput in(buf);
  const Cont read = reader(in);
  ASSERT_EQ(src, read);
}

void ReadWriteBlock(const std::vector<uint32_t>& source,
                    std::vector<uint32_t>& enc_dec_buf) {
  const auto size = source.size();

  auto pack = [&](const uint32_t* decoded, uint32_t* encoded,
                  const uint32_t bits) {
    irs::packed::Pack(decoded, decoded + size, encoded, bits);
  };

  auto unpack = [&](uint32_t* decoded, const uint32_t* encoded,
                    const uint32_t bits) {
    irs::packed::Unpack(decoded, decoded + size, encoded, bits);
  };

  // write block
  irs::bstring buf;
  irs::BytesOutput out(buf);
  irs::bitpack::write_block32(pack, out, source.data(), enc_dec_buf.data(),
                              size);

  // read block
  BytesInput in(buf);
  std::vector<uint32_t> read(size);
  irs::bitpack::read_block32(unpack, in, enc_dec_buf.data(), read.data(), size);

  ASSERT_EQ(source, read);
}

void ReadWriteBlock(const std::vector<uint32_t>& source) {
  // intermediate buffer for encoding/decoding
  std::vector<uint32_t> enc_dec_buf(source.size());
  ReadWriteBlock(source, enc_dec_buf);
}

void ShiftPackUnpackCore32(uint32_t value, bool flag) {
  const uint32_t packed = ShiftPack32(value, flag);
  uint32_t unpacked;

  ASSERT_EQ(flag, ShiftUnpack32(packed, unpacked));
  ASSERT_EQ(value, unpacked);
}

void ShiftPackUnpackCore64(uint64_t value, bool flag) {
  const uint64_t packed = ShiftPack64(value, flag);
  uint64_t unpacked;

  ASSERT_EQ(flag, ShiftUnpack64(packed, unpacked));
  ASSERT_EQ(value, unpacked);
}

template<typename T>
void VencodeFromArray(T expected_value, size_t expected_length) {
  ASSERT_EQ(expected_length, irs::bytes_io<T>::vsize(expected_value));

  irs::byte_type buf[irs::bytes_io<T>::kMaxVSize]{};

  // write data
  {
    auto* ptr = buf;
    irs::WriteVarint<T>(expected_value, ptr);
    ASSERT_EQ(expected_length, std::distance(buf, ptr));
  }

  // read data
  {
    const auto* ptr = buf;
    ASSERT_EQ(expected_value, irs::vread<T>(ptr));
    ASSERT_EQ(expected_length,
              std::distance((const irs::byte_type*)(buf), ptr));
  }

  // skip data
  {
    const auto* ptr = buf;
    irs::vskip<T>(ptr);
    ASSERT_GE(ptr, buf);
    ASSERT_EQ(expected_length,
              std::distance((const irs::byte_type*)(buf), ptr));
  }
}

