#include "f2c.h"

// Define log10e constant
#define log10e 0.43429448190325182765

#ifdef KR_headers
// Old-style K&R C function declaration
double log();
double r_lg10(x) real *x;
#else
// Standard C function declaration
#undef abs
#include "math.h"
double r_lg10(real *x)
#endif
{
    // Compute base-10 logarithm using natural logarithm
    return( log10e * log(*x) );
}

#include <iostream>

// Multiplies x by n
void timesN(int &x, int n)
{
    x *= n;
}

// Adds n to x
void plusN(int &x, int n)
{
    x += n;
}

// Prints x followed by a space
void print(int& x)
{
    std::cout << x << ' ';
}

// Maps a unary function over the array
void map(int* arr, int size, void (*mappingFunction)(int&))
{
    for (int i = 0; i < size; i++)
    {
        mappingFunction(arr[i]);
    }
}

// Maps a binary function with an additional parameter over the array
void map(int* arr, int size, void (*mappingFunction)(int&, int), int n)
{
    for (int i = 0; i < size; i++)
    {
        mappingFunction(arr[i], n);
    }
}

int main()
{
    int arr[5] {1,2,3,4,5};

    // Multiply each element by 10
    map(arr, 5, timesN, 10);

    // Add 1 to each element (note: original code missing semicolon here)
    map(arr, 5, plusN, 1);

    // Multiply each element by 10 using lambda
    map(arr, 5, [](int& x){ x *= 10; });

    // Print each element
