  for (int i = 0; i < required.size(); ++i) {
    ui->requiredPlugins->setItem(i, 0,
                                 new QTableWidgetItem(required[i]->localizedName()));
    ui->requiredPlugins->setItem(i, 1,
                                 new QTableWidgetItem(required[i]->description()));
