namespace conv {

// Convert wide string to UTF-8 bytes
auto ToBytes(const std::wstring& wstr) -> std::string
{
    std::string str;
    utf8::utf16to8(wstr.begin(), wstr.end(), std::back_inserter(str));
    return str;
}

// Convert wide string (rvalue reference) to UTF-8 bytes
auto ToBytes(std::wstring&& wstr) -> std::string
{
    std::string str;
    utf8::utf16to8(wstr.begin(), wstr.end(), std::back_inserter(str));
    return str;
}

// Convert UTF-8 bytes to wide string
auto FromBytes(const std::string& str) -> std::wstring
{
    std::wstring wstr;
    utf8::utf8to16(str.begin(), str.end(), std::back_inserter(wstr));
    return wstr;
}

// Convert UTF-8 bytes (rvalue reference) to wide string
auto FromBytes(std::string&& str) -> std::wstring
{
    std::wstring wstr;
    utf8::utf8to16(str.begin(), str.end(), std::back_inserter(wstr));
    return wstr;
}

