    Ar.SetByteSwapping(true);
    Ar << FlagsAndLength;
    Ar << Vector;
    Ar << Page;
    Ar << Last;
    Ar.SetByteSwapping(false);
    Ar.Serialize((void*)Universes, sizeof(Universes));
}

