                rate,i,rate/2 / (i/2),toBARK(rate/2 /(i/2)),toBARK(rate/2));

        rate=22050.f;
        fprintf(stderr,"rate=%gHz, block=%d, f(1)=%.2gHz bark(1)=%.2g (of %.2g)\n",
                rate,i,rate/2 / (i/2),toBARK(rate/2 /(i/2)),toBARK(rate/2));

