namespace {

const u32 Function_GetErrorMessage = 0x00491E80;

void __declspec(naked) techErrorMessageWrapper() {
  static CUnit *unitTarget;
  static u8 playerIndex;
  static u16 technologyId;
  static u16 errorResult;

  __asm {
    PUSHAD
    MOV EBP, ESP
    MOV unitTarget, EAX
    MOV playerIndex, BL
    MOV EAX, [ESP + 36]   ;// (PUSHAD saves 32) + (CALL saves 4) == 36
    MOV technologyId, AX
  }

  errorResult = hooks::techErrorMessageHook(unitTarget, playerIndex, technologyId);

  __asm {
    POPAD
    MOV AX, errorResult
    RETN 4
  }
}

} //Unnamed namespace

namespace hooks {

void installTechTargetHooks() {
  jmpPatch(techErrorMessageWrapper, Function_GetErrorMessage);
}

u16 techErrorMessage(const CUnit *targetUnit, s8 sourcePlayer, u16 techCode) {
  u32 techCode_ = techCode;
  static u16 resultError;

  __asm {
    PUSHAD
    PUSH techCode_
    MOV BL, sourcePlayer
    MOV EAX, targetUnit
    CALL Function_GetErrorMessage
    MOV resultError, AX
    POPAD
  }

  return resultError;
}

} //hooks

