template<typename IteratorT>
void display(const range<IteratorT>& r)
{
    for (auto val : r)
        std::cout << val << " ";
    std::cout << std::endl;
}

template<typename IteratorT>
size_t count_elements(const range<IteratorT>& r)
{
    return std::distance(r.begin(), r.end());
}

int main()
{
    std::list<int> dataList{ 5, 2, 7, 18, 40 };
    auto r1 = make_range(dataList.begin(), dataList.end());
    display(r1);
    std::cout << "Element count: " << count_elements(r1) << std::endl;

    std::vector<int> vecData;
    std::copy(dataList.begin(), dataList.end(), std::back_inserter(vecData));

    auto r2 = make_range(vecData.begin(), std::next(vecData.begin(), 3));
    display(r2);
    std::cout << "Element count: " << count_elements(r2) << std::endl;

    randomize();
    std::shuffle(r2.begin(), r2.end(), global_urng());

    std::copy(r2.begin(), r2.end(), std::ostream_iterator<int>(std::cout, " "));
    std::cout << std::endl;

    std::copy(r1.begin(), r1.end(), std::ostream_iterator<int>(std::cout, " "));
    std::cout << std::endl;

    return 0;
}

