PatternPostureGenerator::PatternPostureGenerator() {}

PatternPostureGenerator::PatternPostureGenerator(ros::NodeHandle& nh) {
  if (!nh.getParam("pattern", pattern_names)) return;

  for (std::map<std::string, std::string>::iterator iter = pattern_names.begin();
       iter != pattern_names.end();
       ++iter) {
    std::vector<double> joint_values;
    if (!nh.getParam(std::string("pattern/").append(iter->second), joint_values)) return;

    std::copy(joint_values.begin(), joint_values.end(),
              std::back_inserter(posture_datas[iter->second]));
  }

  key_service = nh.advertiseService("getPostureKey", &PatternPostureGenerator::getPostureKey, this);
}

bool PatternPostureGenerator::getPostureKey(pattern_posture_generator::PatternKeyPosture::Request&  request,
                                            pattern_posture_generator::PatternKeyPosture::Response& response) {
  std::copy(posture_datas[request.name].begin(), posture_datas[request.name].end(),
            std::back_inserter(response.posture));
  return true;
}

