WindowObserver::WindowObserver() : observation_count_(0) {
}

WindowObserver::~WindowObserver() {
  CHECK_EQ(0, observation_count_);
}

void WindowObserver::OnObservingWindow(aura::Window* window) {
  if (!window->HasObserver(this)) {
    observation_count_ += 1;
  }
}

void WindowObserver::OnUnobservingWindow(aura::Window* window) {
  if (window->HasObserver(this)) {
    observation_count_ = observation_count_ - 1;
  }
}

