// Test fixture for Engine, based on EngineLauncher structure
class EngineTest : public ::testing::Test {
protected:
    void SetUp() override {
        // Initialize any required test state here
        stopSignal = false;
        condVar.notify_all();
    }

    void TearDown() override {
        // Clean up resources if needed
    }

    std::atomic<bool> stopSignal;
    std::condition_variable condVar;
    std::mutex mtx;
};

// Test that verifies engine starts correctly and echo functionality works
TEST_F(EngineTest, EchoServerFunctionality) {
    // Step 1: Create engine instance
    core::Engine engine;

    // Step 2: Start the engine in a separate thread
    std::thread engineThread([&engine]() {
        engine.run();
    });

    // Step 3: Wait briefly for server socket to be established
    std::this_thread::sleep_for(std::chrono::milliseconds(100));

    // Step 4: Create TCP client and send test data to echo server
    const std::string testData = "Hello, Echo!";
    int clientSocket = socket(AF_INET, SOCK_STREAM, 0);
    ASSERT_NE(clientSocket, -1);

    struct sockaddr_in serverAddr;
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(8080); // Assuming default port
    inet_pton(AF_INET, "127.0.0.1", &serverAddr.sin_addr);

    int connectResult = connect(clientSocket, (struct sockaddr*)&serverAddr, sizeof(serverAddr));
    ASSERT_EQ(connectResult, 0);

    send(clientSocket, testData.c_str(), testData.size(), 0);

    // Step 5: Receive and verify echoed response
    char buffer[256] = {0};
    ssize_t bytesRead = recv(clientSocket, buffer, sizeof(buffer) - 1, 0);
    close(clientSocket);

    EXPECT_EQ(std::string(buffer, bytesRead), testData);

    // Signal engine to stop
    stopSignal = true;
    condVar.notify_all();

    // Join engine thread
    if (engineThread.joinable()) {
        engineThread.join();
    }
}

