class IncrementAndDoubling
{
    public:
        int getMinHelper(vector<int> targetArray, int steps)
        {
            if(all_of(begin(targetArray), end(targetArray), [] (const int & value) {return value==0;}))
            {   
                return steps;
            }

            if(all_of(begin(targetArray), end(targetArray), [] (int & value) {return value%2==0;}))
            {   
                for(auto & value : targetArray)
                {
                    value /= 2;
                }

                steps++;
            }
            else
            {   
                for(auto & value : targetArray)
                {
                    if(value % 2 == 1)
                    {
                        value--;

                        steps++;
                    }
                }
            }

            return getMinHelper(targetArray, steps);
        }

        int getMin(vector<int> targetArray)
        {   
            int steps{};

            int outcome = getMinHelper(targetArray, steps);

            return outcome;
        }
};

