#include <iostream>
#include <string>
using namespace std;

int main() {
    string input1, input2;
    cout << "Please enter two strings: ";
    cin >> input1 >> input2;

    int len1 = input1.length();
    int len2 = input2.length();

    // Create DP table for edit distance calculation
    int dp[len1 + 1][len2 + 1];

    // Initialize base cases
    for (int row = 0; row <= len1; row++) {
        for (int col = 0; col <= len2; col++) {
            if (row == 0) {
                dp[row][col] = col;
            } else if (col == 0) {
                dp[row][col] = row;
            } else if (input1[row - 1] == input2[col - 1]) {
                dp[row][col] = dp[row - 1][col - 1];
            } else {
                dp[row][col] = 1 + min(dp[row - 1][col], 
                                      min(dp[row][col - 1], 
                                          dp[row - 1][col - 1]));
            }
        }
    }

    cout << "The edit distance is " << dp[len1][len2] << "." << endl;
    return 0;
}

