// Function to redirect cout to a file and return the written content
std::string RedirectOutput(std::string text)
{
    std::ofstream writer("temp.txt");
    std::streambuf* originalCoutBuffer = std::cout.rdbuf();
    std::cout.rdbuf(writer.rdbuf());

    // Simulate rang-style formatting (without actual rang dependency)
    // In original code, rang::fg::blue would add ANSI codes; here we skip for simplicity
    std::cout << text;

    std::cout.rdbuf(originalCoutBuffer);
    writer.close();

    std::ifstream reader("temp.txt");
    std::string result;
    std::getline(reader, result);
    return result;
}

int main() {
    // Unit test simulation
    std::string testInput = "HelloWorld";
    std::string actualOutput = RedirectOutput(testInput);

    if (actualOutput == testInput) {
        std::cout << "Test passed: Output matches input" << std::endl;
        return 0;
    } else {
        std::cout << "Test failed: Output does not match input" << std::endl;
        return 1;
    }
}

