// Move constructor for VertexBuffer
VertexBuffer::VertexBuffer(VertexBuffer&& other) : vBO{other.vBO}, iBO{other.iBO}, nBO{other.nBO}, vao(other.vao), numIndices{other.numIndices}, extremes{other.extremes},
bounds(std::move(other.bounds)) {
}

// Constructor with explicit buffer handles and bounding data
VertexBuffer::VertexBuffer(GLuint bufferVBO, GLuint bufferIBO, GLuint bufferNBO, unsigned int indexCount, std::tuple<glm::vec3, glm::vec3> boundaryExtremes)
: vBO(bufferVBO), iBO(bufferIBO), nBO(bufferNBO), numIndices(indexCount), extremes(boundaryExtremes), bounds{new collisiondetection::AxisAlignedBoundingBox(boundaryExtremes)} {
	// Initialize VAO and configure vertex attributes
	glGenVertexArrays(1, &vao);
	glBindVertexArray(vao);
	glBindBuffer(GL_ARRAY_BUFFER, vBO);
	glVertexAttribPointer(0, 3, GL_FLOAT, false, 0, 0);
	glEnableVertexAttribArray(0);
	glBindBuffer(GL_ARRAY_BUFFER, nBO);
	glVertexAttribPointer(1, 3, GL_FLOAT, false, 0, 0);
	glEnableVertexAttribArray(1);
}

// Bind vertex array and element buffer for rendering
void VertexBuffer::bindBuffers() const {
	glBindVertexArray(vao);
	glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, iBO);
}

#include <iostream>
#include <bitset>
#include <vector>
using namespace std;

int main() {
    vector<int> numbers = {1, 2, 3, 5, 8, 13, 21};
    unsigned long result = 0UL;
    for(auto index : numbers) {
        result |= 1UL << index;
    }
    cout << result << endl;
    bitset<32> bits(result);
    cout << bits << endl;

    bitset<32> otherBits;
    for(auto index : numbers) {
        otherBits.set(index);
    }
    cout << otherBits << endl;
    if(bits == otherBits) {
        cout << "bits == otherBits" << endl;
    }
}

