namespace RosettaStone
{
Enchant Enchants::ParseEnchantFromString(const std::string& cardIdentifier)
{
    std::vector<Effect> effectList;
    static std::regex powerToughnessPattern("\\+([[:digit:]]+)/\\+([[:digit:]]+)");
    static std::regex powerPattern("\\+([[:digit:]]+) Attack");

    const std::string description = Cards::RetrieveCardById(cardIdentifier).description;
    std::smatch matchResults;

    if (std::regex_search(description, matchResults, powerToughnessPattern))
    {
        effectList.push_back(Effects::PowerN(std::stoi(matchResults[1].str())));
        effectList.push_back(Effects::ToughnessN(std::stoi(matchResults[2].str())));
    }
    else if (std::regex_search(description, matchResults, powerPattern))
    {
        effectList.push_back(Effects::PowerN(std::stoi(matchResults[1].str())));
    }

    return Enchant(effectList);
}
}  // namespace RosettaStone

