static void BM_Farmhash(benchmark::State& state) {
  // Create a string of dots with size determined by the argument
  auto data = std::string(state.range(0), '.');

  // Run the benchmark loop
  for (auto _ : state) {
    util::Hash64(data);
  }

  // Update metrics: bytes processed = iterations * input size
  state.SetBytesProcessed(int64_t(state.iterations()) * int64_t(state.range(0)));
