void prefix::operator()(contents& buffer, boost::optional<int> opt) {
    show_message(message + "-");
    char input_char = getch();
    auto iter = actions.find(input_char);

    if(iter == actions.end()) {
        show_message(std::string("Unknown key sequence: '")
