      const auto head_transform {tf2::transformToEigen(transform_buffer.lookupTransform("openni_depth_frame", "head_1", ros::Time {0}))};
      const auto torso_transform {tf2::transformToEigen(transform_buffer.lookupTransform("openni_depth_frame", "torso_1", ros::Time {0}))};

      const Eigen::Vector3d direction_vector {head_transform.translation() - torso_transform.translation()};
      const Eigen::Quaterniond rotation_quaternion {Eigen::Quaterniond::FromTwoVectors(Eigen::Vector3d::UnitX(), direction_vector)};

      visual_markers.deleteAllMarkers();
      Eigen::Affine3d arrow_pose {rotation_quaternion};
      visual_markers.publishArrow(arrow_pose);
      visual_markers.trigger();
    } catch (tf2::TransformException &error) {
      ROS_WARN("%s", error.what());
    }

    loop_rate.sleep();
  }
}

