	Room<T>::~Room()
	{
		Clear();
	}
	template <typename T>
	Room<T>::Room(Room&& other)
	{
		contents = other.contents;
		other.contents.clear();
	}
	template<typename T>
	void Room<T>::Insert(T* element)
	{
		contents.push_back(element);
	}
	template <typename T>
	void Room<T>::Clear()
	{
		for (T* obj : contents)
		{
			obj->Release();
			delete obj;
		}
		contents.clear();
	}
