// Map to store word frequency counts
using word_freq_map = std::map<std::string, int>;

int main() {
    word_freq_map freq_table;
    std::string current_word;

    // Read words and count occurrences
    while (std::cin >> current_word) {
        freq_table[current_word]++;
    }

    // Convert map to vector of pairs for sorting
    std::vector<std::pair<std::string, int>> word_list(freq_table.begin(), freq_table.end());

    // Sort to get top 10 words by frequency (descending)
    std::partial_sort(word_list.begin(), word_list.begin() + 10, word_list.end(),
            [](const auto& a, const auto& b) { 
                return a.second > b.second; 
            });

    // Output top 10 words with their counts
    for (const auto& entry : take(word_list, 10)) {
        std::cout << entry.second << ": " << entry.first << '\n';
    }

    return 0;
}

#include "threadpool.h"

// Constructor: initializes the thread pool with a specified number of threads
ThreadPool::ThreadPool(size_t num_threads)
{
    for (size_t index = 0; index < num_threads; ++index) {
        workers.emplace_back([this] {
            for (;;) {
                std::unique_lock<std::mutex> guard(this->queue_mutex);
                while (!this->m_shutdown && this->pending_tasks.empty())
                    this->task_condition.wait(guard);
                if (this->m_shutdown && this->pending_tasks.empty())
                    return;
                std::function<void()> job(this->pending_tasks.front());
                this->pending_tasks.pop();
                guard.unlock();
                job();
            }
        });
    }
}

// Destructor: stops all threads and joins them
ThreadPool::~ThreadPool()
{
    {
        std::unique_lock<std::mutex> guard(queue_mutex);
        m_shutdown = true;
    }
    task_condition.notify_all();
    for (size_t k = 0; k < workers.size(); ++k)
        workers[k].join();
}

