// Process incoming data queue with provided handler function
void handleIncomingData(ByteQueue* inputBuffer, bool (*handler)(uint8_t*)) {
    uint8_t bufferCopy[queue_length(inputBuffer)];
    queue_snapshot(inputBuffer, bufferCopy);

    if(handler == NULL) {
        debug("Handler function is NULL (%p) -- cannot process queue at %p\r\n",
                handler, inputBuffer);
        return;
    }

    if(handler(bufferCopy)) {
        queue_init(inputBuffer);
    } else if(queue_full(inputBuffer)) {
        debug("Data packet exceeds buffer capacity\r\n");
        queue_init(inputBuffer);
    } else if(strnchr((char*)bufferCopy, queue_length(inputBuffer) - 1, '\0') != NULL) {
        debug("Received buffered data is invalid (%s) -- flushing buffer\r\n",
                bufferCopy);
        queue_init(inputBuffer);
    }
}

