// Define peer nodes for the Raft cluster
std::vector<raft_node_endpoint_t> cluster_peers{
        {1ul, "localhost", 12345, 13001},
        {2ul, "localhost", 12346, 13002},
        {3ul, "localhost", 12347, 13003}
};

int main(int argc, char* argv[]) {
    try {
        // Launch raft node instances in separate threads
        std::vector<std::thread> worker_threads;
        for (auto &peer : cluster_peers) {
            worker_threads.emplace_back([&peer]() {
                auto node_instance = raft_node(peer.uuid, std::make_shared<raft::config>(cluster_peers));
                node_instance.run();
            });
        }

        // Synchronize all worker threads before exiting
        std::for_each(worker_threads.begin(), worker_threads.end(), [](std::thread &worker){
            worker.join();
        });
    }
    catch(std::exception& ex) {
        std::cerr << "Exception occurred" << std::endl;
        std::cerr << ex.what() << std::endl;
    }

    return 0;
}

