// Macro to define singleton-like accessor functions with lazy initialization
#define CREATE_ACCESSOR(Name, Type, Args)         \
  namespace {                                     \
    vw::RunOnce Name ## _init_flag = VW_RUNONCE_INIT; \
    Type* Name ## _instance_ptr = nullptr;        \
    void construct_ ## Name() {                   \
      Name ## _instance_ptr = new Type Args;      \
    }                                             \
  }                                               \
  Type& vw::vw_ ## Name() {                       \
    Name ## _init_flag.run(construct_ ## Name);   \
    return *Name ## _instance_ptr;                \
  }

CREATE_ACCESSOR(     settings, vw::Settings,     ());
