template <typename CharT, typename Alloc>
void test_move_construct(Alloc const& alloc)
{
    using MatchResult = std::match_results<const CharT*, Alloc>;
    static_assert(std::is_nothrow_move_constructible<MatchResult>::value, "");

    MatchResult result1(alloc);
    MatchResult result2(std::move(result1));

    assert(result2.size() == 0);
    assert(result2.str() == std::basic_string<CharT>());
    assert(result2.get_allocator() == alloc);
}

int main()
{
    test_move_construct<char>(std::allocator<std::sub_match<const char*>>());
    test_move_construct<wchar_t>(std::allocator<std::sub_match<const wchar_t*>>());
    test_move_construct<char>(test_allocator<std::sub_match<const char*> >(5));
    test_move_construct<wchar_t>(test_allocator<std::sub_match<const wchar_t*> >(5));
}

