LCD5110 display;

void LCD_setup(void)
{
  /* Configure MOSI and SCK as output pins */
  DDRB |= (1<<PB3)|(1<<PB5);

  /* Enable SPI in master mode with CPOL=1, CPHA=1 */
  /* Data order: MSB first; Clock speed: fosc/4 */
  SPCR = (1<<SPE)|(1<<MSTR)|(1<<CPOL)|(1<<CPHA) | (1<<SPR0);

  /* Set DC, RST, and CS pins as outputs */
  DDRB |= (1<<PB0) | (1<<PB2);
  DDRC |= (1<<PC0);

  display.InitLCD(0x46);
}

