#include <bits/stdc++.h>
using namespace std;

// Adjacency list representation for graph
vector<int> adjList[MAX];
// Track visited nodes - must be initialized to false before use
bool isVisited[MAX];

// Breadth-First Search implementation starting from a given node
void performBFS(int startNode) {
    queue<int> nodeQueue;
    nodeQueue.push(startNode);

    while (!nodeQueue.empty()) {
        int currentNode = nodeQueue.front();
        isVisited[currentNode] = true;
        nodeQueue.pop();

        // Visit all neighbors of the current node
        for (int j = 0; j < adjList[currentNode].size(); j++) {
            int neighbor = adjList[currentNode][j];
            if (!isVisited[neighbor]) {
                nodeQueue.push(neighbor);
            }
        }
    }
}

