// Constructor for GpsdConnection class
GpsdConnection::GpsdConnection( QObject* parent )
    : QObject( parent ),
      m_timer( 0 )
{
    gps_data_t* info = m_gpsd.open();
    if ( info ) {
#if GPSD_API_MAJOR_VERSION == 3
        m_gpsd.stream( WATCH_ENABLE );
#endif
        connect( &m_timer, SIGNAL( timeout() ), this, SLOT( update() ) );
        m_timer.start( 1000 );
    } else
        mDebug() << "Failed to connect to gpsd, position data unavailable.";
}

// Update method to fetch and emit GPS data
void GpsdConnection::update()
{
    gps_data_t* result;
#if GPSD_API_MAJOR_VERSION == 2
    result = m_gpsd.query( "o" );
#elif GPSD_API_MAJOR_VERSION == 3
    while ((result = m_gpsd.poll()) && !(result->set & POLICY_SET)) {
        result = m_gpsd.poll();
    }
#endif
    if ( result )
        emit gpsdInfo( *result );
}

