#include <map>
#include <common/buffer.h>
#include <common/endian.h>
#include <ssh/ssh_algorithm_negotiation.h>
#include <ssh/ssh_protocol.h>

namespace {
    static uint8_t fixed_cookie[16] = {
        0x00, 0x10, 0x20, 0x30,
        0x40, 0x50, 0x60, 0x70,
        0x80, 0x90, 0xa0, 0xb0,
        0xc0, 0xd0, 0xe0, 0xf0
    };

    template<typename Container>
    Buffer format_name_list(const Container& names_container)
    {
        typename Container::const_iterator iter;
        std::vector<Buffer> name_buffers;
        Buffer combined;
        uint32_t size;
        Buffer result;

        for (iter = names_container.begin(); iter != names_container.end(); ++iter)
            name_buffers.push_back(iter->first);

        combined = Buffer::join(name_buffers, ",");
        size = combined.length();
        size = BigEndian::encode(size);
        result.append(&size);
        result.append(combined);
        return (result);
    }
}

bool
SSHAlgorithmNegotiation::input(Buffer *data)
{
    switch (data->peek()) {
    case SSH::Message::KeyExchangeInitializationMessage:
        DEBUG(log_) << "Ignoring initialization message.";
        return (true);
    default:
        DEBUG(log_) << "Unsupported algorithm negotiation message:" << std::endl << data->hexdump();
        return (false);
    }
}

bool
SSHAlgorithmNegotiation::output(Buffer *buffer)
{
    ASSERT(buffer->empty());
    buffer->append(SSH::Message::KeyExchangeInitializationMessage);
    buffer->append(fixed_cookie, sizeof fixed_cookie); /* XXX Synchronous random byte generation?  */
    buffer->append(format_name_list(key_exchange_map_));
    buffer->append(format_name_list(server_host_key_map_));
    buffer->append(format_name_list(encryption_client_to_server_map_));
    buffer->append(format_name_list(encryption_server_to_client_map_));
    buffer->append(format_name_list(mac_client_to_server_map_));
    buffer->append(format_name_list(mac_server_to_client_map_));
    buffer->append(format_name_list(compression_client_to_server_map_));
    buffer->append(format_name_list(compression_server_to_client_map_));
    buffer->append(format_name_list(language_client_to_server_map_));
    buffer->append(format_name_list(language_server_to_client_map_));
    buffer->append(SSH::Boolean::False);
    uint32_t padding(0);
    buffer->append(&padding);
    return (true);
}

