#include <ctx.hpp>
#include <cl.hpp>
#include <vector>

namespace opencl
{
using std::vector;
using cl::Platform;
using cl::Device;

void contextCallback(const char *errorInfo, const void *privateData, size_t size, void *userData)
{
    printf("OpenCL Context Error: %s\n", errorInfo);
    fflush(stdout);
}

const cl::Context&
getContext(unsigned char index)
{
    static std::vector<cl::Platform> availablePlatforms(0);
    static std::vector<cl::Context> openclContexts(0);

    if(openclContexts.empty()) {
        Platform::get(&availablePlatforms);
        for(auto platform : availablePlatforms) {
            vector<cl_context_properties> properties = {CL_CONTEXT_PLATFORM, (cl_context_properties)platform(), 0};
            openclContexts.emplace_back(CL_DEVICE_TYPE_DEFAULT, &properties.front(), contextCallback);
        }
    }
    return openclContexts[index];
}

cl::CommandQueue&
getCommandQueue(unsigned char index) 
{
    static std::vector<cl::CommandQueue> commandQueues;
    if(commandQueues.empty()) {
        commandQueues.emplace_back(getContext(0));
    }
    return commandQueues[index];
}
}

