#include <type_traits>
#include <cstdint>

// Template function to verify alignment properties for type T and expected alignment A
template <typename Type, unsigned ExpectedAlign>
void check_type_alignment()
{
    static_assert(std::alignment_of<Type>::value == ExpectedAlign, "");
    static_assert(std::alignment_of<const Type>::value == ExpectedAlign, "");
    static_assert(std::alignment_of<volatile Type>::value == ExpectedAlign, "");
    static_assert(std::alignment_of<const volatile Type>::value == ExpectedAlign, "");
}

// Custom class with destructor declared but not defined
class UserDefinedClass
{
public:
    ~UserDefinedClass();
};

int main()
{
    // Test various types for their alignment requirements
    check_type_alignment<int&, 4>();
    check_type_alignment<UserDefinedClass, 1>();
    check_type_alignment<int*, sizeof(std::intptr_t)>();
    check_type_alignment<const int*, sizeof(std::intptr_t)>();
    check_type_alignment<char[3], 1>();
    check_type_alignment<int, 4>();
    check_type_alignment<double, 8>();

#if (defined(__ppc__) && !defined(__ppc64__))
    check_type_alignment<bool, 4>();  // 32-bit PowerPC uses 4-byte bool
#else
    check_type_alignment<bool, 1>();
#endif

    check_type_alignment<unsigned, 4>();

    return 0;
}

