class TestInputConversion : public QObject
{
	Q_OBJECT
private slots:
	void testSpecialKeyHandling();
private:
	NeovimQt::InputConv conv;
};

void TestInputConversion::testSpecialKeyHandling()
{
	foreach(int key, conv.specialKeys.keys()) {
		QCOMPARE(conv.convertKey("", key, Qt::NoModifier),
			QString("<%1>").arg(conv.specialKeys.value(key)));
		QCOMPARE(conv.convertKey("", key, Qt::ControlModifier),
#ifdef Q_OS_MAC
			// On macOS, Control maps to the Cmd key, which is not yet supported
			QString("<D-%1>").arg(conv.specialKeys.value(key)));
#else
			QString("<C-%1>").arg(conv.specialKeys.value(key)));
#endif
		QCOMPARE(conv.convertKey("", key, Qt::AltModifier),
			QString("<A-%1>").arg(conv.specialKeys.value(key)));
		QCOMPARE(conv.convertKey("", key, Qt::MetaModifier),
#ifdef Q_OS_MAC
			// On macOS, Meta corresponds to the Control key
			QString("<C-%1>").arg(conv.specialKeys.value(key)));
#else
			// Meta key support is currently not implemented
			QString("<%1>").arg(conv.specialKeys.value(key)));
#endif
	}
}

QTEST_MAIN(TestInputConversion)
