Herbs::String Doxymax::Item::expand(const Macro& macro, CommentProcessor& processor)
{
    if (macro.args.length() < 1) {
        throw Herbs::ExceptionMissing(___FILE__, __LINE__);
    }

    Herbs::String result(64);

    result.append(STR("<li class=\"itemdoxmax\""));
    if (processor.macroExpansionDepth() == 1) {
        result.append(STR(" style=\"position:relative\""));
    }
    result.append(STR("><div class=\"itemhead\">")).append(macro.args[0])
        .append(STR("</div>"));

    if (macro.args.length() > 2) {
        result.append(STR("<div class=\"itemcomment\">"))
            .append(macro.args[2])
            .append(STR("</div>"));
    }

    if (macro.args.length() > 1) {
        result.append(macro.args[1]);
    }

    result.append(STR("</li>"));
    return std::move(result);
}

