// Safely add two integers with overflow checking
int safe_add(int x, int y)
{
    if (((y > 0) && (x > (numeric_limits<int>::max() - y))) ||
        ((y < 0) && (x < (numeric_limits<int>::min() - y))))
            error("safe_add(): integer addition overflows.");
    else
        return x + y;
}

// Generate Fibonacci-like sequence starting with x and y
void generate_sequence(int first, int second, vector<int>& result, int count)
// Precondition: result must be empty and count >= 2
{
    if (result.size() != 0)
        error("generate_sequence(): Non-empty vector provided.");
    if (count < 2)
        error("generate_sequence(): count must be at least 2.");

    result.push_back(first);
    result.push_back(second);

    for (int index = 2; index < count; ++index)
        result.push_back(safe_add(result[index-2], result[index-1]));
}

