// Class for decoding Caesar cipher encoded text
class CaesarDecoder {
public:
  // Decodes the given cipher text by shifting letters backward by offset positions
  std::string decode(std::string encodedText, int offset) {
    std::string decoded;
    for (int i = 0; i < encodedText.length(); ++i) {
      char ch = encodedText[i];
      decoded += 'A' + (ch - 'A' - offset + 26) % 26;
    }
    return decoded;
  }
};

int main() {
  CaesarDecoder cd;
  assert(cd.decode("ABCDEFGHIJKLMNOPQRSTUVWXYZ", 10) == "QRSTUVWXYZABCDEFGHIJKLMNOP");
  return 0;
}

