    QTest::addColumn<GeoDataCoordinates>("expectedCoords");

    addRow() << QPoint(5, 15) << GeoDataCoordinates(-45, 76.135, 0, GeoDataCoordinates::Degree);
    addRow() << QPoint(15, 5) << GeoDataCoordinates(135, 76.135, 0, GeoDataCoordinates::Degree);
}

void StereographicProjectionTest::testCenterScreenCoordinates()
{
    QFETCH(QPoint, screenPoint);
    QFETCH(GeoDataCoordinates, expectedCoords);

    ViewportParams viewport;
    viewport.setProjection(Stereographic);
    viewport.setRadius(180 / 4); // for easy mapping of lon <-> x
    viewport.setSize(QSize(20, 20));
    viewport.centerOn(0 * DEG2RAD, 90 * DEG2RAD);

    {
        qreal longitude, latitude;
        const bool success = viewport.geoCoordinates(screenPoint.x(), screenPoint.y(), longitude, latitude, GeoDataCoordinates::Degree);
        QVERIFY(success); // we want valid coordinates

        QCOMPARE(longitude, expectedCoords.longitude(GeoDataCoordinates::Degree));
        QFUZZYCOMPARE(latitude, expectedCoords.latitude(GeoDataCoordinates::Degree), 0.0001);
    }
}
}

