// Convert error code to human-readable string (POSIX/Windows)
std::string get_error_message(int error_code)
{
    char temp_buffer[2048];
#ifdef _WIN32
    if (strerror_s(temp_buffer, sizeof(temp_buffer), error_code) != 0) 
        throw std::runtime_error("Failed to retrieve error description");
    return temp_buffer;
#else
    strerror_r(error_code, temp_buffer, sizeof(temp_buffer));
    return temp_buffer;
#endif
}

