// Retrieve Windows system error message and convert to UTF-8
std::string get_windows_error_description(int win_error_code)
{
    std::unique_ptr<wchar_t[], LocalFreeDeleter> message_buffer;
    FormatMessageW(
        FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
        nullptr, win_error_code, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
        (LPWSTR)(wchar_t**)unique_out_ptr(message_buffer), 0, nullptr);
    return utf16_to_utf8(message_buffer.get());
