#include "SimpleString.h"
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

// Default constructor: initializes an empty string
SimpleString::SimpleString()
    : buffer(new char[1])
{
    buffer[0] = '\0';
}

// Constructor from C-string
SimpleString::SimpleString(const char* inputBuffer)
    : buffer(new char[strlen(inputBuffer) + 1])
{
    strcpy(buffer, inputBuffer);
}

// Copy constructor
SimpleString::SimpleString(const SimpleString& source)
{
    buffer = new char[source.size() + 1];
    strcpy(buffer, source.buffer);
}

// Assignment operator
SimpleString& SimpleString::operator=(const SimpleString& source)
{
    delete[] buffer;
    buffer = new char[source.size() + 1];
    strcpy(buffer, source.buffer);
    return *this;
}

// Return internal C-string representation
char* SimpleString::asCharString() const
{
    return buffer;
}

// Return length of the stored string
int SimpleString::size() const
{
    return strlen(buffer);
}

// Destructor: releases allocated memory
SimpleString::~SimpleString()
{
    delete[] buffer;
}

// Equality comparison operator (non-member)
bool operator==(const SimpleString& lhs, const SimpleString& rhs)
{
    return !strcmp(lhs.asCharString(), rhs.asCharString());
}

