#include <opencv2/opencv.hpp>
#include <opencv/highgui.h>
#include <unistd.h>

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cout << "Usage: program <output_directory>\n";
        return -1;
    }

    cv::VideoCapture capture(CV_CAP_OPENNI);
    std::cout << "Started streaming data to main system..\n";

    int count = 0;
    cv::namedWindow("DEPTH");

    while (true) {
        cv::Mat depthImage, colorImage;
        usleep(500000);

        capture.grab();
        capture.retrieve(depthImage, CV_CAP_OPENNI_DEPTH_MAP);
        cv::imshow("DEPTH", depthImage);
        cv::waitKey(1);

        capture.retrieve(colorImage, CV_CAP_OPENNI_BGR_IMAGE);
        cv::imshow("RGB", colorImage);
        cv::waitKey(1);

        std::string path = std::string(argv[1]) + "/";
        std::string tempRgb = path + "rgb1.png";
        std::string tempDepth = path + "depth1.png";

        imwrite(tempRgb, colorImage);
        imwrite(tempDepth, depthImage);

        std::string command = "mv " + tempRgb + " " + path + "rgb.png ; mv " + tempDepth + " " + path + "depth.png";
        system(command.c_str());

        std::cout << ++count << "\n";
    }

    return 0;
}

