#include "cmbf.h"
#include <unordered_map>
using namespace sketch::cmbf;

int main(int argc, char *argv[]) {
    cmbf_exp_t estimator(4, 16, 1);
    cmbf_t exact_estimator(4, 16, 5);

    auto [stack_usage, heap_usage] = estimator.est_memory_usage();
    std::fprintf(stderr, "stack space: %zu\theap space:%zu\n", stack_usage, heap_usage);

    size_t num_items = argc > 1 ? std::strtoull(argv[1], nullptr, 10) : 100000;
    std::vector<uint64_t> data_items;
    std::mt19937_64 rng_engine;

    while(data_items.size() < num_items) {
        data_items.emplace_back(rng_engine());
    }

    // Verify initial state is zero
    for(const auto element : estimator.ref()) {
        assert(unsigned(element) == 0);
    }

    auto &estimator_ref = estimator.ref();
    for(const auto item : data_items) {
        estimator.add_conservative(item);
        exact_estimator.add_conservative(item);
    }

    std::unordered_map<uint64_t, uint64_t> exact_histogram, approx_histogram;
    for(const auto value : data_items) {
        ++approx_histogram[estimator.est_count(value)];
        ++exact_histogram[exact_estimator.est_count(value)];
    }

    for(const auto &entry : exact_histogram) {
        std::fprintf(stderr, "Exact %" PRIu64 "\t%" PRIu64 "\n", entry.first, entry.second);
    }

    for(const auto &entry : approx_histogram) {
        std::fprintf(stderr, "Approx %" PRIu64 "\t%" PRIu64 "\n", entry.first, entry.second);
    }

    return 0;
}

