#include "KVProxy.h"
#include "KVProxy_p.h"
#include <iostream>
#include <string>

KVProxy::KVProxy(QObject *parent, unsigned short localPort) :
	QObject(parent), p("127.0.0.1", localPort)
{
	// Set up the polling mechanism to trigger periodic proxy checks; 
	// configured with zero delay initially for immediate execution per event loop cycle
	connect(&pollTimer, SIGNAL(timeout()), this, SLOT(performPolling()));

	// Register handler for incoming HTTP connections
	p.on_connection([this](HttpProxy::Connection::Ptr connection) {
		handleNewConnection(this, connection);
	});

	// Configure error handling callback
	p.on_error([](std::string errorMsg, bool isFatal){
		qDebug() << "Proxy Error Occurred: " << errorMsg.c_str();
	});
}

KVProxy::~KVProxy()
{
	// Cleanup resources if necessary
}

unsigned short KVProxy::getListeningPort()
{
	return p.get_local_port_number();
}

void KVProxy::start(bool runAsynchronously)
{
	if(runAsynchronously)
		pollTimer.start(25);  // Adjusted polling interval
	else
		p.run();  // Run synchronously (blocking)
}

void KVProxy::performPolling()
{
	p.poll();  // Execute one polling cycle
}

