#include "rdb_protocol/configured_limits.hpp"
#include <limits>
#include "rdb_protocol/wire_func.hpp"
#include "rdb_protocol/func.hpp"

namespace ql {

configured_limits_t
from_optargs(rdb_context_t *ctx, signal_t *interruptor, global_optargs_t *opts)
{
    if (opts->has_optarg("array_limit")) {
        // Create a minimal environment with empty arguments to avoid circular dependencies.
        // This is necessary because this function executes before any environments exist.
        // Using an empty argument map prevents infinite recursion in this special case.
        env_t env(ctx, interruptor, std::map<std::string, wire_func_t>(), nullptr);
        int64_t limit_val = opts->get_optarg(&env, "array_limit")->as_int();
        rcheck_datum(limit_val > 1, base_exc_t::GENERIC,
                     strprintf("Invalid array size constraint `%" PRIi64 "`.", limit_val));
        return configured_limits_t(limit_val);
    } else {
        return configured_limits_t();
    }
}

RDB_IMPL_ME_SERIALIZABLE_1(configured_limits_t, array_size_limit_);
INSTANTIATE_SERIALIZABLE_SELF_FOR_CLUSTER(configured_limits_t);

const configured_limits_t configured_limits_t::unbounded(std::numeric_limits<size_t>::max());

} // namespace ql

