class identity final : public tm_abstract_problem {
  public:
    const char *name() const override {
        return "Null";
    }
    void setup() override {
        // No operations needed - tape content remains unchanged
    }
    void register_tests() override {
        ADD_UNIT_TEST(">#01#", ">#01#");
        ADD_UNIT_TEST(">", ">");
        ADD_UNIT_TEST(">9$1#", ">9$1#");
    }
};

class placeholder final : public tm_abstract_problem {
  public:
    const char *name() const override {
        return "Placeholder";
    }
    void setup() override {
        // Final state is implicitly the last defined state
        ADD_TRANSITION(0, '#', 1, '0', GO_RIGHT);
    }
    void register_tests() override {
        ADD_UNIT_TEST(">#01#", ">001#");
    }
};

int main() {
