    void *heap_object = malloc(16);
    std::thread worker1([heap_object] {
      PerformExternalWrite(heap_object);
      barrier_wait(&barrier);
    });
    std::thread worker2([heap_object] {
      barrier_wait(&barrier);
      PerformExternalWrite(heap_object);
    });
    // CHECK: WARNING: ThreadSanitizer: race on a library object
    worker1.join();
    worker2.join();
  }

  fprintf(stderr, "First phase done.\n");
  // CHECK: First phase done.
  for (int cycle = 0; cycle < 4; cycle++) {
    void *heap_object = malloc(16);
    std::thread worker1([heap_object] {
