#include "AbsPositionOverview.h"

// Constructor for AbsPositionOverview
AbsPositionOverview::AbsPositionOverview(QObject *parent) :
    QObject(parent)
{
}

// Process GPS raw integer data when available
void AbsPositionOverview::parseGpsRawInt(LinkInterface *link, const mavlink_message_t &msg, const mavlink_gps_raw_int_t &data)
{
    // Only update position if fix type indicates a valid 3D fix or better
    if (data.fix_type > 2)
    {
        this->setLat(data.lat);
        this->setLon(data.lon);
        this->setAlt(data.alt);
        this->setVel(data.vel);
    }
}

// Handle global position integer messages
void AbsPositionOverview::parseGlobalPositionInt(LinkInterface *link, const mavlink_message_t &msg, const mavlink_global_position_int_t &data)
{
    // Convert millimeters to meters for relative altitude
    this->setRelativeAlt(data.relative_alt / 1000.0);
}

// Main message handler - routes incoming messages to appropriate parsers
void AbsPositionOverview::messageReceived(LinkInterface* link, mavlink_message_t msg)
{
    switch (msg.msgid)
    {
        case MAVLINK_MSG_ID_GPS_RAW_INT:
        {
            mavlink_gps_raw_int_t data;
            mavlink_msg_gps_raw_int_decode(&msg, &data);
            parseGpsRawInt(link, msg, data);
            break;
        }
        case MAVLINK_MSG_ID_GLOBAL_POSITION_INT:
        {
            mavlink_global_position_int_t data;
            mavlink_msg_global_position_int_decode(&msg, &data);
            parseGlobalPositionInt(link, msg, data);
            break;
        }
    }
}

