#include "binarytree.h"
#include <iostream>
using namespace std;

// Recursive helper to print tree in DOT format with node IDs
template <class T>
void visualizeTreeDOT(ostream& out, typename BinaryTree<T>::Inspector inspector, size_t nodeId)
{
	if (inspector.isEmpty())
	{
		out << nodeId << "[label=\"NULL\" shape=point];" << endl;
		return;
	}
	out << nodeId << "[label=\"" << inspector.getData() << "\"];" << endl;
	out << nodeId << " -> " << 2*nodeId + 1 << ";" << endl;
	visualizeTreeDOT<T>(out, inspector.left(), 2*nodeId + 1);
	out << nodeId << " -> " << 2*nodeId + 2 << ";" << endl;
	visualizeTreeDOT<T>(out, inspector.right(), 2*nodeId + 2);
}

// Main DOT output function for a binary tree
template <class T>
void visualizeTreeDOT(ostream& out, const BinaryTree<T>& tree)
{
	out << "digraph G\n{\n";
	visualizeTreeDOT<T>(out, tree.getInspector(), 0);
	out << "}\n";
}

int main()
{
	BinaryTree<int> tree;
	BinaryTree<int>::Transformer transformer = tree.getTransformer();
	transformer.addData(7);
	transformer.goLeft();
	transformer.addData(4);
	transformer.goToParent();
	transformer.goRight();
	transformer.addData(9);
	visualizeTreeDOT(cout, tree);
	return 0;
}

