#include <pthread.h>
#include <unistd.h>

pthread_rwlock_t global_rwlock;
int shared_global_var;

void *WorkerThread(void *arg) {
  (void)arg;
  pthread_rwlock_rdlock(&global_rwlock);
  // Incorrectly modifying data while holding a read lock
  usleep(100);
  shared_global_var++;
  pthread_rwlock_unlock(&global_rwlock);
  return 0;
}

int main(int argc, char *argv[]) {
  pthread_rwlock_init(&global_rwlock, NULL);

  pthread_rwlock_rdlock(&global_rwlock);

  pthread_t worker;
  pthread_create(&worker, 0, WorkerThread, 0);

  volatile int temp = shared_global_var;
  (void)temp;

  pthread_rwlock_unlock(&global_rwlock);
  pthread_join(worker, 0);
  pthread_rwlock_destroy(&global_rwlock);

  return 0;
}
