// Create a Status instance from a printf-style format and variable arguments
Status ToStatusF(Code error_code, const char* message_format, ...) {
  va_list args;
  va_start(args, message_format);
  char* buffer;
  if (vasprintf(&buffer, message_format, args) < 0) {
    abort();
  }
  va_end(args);

  Status result(error_code, buffer);
  free(buffer);
