#include <iostream>
#include <stack>
using std::cout;
using std::endl;
using std::stack;

class MyQueue {
    stack<int> inputStack, outputStack;

    void moveElements() {
        while (!inputStack.empty()) {
            outputStack.push(inputStack.top());
            inputStack.pop();
        }
    }

public:
    bool isEmpty() {
        return inputStack.empty() && outputStack.empty();
    }

    int peek() {
        if (outputStack.empty()) {
            moveElements();
        }
        return outputStack.top();
    }

    void remove() {
        if (outputStack.empty()) {
            moveElements();
        }
        outputStack.pop();
    }

    void add(int value) {
        inputStack.push(value);
    }
};

int main() {
    MyQueue queue;
    queue.add(1);
    queue.add(2);
    cout << queue.peek() << endl;
    queue.remove();
    queue.add(3);
    cout << queue.peek() << endl;
    queue.remove();
    queue.add(4);
    queue.add(5);
    queue.add(6);
    cout << queue.peek() << endl;
    queue.remove();
    cout << queue.peek() << endl;
    queue.remove();
    cout << queue.peek() << endl;
    queue.remove();
    cout << queue.peek() << endl;
    queue.remove();

    return 0;
}

