{
    Q_ASSERT( parser.isStartElement() && parser.isValidElement( kmlTag_Region ) );
    GeoDataRegion newRegion;
    GeoStackItem currentItem = parser.parentElement();
#ifdef DEBUG_TAGS
    mDebug() << "Parsed <" << kmlTag_Region << ">"
             << " parent element name: " << currentItem.qualifiedName().first;
