PatternPostureGenerator::PatternPostureGenerator(ros::NodeHandle& nh) {
  if (!nh.getParam("pattern", pattern_names)) return;
  ROS_INFO("Get map of patterns parent");
  for (std::map<std::string, std::string>::iterator iter = pattern_names.begin();
       iter != pattern_names.end();
       ++iter) {
    std::vector<double> posture_data;
    if (!nh.getParam(std::string("pattern/").append(iter->second), posture_data)) return;
    std::copy(posture_data.begin(), posture_data.end(), std::back_inserter(posture_datas[iter->second]));
