#include <xpcc/architecture.hpp>
#include "../stm32f4_discovery.hpp"

// ----------------------------------------------------------------------------
/**
 * Minimal USART example: continuously transmit ASCII letters A-Z in a loop.
 * Output is sent via USART2 at 9600 baud, 8N1 configuration on PA3 (TX).
 */
MAIN_FUNCTION
{
    // Initialize system clock and LEDs
    defaultSystemClock::enable();

    LedOrange::setOutput(xpcc::Gpio::Low);
    LedGreen::setOutput(xpcc::Gpio::High);
    LedRed::setOutput(xpcc::Gpio::Low);
    LedBlue::setOutput(xpcc::Gpio::Low);

    // Configure USART2 pins: TX on PA2, RX on PA3 with pull-up
    GpioOutputA2::connect(Usart2::Tx);
    GpioInputA3::connect(Usart2::Rx, Gpio::InputType::PullUp);

    // Initialize USART2 with given clock and baud rate
    Usart2::initialize<defaultSystemClock, 9600>(12);

    // Main transmission loop
    while (true)
    {
        static char letter = 'A';

        // Toggle status LEDs to indicate activity
        LedRed::toggle();
        LedGreen::toggle();

        // Send current character
        Usart2::write(letter);

        // Advance to next letter, wrap around after 'Z'
        ++letter;
        if (letter > 'Z') {
            letter = 'A';
        }

        // Delay before next transmission
        xpcc::delay_ms(500);
    }

    return 0;
}

