#include "ihex.h"
#include <stdlib.h>

int main(int argc, char* argv[])
{
	if (argc != 5)
	{
		std::cerr << argv[0] << " source.hex secret output.hex\n"
			"Encrypts or decrypts the data in an Intel Hex file.\n"
			"Memory addresses remain unchanged, but checksum is recalculated.\n\n"
			"The [secret] is a raw binary file containing key material. The entire file\n"
			"is utilized as key data, and may be of any length.\n"
			;
		exit(-1);
	}
	IntelHex hexfile;
	hexfile.Read(argv[1]);
	std::ifstream secretfile;
	secretfile.open(argv[2], std::ios::in | std::ios::binary | std::ios::ate);
	if(!secretfile.is_open()) {
		std::cerr << "Failed to open key file.\n";
		exit(-3);
	}
	secretfile.seekg(0, std::ios::end);
	int length = secretfile.tellg();
	secretfile.seekg(0, std::ios::beg);
	uint8_t keydata[length];
	secretfile.read((char*)keydata, length);
	hexfile.Cipher(keydata, length);
	hexfile.Write(argv[4]);
}

