namespace odb {
    void internalLog(const char *fmt, va_list ap) {
        char msg[512];
        return;
        memset(msg, 0, sizeof(msg));
        std::vsnprintf(msg, sizeof(msg), fmt, ap);
#ifdef __ANDROID__
        __android_log_print(ANDROID_LOG_DEBUG, "ODB::Log", "%s", msg);
#else
        std::fprintf(stderr, "%s\n", msg);
#endif
    }

    void Logger::write(const char *fmt, ...) {
        va_list args;
        va_start(args, fmt);
        internalLog(fmt, args);
        va_end(args);
    }

    void Logger::write(std::string fmt, ...) {
        va_list args;
        va_start(args, fmt);
        const char *rawFmt = fmt.c_str();
        internalLog(rawFmt, args);
        va_end(args);
    }
}

