template <typename U>
string debug_rep(const U &value) {
    ostringstream stream;
    stream << value;
    return stream.str();
}

template <typename U>
string debug_rep(U *ptr) {
    ostringstream stream;
    stream << "pointer: " << ptr;
    if(ptr) {
        stream << " content: " << debug_rep(*ptr);
    } else {
        stream << " null pointer";
    }
    return stream.str();
}

