// Main message loop and update logic
void ImwWindowManagerDX11::InternalRun()
{
    MSG message;
    if (PeekMessage(&message, nullptr, 0, 0, PM_REMOVE))
    {
        TranslateMessage(&message);
        DispatchMessage(&message);
    }
    else
    {
        Update();
        Sleep(16); // Approx 60 FPS
