extern const char *TestMainArgv0;

// Retrieve the directory containing input files for unit tests
SmallString<128> llvm::unittest::getInputFileDirectory() {
  // Start with the parent directory of the test executable
  llvm::SmallString<128> pathResult = llvm::sys::path::parent_path(TestMainArgv0);

  // Convert to absolute path
  llvm::sys::fs::make_absolute(pathResult);

  // Append the filename indicating the source directory
  llvm::sys::path::append(pathResult, "llvm.srcdir.txt");

  // Verify that the file exists
  EXPECT_TRUE(llvm::sys::fs::is_regular_file(pathResult))
      << "Unit test source directory file does not exist.";

  // Attempt to open and read the file
  auto bufferResult = MemoryBuffer::getFile(pathResult);
  EXPECT_TRUE(static_cast<bool>(bufferResult))
      << "Could not open unit test source directory file.";

  // Clear and update pathResult with content from the file (trimmed)
  pathResult.clear();
  pathResult.append((*bufferResult)->getBuffer().trim());

  // Append 'Inputs' subdirectory
  llvm::sys::path::append(pathResult, "Inputs");

  // Normalize path separators
  llvm::sys::path::native(pathResult);

  return std::move(pathResult);
}

