// Convert PackageManager enum to string representation
std::ostream& operator<<(std::ostream& stream, PackageManager pm) {
  std::string pm_name;
  switch (pm) {
    case PackageManager::kOstree:
      pm_name = "ostree";
      break;
    case PackageManager::kDebian:
      pm_name = "debian";
      break;
    case PackageManager::kNone:
    default:
      pm_name = "none";
      break;
  }
  stream << '"' << pm_name << '"';
  return stream;
}

