#include <catch.hpp>
#include <jsonpp/value.hpp>

TEST_CASE("accessor_methods", "[subscripts-accessors]") {
    json::value data = { json::object{ {"sample", 1} }, nullptr, "example_string", 2.5 };
    json::value obj = json::object{ {"name", "text"}, {"count", 42} };

    SECTION("retrieve_elements_from_array") {
        REQUIRE(data[0].is<json::object>());
        REQUIRE(data[1].is<json::null>());
        REQUIRE(data[2].is<std::string>());
        REQUIRE(data[3].is<double>());
        REQUIRE(data[3].is<float>());
        REQUIRE(data[3].is<int>());
        REQUIRE(data[4].is<json::null>()); // Always safe, returns json::null
    };

    SECTION("retrieve_elements_from_object") {
        REQUIRE(obj["name"].is<std::string>());
        REQUIRE(obj["count"].is<int>());
        REQUIRE(obj["missing"].is<json::null>()); // Always safe, returns json::null
    };

    SECTION("retrieve_nested_values") {
        REQUIRE(data[0]["sample"].is<int>());
        REQUIRE(data[0]["sample"].as<int>() == 1);
    };
}

