#include <iostream>
#include <asio.hpp>
#include <boost/bind.hpp>

void timerCallback(const asio::error_code& /*errorCode*/,
    asio::steady_timer* timerObj, int* counterVar)
{
  if (*counterVar < 10)
  {
    std::cout << *counterVar << std::endl;
    ++(*counterVar);
    timerObj->expires_at(timerObj->expiry() + asio::chrono::seconds(2));
    timerObj->async_wait(boost::bind(timerCallback,
          asio::placeholders::error, timerObj, counterVar));
  }
}

int main()
{
  asio::io_context service;
  int iteration = 0;
  asio::steady_timer timer(service, asio::chrono::seconds(2));
  timer.async_wait(boost::bind(timerCallback,
        asio::placeholders::error, &timer, &iteration));
  service.run();
  std::cout << "Termination count: " << iteration << std::endl;
  return 0;
}

