TEST_F(SmallVectorTestSuite, DynamicGrowthBehavior) {
    SmallVector<int, 7> data;
    data.push_back(11);
    data.push_back(22);
    ASSERT_EQ(data.size(), 2);
    ASSERT_EQ(data[0], 11);
