TEST_F(SmallVectorTestSuite, RangeIterationTest) {
    constexpr size_t CAPACITY = 5;
    std::vector<int> referenceVec;
    SmallVector<int, CAPACITY> testVec;

    // Fill both containers with identical values
    for (size_t idx = 0; idx < CAPACITY; ++idx) {
        testVec.push_back(static_cast<int>(idx));
        referenceVec.push_back(static_cast<int>(idx));
    }

    ASSERT_EQ(testVec.size(), referenceVec.size());
    ASSERT_EQ(testVec, referenceVec);

    size_t index = 0;
    for (auto iter = testVec.begin(); iter != testVec.end(); ++iter, ++index) {
        ASSERT_EQ(*iter, referenceVec[index]);
    }

    index = 0;
    for (int value : testVec) {
        ASSERT_EQ(value, referenceVec[index]);
        ++index;
    }
}

TEST_F(SmallVectorTestSuite, MapOperationValidation) {
    constexpr size_t ELEMENT_COUNT = 50000;
    SmallVector<int, 200> sourceVec;
    for (size_t k = 0; k < ELEMENT_COUNT; ++k) {
        sourceVec.push_back(static_cast<int>(k));
    }

    std::vector<int> targetVec;
    sourceVec.map([&targetVec](int val) {
        targetVec.push_back(val);
    });

    ASSERT_EQ(sourceVec, targetVec);
}

