using namespace tabulate;
using Row_t = Table::Row_t;

int main() {
  // Create a table without any padding
  Table no_padding_table;
  no_padding_table.format().font_style({FontStyle::bold}).padding(0);
  no_padding_table.add_row(Row_t{"This cell has no padding"});
  std::cout << "Table with no padding:\n" << no_padding_table << std::endl;

  // Create a table with different top and bottom padding
  Table custom_padding_table;
  custom_padding_table.format().font_style({FontStyle::bold}).padding(0);
  custom_padding_table.add_row(
      Row_t{"This cell has padding top = 1", "This cell has padding bottom = 1"});
  custom_padding_table[0][0].format().padding_top(1);
  custom_padding_table[0][1].format().padding_bottom(1);
  std::cout << "\nTable with top/bottom padding:\n" << custom_padding_table << std::endl;

  return 0;
}

