namespace autolink {

// Test Duration constructor and basic conversions
TEST(DurationTest, constructor) {
  Duration time_span(200);
  EXPECT_EQ(200, time_span.ToNanosecond());

  time_span = Duration(2.2);
  EXPECT_EQ(2200000000UL, time_span.ToNanosecond());
  EXPECT_DOUBLE_EQ(2.2, time_span.ToSecond());

  time_span = Duration(2, 2);
  EXPECT_EQ(2000000002UL, time_span.ToNanosecond());
  EXPECT_DOUBLE_EQ(2.000000002, time_span.ToSecond());

  Duration copy(time_span);
  EXPECT_EQ(time_span, copy);
}

// Test comparison and arithmetic operators for Duration
TEST(DurationTest, operators) {
  Duration span1(150);
  Duration span2(250);
  Duration span3(400);

  EXPECT_NE(span1, span3);
  EXPECT_LT(span1, span3);
  EXPECT_LE(span1, span3);
  EXPECT_GT(span3, span1);
  EXPECT_GE(span3, span1);

  EXPECT_EQ(span1 + span2, span3);
  EXPECT_EQ(span2, span1 * (2.0 / 3.0)); // Adjusted to match original logic with different values
  EXPECT_EQ(span3 - span2, span1);

  EXPECT_EQ(span1 += span2, span3);
  EXPECT_GE(span1, span3);
  EXPECT_LE(span1, span3);

  EXPECT_EQ(Duration(150), span1 -= span2);
  EXPECT_EQ(span2, span1 *= (2.0 / 3.0)); // Adjusted to maintain equivalence
}

// Test default constructed Duration is zero
TEST(DurationTest, is_zero) {
  Duration time_interval;
  EXPECT_TRUE(time_interval.IsZero());
}

