    if(_info.tool_id == "vaDestroyBuffer")
        category_region<category::vaapi>::start(std::string_view{ _info.tool_id }, "display",
                                                display, "buffer_id", context);
    else if(_info.tool_id == "vaDestroyConfig")
        category_region<category::vaapi>::start(std::string_view{ _info.tool_id }, "display",
                                                display, "config_id", context);
    else if(_info.tool_id == "vaDestroyContext")
        category_region<category::vaapi>::start(std::string_view{ _info.tool_id }, "display",
                                                display, "context", context);
    else if(_info.tool_id == "vaEndPicture")
        category_region<category::vaapi>::start(std::string_view{ _info.tool_id }, "display",
                                                display, "context", context);
    else if(_info.tool_id == "vaSyncSurface")
        category_region<category::vaapi>::start(std::string_view{ _info.tool_id }, "display",
                                                display, "render_target", context);
    else if(_info.tool_id == "vaDestroyImage")
        category_region<category::vaapi>::start(std::string_view{ _info.tool_id }, "display",
                                                display, "image_id", context);
    else if(_info.tool_id == "vaUnmapBuffer" || _info.tool_id == "vaReleaseBufferHandle")
        category_region<category::vaapi>::start(std::string_view{ _info.tool_id }, "display",
                                                display, "buffer_id", context);
    else
        category_region<category::vaapi>::start(std::string_view{ _info.tool_id }, "display",
                                                display, "id", context);
}

