namespace
{
    // Helper function to copy data into buffer as raw bytes
    template <typename T>
    void storeDataIntoBuffer(BufferedTestReader& buffer, const T& value)
    {
        if constexpr (std::is_same_v<T, std::string>)
        {
            sen::test::TestWriter writer;
            sen::OutputStream out(writer);
            out.writeString(value);
            buffer.getBuffer() = writer.getBuffer();
        }
        else
        {
            // NOLINTNEXTLINE(cppcoreguidelines-pro-type-reinterpret-cast)
            auto bytePtr = reinterpret_cast<const uint8_t*>(&value);  // NOSONAR
            for (std::size_t idx = 0U; idx < sizeof(T); ++idx)
            {
                buffer.getBuffer().push_back(*(std::next(bytePtr, static_cast<int>(idx))));
            }
        }
    }

    // Specialization for Duration type
    void storeDataIntoBuffer(BufferedTestReader& buffer, const sen::Duration& duration)
    {
        storeDataIntoBuffer(buffer, duration.getNanoseconds());
    }

    // Specialization for TimeStamp type
    void storeTimeIntoBuffer(BufferedTestReader& buffer, const sen::TimeStamp& timestamp)
    {
        auto duration = timestamp.sinceEpoch();
        storeDataIntoBuffer(buffer, duration);
    }

    // Test reading of unsigned 8-bit integers
    void verifyUInt8Read(const uint8_t input)
    {
        BufferedTestReader buffer;
        storeDataIntoBuffer(buffer, input);
        InputStream stream(buffer.getBuffer());
        uint8_t output {};
        stream.readUInt8(output);
        EXPECT_EQ(output, input);
        EXPECT_EQ(sizeof(uint8_t), buffer.getBuffer().size() * sizeof(uint8_t));
    }

    // Test reading of signed 8-bit integers
    void verifyInt8Read(const int8_t input)
    {
        BufferedTestReader buffer;
        storeDataIntoBuffer(buffer, input);
        InputStream stream(buffer.getBuffer());
        int8_t output {};
        stream.readInt8(output);
        EXPECT_EQ(output, input);
        EXPECT_EQ(sizeof(int8_t), buffer.getBuffer().size() * sizeof(uint8_t));
    }

