        int16_t output {};
        stream.readInt16(output);
        EXPECT_EQ(output, input);
        EXPECT_EQ(sizeof(int16_t), buffer.getBuffer().size() * sizeof(uint8_t));
    }

    // Test reading of unsigned 32-bit integers
    void verifyUInt32Read(const uint32_t input)
    {
        BufferedTestReader buffer;
        storeDataIntoBuffer(buffer, input);
        InputStream stream(buffer.getBuffer());
        uint32_t output {};
        stream.readUInt32(output);
        EXPECT_EQ(output, input);
        EXPECT_EQ(sizeof(uint32_t), buffer.getBuffer().size() * sizeof(uint8_t));
    }

    // Test reading of signed 32-bit integers
    void verifyInt32Read(const int32_t input)
    {
        BufferedTestReader buffer;
        storeDataIntoBuffer(buffer, input);
        InputStream stream(buffer.getBuffer());
        int32_t output {};
        stream.readInt32(output);
        EXPECT_EQ(output, input);
        EXPECT_EQ(sizeof(int32_t), buffer.getBuffer().size() * sizeof(uint8_t));
    }

    // Test reading of unsigned 64-bit integers
    void verifyUInt64Read(const uint64_t input)
    {
        BufferedTestReader buffer;
        storeDataIntoBuffer(buffer, input);
        InputStream stream(buffer.getBuffer());
        uint64_t output {};
        stream.readUInt64(output);
        EXPECT_EQ(output, input);
        EXPECT_EQ(sizeof(uint64_t), buffer.getBuffer().size() * sizeof(uint8_t));
    }

    // Test reading of signed 64-bit integers
