    {
        BufferedTestReader buffer;
        storeDataIntoBuffer(buffer, input);
        InputStream stream(buffer.getBuffer());
        int64_t output {};
        stream.readInt64(output);
        EXPECT_EQ(output, input);
        EXPECT_EQ(sizeof(int64_t), buffer.getBuffer().size() * sizeof(uint8_t));
    }

    // Test reading of 32-bit floats
    void verifyFloat32Read(const float32_t input)
    {
        BufferedTestReader buffer;
        storeDataIntoBuffer(buffer, input);
        InputStream stream(buffer.getBuffer());
        float32_t output {};
        stream.readFloat32(output);
        EXPECT_EQ(output, input);
        EXPECT_EQ(sizeof(float32_t), buffer.getBuffer().size() * sizeof(uint8_t));
    }

    // Test reading of 64-bit floats
    void verifyFloat64Read(const float64_t input)
    {
