        InputStream stream(buffer.getBuffer());
        float64_t output {};
        stream.readFloat64(output);
        EXPECT_EQ(output, input);
        EXPECT_EQ(sizeof(float64_t), buffer.getBuffer().size() * sizeof(uint8_t));
    }

    // Test reading of strings
    void verifyStringRead(const std::string& input)
    {
        std::string output {};
        BufferedTestReader buffer;
        storeDataIntoBuffer(buffer, input);
        InputStream stream(buffer.getBuffer());
        stream.readString(output);
        EXPECT_EQ(input, output);
    }

    // Test reading of timestamps
    void verifyTimestampRead(const sen::TimeStamp input)
    {
        BufferedTestReader buffer;
        storeTimeIntoBuffer(buffer, input);
        InputStream stream(buffer.getBuffer());
        sen::TimeStamp output;
        stream.readTimeStamp(output);
        EXPECT_EQ(input, output);
        EXPECT_EQ(sizeof(int64_t), buffer.getBuffer().size() * sizeof(uint8_t));
    }

    // Test reading of booleans
    void verifyBoolRead(const bool input)
    {
        BufferedTestReader buffer;
        storeDataIntoBuffer(buffer, static_cast<sen::impl::BoolTransportType>(input ? 1U : 0U));
        InputStream stream(buffer.getBuffer());
        bool output = !input;
        stream.readBool(output);
        EXPECT_EQ(input, output);
        EXPECT_EQ(sizeof(bool), buffer.getBuffer().size() * sizeof(uint8_t));
    }

    // Template helper to test numeric limits
    template <typename T>
    void verifyNumericLimits()
    {
        verifyUInt8Read(static_cast<uint8_t>(0));
        verifyInt8Read(std::numeric_limits<T>::max());
        verifyInt8Read(std::numeric_limits<T>::min());
        verifyInt8Read(std::numeric_limits<T>::lowest());
    }
}  // namespace

/// @test
/// Check reading of basic types
/// @requirements(SEN-1051)
TEST(InputStream, basics)
{
    verifyInt8Read(-8);
    verifyUInt8Read(2U);
    verifyInt16Read(304);
    verifyUInt16Read(298U);
    verifyInt32Read(-1025);
    verifyUInt32Read(1214U);
    verifyInt64Read(23023);
    verifyUInt64Read(0U);
    verifyFloat32Read(-3.14159f);
    verifyFloat64Read(2.89);
}

/// @test
/// Check correct reading of basic types numeric limits
/// @requirements(SEN-1051)
TEST(InputStream, numberLimits)
{
    verifyNumericLimits<int8_t>();
    verifyNumericLimits<uint8_t>();
    verifyNumericLimits<int16_t>();
    verifyNumericLimits<uint16_t>();
    verifyNumericLimits<int32_t>();
    verifyNumericLimits<uint32_t>();
    verifyNumericLimits<uint64_t>();
    verifyNumericLimits<int64_t>();
    verifyNumericLimits<float32_t>();
    verifyNumericLimits<float64_t>();
}

/// @test
/// Check reading of string types
/// @requirements(SEN-1051)
TEST(InputStream, string)
{
    verifyStringRead("hello world this is me");
    verifyStringRead({});
    verifyStringRead("hello \0 world");              // NOLINT(bugprone-string-literal-with-embedded-nul)
    verifyStringRead("UPPER CASE minor \0 case\n");  // NOLINT(bugprone-string-literal-with-embedded-nul)
    verifyStringRead("@#$$%^&*(){}!@#$$#@\\@");
}

/// @test
/// Check reading of timestamps types
/// @requirements(SEN-1051)
TEST(InputStream, timestamp)
{
    verifyTimestampRead({});
    verifyTimestampRead(sen::TimeStamp {sen::Duration {10}});
    verifyTimestampRead(sen::TimeStamp {sen::Duration {-10}});
    verifyTimestampRead(sen::TimeStamp {sen::Duration {10000000}});
    verifyTimestampRead(sen::TimeStamp {sen::Duration {-10000000}});
    verifyTimestampRead(sen::TimeStamp {sen::Duration(99999)});
    verifyTimestampRead(sen::TimeStamp {sen::Duration({})});
    verifyTimestampRead(sen::TimeStamp {sen::Duration(0.223)});
    verifyTimestampRead(sen::TimeStamp {std::numeric_limits<sen::Duration::ValueType>::max()});
    verifyTimestampRead(sen::TimeStamp {std::numeric_limits<sen::Duration::ValueType>::min()});
    verifyTimestampRead(sen::TimeStamp {std::numeric_limits<sen::Duration::ValueType>::lowest()});
}

/// @test
/// Check reading of boolean types
/// @requirements(SEN-1051)
