/// @test
/// Check reading of some types using big endian
/// @requirements(SEN-1051)
TEST(InputStream, BigEndian)
{
    // uint32_t
    {
        uint32_t data = 93982U;
        BufferedTestReader buffer;
        storeDataIntoBuffer(buffer, data);
        sen::InputStreamTemplate<sen::BigEndian> stream(buffer.getBuffer());
        uint32_t val {};
        stream.readUInt32(val);
        EXPECT_EQ(sen::impl::swapBytes(val), data);
        EXPECT_EQ(sizeof(uint32_t), buffer.getBuffer().size() * sizeof(uint8_t));
    }

    // float64_t
    {
        float64_t data = 6533.32;
        BufferedTestReader buffer;
        storeDataIntoBuffer(buffer, data);
        sen::InputStreamTemplate<sen::BigEndian> stream(buffer.getBuffer());
        float64_t val {};
        stream.readFloat64(val);
        EXPECT_EQ(sen::impl::swapBytes(val), data);
        EXPECT_EQ(sizeof(float64_t), buffer.getBuffer().size() * sizeof(uint8_t));
    }
}

