int main(int argc, char **argv) {
  ros::init(argc, argv, "tofsense_parser");
  ros::NodeHandle node;
  serial::Serial port;
  initSerial(&port);
  NProtocolExtracter parser;
  tofsense::Init initializer(&parser, &port);
  ros::Rate update_rate(1000);

  while (ros::ok()) {
    auto bytes_available = port.available();
    std::string buffer;

    if (bytes_available) {
      port.read(buffer, bytes_available);
      parser.AddNewData(buffer);
    }

    ros::spinOnce();
    update_rate.sleep();
  }

  return EXIT_SUCCESS;
}

