int main() {
    std::cout << "======= SMTParser Test Program =======" << std::endl;
    std::cout << "\n--- Testing Boolean Value Parsing ---" << std::endl;
    {
        SMTParser::ParserPtr smt_parser = SMTParser::newParser();
        std::shared_ptr<SMTParser::DAGNode> output = smt_parser->mkExpr("true");
        assert(output && output->isTrue() && !output->isFalse());
        std::cout << "Input: true" << std::endl;
        std::cout << "Result: " << smt_parser->toString(output) << std::endl;
        std::cout << "isTrue: yes" << std::endl;
    }
    {
        SMTParser::ParserPtr smt_parser = SMTParser::newParser();
        std::shared_ptr<SMTParser::DAGNode> output = smt_parser->mkExpr("false");
        assert(output && output->isFalse() && !output->isTrue());
        std::cout << "Input: false" << std::endl;
        std::cout << "Result: " << smt_parser->toString(output) << std::endl;
        std::cout << "isFalse: yes" << std::endl;
    }
    std::cout << "\n--- Testing Integer Parsing ---" << std::endl;
    {
        SMTParser::ParserPtr smt_parser = SMTParser::newParser();
        std::shared_ptr<SMTParser::DAGNode> output = smt_parser->mkExpr("17");
        assert(output && smt_parser->toString(output) == "17");
        std::cout << "Input: 17" << std::endl;
        std::cout << "Result: " << smt_parser->toString(output) << std::endl;
    }
    std::cout << "\n--- Testing Real Number Parsing ---" << std::endl;
    {
        SMTParser::ParserPtr smt_parser = SMTParser::newParser();
        std::shared_ptr<SMTParser::DAGNode> output = smt_parser->mkExpr("2.71");
        assert(output && smt_parser->toString(output) == "2.71");
        std::cout << "Input: 2.71" << std::endl;
        std::cout << "Result: " << smt_parser->toString(output) << std::endl;
    }
    std::cout << "\n--- Testing Expression Parsing ---" << std::endl;
    {
        SMTParser::ParserPtr smt_parser = SMTParser::newParser();
        std::shared_ptr<SMTParser::DAGNode> output = smt_parser->mkExpr("(or false true)");
        assert(output && output->isTrue());
        std::cout << "Input: (or false true)" << std::endl;
        std::cout << "Result: " << smt_parser->toString(output) << std::endl;
    }
    return 0;
}

