void decodeTofsensemData(const uint8_t *buffer, size_t buffer_size) {
  if (g_ntsm_frame0.UnpackData(buffer, buffer_size)) {
    printf("TOFSense-M Frame0 %d Pixel data decoded successfully:\r\n",
           g_ntsm_frame0.pixel_count);
    printf("identifier:%d, timestamp:%d\r\n", g_ntsm_frame0.id,
           g_ntsm_frame0.system_time);
    for (int index = 0; index < g_ntsm_frame0.pixel_count; ++index) {
      ntsm_frame0_pixel_t *pixel_ptr = &g_ntsm_frame0.pixels[index];
      printf("pixel %d: distance:%f, status:%d, signal_level:%d\r\n", index,
             pixel_ptr->dis, pixel_ptr->dis_status, pixel_ptr->signal_strength);
    }
  } else {
    printf("decoding failed\n");
  }
}

int main() {
  // Verify little-endian architecture
  {
    uint32_t test_value = 1;
    if (*(uint8_t *)(&test_value) != 1) {
      printf("Error: this code must run in little endian.");
      return EXIT_FAILURE;
    }
  }

  // Validate structure packing
  if (sizeof(aligned_struct_t) != 15) {
    printf("Error: Pack do not work, pack size:%zu. Contact us for support",
           sizeof(aligned_struct_t));
    return EXIT_FAILURE;
  }

  uint8_t input_buffer[1024];
