// Convert a UTF-8 encoded std::string to std::u16string
std::u16string convert_string_to_u16(const std::string & source)
{
  std::wstring_convert<std::codecvt_utf8_utf16<char16_t>, char16_t> converter;
  return converter.from_bytes(source);
}

// Convert a std::u16string to UTF-8 encoded std::string
std::string convert_u16_to_string(const std::u16string & source)
{
  std::wstring_convert<std::codecvt_utf8_utf16<char16_t>, char16_t> converter;
  return converter.to_bytes(source);
}

