#define TILING_KEY_UNQUANTIZED 20001
#define TILING_KEY_QUANTIZED   20003

extern "C" __global__ __aicore__ void cam_moe_dispatch_normal(
    GM_ADDR inputTensor,
    GM_ADDR expertIndices,
    GM_ADDR sendDisplacements,
    GM_ADDR sendTokenLocations,
    GM_ADDR recvDisplacements,
    GM_ADDR recvCounts,
    GM_ADDR expertGlobalBase,
    GM_ADDR srcRankInExpertOffset,
    GM_ADDR relativePosInSrcRank,
    GM_ADDR expandedOutput,
    GM_ADDR scaleOutput,
    GM_ADDR combineAssistData,
    GM_ADDR recvLatencyStats,
    GM_ADDR scratchGM,
    GM_ADDR tilingBuffer)
{
    REGISTER_TILING_DEFAULT(CamMoeDispatchNormalTilingData);
    TPipe pipeline;

#if (INPUT_DTYPE_RECV == DT_BF16 || INPUT_DTYPE_RECV == DT_FLOAT16)
    if (IS_TILING_KEY(TILING_KEY_UNQUANTIZED)) {
        RETRIEVE_TILING_DATA(CamMoeDispatchNormalTilingData, tilingConfig, tilingBuffer);
        CamMoeDispatchNormal<DTYPE_INPUT, DTYPE_RECV, false, false, false> dispatcher;
        dispatcher.Init(inputTensor,
                        expertIndices,
                        sendDisplacements,
                        sendTokenLocations,
                        recvDisplacements,
                        recvCounts,
                        expertGlobalBase,
                        srcRankInExpertOffset,
                        relativePosInSrcRank,
                        expandedOutput,
                        scaleOutput,
                        combineAssistData,
                        recvLatencyStats,
                        scratchGM,
                        &pipeline,
                        tilingBuffer);
        dispatcher.Run();
        return;
    }
#elif (INPUT_DTYPE_RECV == DT_INT8)
    if (IS_TILING_KEY(TILING_KEY_QUANTIZED)) {
        RETRIEVE_TILING_DATA(CamMoeDispatchNormalTilingData, tilingConfig, tilingBuffer);
        CamMoeDispatchNormal<DTYPE_INPUT, DTYPE_RECV, true, false, false> dispatcher;
        dispatcher.Init(inputTensor,
                        expertIndices,
                        sendDisplacements,
                        sendTokenLocations,
                        recvDisplacements,
                        recvCounts,
                        expertGlobalBase,
                        srcRankInExpertOffset,
                        relativePosInSrcRank,
                        expandedOutput,
                        scaleOutput,
                        combineAssistData,
                        recvLatencyStats,
                        scratchGM,
                        &pipeline,
                        tilingBuffer);
        dispatcher.Run();
        return;
    }
#endif
}

