#include <bpf/bpf.h>

// Tracepoint structure for scheduler switch event
struct sched_switch_event {
    u64 reserved;
    char prev_task_name[16];
    u32 prev_process_id;
    u32 prev_priority;
    u64 prev_state_info;
    char next_task_name[16];
    u32 next_process_id;
    u32 next_priority;
};

SEC("tracepoint/sched/sched_switch")
int handle_sched_switch(struct sched_switch_event* event) {
    u64 current_tgid = bpf_get_current_pid_tgid();
    BPF_PRINTK("Processing scheduler switch: %u -> %u (current thread: %u)\n", 
               event->prev_process_id, 
               event->next_process_id, 
               (u32)current_tgid);
    return 0;
}
