struct MD5Hasher {
    static void compute(const string_t& input, string_t& output, ValueVector& outputVector) {
        MD5 digest;
        digest.addToMD5(reinterpret_cast<const char*>(input.getData()), input.len);
        StringVector::addString(&outputVector, output, std::string(digest.finishMD5()));
    }
};

function_set MD5Function::getFunctionSet() {
    function_set functions;
    functions.push_back(std::make_unique<ScalarFunction>(name,
        std::vector<LogicalTypeID>{LogicalTypeID::STRING}, LogicalTypeID::STRING,
        ScalarFunction::UnaryStringExecFunction<string_t, string_t, MD5Hasher>));
    return functions;
}

