// Compute maximum indices for block-wise operations
std::vector<at::Tensor> index_max(
  at::Tensor input_vals,
  at::Tensor input_indices,
  int64_t block_size_A,
  int64_t block_size_B
) {
  return index_max_kernel(
    input_vals,
    input_indices,
    static_cast<int>(block_size_A),
    static_cast<int>(block_size_B)
  );
}

// Convert dense matrix multiplication result to sparse format
at::Tensor mm_to_sparse(
  at::Tensor matrix_A,
  at::Tensor matrix_B,
  at::Tensor sparse_indices
) {
  return mm_to_sparse_kernel(
    matrix_A,
    matrix_B,
    sparse_indices
  );
}

// Perform sparse-dense matrix multiplication
at::Tensor sparse_dense_mm(
  at::Tensor sparse_matrix,
  at::Tensor row_indices,
  at::Tensor dense_matrix,
  int64_t num_blocks_A
) {
  return sparse_dense_mm_kernel(
    sparse_matrix,
    row_indices,
    dense_matrix,
    static_cast<int>(num_blocks_A)
  );
}

// Compute reduction sum over sparse structure
at::Tensor reduce_sum(
  at::Tensor sparse_tensor,
  at::Tensor mapping_indices,
  int64_t blocks_in_A,
  int64_t blocks_in_B
) {
  return reduce_sum_kernel(
    sparse_tensor,
    mapping_indices,
    static_cast<int>(blocks_in_A),
    static_cast<int>(blocks_in_B)
  );
}

// Scatter dense tensor into sparse layout
at::Tensor scatter(
  at::Tensor source_tensor,
  at::Tensor scatter_indices,
  int64_t target_blocks
) {
  return scatter_kernel(
    source_tensor,
    scatter_indices,
    static_cast<int>(target_blocks)
  );
}

// Register CUDA kernels with PyTorch extension
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, ops) {
  ops.def("index_max(Tensor index_vals, Tensor indices, int A_num_block, int B_num_block) -> Tensor[]");
  ops.impl("index_max", torch::kCUDA, &index_max);

  ops.def("mm_to_sparse(Tensor dense_A, Tensor dense_B, Tensor indices) -> Tensor");
  ops.impl("mm_to_sparse", torch::kCUDA, &mm_to_sparse);

  ops.def("sparse_dense_mm(Tensor sparse_A, Tensor indices, Tensor dense_B, int A_num_block) -> Tensor");
  ops.impl("sparse_dense_mm", torch::kCUDA, &sparse_dense_mm);

  ops.def("reduce_sum(Tensor sparse_A, Tensor indices, int A_num_block, int B_num_block) -> Tensor");
  ops.impl("reduce_sum", torch::kCUDA, &reduce_sum);

  ops.def("scatter(Tensor dense_A, Tensor indices, int B_num_block) -> Tensor");
  ops.impl("scatter", torch::kCUDA, &scatter);
}

REGISTER_EXTENSION(TORCH_EXTENSION_NAME);

