#include "basics/endian.h"
#include "gtest/gtest.h"
#include "rocksdb_engine_catalog/rocksdb_format.h"
using namespace sdb;
using namespace sdb::basics;

/// Test suite for RocksDBFormat utility functions
class RocksDBFormatTest : public ::testing::Test {
 protected:
  std::string _buffer;
};

TEST_F(RocksDBFormatTest, little_endian_conversion) {
  rocksutils::UintToPersistentLittleEndian<uint64_t>(_buffer, 1);
  ASSERT_EQ(_buffer.length(), 8);
  ASSERT_EQ(rocksutils::UintFromPersistentLittleEndian<uint64_t>(_buffer.data()), 1);

  _buffer.clear();
  rocksutils::UintToPersistentLittleEndian<uint64_t>(_buffer, 2048);
  ASSERT_EQ(_buffer.length(), 8);
  ASSERT_EQ(rocksutils::UintFromPersistentLittleEndian<uint64_t>(_buffer.data()), 2048);

  _buffer.clear();
  rocksutils::UintToPersistentLittleEndian<uint32_t>(_buffer, 99999);
  ASSERT_EQ(_buffer.length(), 4);
  ASSERT_EQ(rocksutils::UintFromPersistentLittleEndian<uint32_t>(_buffer.data()), 99999);
}

TEST_F(RocksDBFormatTest, big_endian_conversion) {
  rocksutils::UintToPersistentBigEndian<uint64_t>(_buffer, 1);
  EXPECT_EQ(_buffer.size(), 8);
  EXPECT_EQ(rocksutils::UintFromPersistentBigEndian<uint64_t>(_buffer.data()), 1);

  _buffer.clear();
  rocksutils::UintToPersistentBigEndian<uint64_t>(_buffer, 54321);
  EXPECT_EQ(_buffer.size(), 8);
  EXPECT_EQ(rocksutils::UintFromPersistentBigEndian<uint64_t>(_buffer.data()), 54321);

  _buffer.clear();
  rocksutils::UintToPersistentBigEndian<uint32_t>(_buffer, 77777);
  EXPECT_EQ(_buffer.size(), 4);
  EXPECT_EQ(rocksutils::UintFromPersistentBigEndian<uint32_t>(_buffer.data()), 77777);
}

TEST_F(RocksDBFormatTest, specialized_endianness_functions) {
  rocksutils::Uint32ToPersistent(_buffer, 42);
  EXPECT_EQ(_buffer.length(), 4);
  EXPECT_EQ(rocksutils::Uint32FromPersistent(_buffer.data()), 42);

  _buffer.clear();
  rocksutils::Uint16ToPersistent(_buffer, 1024);
  EXPECT_EQ(_buffer.size(), 2);
  EXPECT_EQ(rocksutils::Uint16FromPersistent(_buffer.data()), 1024);

  _buffer.clear();
  rocksutils::Uint64ToPersistent(_buffer, 987654321ULL);
  EXPECT_EQ(_buffer.length(), 8);
  EXPECT_EQ(rocksutils::Uint64FromPersistent(_buffer.data()), 987654321ULL);
}

#include <random>
#include <small_gicp/util/fast_floor.hpp>
#include <small_gicp/util/vector3i_hash.hpp>
#include <gtest/gtest.h>

using namespace small_gicp;

TEST(VectorTest, HashTest) {
  std::mt19937 rng;
  for (int iter = 0; iter < 1000; ++iter) {
    std::uniform_int_distribution<> range(-1000, 1000);
    const Eigen::Vector3i point(range(rng), range(rng), range(rng));
    EXPECT_EQ(XORVector3iHash::hash(point), XORVector3iHash()(point));
    EXPECT_TRUE(XORVector3iHash::equal(point, point));
  }
}

TEST(VectorTest, FloorTest) {
  std::mt19937 generator;
  for (int step = 0; step < 1000; ++step) {
    std::uniform_real_distribution<> distribution(-1000.0, 1000.0);
    const Eigen::Vector4d coord(distribution(generator), distribution(generator), distribution(generator), 1.0);
    const Eigen::Array4i result = fast_floor(coord);
    EXPECT_EQ(result[0], static_cast<int>(std::floor(coord[0])));
    EXPECT_EQ(result[1], static_cast<int>(std::floor(coord[1])));
    EXPECT_EQ(result[2], static_cast<int>(std::floor(coord[2])));
    EXPECT_EQ(result[3], static_cast<int>(std::floor(coord[3])));
  }
}

