#include "test/jemalloc_test.h"
#include "jemalloc/internal/peak.h"

TEST_BEGIN(test_peak_modifications) {
    peak_t peak = PEAK_INITIALIZER;
    expect_u64_eq(0, peak_max(&peak),
        "Initial peak should be zero");

    peak_update(&peak, 150, 75);
    expect_u64_eq(75, peak_max(&peak),
        "First update should set peak to allocated - deallocated");

    peak_update(&peak, 150, 150);
    expect_u64_eq(75, peak_max(&peak), 
        "Deallocation events should not affect the peak");

    peak_update(&peak, 150, 250);
    expect_u64_eq(75, peak_max(&peak), 
        "Still net negative, no change to peak");

    peak_update(&peak, 250, 250);
    expect_u64_eq(75, peak_max(&peak), 
        "Not yet reached previous peak level");

    peak_update(&peak, 350, 250);
    expect_u64_eq(100, peak_max(&peak), 
        "New peak reached after positive net allocation");

    peak_set_zero(&peak, 350, 250);
    expect_u64_eq(0, peak_max(&peak), 
        "Zeroing should reset the peak value");

    peak_update(&peak, 350, 350);
    expect_u64_eq(0, peak_max(&peak), 
        "Net deallocation shouldn't create a new peak");

    peak_update(&peak, 450, 350);
    expect_u64_eq(0, peak_max(&peak), 
        "Still net negative, peak remains zero");

    peak_update(&peak, 550, 350);
    expect_u64_eq(100, peak_max(&peak), 
        "New positive net allocation creates new peak");

    /*
     * Now test zeroing when current state is net deallocator.
     */
    peak_set_zero(&peak, 650, 800);
    expect_u64_eq(0, peak_max(&peak), 
        "Zeroing while net deallocator has no effect.");

    peak_update(&peak, 650, 900);
    expect_u64_eq(0, peak_max(&peak), 
        "Additional deallocation doesn't affect peak.");

    peak_update(&peak, 750, 900);
    expect_u64_eq(0, peak_max(&peak), 
        "Still net negative overall.");

    peak_update(&peak, 850, 900);
    expect_u64_eq(100, peak_max(&peak), 
        "Finally reach new positive net allocation level.");
}
TEST_END

int main(void) {
    return test_no_reentrancy(
        test_peak_modifications);
}

