#include <ros/ros.h>
#include "init.h"
#include "init_serial.h"

int main(int argc, char **argv) {
  ros::init(argc, argv, "linktrack_aoa");
  ros::NodeHandle node_handle;
  serial::Serial device_serial;
  initSerial(&device_serial);
  NProtocolExtracter data_extractor;
  linktrack_aoa::Init aoa_initializer(&data_extractor, &device_serial);
  ros::Rate update_rate(1000);

  while (ros::ok()) {
    auto bytes_available = device_serial.available();
    std::string incoming_data;

    if (bytes_available) {
      device_serial.read(incoming_data, bytes_available);
      data_extractor.AddNewData(incoming_data);
    }

    ros::spinOnce();
    update_rate.sleep();
  }

  return EXIT_SUCCESS;
}

