template<typename Element, typename Count>
struct StaticArray {
    Element* elements = nullptr;
    Count size = 0;

    ~StaticArray() {
        delete[] elements;
    }

    void AllocateFrom(BinaryReader& stream) {
        stream.ReadLE(size);
        delete[] elements;
        if (size > 0)
            elements = new Element[size];
    }

    void LoadFrom(BinaryReader& stream) {
        for (Count index = 0; index < size; ++index)
            elements[index].LoadFrom(stream);
    }

    void AllocateAndLoad(BinaryReader& stream) {
        AllocateFrom(stream);
        LoadFrom(stream);
    }
};

struct stringReference_t {
    uint32_t length = 0;
    const char* text = nullptr;

    void LoadFrom(BinaryReader& stream) {
        assert(stream.ReadLE(length));
        assert(stream.ReadBytes(text, length));
    }
};

typedef StaticArray<stringReference_t, uint32_t> stringTable_t;

void DisplayStrings(stringTable_t& table) {
    for (uint32_t i = 0; i < table.size; i++)
        printf("\"%.*s\"\n", table.elements[i].length, table.elements[i].text);
}

struct sectionHeaderItem_t {
    uint32_t field0;
    uint32_t field1;
    uint32_t field2;
    uint32_t field3;
    uint32_t field4;
    uint32_t field5;
    uint32_t field6;
    uint32_t field7;

    void LoadFrom(BinaryReader& stream) {
        stream.ReadLE(field0);
        stream.ReadLE(field1);
        stream.ReadLE(field2);
        stream.ReadLE(field3);
        stream.ReadLE(field4);
        stream.ReadLE(field5);
        stream.ReadLE(field6);
        stream.ReadLE(field7);
    }
};

struct sectionHeaderBlock_t {
    StaticArray<sectionHeaderItem_t, uint32_t> entries;
    uint32_t zeroValue;
    uint32_t worldEntityId;
    uint32_t primaryTableSize;

    void LoadFrom(BinaryReader& stream) {
        entries.AllocateFrom(stream);
        stream.ReadLE(zeroValue);
        assert(zeroValue == 0);
        stream.ReadLE(worldEntityId);
        stream.ReadLE(primaryTableSize);
        entries.LoadFrom(stream);
    }
};

void AbortParsing(BinaryReader& stream) {
    printf("%zu\n", stream.GetPosition());
    assert(0);
}

struct StaticDataSection {
    sectionHeaderBlock_t mainHeader;
    stringTable_t tableA;
    stringTable_t tableB;

    void LoadFrom(BinaryReader& stream) {
        mainHeader.LoadFrom(stream);
        tableA.AllocateAndLoad(stream);
        assert(tableA.size == mainHeader.primaryTableSize);

        while (true) {
            uint32_t opcode, operand0, operand1;
            assert(stream.ReadLE(opcode));

            if (opcode == 0) {
                stream.ReadLE(operand0);
                stream.ReadLE(operand1);
                assert(operand0 == 0 && operand1 == 0);
            } else {
                AbortParsing(stream);
            }
        }
    }
};

void StaticsParser::Parse(BinaryReader& reader) {
    StaticDataSection data;
    data.LoadFrom(reader);
}

