class Solution {
public:
    uint32_t reverseBits(uint32_t value) {
        uint32_t result = 0;
        for (int bitPosition = 0; bitPosition < 32; bitPosition++) {
            result <<= 1;
            result |= (value & 1);
            value >>= 1;
        }
        return result;
    }
};

