#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <string.h>

void print_usage() {
    fprintf(stderr, "tone <frequency_Hz>,[<amplitude>] [<frequency_Hz>,[<amplitude>]...]\n");
    exit(1);
}

int main(int argc, char *argv[]) {
    int index;
    int tone_count;
    double *freq_array;
    double *ampl_array;

    if (argc < 2) {
        print_usage();
    }

    tone_count = argc - 1;
    freq_array = alloca(sizeof(*freq_array) * tone_count);
    ampl_array = alloca(sizeof(*ampl_array) * tone_count);

    index = 0;
    while (index < tone_count) {
        char *comma_pos = strchr(argv[index + 1], ',');

        freq_array[index] = atof(argv[index + 1]);
        if (comma_pos) {
            ampl_array[index] = atof(comma_pos + 1) * 32767.0;
        } else {
            ampl_array[index] = 32767.0;
        }
        fprintf(stderr, "%g Hz, %g amp\n", freq_array[index], ampl_array[index]);
        index++;
    }

    // Generate 5 seconds of audio instead of 10
    for (int sample = 0; sample < 44100 * 5; sample++) {
        float sample_value = 0.0f;
        int int_sample;

        for (int tone = 0; tone < tone_count; tone++) {
            sample_value += ampl_array[tone] * sin(sample / 44100.0f * freq_array[tone] * 2.0 * M_PI);
        }

        int_sample = (int)rint(sample_value);
        if (int_sample > 32767) {
            int_sample = 32767;
        }
        if (int_sample < -32768) {
            int_sample = -32768;
        }

        fprintf(stdout, "%c%c%c%c",
                (char)(int_sample & 0xff),
                (char)((int_sample >> 8) & 0xff),
                (char)(int_sample & 0xff),
                (char)((int_sample >> 8) & 0xff));
    }

    return 0;
}

