int main() {
    Storage memory;
    Builder compiler(true);
    int location;
    Context engine;

    morgana::desconstruct d(morgana::mics::this_, {});
    engine << d.string();

    auto int_type = morgana::type::integer(32);
    morgana::alloc variable(memory, int_type.vec(12).shared());
    engine << variable.string();

    morgana::setindex assign(variable, morgana::value);
    engine << assign.string();

    engine << morgana::ret::string();

    morgana::function func("entry", morgana::type::integer(32).shared(), {}, engine.string());
    compiler << func.string();

    memory.leave();

    std::cout << memory.string() << compiler.string();
    return 0;
}

