#include <tabulate/table.hpp>
using namespace tabulate;
using Row_t = Table::Row_t;

int main() {
  Table table;
  table.add_row(Row_t{"Text in Red", "Text in Blue", "Text in Green"});
  table.add_row(Row_t{"All Red", "All Blue", "All Green"});
  table.add_row(
      Row_t{"Red Background", "Blue Background", "Green Background"});

  table[0][0].format().font_color(Color::red).font_style({FontStyle::bold});
  table[0][1].format().font_color(Color::blue).font_style({FontStyle::bold});
  table[0][2].format().font_color(Color::green).font_style({FontStyle::bold});

  table[1][0]
      .format()
      .border_left_color(Color::red)
      .border_left_background_color(Color::red)
      .font_background_color(Color::red)
      .font_color(Color::red);
  table[1][1]
      .format()
      .border_left_color(Color::blue)
      .border_left_background_color(Color::blue)
      .font_background_color(Color::blue)
      .font_color(Color::blue);
  table[1][2]
      .format()
      .border_left_color(Color::green)
      .border_left_background_color(Color::green)
      .font_background_color(Color::green)
      .font_color(Color::green)
      .border_right_color(Color::green)
      .border_right_background_color(Color::green);

  table[2][0].format().font_background_color(Color::red).font_style({FontStyle::bold});
  table[2][1].format().font_background_color(Color::blue).font_style({FontStyle::bold});
  table[2][2].format().font_background_color(Color::green).font_style({FontStyle::bold});

  std::cout << table << std::endl;
}

