void test_dswap_zero_stride(void)
{
    int idx = 0;
    int count = 4, strideX = 0, strideY = 0;
    double srcA1[] = {1.0, 3.0, 5.0, 7.0};
    double srcB1[] = {2.0, 4.0, 6.0, 8.0};
    double srcA2[] = {1.0, 3.0, 5.0, 7.0};
    double srcB2[] = {2.0, 4.0, 6.0, 8.0};

    // OpenBLAS implementation
    BLASFUNC(dswap)(&count, srcA1, &strideX, srcB1, &strideY);
    // Reference implementation
    BLASFUNC_REF(dswap)(&count, srcA2, &strideX, srcB2, &strideY);

    for (idx = 0; idx < count; idx++) {
        CU_ASSERT_DOUBLE_EQUAL(srcA1[idx], srcA2[idx], CHECK_EPS);
        CU_ASSERT_DOUBLE_EQUAL(srcB1[idx], srcB2[idx], CHECK_EPS);
    }
}

