#include <perforator/lib/tls/parser/tls.h>
#include <perforator/lib/llvmex/llvm_exception.h>
#include <util/stream/format.h>
#include <llvm/Object/ObjectFile.h>

int main(int argCount, const char* arguments[]) {
    Y_THROW_UNLESS(argCount == 2);

    auto binaryImage = Y_LLVM_RAISE(llvm::object::ObjectFile::createObjectFile(arguments[1]));

    NPerforator::NThreadLocal::TTlsParser tlsAnalyzer{binaryImage.getBinary()};

    tlsAnalyzer.VisitVariables([](auto&& tlsSymbol) {
        Cerr
            << "Detected TLS symbol " << tlsSymbol.Name
            << " at offset " << Hex(tlsSymbol.ThreadImageOffset, HF_ADDX)
            << Endl;
    });
}

