#include <gtest/gtest.h>
#include "chromaprint3d/vec3.h"
using namespace ChromaPrint3D;

// Test suite for Vec3i class functionality
TEST(Vec3i, DefaultConstruction) {
    Vec3i point;
    EXPECT_EQ(point.x, 0);
    EXPECT_EQ(point.y, 0);
    EXPECT_EQ(point.z, 0);
}

TEST(Vec3i, VectorAddition) {
    Vec3i first(1, 2, 3), second(4, 5, 6);
    Vec3i result = first + second;
    EXPECT_EQ(result.x, 5);
    EXPECT_EQ(result.y, 7);
    EXPECT_EQ(result.z, 9);
}

TEST(Vec3i, VectorSubtraction) {
    Vec3i larger(10, 20, 30), smaller(3, 5, 7);
    Vec3i diff = larger - smaller;
    EXPECT_EQ(diff.x, 7);
    EXPECT_EQ(diff.y, 15);
    EXPECT_EQ(diff.z, 23);
}

TEST(Vec3i, ScalarMultiplication) {
    Vec3i original(2, 3, 4);
    Vec3i rightResult = original * 3;
    EXPECT_EQ(rightResult.x, 6);
    EXPECT_EQ(rightResult.y, 9);
    EXPECT_EQ(rightResult.z, 12);
    Vec3i leftResult = 3 * original;
    EXPECT_EQ(leftResult.x, 6);
}

TEST(Vec3i, DotProductCalculation) {
    Vec3i orthogonal1(1, 0, 0), orthogonal2(0, 1, 0);
    EXPECT_EQ(orthogonal1.Dot(orthogonal2), 0);
    Vec3i vector(1, 2, 3);
    EXPECT_EQ(vector.Dot(vector), 14);
}

TEST(Vec3i, ElementAccess) {
    Vec3i coordinates(10, 20, 30);
    EXPECT_EQ(coordinates[0], 10);
    EXPECT_EQ(coordinates[1], 20);
    EXPECT_EQ(coordinates[2], 30);
    coordinates[1] = 99;
    EXPECT_EQ(coordinates.y, 99);
}

// Test suite for Vec3f class functionality
TEST(Vec3f, DefaultInitialization) {
    Vec3f value;
    EXPECT_FLOAT_EQ(value.x, 0.0f);
    EXPECT_FLOAT_EQ(value.y, 0.0f);
    EXPECT_FLOAT_EQ(value.z, 0.0f);
}

TEST(Vec3f, MagnitudeAndNormalization) {
    Vec3f input(3.0f, 4.0f, 0.0f);
    EXPECT_FLOAT_EQ(input.Length(), 5.0f);
    Vec3f normalized = input.Normalized();
    EXPECT_NEAR(normalized.Length(), 1.0f, 1e-6f);
}

TEST(Vec3f, LinearInterpolation) {
    Vec3f start(0.0f, 0.0f, 0.0f), end(10.0f, 10.0f, 10.0f);
    Vec3f midpoint = Vec3f::Lerp(start, end, 0.5f);
    EXPECT_NEAR(midpoint.x, 5.0f, 1e-6f);
    EXPECT_NEAR(midpoint.y, 5.0f, 1e-6f);
}

TEST(Vec3f, ClampToUnitRange) {
    Vec3f unclamped(-0.5f, 0.5f, 1.5f);
    Vec3f clamped = Vec3f::Clamp01(unclamped);
    EXPECT_FLOAT_EQ(clamped.x, 0.0f);
    EXPECT_FLOAT_EQ(clamped.y, 0.5f);
    EXPECT_FLOAT_EQ(clamped.z, 1.0f);
}

TEST(Vec3f, ApproximateEquality) {
    Vec3f reference(1.0f, 2.0f, 3.0f);
    Vec3f similar(1.0f + 1e-7f, 2.0f, 3.0f);
    EXPECT_TRUE(reference.NearlyEqual(similar));
    Vec3f different(1.1f, 2.0f, 3.0f);
    EXPECT_FALSE(reference.NearlyEqual(different));
}

TEST(Vec3f, EuclideanDistance) {
    Vec3f origin(0.0f, 0.0f, 0.0f), target(1.0f, 0.0f, 0.0f);
    EXPECT_FLOAT_EQ(Vec3f::Distance(origin, target), 1.0f);
}

TEST(Vec3f, CompoundOperations) {
    Vec3f vector(1.0f, 2.0f, 3.0f);
    vector += Vec3f(1.0f, 1.0f, 1.0f);
    EXPECT_FLOAT_EQ(vector.x, 2.0f);
    vector *= 2.0f;
    EXPECT_FLOAT_EQ(vector.x, 4.0f);
}

