// Base class with virtual destructor and virtual function
struct Base {
public:
  virtual ~Base() = default;
  virtual void VirtualMethod() {}
};

// Derived class overriding the virtual function
struct Derived : public Base {
public:
  virtual ~Derived() = default;
  virtual void VirtualMethod() override {}
};

int main() {
  Base obj1;
  obj1.VirtualMethod();
  Derived obj2;
  obj2.VirtualMethod();
  return 0;
}

