Y_UNIT_TEST_SUITE(TSimpleTMTest) {
    TString GenerateLabel(const TString& testName, int lineNumber) {
        return TStringBuilder() << "test case " << testName << " at line " << lineNumber;
    }

    TString AppendTimestamp(const TString& label, time_t timestamp) {
        return TStringBuilder() << label << " (timestamp=" << timestamp << ")";
    }

    TString GenerateLabel(const TString& testName, int lineNumber, time_t timestamp) {
        return AppendTimestamp(GenerateLabel(testName, lineNumber), timestamp);
    }

    void VerifyTmStructure(const TString& context, const struct tm& expected, const NDatetime::TSimpleTM& actual) {
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.Sec, expected.tm_sec, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.Min, expected.tm_min, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.Hour, expected.tm_hour, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.WDay, expected.tm_wday, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.MDay, expected.tm_mday, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.Mon, expected.tm_mon, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.YDay, expected.tm_yday, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.Year, expected.tm_year, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.IsDst, expected.tm_isdst, context);
#ifndef _win_
        UNIT_ASSERT_VALUES_EQUAL_C((int)actual.GMTOff, expected.tm_gmtoff, context);
#endif
    }

    void ValidateSimpleTM(const TString& label,
                          const NDatetime::TSimpleTM& timeObj,
                          time_t timestamp, ui32 year, ui32 month, ui32 day, ui32 hour, ui32 minute, ui32 second) {
        TString context = AppendTimestamp(label, timestamp);
        struct tm referenceTime;
        Zero(referenceTime);
        GmTimeR(&timestamp, &referenceTime);
        VerifyTmStructure(context, referenceTime, timeObj);

        referenceTime = timeObj.AsStructTmUTC();
        time_t reconstructedTime = TimeGM(&referenceTime);
        UNIT_ASSERT_VALUES_EQUAL_C(timestamp, reconstructedTime, context);
        UNIT_ASSERT_VALUES_EQUAL_C(timestamp, timeObj.AsTimeT(), context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)timeObj.RealYear(), year, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)timeObj.RealMonth(), month, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)timeObj.MDay, day, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)timeObj.Hour, hour, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)timeObj.Min, minute, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)timeObj.Sec, second, context);
    }

    Y_UNIT_TEST(TestLeapYearDetection) {
        using namespace NDatetime;
        UNIT_ASSERT(LeapYearAD(2000));
        UNIT_ASSERT(LeapYearAD(2012));
        UNIT_ASSERT(!LeapYearAD(1999));
        UNIT_ASSERT(LeapYearAD(2004));
        UNIT_ASSERT(!LeapYearAD(1900));
    }

    Y_UNIT_TEST(TestDayOfYearConversion) {
        using namespace NDatetime;
        ui32 monthIndex;
        ui32 dayOfMonth;

        for (ui32 dayOfYear = 0; dayOfYear < 365; ++dayOfYear) {
            YDayToMonthAndDay(dayOfYear, false, &monthIndex, &dayOfMonth);
            UNIT_ASSERT_VALUES_EQUAL(dayOfYear, YDayFromMonthAndDay(monthIndex, dayOfMonth, false));
        }

        for (ui32 dayOfYear = 0; dayOfYear < 366; ++dayOfYear) {
            YDayToMonthAndDay(dayOfYear, true, &monthIndex, &dayOfMonth);
            UNIT_ASSERT_VALUES_EQUAL(dayOfYear, YDayFromMonthAndDay(monthIndex, dayOfMonth, true));
        }

        UNIT_ASSERT_EXCEPTION(YDayToMonthAndDay(365, false, &monthIndex, &dayOfMonth), yexception);
        UNIT_ASSERT_EXCEPTION(YDayToMonthAndDay(366, true, &monthIndex, &dayOfMonth), yexception);
    }

    Y_UNIT_TEST(SimpleTMFunctionalityTest) {
        using namespace NDatetime;
        tzset();

        TSimpleTM::New(-1); // Should not cause program termination

        UNIT_ASSERT_VALUES_EQUAL((ui32)0, (ui32)TSimpleTM::New(0));
        UNIT_ASSERT((ui32)TSimpleTM::New(0).IsUTC());

        time_t currentTime = time(nullptr);

        // UTC time tests
        {
            struct tm utcTime;
            Zero(utcTime);
            gmtime_r(&currentTime, &utcTime);

            UNIT_ASSERT_VALUES_EQUAL_C((i64)currentTime, (i64)TSimpleTM::New(currentTime).AsTimeT(), ToString(currentTime));
            UNIT_ASSERT_VALUES_EQUAL_C((i64)currentTime, (i64)TSimpleTM::New(utcTime).AsTimeT(), ToString(currentTime));

            VerifyTmStructure(GenerateLabel("UTC:from_time_t", __LINE__, currentTime),
                              utcTime, TSimpleTM::New(currentTime));
            VerifyTmStructure(GenerateLabel("UTC:from_tm", __LINE__, currentTime),
                              utcTime, TSimpleTM::New(utcTime));

            UNIT_ASSERT(TSimpleTM::New(currentTime).IsUTC());
            UNIT_ASSERT(TSimpleTM::New(utcTime).IsUTC());
        }

        // Local time tests
        {
            struct tm localTime;
            Zero(localTime);
            localtime_r(&currentTime, &localTime);

            UNIT_ASSERT_VALUES_EQUAL((i64)currentTime, (i64)TSimpleTM::NewLocal(currentTime).AsTimeT());
            UNIT_ASSERT_VALUES_EQUAL((i64)currentTime, (i64)TSimpleTM::New(localTime).AsTimeT());

            VerifyTmStructure(GenerateLabel("local:from_time_t", __LINE__, currentTime),
                              localTime, TSimpleTM::NewLocal(currentTime));
            VerifyTmStructure(GenerateLabel("local:from_tm", __LINE__, currentTime),
                              localTime, TSimpleTM::New(localTime));
            VerifyTmStructure(GenerateLabel("local:regenerated_fields", __LINE__, currentTime),
                              localTime, TSimpleTM::New(localTime).RegenerateFields());
            VerifyTmStructure(GenerateLabel("local:set_real_date", __LINE__, currentTime),
                              localTime, TSimpleTM::NewLocal(currentTime).SetRealDate(
                                  localTime.tm_year + 1900,
                                  localTime.tm_mon + 1,
                                  localTime.tm_mday,
                                  localTime.tm_hour,
                                  localTime.tm_min,
                                  localTime.tm_sec,
                                  localTime.tm_isdst));
        }

        // Date arithmetic and manipulation tests
        {
            TSimpleTM testTime = TSimpleTM::New(0);

            testTime.SetRealDate(2012, 3, 30, 5, 6, 7);
            ValidateSimpleTM(GenerateLabel("UTC:set_date_1", __LINE__),
                             testTime, 1333083967, 2012, 3, 30, 5, 6, 7);

            testTime.SetRealDate(2012, 3, 8, 5, 6, 7);
            ValidateSimpleTM(GenerateLabel("UTC:set_date_2", __LINE__),
                             testTime, 1331183167, 2012, 3, 8, 5, 6, 7);

            testTime.SetRealDate(2010, 10, 4, 5, 6, 7);
            ValidateSimpleTM(GenerateLabel("UTC:set_date_3", __LINE__),
                             testTime, 1286168767, 2010, 10, 4, 5, 6, 7);

            testTime.Add(TSimpleTM::F_MON);
            ValidateSimpleTM(GenerateLabel("UTC:add_month", __LINE__),
                             testTime, 1288847167, 2010, 11, 4, 5, 6, 7);

            testTime.Add(TSimpleTM::F_DAY);
            ValidateSimpleTM(GenerateLabel("UTC:add_day", __LINE__),
                             testTime, 1288933567, 2010, 11, 5, 5, 6, 7);

            testTime.Add(TSimpleTM::F_YEAR);
            ValidateSimpleTM(GenerateLabel("UTC:add_year", __LINE__),
                             testTime, 1320469567, 2011, 11, 5, 5, 6, 7);

            for (ui32 i = 0; i < 365; ++i) {
                testTime.Add(TSimpleTM::F_DAY);
            }
            ValidateSimpleTM(GenerateLabel("UTC:365_days_addition", __LINE__),
                             testTime, 1352005567, 2012, 11, 4, 5, 6, 7);

            testTime.Add(TSimpleTM::F_MON, -10);
            ValidateSimpleTM(GenerateLabel("UTC:subtract_months", __LINE__),
                             testTime, 1325653567, 2012, 1, 4, 5, 6, 7);

            testTime.Add(TSimpleTM::F_HOUR, -24 * 4 - 6);
            ValidateSimpleTM(GenerateLabel("UTC:subtract_hours", __LINE__),
                             testTime, 1325286367, 2011, 12, 30, 23, 6, 7);
        }

        // Edge case and leap year handling tests
        {
            TSimpleTM testTime = TSimpleTM::New();

            testTime.SetRealDate(2012, 2, 29);
            ValidateSimpleTM(GenerateLabel("UTC:leap_day", __LINE__),
                             testTime, 1330473600, 2012, 2, 29, 0, 0, 0);

            testTime.SetRealDate(2013, 12, 28);
            ValidateSimpleTM(GenerateLabel("UTC:year_end", __LINE__),
                             testTime, 1388188800, 2013, 12, 28, 0, 0, 0);

            testTime.SetRealDate(2012, 10, 23);
            ValidateSimpleTM(GenerateLabel("UTC:october", __LINE__),
                             testTime, 1350950400, 2012, 10, 23, 0, 0, 0);

            testTime.SetRealDate(2013, 3, 16);
            ValidateSimpleTM(GenerateLabel("UTC:march", __LINE__),
                             testTime, 1363392000, 2013, 3, 16, 0, 0, 0);

            testTime.SetRealDate(2013, 2, 17);
            ValidateSimpleTM(GenerateLabel("UTC:february", __LINE__),
                             testTime, 1361059200, 2013, 2, 17, 0, 0, 0);

            testTime.SetRealDate(2012, 12, 23);
            ValidateSimpleTM(GenerateLabel("UTC:december", __LINE__),
                             testTime, 1356220800, 2012, 12, 23, 0, 0, 0);

            testTime.SetRealDate(2012, 5, 17);
            ValidateSimpleTM(GenerateLabel("UTC:may", __LINE__),
                             testTime, 1337212800, 2012, 5, 17, 0, 0, 0);

            testTime.SetRealDate(2012, 6, 15);
            ValidateSimpleTM(GenerateLabel("UTC:june", __LINE__),
                             testTime, 1339718400, 2012, 6, 15, 0, 0, 0);

            testTime.SetRealDate(2009, 3, 17);
            ValidateSimpleTM(GenerateLabel("UTC:early_year", __LINE__),
                             testTime, 1237248000, 2009, 3, 17, 0, 0, 0);

            testTime.SetRealDate(2013, 8, 12);
            ValidateSimpleTM(GenerateLabel("UTC:august", __LINE__),
                             testTime, 1376265600, 2013, 8, 12, 0, 0, 0);

            testTime.SetRealDate(2015, 12, 11, 10, 9, 8);
            ValidateSimpleTM(GenerateLabel("UTC:specific_time", __LINE__),
                             testTime, 1449828548, 2015, 12, 11, 10, 9, 8);
        }
    }
} // Y_UNIT_TEST_SUITE(TSimpleTMTest)

