#include "single_heap_gtest.hpp"
using namespace rocshmem;

// Test that the heap size is correctly initialized to 1 GiB
TEST_F(SingleHeapTestFixture, unallocated_size_check) {
  EXPECT_EQ(single_heap_.get_size(), 1 << 30);
}

// Test freeing a null pointer (should be safe and no-op)
TEST_F(SingleHeapTestFixture, free_null) {
  void* null_ptr{nullptr};
  single_heap_.free(null_ptr);
}

// Test allocation of zero bytes (should return nullptr and not change used memory)
TEST_F(SingleHeapTestFixture, alloc_0) {
  size_t start_used{single_heap_.get_used()};
  size_t req_size{0};
  void* alloc_result{nullptr};
  single_heap_.malloc(&alloc_result, req_size);
  EXPECT_EQ(alloc_result, nullptr);
  EXPECT_EQ(single_heap_.get_used(), start_used);
  single_heap_.free(alloc_result);
  EXPECT_EQ(single_heap_.get_used(), start_used);
}

// Test allocation of 1 byte with alignment check
TEST_F(SingleHeapTestFixture, alloc_1) {
  size_t start_used{single_heap_.get_used()};
  size_t req_size{1};
  void* alloc_result{nullptr};
  single_heap_.malloc(&alloc_result, req_size);
  EXPECT_NE(alloc_result, nullptr);
  EXPECT_EQ(reinterpret_cast<uintptr_t>(alloc_result) & (ALIGNMENT-1), 0);
  single_heap_.free(alloc_result);
  EXPECT_EQ(single_heap_.get_used(), start_used);
}

