// Global configuration variables
std::uint32_t unpack_config_context     = 0;
std::uint32_t pack_sync_tile_dest_ptr   = 0;
std::uint32_t math_sync_tile_dest_idx   = 0;

#ifdef LLK_TRISC_UNPACK
#include "llk_unpack_AB.h"
#include "llk_unpack_common.h"
#include "params.h"

void execute_kernel(const volatile struct RuntimeParams* cfg)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmt = cfg->formats;
#endif

    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        fmt.unpack_A_src, fmt.unpack_B_src, fmt.unpack_A_dst, fmt.unpack_B_dst,
        FACE_R_DIM, FACE_R_DIM, 4 /* num_faces */, 4 /* num_faces */);

    _llk_unpack_AB_init_<>();

    for (int tile_index = 0; tile_index < cfg->TILE_CNT; ++tile_index)
    {
        _llk_unpack_AB_<>(L1_ADDRESS(cfg->buffer_A[tile_index]), L1_ADDRESS(cfg->buffer_B[tile_index]));
    }
}
#endif

#ifdef LLK_TRISC_MATH
#include "llk_math_common.h"
#include "llk_math_eltwise_binary.h"
#include "params.h"

void execute_kernel(const volatile struct RuntimeParams* cfg)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmt = cfg->formats;
#endif

    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(fmt.math, fmt.math);
    _llk_math_eltwise_binary_init_<ELTWISE_BINARY_OP, BroadcastType::NONE, MATH_FIDELITY>(4, 0);
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    for (int tile_num = 0; tile_num < cfg->TILE_CNT; ++tile_num)
    {
        LLK_ASSERT(
            tile_num < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");

        _llk_math_eltwise_binary_<
            ELTWISE_BINARY_OP,
            BroadcastType::NONE,
            DstSync::SyncHalf,
            is_fp32_dest_acc_en,
            MATH_FIDELITY,
            EltwiseBinaryReuseDestType::NONE>(4, tile_num, false);
    }

    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

void execute_kernel(const volatile struct RuntimeParams* cfg)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmt = cfg->formats;
#endif

#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(fmt.pack_src, fmt.pack_dst, 16 * 16 * 4);
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(fmt.pack_src, fmt.pack_dst, 16 * 16 * 4);
#endif

    _llk_pack_init_<false, false>(fmt.pack_dst);

#ifdef ARCH_BLACKHOLE
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>();
#endif

    _llk_packer_wait_for_math_done_();

    for (int tile_id = 0; tile_id < cfg->TILE_CNT; ++tile_id)
    {
        LLK_ASSERT(
            tile_id < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");

        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(tile_id, L1_ADDRESS(cfg->buffer_Res[tile_id]));
    }

    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

