std::shared_ptr<Stream::stream<std::shared_ptr<Nat>>>
Stream::generate_naturals(std::shared_ptr<Nat> start_value) {
  return stream<std::shared_ptr<Nat>>::ctor::lazy_(
      [=](void) -> std::shared_ptr<Stream::stream<std::shared_ptr<Nat>>> {
