#include <gtest/gtest.h>
#include "ros2_medkit_serialization/service_action_types.hpp"

namespace ros2_medkit_serialization {

class ServiceActionTypesTest : public ::testing::Test {};

TEST_F(ServiceActionTypesTest, GetServiceRequestType) {
  EXPECT_EQ(ServiceActionTypes::get_service_request_type("std_srvs/srv/SetBool"), 
            "std_srvs/srv/SetBool_Request");
}

TEST_F(ServiceActionTypesTest, GetServiceResponseType) {
  EXPECT_EQ(ServiceActionTypes::get_service_response_type("std_srvs/srv/SetBool"), 
            "std_srvs/srv/SetBool_Response");
}

TEST_F(ServiceActionTypesTest, GetActionGoalType) {
  EXPECT_EQ(ServiceActionTypes::get_action_goal_type("example_interfaces/action/Fibonacci"),
            "example_interfaces/action/Fibonacci_Goal");
}

TEST_F(ServiceActionTypesTest, GetActionResultType) {
  EXPECT_EQ(ServiceActionTypes::get_action_result_type("example_interfaces/action/Fibonacci"),
            "example_interfaces/action/Fibonacci_Result");
}

TEST_F(ServiceActionTypesTest, GetActionFeedbackType) {
  EXPECT_EQ(ServiceActionTypes::get_action_feedback_type("example_interfaces/action/Fibonacci"),
            "example_interfaces/action/Fibonacci_Feedback");
}

TEST_F(ServiceActionTypesTest, ParseInterfaceTypeMsg) {
  auto parsed = ServiceActionTypes::parse_interface_type("std_msgs/msg/String");
  ASSERT_TRUE(parsed.has_value());
  EXPECT_EQ(std::get<0>(*parsed), "std_msgs");
  EXPECT_EQ(std::get<1>(*parsed), "msg");
  EXPECT_EQ(std::get<2>(*parsed), "String");
}

TEST_F(ServiceActionTypesTest, ParseInterfaceTypeSrv) {
  auto parsed = ServiceActionTypes::parse_interface_type("std_srvs/srv/SetBool");
  ASSERT_TRUE(parsed.has_value());
  EXPECT_EQ(std::get<0>(*parsed), "std_srvs");
  EXPECT_EQ(std::get<1>(*parsed), "srv");
  EXPECT_EQ(std::get<2>(*parsed), "SetBool");
}

TEST_F(ServiceActionTypesTest, ParseInterfaceTypeAction) {
  auto parsed = ServiceActionTypes::parse_interface_type("example_interfaces/action/Fibonacci");
  ASSERT_TRUE(parsed.has_value());
  EXPECT_EQ(std::get<0>(*parsed), "example_interfaces");
  EXPECT_EQ(std::get<1>(*parsed), "action");
  EXPECT_EQ(std::get<2>(*parsed), "Fibonacci");
}

TEST_F(ServiceActionTypesTest, ParseInterfaceTypeInvalid) {
  EXPECT_FALSE(ServiceActionTypes::parse_interface_type("invalid").has_value());
  EXPECT_FALSE(ServiceActionTypes::parse_interface_type("").has_value());
  EXPECT_FALSE(ServiceActionTypes::parse_interface_type("pkg/type").has_value());
}

TEST_F(ServiceActionTypesTest, IsServiceType) {
  EXPECT_TRUE(ServiceActionTypes::is_service_type("std_srvs/srv/SetBool"));
  EXPECT_FALSE(ServiceActionTypes::is_service_type("std_msgs/msg/String"));
  EXPECT_FALSE(ServiceActionTypes::is_service_type("example_interfaces/action/Fibonacci"));
}

TEST_F(ServiceActionTypesTest, IsActionType) {
  EXPECT_TRUE(ServiceActionTypes::is_action_type("example_interfaces/action/Fibonacci"));
  EXPECT_FALSE(ServiceActionTypes::is_action_type("std_msgs/msg/String"));
  EXPECT_FALSE(ServiceActionTypes::is_action_type("std_srvs/srv/SetBool"));
}

TEST_F(ServiceActionTypesTest, IsMessageType) {
  EXPECT_TRUE(ServiceActionTypes::is_message_type("std_msgs/msg/String"));
  EXPECT_FALSE(ServiceActionTypes::is_message_type("std_srvs/srv/SetBool"));
  EXPECT_FALSE(ServiceActionTypes::is_message_type("example_interfaces/action/Fibonacci"));
}

}  // namespace ros2_medkit_serialization

int main(int argc, char ** argv) {
  testing::InitGoogleTest(&argc, argv);
  return RUN_ALL_TESTS();
}

#include <llarp/config/config.hpp>
#include <common.hpp>
#include <netinet/in.h>

namespace llarp
{
    // Helper function to set in_addr from string representation
    void ip_address_assign(in_addr* addr, const char* str) { inet_aton(str, addr); }

    void Config_Init(py::module& mod)
    {
        using Config_ptr = std::shared_ptr<Config>;

        // Bind the main Config class
        py::class_<Config, Config_ptr>(mod, "Config")
            .def(py::init<std::string>())
            .def_readwrite("router", &Config::router)
            .def_readwrite("network", &Config::network)
            .def_readwrite("connect", &Config::connect)
            .def_readwrite("links", &Config::links)
            .def_readwrite("api", &Config::api)
            .def_readwrite("lokid", &Config::lokid)
            .def_readwrite("bootstrap", &Config::bootstrap)
            .def_readwrite("logging", &Config::logging)
            .def_readwrite("paths", &Config::paths)
            .def("Load", &Config::Load);

        // RouterConfig binding
        py::class_<RouterConfig>(mod, "RouterConfig")
            .def(py::init<>())
            .def_readwrite("minConnectedRouters", &RouterConfig::m_minConnectedRouters)
            .def_readwrite("maxConnectedRouters", &RouterConfig::m_maxConnectedRouters)
            .def_readwrite("netid", &RouterConfig::m_netId)
            .def_readwrite("nickname", &RouterConfig::m_nickname)
            .def_property(
                "dataDir",
                [](RouterConfig& self) { return self.m_dataDir.c_str(); },
                [](RouterConfig& self, std::string dir) { self.m_dataDir = dir; })
            .def_readwrite("blockBogons", &RouterConfig::m_blockBogons)
            .def_readwrite("workerThreads", &RouterConfig::m_workerThreads)
            .def_readwrite("numNetThreads", &RouterConfig::m_numNetThreads)
            .def_readwrite("JobQueueSize", &RouterConfig::m_JobQueueSize);

        // PeerSelectionConfig binding
        py::class_<PeerSelectionConfig>(mod, "PeerSelectionConfig")
            .def(py::init<>())
            .def_readwrite("netmask", &PeerSelectionConfig::m_UniqueHopsNetmaskSize);

        // NetworkConfig binding (with duplicate 'endpointType' removed)
        py::class_<NetworkConfig>(mod, "NetworkConfig")
            .def(py::init<>())
            .def_readwrite("enableProfiling", &NetworkConfig::m_enableProfiling)
            .def_readwrite("endpointType", &NetworkConfig::m_endpointType)
            .def_readwrite("keyfile", &NetworkConfig::m_keyfile)
            .def_readwrite("reachable", &NetworkConfig::m_reachable)
            .def_readwrite("hops", &NetworkConfig::m_Hops)
            .def_readwrite("paths", &NetworkConfig::m_Paths)
            .def_readwrite("snodeBlacklist", &NetworkConfig::m_snodeBlacklist)
            .def_readwrite("mapAddr", &NetworkConfig::m_mapAddrs)
            .def_readwrite("strictConnect", &NetworkConfig::m_strictConnect);

        // ConnectConfig binding
        py::class_<ConnectConfig>(mod, "ConnectConfig")
            .def(py::init<>())
            .def_readwrite("routers", &ConnectConfig::routers);

        // DnsConfig binding
        py::class_<DnsConfig>(mod, "DnsConfig").def(py::init<>());

        // LinksConfig binding with lambda wrappers for adding links
        py::class_<LinksConfig>(mod, "LinksConfig")
            .def(py::init<>())
            .def(
                "addOutboundLink",
                [](LinksConfig& self, std::string _addr) { self.OutboundLinks.emplace_back(std::move(_addr)); })
            .def("addInboundLink", [](LinksConfig& self, std::string _addr) {
                self.InboundListenAddrs.emplace_back(std::move(_addr));
            });

        // ApiConfig binding
        py::class_<ApiConfig>(mod, "ApiConfig")
            .def(py::init<>())
            .def_readwrite("enableRPCServer", &ApiConfig::m_enableRPCServer)
            .def_readwrite("rpcBindAddresses", &ApiConfig::m_rpcBindAddresses);

        // LokidConfig binding
        py::class_<LokidConfig>(mod, "LokidConfig")
            .def(py::init<>())
            .def_readwrite("whitelistRouters", &LokidConfig::whitelistRouters)
            .def_readwrite("ident_keyfile", &LokidConfig::ident_keyfile)
            .def_property(
                "lokidRPCAddr",
                [](LokidConfig& self) { return self.lokidRPCAddr.full_address().c_str(); },
                [](LokidConfig& self, std::string arg) { self.lokidRPCAddr = oxenmq::address(arg); });

        // BootstrapConfig binding
        py::class_<BootstrapConfig>(mod, "BootstrapConfig")
            .def(py::init<>())
            .def_readwrite("seednode", &BootstrapConfig::seednode)
            .def_property(
                "routers",
                [](BootstrapConfig& self) {
                    std::vector<std::string> args;
                    for (const auto& rc : self.routers)
                    {
                        args.emplace_back(rc.pubkey.ToString());
                    }
                    return args;
                },
                [](BootstrapConfig& self, std::vector<std::string> args) {
                    self.routers.clear();
                    for (const auto& arg : args)
                    {
                        RelayContact rc{};
                        if (rc.Read(arg))
                            self.routers.emplace(std::move(rc));
                        else
                            throw std::invalid_argument{"cannot read rc from " + arg};
                    }
                });

        // LoggingConfig binding
        py::class_<LoggingConfig>(mod, "LoggingConfig")
            .def(py::init<>())
            .def_readwrite("m_logType", &LoggingConfig::m_logType)
            .def_readwrite("m_logFile", &LoggingConfig::m_logFile);

        // sockaddr_in binding
        py::class_<sockaddr_in>(mod, "sockaddr_in")
            .def_readwrite("sin_family", &sockaddr_in::sin_family)
            .def_readwrite("sin_port", &sockaddr_in::sin_port)
            .def_readwrite("sin_addr", &sockaddr_in::sin_addr);

        // in_addr binding with helper method
        py::class_<in_addr>(mod, "in_addr").def("set", &ip_address_assign);
    }
}  // namespace llarp

#include <unitree/robot/channel/channel_subscriber.hpp>
#include <unitree/common/time/time_tool.hpp>
#include "HelloWorldData.hpp"

#define MESSAGE_TOPIC "TopicHelloWorld"
using namespace unitree::robot;
using namespace unitree::common;

void MessageHandler(const void* data)
{
    const HelloWorldData::Msg* message = (const HelloWorldData::Msg*)data;
    std::cout << "userID:" << message->userID() << ", message:" << message->message() << std::endl;
}

int main()
{
    ChannelFactory::Instance()->Init(0);
    ChannelSubscriber<HelloWorldData::Msg> receiver(MESSAGE_TOPIC);
    receiver.InitChannel(MessageHandler);

    sleep(5);
    receiver.CloseChannel();
    std::cout << "reseted. sleep 3" << std::endl;
    sleep(3);

    receiver.InitChannel();
    sleep(5);
    receiver.CloseChannel();
    std::cout << "reseted. sleep 3" << std::endl;
    sleep(3);

    receiver.InitChannel();
    while (true)
    {
        sleep(10);
