#include "VarSet.h"
using std::cout;
using std::cerr;
using std::endl;
using std::string;

int main() {
  VarSet setA, setB, setC, setD;
  cout << VarSet::UniverseSet() << '\n';
  cout << VarSet::EmptySet() << '\n';

  setA = VarSet::EmptySet();
  setB = VarSet::EmptySet();

  cout << VarSet::Diff(setA, setB) << '\n';
  cout << VarSet::Diff(setB, setA) << '\n';
  cout << VarSet::Union(setA, setB) << '\n';
  cout << VarSet::Union(setB, setA) << '\n';
  cout << VarSet::Intersect(setA, setB) << '\n';
  cout << VarSet::Intersect(setB, setA) << '\n';
  cout << setA << '\n';
  cout << setB << '\n';
  cout << VarSet::Eq(setA, setB) << '\n';

  setC = VarSet::Union(VarSet::Diff(setA, setB), 
                       VarSet::Union(VarSet::Diff(setB, setA), 
                                     VarSet::Intersect(setA, setB)));
  setD = VarSet::Union(setA, setB);
  cout << setC << " == " << setD << ": " << VarSet::Eq(setC, setD) << '\n';

  setA.Insert("x");
  setA.Insert("y");
  setA.Insert("z");
  setA.Insert("w");

  setB = mkVarSet("z", "w", "u", "v");

  cout << VarSet::Diff(setA, setB) << '\n';
  cout << VarSet::Diff(setB, setA) << '\n';
  cout << VarSet::Union(setA, setB) << '\n';
  cout << VarSet::Union(setB, setA) << '\n';
  cout << VarSet::Intersect(setA, setB) << '\n';
  cout << VarSet::Intersect(setB, setA) << '\n';
  cout << setA << '\n';
  cout << setB << '\n';
  cout << VarSet::Eq(setA, setB) << '\n';

  setC = VarSet::Union(VarSet::Diff(setA, setB), 
                       VarSet::Union(VarSet::Diff(setB, setA), 
                                     VarSet::Intersect(setA, setB)));
  setD = VarSet::Union(setA, setB);
  cout << setC << " == " << setD << ": " << VarSet::Eq(setC, setD) << '\n';

  return(0);
}

