#include "test.h"

// Additional coverage for the Text class in apLib
TEST_CASE("string::Text") {
    SECTION("Basic operations") {
        SECTION("Direct initialization") {
            Text sample = "sample";
            REQUIRE(!Txtcmp(sample, "sample"));
            REQUIRE(sample);
        }
        SECTION("Move assignment operator") {
            Text src = "Hello";
            Text dest = std::move(src);
            REQUIRE(dest == "Hello");
            REQUIRE(src == "");
            Text another = std::move(dest);
            REQUIRE(src == "");
            REQUIRE(another == "Hello");
        }
        SECTION("Move constructor usage") {
            Text original = "Hello";
            Text copy(std::move(original));
            REQUIRE(copy == "Hello");
            REQUIRE(original == "");
            Text final = std::move(copy);
            REQUIRE(original == "");
            REQUIRE(final == "Hello");
        }
        SECTION("Relational comparisons") {
            REQUIRE(Text("apple") < Text("banana"));
            REQUIRE(Text("cherry") > Text("apricot"));
            REQUIRE(!(Text("date") > Text("date")));
            REQUIRE(!(Text("fig") < Text("fig")));
        }
        SECTION("Case conversion - lowercase") {
            REQUIRE(Text("STOP SHOUTING").lowerCase() == "stop shouting");
        }
        SECTION("Case conversion - uppercase") {
            REQUIRE(Text("whispering").upperCase() == "WHISPERING");
        }
        SECTION("Whitespace trimming") {
            REQUIRE(Text("   leading and trailing spaces   ").trim() ==
                    "leading and trailing spaces");
        }
        SECTION("Quote removal") {
            REQUIRE(Text("\"quoted\"").removeQuotes() == "quoted");
        }
        SECTION("String splitting") {
            auto parts = Text(",a,b,c,d,").split(',');
            REQUIRE(parts == std::vector<Text>{"a", "b", "c", "d"});
            parts = Text(",a,b,c,d,").split(',', true);
            REQUIRE(parts == std::vector<Text>{"", "a", "b", "c", "d", ""});
        }
        SECTION("Joining strings") {
            REQUIRE(concat(std::vector<Text>{"x", "y", "z"}, "-") ==
                    "x-y-z");
            REQUIRE(concat(std::vector<Text>{"x", "y", "z"}, "") ==
                    "xyz");
            REQUIRE(concat(std::vector<Text>{"x", "y", "", "z"}, "-", false) ==
                    "x-y-z");
            REQUIRE(concat(std::vector<Text>{"x", "y", "", "z"}, "-", true) ==
                    "x-y--z");
        }
        SECTION("Suffix checking") {
            REQUIRE(Text("The quick brown fox").endsWith("quick brown fox"));
            REQUIRE(Text("The quick brown fox").endsWith("uick brown fox"));
            REQUIRE(Text("The quick brown fox").endsWith("ick brown fox"));
            REQUIRE(Text("The quick brown fox").endsWith("ck brown fox"));
            REQUIRE(Text("The quick brown fox").endsWith("ox"));
            REQUIRE(!Text("The quick brown fox").endsWith(""));
            REQUIRE(Text("The quick brown fox").endsWith("Quick Brown Fox", false));
            REQUIRE(Text("The quick brown fox").endsWith("UICK BROWN FOX", false));
            REQUIRE(Text("The quick brown fox").endsWith("ICK BROWN FOX", false));
            REQUIRE(Text("The quick brown fox").endsWith("CK BROWN FOX", false));
            REQUIRE(Text("The quick brown fox").endsWith("OX", false));
            REQUIRE(!Text("The quick brown fox").endsWith("Quick Brown Fox", true));
            REQUIRE(!Text("The quick brown fox").endsWith("UICK BROWN FOX", true));
            REQUIRE(!Text("The quick brown fox").endsWith("ICK BROWN FOX", true));
            REQUIRE(!Text("The quick brown fox").endsWith("CK BROWN FOX", true));
            REQUIRE(!Text("The quick brown fox").endsWith("OX", true));
        }
        SECTION("Prefix checking") {
            REQUIRE(Text("The quick brown fox").startsWith("The quick brown fox"));
            REQUIRE(Text("The quick brown fox").startsWith("The quick "));
            REQUIRE(Text("The quick brown fox").startsWith("The "));
            REQUIRE(Text("The quick brown fox").startsWith("T"));
            REQUIRE(!Text("The quick brown fox").startsWith(""));
            REQUIRE(Text("The quick brown fox").startsWith("the Quick brown fox", false));
            REQUIRE(Text("The quick brown fox").startsWith("the quick ", false));
            REQUIRE(Text("The quick brown fox").startsWith("THE", false));
            REQUIRE(Text("The quick brown fox").startsWith("t", false));
            REQUIRE(!Text("The quick brown fox").startsWith("the Quick brown fox", true));
            REQUIRE(!Text("The quick brown fox").startsWith("the quick ", true));
            REQUIRE(!Text("The quick brown fox").startsWith("THE", true));
            REQUIRE(!Text("The quick brown fox").startsWith("t", true));
        }
        SECTION("Substring removal") {
            REQUIRE(Text("REMOVE THIS PART").remove("THIS ") == "REMOVE PART");
            REQUIRE(Text("REMOVE THIS THIS THIS PART").remove("THIS ") ==
                    "REMOVE PART");
            REQUIRE(Text("PREFIX: REMOVE THIS PART")
                        .remove("PREFIX: ", " THIS") == "REMOVE PART");
        }
        SECTION("Substring replacement") {
            REQUIRE(Text("REPLACE THIS PART").replace("THIS ", "THAT ") ==
                    "REPLACE THAT PART");
            REQUIRE(Text("REPLACE THIS THIS THIS PART").replace("THIS ", "") ==
                    "REPLACE  PART");
            REQUIRE(Text("ORIGINAL: REPLACE THIS PART")
                        .replace("ORIGINAL: ", "MODIFIED: ") ==
                    "MODIFIED: REPLACE THIS PART");
        }
        SECTION("Character substitution") {
            REQUIRE(Text("ABCDEFG").replaceAnyOf("ACEG", 'Z') == "ZBZDZFZ");
        }
        SECTION("Append with rvalue reference") {
            Text left;
            Text right("value");
            left.append(_mv(right));
            REQUIRE(left == "value");
            REQUIRE(right.empty());
        }
        SECTION("Operator += with rvalue reference") {
            Text lhs;
            Text rhs("value");
            lhs += _mv(rhs);
            REQUIRE(lhs == "value");
            REQUIRE(rhs.empty());
        }
        SECTION("Substring extraction") {
            using string::npos;
            Text text("magnificent");
            auto check = [&](size_t offset, size_t len, TextView expected) {
                REQUIRE(text.substr(offset, len) == expected);
                REQUIRE(text.substrView(offset, len) == expected);
            };
            check(0, 0, {});
            check(0, npos, text);
            check(text.length(), 100, {});
            check(0, 5, "magic"_tv);
            check(1, 6, "agnifi"_tv);
            check(7, 3, "ent"_tv);
            check(7, 4, "ent"_tv);
        }
    }

#if WIN32
    SECTION("Wide string handling") {
        SECTION("Implicit conversion") {
            Utf16 wide = L"wide";
            REQUIRE(Utf16eql(static_cast<const Utf16Chr *>(wide), L"wide"));
            REQUIRE(wide);
        }
        SECTION("Move assignment") {
            Utf16 source = L"World";
            Utf16 target = std::move(source);
            REQUIRE(target == L"World");
            REQUIRE(source == L"");
            Utf16 third = std::move(target);
            REQUIRE(source == L"");
            REQUIRE(third == L"World");
        }
        SECTION("Move construction") {
            Utf16 init = L"World";
            Utf16 copy(init);
            // Note: This line intentionally uses move semantics as in original
            Utf16 moved(std::move(init));
            REQUIRE(moved == L"World");
            REQUIRE(init == L"");
            Utf16 final_move = std::move(moved);
            REQUIRE(init == L"");
            REQUIRE(final_move == L"World");
        }
        SECTION("Wide string comparison") {
            REQUIRE(Utf16(L"alpha") < Utf16(L"beta"));
            REQUIRE(Utf16(L"gamma") > Utf16(L"delta"));
            REQUIRE(!(Utf16(L"epsilon") > Utf16(L"epsilon")));
            REQUIRE(!(Utf16(L"zeta") < Utf16(L"zeta")));
        }
        SECTION("Wide case conversion") {
            REQUIRE(Utf16(L"LOUD NOISES").lowerCase() == L"loud noises");
            REQUIRE(Utf16(L"soft sounds").upperCase() == L"SOFT SOUNDS");
        }
        SECTION("Wide trim") {
            Utf16 padded = L"   padded spaces   ";
            padded.trim();
            REQUIRE(padded == L"padded spaces");
        }
        SECTION("Wide quote removal") {
            REQUIRE(Utf16(L"\"data\"").removeQuotes() == L"data");
        }
        SECTION("Wide split") {
            auto fields = Utf16(L",one,two,three,").split(L',');
            REQUIRE(fields == std::vector<Utf16>{L"one", L"two", L"three"});
            fields = Utf16(L",one,two,three,").split(L',', true);
            REQUIRE(fields == std::vector<Utf16>{L"", L"one", L"two", L"three", L""});
        }
        SECTION("Wide suffix/prefix checks") {
            REQUIRE(Utf16(L"Sample text here").endsWith(L"text here"));
            REQUIRE(Utf16(L"Sample text here").startsWith(L"Sample "));
            REQUIRE(!Utf16(L"Sample text here").endsWith(L""));
            REQUIRE(!Utf16(L"Sample text here").startsWith(L""));
        }
        SECTION("Wide equals") {
            REQUIRE(Utf16eql(L"Match this", L"Match this"));
            REQUIRE(Utf16ieql(L"Match this", L"match THIS"));
            REQUIRE(!Utf16eql(L"Match this", L"match this"));
        }
        SECTION("Wide remove/replace") {
            REQUIRE(Utf16(L"DELETE THIS").remove(L"THIS ") == L"DELETE");
            REQUIRE(Utf16(L"CHANGE THIS TO THAT").replace(L"THIS TO ", L"THAT ") ==
                    L"CHANGE THAT");
        }
    }
