TEST(HexDumpTest, PointerExample) {
  std::shared_ptr<Builder> builder = Parser::fromJson("\"foobar\"");
  std::ostringstream output;
  Slice slice = builder->slice();
  output << HexDump(slice);
  EXPECT_EQ("0x86 0x66 0x6f 0x6f 0x62 0x61 0x72", output.str());
  EXPECT_EQ("0x86 0x66 0x6f 0x6f 0x62 0x61 0x72",
            HexDump(builder->slice()).toString());
}

TEST(HexDumpTest, NoneValue) {
  std::ostringstream output;
  output << HexDump(Slice::noneSlice());
  EXPECT_EQ("0x00", output.str());
  EXPECT_EQ("0x00", HexDump(Slice::noneSlice()).toString());
}

