// Writes configuration flags and scalar parameters to file (append mode)
void stateOptions::recordParameters()
{
    std::string temp_str;
    std::ofstream out_file(std::string(output_path + "/parameter_list.txt"), std::ios::app);

    temp_str = use_fej ? "true" : "false";
    out_file << "use_fej: " << temp_str << std::endl;

    temp_str = calib_cam_extrinsics ? "true" : "false";
    out_file << "calib_cam_extrinsics: " << temp_str << std::endl;

    temp_str = calib_cam_intrinsics ? "true" : "false";
    out_file << "calib_cam_intrinsics: " << temp_str << std::endl;

    temp_str = calib_cam_timeoffset ? "true" : "false";
    out_file << "calib_cam_timeoffset: " << temp_str << std::endl;

    temp_str = calib_imu_bias_cov ? "true" : "false";
    out_file << "calib_imu_bias_cov: " << temp_str << std::endl;

    temp_str = calib_imu_scale_sens ? "true" : "false";
    out_file << "calib_imu_scale_sens: " << temp_str << std::endl;

    switch (imu_type)
    {
        case 0:
            temp_str = "kalibr";
            break;
        case 1:
            temp_str = "rpng";
            break;
        default:
            temp_str = "unknown";
            break;
    }
    out_file << "imu_type: " << temp_str << std::endl;

    out_file << "max_clone_count: " << max_clone_count << std::endl;
    out_file << "max_slam_landmarks: " << max_slam_landmarks << std::endl;
    out_file << "max_slam_update_size: " << max_slam_update_size << std::endl;
    out_file << "max_msckf_update_size: " << max_msckf_update_size << std::endl;

    out_file.close();
}

