    temp_str = optimize_calib_in_dyn_mle ? "true" : "false";
    out_file << "optimize_calib_in_dyn_mle: " << temp_str << std::endl;

    out_file << "dyn_mle_max_iterations: " << dyn_mle_max_iterations << std::endl;
    out_file << "dyn_mle_max_threads: " << dyn_mle_max_threads << std::endl;
    out_file << std::fixed << "dyn_mle_max_duration: " << dyn_mle_max_duration << std::endl;
    out_file << "dyn_num_poses: " << dyn_num_poses << std::endl;

    out_file << std::fixed << "dyn_min_rotation_deg: " << dyn_min_rotation_deg << std::endl;
    out_file << std::fixed << "dyn_rot_inflation_factor: " << dyn_rot_inflation_factor << std::endl;
    out_file << std::fixed << "dyn_vel_inflation_factor: " << dyn_vel_inflation_factor << std::endl;
    out_file << std::fixed << "dyn_gyro_bias_inflation: " << dyn_gyro_bias_inflation << std::endl;
    out_file << std::fixed << "dyn_accel_bias_inflation: " << dyn_accel_bias_inflation << std::endl;
    out_file << std::fixed << "dyn_min_reciprocal_cond: " << dyn_min_reciprocal_cond << std::endl;
    out_file << std::fixed << "dyn_bias_gyro: " << dyn_bias_gyro.transpose() << std::endl;
    out_file << std::fixed << "dyn_bias_accel: " << dyn_bias_accel.transpose() << std::endl;

    out_file << std::fixed << "gyro_noise_sigma: " << gyro_noise_sigma << std::endl;
    out_file << std::fixed << "gyro_bias_noise_sigma: " << gyro_bias_noise_sigma << std::endl;
    out_file << std::fixed << "accel_noise_sigma: " << accel_noise_sigma << std::endl;
    out_file << std::fixed << "accel_bias_noise_sigma: " << accel_bias_noise_sigma << std::endl;
    out_file << std::fixed << "pixel_noise_sigma: " << pixel_noise_sigma << std::endl;
    out_file << std::fixed << "earth_gravity: " << earth_gravity << std::endl;

    temp_str = subsample_cameras ? "true" : "false";
    out_file << "subsample_cameras: " << temp_str << std::endl;

    out_file << std::fixed << "cam_imu_delay: " << cam_imu_delay << std::endl;

    for (int cam_idx = 0; cam_idx < 2; ++cam_idx)
    {
        if (cam_idx == 0) out_file << "left camera config: " << std::endl;
        else out_file << "right camera config: " << std::endl;

        out_file << std::fixed << "camera intrinsics: " << camera_intrinsics[cam_idx]->getValue().transpose() << std::endl;

        Eigen::Matrix<double, 3, 3> K_mat = camera_intrinsics[cam_idx]->getK();
        out_file << std::fixed << "camera_k_OPENCV: "
                 << K_mat(0, 0) << " " << K_mat(0, 1) << " " << K_mat(0, 2) << "\n"
                 << K_mat(1, 0) << " " << K_mat(1, 1) << " " << K_mat(1, 2) << "\n"
                 << K_mat(2, 0) << " " << K_mat(2, 1) << " " << K_mat(2, 2) << std::endl;

        Eigen::Matrix<double, 4, 1> D_vec = camera_intrinsics[cam_idx]->getD();
        out_file << std::fixed << "camera_d_OPENCV: "
                 << D_vec(0) << " " << D_vec(1) << " " << D_vec(2) << " " << D_vec(3) << std::endl;

        out_file << "image width: " << camera_intrinsics[cam_idx]->width() << std::endl;
        out_file << "image height: " << camera_intrinsics[cam_idx]->height() << std::endl;

        out_file << std::fixed << "camera extrinsics: " << camera_extrinsics[cam_idx].transpose() << std::endl;
    }

    out_file.close();
}

