                 << D_vec(0) << " " << D_vec(1) << " " << D_vec(2) << " " << D_vec(3) << std::endl;

        out_file << "image width: " << camera_intrinsics[cam_id]->width() << std::endl;
        out_file << "image height: " << camera_intrinsics[cam_id]->height() << std::endl;

        out_file << std::fixed << "camera extrinsics: " << camera_extrinsics[cam_id].transpose() << std::endl;
    }

    temp_str = apply_mask ? "true" : "false";
    out_file << "apply_mask: " << temp_str << std::endl;

    temp_str = subsample_cameras ? "true" : "false";
    out_file << "subsample_cameras: " << temp_str << std::endl;

    out_file << "feature_count: " << feature_count << std::endl;
    out_file << "corner_detector_thresh: " << corner_detector_thresh << std::endl;
    out_file << "patch_width: " << patch_width << std::endl;
    out_file << "patch_height: " << patch_height << std::endl;
    out_file << "min_corner_dist: " << min_corner_dist << std::endl;

    switch (histogram_mode)
    {
        case 0:
            temp_str = "none";
            break;
        case 1:
            temp_str = "histogram";
            break;
        case 2:
            temp_str = "clahe";
            break;
        default:
            temp_str = "default";
            break;
    }
    out_file << "histogram_mode: " << temp_str << std::endl;

    out_file << std::fixed << "tracking_rate: " << tracking_rate << std::endl;

    featinit_opts.recordParameters();
    out_file.close();
}

