TEST(IntervalTests, FromCString_Variant) {
    interval_t output;
    output = Interval::fromCString("5 years 3 months 15 days 2 hours 5 minutes 15 us",
        strlen("5 years 3 months 15 days 2 hours 5 minutes 15 us"));
    EXPECT_EQ(output.months, 63);
    EXPECT_EQ(output.days, 15);
    EXPECT_EQ(output.micros, 7410000015);

    output = Interval::fromCString("25 days 36 hours 8 minutes 120 us",
        strlen("25 days 36 hours 8 minutes 120 us"));
    EXPECT_EQ(output.months, 0);
    EXPECT_EQ(output.days, 25);
    EXPECT_EQ(output.micros, 223680000120);

    output = Interval::fromCString(
        "1 year 20 days     4 years 24 hours 6 minutes 140 us 26 days 16 months 10 minutes",
        strlen(
            "1 year 20 days     4 years 24 hours 6 minutes 140 us 26 days 16 months 10 minutes"));
    EXPECT_EQ(output.months, 73);
    EXPECT_EQ(output.days, 46);
    EXPECT_EQ(output.micros, 87360000140);

    output = Interval::fromCString("3 years 2 months 10 days 02:03:00.000015",
        strlen("3 years 2 months 10 days 02:03:00.000015"));
    EXPECT_EQ(output.months, 38);
    EXPECT_EQ(output.days, 10);
    EXPECT_EQ(output.micros, 31104000015);

    output = Interval::fromCString("1 year 6 months 14 days 01:02:03",
        strlen("1 year 6 months 14 days 01:02:03"));
    EXPECT_EQ(output.months, 18);
    EXPECT_EQ(output.days, 14);
    EXPECT_EQ(output.micros, 50532000000);
}

TEST(IntervalTests, toString_Variant) {
    std::string result_str;
    result_str = Interval::toString(
        Interval::fromCString("2 years 3 months 14 days 350 microseconds 10 seconds",
            strlen("2 years 3 months 14 days 350 microseconds 10 seconds")));
    EXPECT_EQ(result_str, "2 years 3 months 14 days 00:00:10.00035");

    result_str = Interval::toString(
        Interval::fromCString("2 hours 1 day 15 years 400 microseconds 100 seconds",
            strlen("2 hours 1 day 15 years 400 microseconds 100 seconds")));
    EXPECT_EQ(result_str, "15 years 1 day 02:01:40.0004");
}

