/// @brief Reboot system using ACPI or triple fault mechanism.
/// @return This function never returns as it reboots the system.
Void ACPIFactoryInterface::Reboot() {
  asm volatile(
      ".intel_syntax noprefix; "
      "hw_reboot_sequence:; "
      "cli; "
      "poll_kbd_controller: ; "
      "in al,0x64 ; "
      "test al,0x02 ; "
      "jnz poll_kbd_controller ; "
      "mov al,0xD1 ; "
      "out 0x64,al ; "
      "poll_output_buffer: ; "
      "in al,0x64 ; "
      "test al,0x02 ; "
      "jnz poll_output_buffer ; "
      "mov al,0xFE ; "
      "out 0x60,al ; "
      "xor rax,rax ; "
      "lidt [rax] ; "
      "forever_halt: ; "
      "jmp forever_halt ; "
      ".att_syntax; ");
}
