// Verify boolean constant handling
void verify_boolean_literals(SMTParser::ParserPtr& parser) {
    std::cout << "=== Validating Boolean Literals ===" << std::endl;

    auto t = parser->mkExpr("true");
    assert(t && t->isTrue() && !t->isFalse());
    std::cout << "Expression: true" << std::endl;
    std::cout << "  Output: " << parser->toString(t) << std::endl;
    std::cout << "  evaluates to true: yes" << std::endl;
    std::cout << "  evaluates to false: no" << std::endl << std::endl;

    auto f = parser->mkExpr("false");
    assert(f && f->isFalse() && !f->isTrue());
    std::cout << "Expression: false" << std::endl;
    std::cout << "  Output: " << parser->toString(f) << std::endl;
    std::cout << "  evaluates to true: no" << std::endl;
    std::cout << "  evaluates to false: yes" << std::endl << std::endl;
}

// Validate logical connectives (results should be true/false)
void validate_logical_connectives(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> test_cases = {
        {"(not true)", false},
        {"(not false)", true},
        {"(and true true)", true},
        {"(and true false)", false},
        {"(and false false)", false},
        {"(or true true)", true},
        {"(or true false)", true},
        {"(or false false)", false},
        {"(=> true true)", true},
        {"(=> true false)", false},
        {"(=> false true)", true},
        {"(=> false false)", true},
        {"(xor true true)", false},
        {"(xor true false)", true},
        {"(xor false false)", false}
    };

    std::cout << "=== Validating Logical Connectives ===" << std::endl;
    for (const auto& item : test_cases) {
        std::cout << "Expression: " << item.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(item.first);
        assert(evaluation);
        assert(evaluation->isTrue() == item.second || evaluation->isFalse() == !item.second);
        std::cout << "  Output: " << parser->toString(evaluation) << std::endl;
        std::cout << std::endl;
    }
}

// Evaluate compound boolean expressions
void evaluate_compound_expressions(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> scenarios = {
        {"(and (or true false) (not false))", true},
        {"(or (and true false) (not true))", false},
        {"(=> (or true false) (and true true))", true},
        {"(xor (not false) (and true false))", true},
        {"(and (=> true false) (or false true))", false},
        {"(not (and (or true false) (=> false true)))", false}
    };

    std::cout << "=== Evaluating Compound Expressions ===" << std::endl;
    for (const auto& scenario : scenarios) {
        std::cout << "Expression: " << scenario.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> outcome = parser->mkExpr(scenario.first);
        assert(outcome);
        assert(outcome->isTrue() == scenario.second || outcome->isFalse() == !scenario.second);
        std::cout << "  Output: " << parser->toString(outcome) << std::endl;
        std::cout << std::endl;
    }
}

int main() {
    std::cout << "======= Boolean Logic Verification Suite =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    verify_boolean_literals(parser);
    validate_logical_connectives(parser);
    evaluate_compound_expressions(parser);

    return 0;
}

