        "    Tensor! out, bool silu_activation, Tensor? cache_seqlens,"
        "    Tensor? conv_state_indices) -> ()");
    ops.impl("causal_conv1d_update", torch::kCUDA, make_pytorch_shim(&causal_conv1d_update));
