namespace autolink {

// Test Time class constructor and basic operations
TEST(TimeTest, constructor) {
  Time timestamp(200UL);
  EXPECT_EQ(200UL, timestamp.ToNanosecond());
  timestamp = Time(2.2);
  EXPECT_EQ(2200000000UL, timestamp.ToNanosecond());
  EXPECT_DOUBLE_EQ(2.2, timestamp.ToSecond());
  timestamp = Time(2, 2);
  EXPECT_EQ(2000000002UL, timestamp.ToNanosecond());
  EXPECT_DOUBLE_EQ(2.000000002, timestamp.ToSecond());
  Time timestamp_copy(timestamp);
  EXPECT_EQ(timestamp, timestamp_copy);
}

// Test comparison and arithmetic operators for Time
TEST(TimeTest, operators) {
  Time start_time(150);
  Duration interval(250);
  Time end_time(400);
  EXPECT_NE(start_time, end_time);
  EXPECT_LT(start_time, end_time);
  EXPECT_LE(start_time, end_time);
  EXPECT_GT(end_time, start_time);
  EXPECT_GE(end_time, start_time);
  EXPECT_EQ(start_time + interval, end_time);
  EXPECT_EQ(end_time - interval, start_time);
  EXPECT_EQ(start_time += interval, end_time);
  EXPECT_GE(start_time, end_time);
  EXPECT_LE(start_time, end_time);
  EXPECT_EQ(Time(150), start_time -= interval);
}

// Test string representation of Time objects
TEST(TimeTest, to_string) {
  Time high_precision_time(1531225311123456789UL);
  std::cout << high_precision_time.ToString().c_str() << std::endl;
  Time medium_precision_time(1531225311000006789UL);
  std::cout << medium_precision_time.ToString().c_str() << std::endl;
}

// Test current time retrieval
TEST(TimeTest, now) { 
    std::cout << "Current Time: " << Time::Now() << std::endl; 
}

// Test zero-time detection and special constants
TEST(TimeTest, is_zero) {
  Time default_time;
  EXPECT_TRUE(default_time.IsZero());
  EXPECT_FALSE(Time::MAX.IsZero());
  EXPECT_TRUE(Time::MIN.IsZero());
}

