u32 PPCReadFpscr() 
{
    union FpscrUnion reg;
    asm {
        mffs fp31
        stfd fp31, reg.f;
    }
    return reg.bits.control; 
}

void PPCWriteFpscr(register u32 value) 
{
    union FpscrUnion reg;
    asm {
        li    r4, 0
        stw   r4, reg.bits.padding;
        stw   value, reg.bits.control
        lfd   fp31, reg.f
        mtfsf 0xff, fp31
    }
}

