// Function to copy the sign of y to x for float values
float copysignf(float x, float y)
{
    union { float f; uint32_t i; } uX = {x}, uY = {y};
    uX.i &= 0x7FFFFFFF;
    uX.i |= uY.i & 0x80000000;
    return uX.f;
}

