#include <iostream>

// Simple calculator for basic arithmetic operations
int main() {
    int num1, num2, result, choice;
    char continueChoice;

start:
    std::cout << "Make a choice, what do you want to do:\n";
    std::cout << "1. Addition of two numbers\n";
    std::cout << "2. Subtraction of two numbers\n";
    std::cout << "3. Square of a number\n";
    std::cout << "4. Cube of a number\n";
    std::cin >> choice;

    switch (choice) {
        case 1:
            std::cout << "Enter any two numbers: ";
            std::cin >> num1 >> num2;
            result = num1 + num2;
            std::cout << "Sum of two numbers = " << result << "\n";
            break;

        case 2:
            std::cout << "Enter any two numbers: ";
            std::cin >> num1 >> num2;
            result = num1 - num2;
            std::cout << "Difference of two numbers = " << result << "\n";
            break;

        case 3:
            std::cout << "Enter a number: ";
            std::cin >> num1;
            result = num1 * num1;
            std::cout << "Square of the number = " << result << "\n";
            break;

        case 4:
            std::cout << "Enter a number: ";
            std::cin >> num1;
            result = num1 * num1 * num1;
            std::cout << "Cube of the number = " << result << "\n";
            break;

        default:
            std::cout << "Invalid choice!\n";
            break;
    }

    std::cout << "Do you want to continue? (y/n): ";
    std::cin >> continueChoice;

    if (continueChoice == 'y' || continueChoice == 'Y') {
        goto start;
    }

    return 0;
}

