// Structure to hold syscall return value and error code
struct syscall_result {
    uintptr_t value;
    uintptr_t error_code;
};

syscall_result gccgoExecuteSyscall(uintptr_t op, uintptr_t p1, uintptr_t p2, uintptr_t p3, uintptr_t p4, uintptr_t p5, uintptr_t p6, uintptr_t p7, uintptr_t p8, uintptr_t p9)
  __asm__(SYM_PREFIX GOPKGPATH ".executeSyscall");

syscall_result
gccgoExecuteSyscall(uintptr_t op, uintptr_t p1, uintptr_t p2, uintptr_t p3, uintptr_t p4, uintptr_t p5, uintptr_t p6, uintptr_t p7, uintptr_t p8, uintptr_t p9)
{
    syscall_result res;
    errno = 0;
    res.value = syscall(op, p1, p2, p3, p4, p5, p6, p7, p8, p9);
    res.error_code = errno;
    return res;
}

uintptr_t gccgoExecuteSyscallNoErr(uintptr_t op, uintptr_t p1, uintptr_t p2, uintptr_t p3, uintptr_t p4, uintptr_t p5, uintptr_t p6, uintptr_t p7, uintptr_t p8, uintptr_t p9)
  __asm__(SYM_PREFIX GOPKGPATH ".executeSyscallNoErr");

uintptr_t
gccgoExecuteSyscallNoErr(uintptr_t op, uintptr_t p1, uintptr_t p2, uintptr_t p3, uintptr_t p4, uintptr_t p5, uintptr_t p6, uintptr_t p7, uintptr_t p8, uintptr_t p9)
{
    return syscall(op, p1, p2, p3, p4, p5, p6, p7, p8, p9);
}

