#include "Misc/AutomationTest.h"

BEGIN_DEFINE_SPEC(AutomationSpec, "System.Automation.Spec", EAutomationTestFlags::EngineFilter | EAutomationTestFlags::ApplicationContextMask)
	bool bTestFlag;
	FString ExecutionSequence; 
END_DEFINE_SPEC()

void AutomationSpec::Define()
{
	Describe("A top-level description block 1", [this]()
	{
		It("includes a test case with an assertion", [this]()
		{
			bTestFlag = true;
			TestEqual("TestFlag", bTestFlag, true);
		});
	});

	Describe("A top-level description block 2", [this]()
	{
		BeforeEach([&]()
		{
			bTestFlag = false;
		});
		xIt("skips disabled test cases", [this]()
		{
			TestEqual("TestFlag", bTestFlag, true);
		});
		xDescribe("with disabled nested groups", [this]()
		{
			It("does not execute tests inside those groups", [this]()
			{
				TestEqual("TestFlag", bTestFlag, true);
			});
		});
	});

	Describe("A test group using setup and teardown", [this]()
	{
		BeforeEach([this]()
		{
			ExecutionSequence = TEXT("INIT");
		});
		It("executes setup before each test and teardown after each test", [this]()
		{
			TestEqual("ExecutionSequence", ExecutionSequence, TEXT("INIT"));
		});
		AfterEach([this]()
		{
			ExecutionSequence += TEXT("_END");
			TestEqual("ExecutionSequence", ExecutionSequence, TEXT("INIT_END"));
		});
	});

	Describe("Another test group using setup and teardown", [this]()
	{
		AfterEach([this]()
		{
			ExecutionSequence += TEXT("_END");
			TestEqual("ExecutionSequence", ExecutionSequence, TEXT("START_MID_END"));
		});
		Describe("nested within another group", [this]()
		{
			It("runs all applicable setup and teardown blocks in order", [this]()
			{
				TestEqual("ExecutionSequence", ExecutionSequence, TEXT("START_MID"));
			});
			AfterEach([this]()
			{
				ExecutionSequence += TEXT("_MID");
			});
			BeforeEach([this]()
			{
				ExecutionSequence += TEXT("_MID");
			});
		});
		BeforeEach([this]()
		{
			ExecutionSequence = TEXT("START");
		});
	});

	Describe("Complex nested setup/teardown scenario", [this]()
	{
		BeforeEach([this]()
		{
			ExecutionSequence = TEXT("STEP1");
		});
		AfterEach([this]()
		{
			ExecutionSequence += TEXT("_FINAL");
			TestEqual("ExecutionSequence", ExecutionSequence, TEXT("STEP1_STEP2_STEP3_STEP4_FINAL"));
		});
		BeforeEach([this]()
		{
			ExecutionSequence += TEXT("_STEP2");
		});
		Describe("first level of nesting", [this]()
		{
			AfterEach([this]()
			{
				ExecutionSequence += TEXT("_STEP3");
			});
			BeforeEach([this]()
			{
				ExecutionSequence += TEXT("_STEP3");
			});
			Describe("second level of nesting", [this]()
			{
				It("ensures correct ordering across multiple nesting levels", [this]()
				{
					TestEqual("ExecutionSequence", ExecutionSequence, TEXT("STEP1_STEP2_STEP3_STEP4"));
				});
				AfterEach([this]()
				{
					ExecutionSequence += TEXT("_STEP4");
				});
				BeforeEach([this]()
				{
					ExecutionSequence += TEXT("_STEP4");
				});
			});
		});
	});
}

