/// @test
/// Verify behavior when adding a remote subscriber without any objects present
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, processANewRemoteSubscriptionWhenThereAreNoObjects_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  handler.addSubscriber(InterestId(10), &participant, true);
  ASSERT_EQ(handler.remotesUpdatesBMMap.size<RemoteParticipant*>(), 0);
  ASSERT_EQ(handler.remotesToInterestsUpdatesMap.size(), 0);
  ASSERT_TRUE(handler.remotesInterestsBMMap.contains(&participant));
}

/// @test
/// Validate object tracking after adding a subscriber and an update
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, processANewObjectWhenASubscriberWasAdded_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;
  handler.addSubscriber(InterestId(20), &participant);
  handler.addObject(InterestId(20), &update);
  ASSERT_TRUE(handler.interestsUpdatesBMMap.contains(InterestId(20)));
  ASSERT_TRUE(handler.remotesUpdatesBMMap.contains(&participant));
  ASSERT_EQ(handler.remotesToInterestsUpdatesMap.size(), 1);
}

/// @test
/// Confirm multiple updates are tracked correctly for one interest
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, processTwoObjectWhenASubscriberWasAdded_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate obj1;
  ObjectUpdate obj2;
  handler.addSubscriber(InterestId(30), &participant);
  handler.addObject(InterestId(30), &obj1);
  handler.addObject(InterestId(30), &obj2);

  const auto* ptr1 = handler.interestsUpdatesBMMap.tryGet(InterestId(30));
  ASSERT_NE(nullptr, ptr1);
  EXPECT_EQ(ptr1->size(), 2);

  const auto* ptr2 = handler.remotesUpdatesBMMap.tryGet(&participant);
  ASSERT_NE(nullptr, ptr2);
  EXPECT_EQ(ptr2->size(), 2);
}

/// @test
/// Ensure new subscriber is registered even if object was added first
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, registersANewRemoteSubscriptionAfterObjectWasAdded_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;
  handler.addObject(InterestId(40), &update);
  handler.addSubscriber(InterestId(40), &participant);
  EXPECT_TRUE(handler.remotesUpdatesBMMap.contains(&participant));
  EXPECT_TRUE(handler.remotesToInterestsUpdatesMap.at(&participant).contains(InterestId(40)));
}

/// @test
/// Check that two subscribers are both registered after object addition
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, registersTwoSubscriptionsAfterObjectWasAdded_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant p1;
  RemoteParticipant p2;
  ObjectUpdate update;
  handler.addObject(InterestId(50), &update);
  handler.addSubscriber(InterestId(50), &p1);
  handler.addSubscriber(InterestId(50), &p2);
  EXPECT_EQ(handler.remotesUpdatesBMMap.size<RemoteParticipant*>(), 2);
  EXPECT_EQ(handler.remotesToInterestsUpdatesMap.size(), 2);
}

/// @test
/// Verify complete cleanup upon subscriber removal
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, removesSubscriptionWithUpdates_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;
  handler.addObject(InterestId(60), &update);
  handler.addSubscriber(InterestId(60), &participant);
  handler.removeSubscriber(InterestId(60), &participant);
  EXPECT_TRUE(handler.remotesUpdatesBMMap.empty());
  EXPECT_TRUE(handler.remotesToInterestsUpdatesMap.empty());
}

/// @test
/// Ensure remaining subscriber data persists after one subscriber removal
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, keepsTheObjectInterestWhenAInterestedSubscriptionRemains_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant p1;
  RemoteParticipant p2;
  ObjectUpdate update;
  handler.addObject(InterestId(70), &update);
  handler.addSubscriber(InterestId(70), &p1);
  handler.addSubscriber(InterestId(70), &p2);
  handler.removeSubscriber(InterestId(70), &p1);

  EXPECT_TRUE(handler.remotesUpdatesBMMap.contains(&p2));
  EXPECT_FALSE(handler.remotesUpdatesBMMap.contains(&p1));
  EXPECT_EQ(handler.remotesToInterestsUpdatesMap.size(), 1);
  EXPECT_TRUE(handler.interestsUpdatesBMMap.contains(InterestId(70)));
}

/// @test
/// Confirm all references cleared when last object removed
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, deregistersObjectAfterObjectRemoval_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant p1;
  RemoteParticipant p2;
  ObjectUpdate update;
  handler.addObject(InterestId(80), &update);
  handler.addSubscriber(InterestId(80), &p1);
  handler.addSubscriber(InterestId(80), &p2);
  handler.removeObject(&update);
  EXPECT_TRUE(handler.remotesUpdatesBMMap.empty());
  EXPECT_TRUE(handler.remotesToInterestsUpdatesMap.empty());
  EXPECT_TRUE(handler.interestsUpdatesBMMap.empty());
}

/// @test
/// Validate partial cleanup when one of two objects is removed
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, deregistersOneOfTwoObjectFromInterestedRemotes_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant p1;
  RemoteParticipant p2;
  ObjectUpdate obj1;
  ObjectUpdate obj2;
  handler.addObject(InterestId(90), &obj1);
  handler.addObject(InterestId(90), &obj2);
  handler.addSubscriber(InterestId(90), &p1);
  handler.addSubscriber(InterestId(90), &p2);

  {
    const auto* ptr = handler.interestsUpdatesBMMap.tryGet(InterestId(90));
    ASSERT_NE(nullptr, ptr);
    EXPECT_EQ(ptr->size(), 2);
  }

  handler.removeObject(&obj1);
  EXPECT_EQ(handler.remotesUpdatesBMMap.size<RemoteParticipant*>(), 2);
  EXPECT_EQ(handler.remotesToInterestsUpdatesMap.size(), 2);

  {
    const auto* ptr = handler.interestsUpdatesBMMap.tryGet(InterestId(90));
    ASSERT_NE(nullptr, ptr);
    EXPECT_EQ(ptr->size(), 1);
  }
}

/// @test
/// Test multiple interests referencing same object
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, registerTwoInterestsToTheSameObject_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;
  handler.addObject(InterestId(100), &update);
  handler.addObject(InterestId(101), &update);
  handler.addSubscriber(InterestId(100), &participant);
  handler.addSubscriber(InterestId(101), &participant);

