/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, keepsObjectForRemoteWhenAInterestRemains_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;
  handler.addObject(InterestId(110), &update);
  handler.addObject(InterestId(111), &update);
  handler.addSubscriber(InterestId(110), &participant);
  handler.addSubscriber(InterestId(111), &participant);
  handler.removeSubscriber(InterestId(110), &participant);

  auto& registeredInterests = handler.remotesToInterestsUpdatesMap.at(&participant);
  EXPECT_TRUE(registeredInterests.contains(InterestId(111)));
  EXPECT_FALSE(registeredInterests.contains(InterestId(110)));
