TEST(DebugInfoTest, Empty) {
    DebugInfo info;
    EXPECT_FALSE(info.has());
    EXPECT_EQ(info.filename(), "");
    EXPECT_EQ(info.start_line(), 0);
    EXPECT_EQ(info.start_column(), 0);
    EXPECT_EQ(info.end_line(), 0);
    EXPECT_EQ(info.end_column(), 0);
}

TEST(DebugInfoTest, Basic) {
    DebugInfo info("source.cpp", 5, 1, 15, 3);
    EXPECT_TRUE(info.has());
    EXPECT_EQ(info.filename(), "source.cpp");
    EXPECT_EQ(info.start_line(), 5);
    EXPECT_EQ(info.start_column(), 1);
    EXPECT_EQ(info.end_line(), 15);
    EXPECT_EQ(info.end_column(), 3);
}

TEST(DebugInfoTest, Merge_Left) {
    DebugInfo left_info;
    DebugInfo right_info("source.cpp", 5, 1, 15, 3);
    auto combined = DebugInfo::merge(left_info, right_info);
    EXPECT_TRUE(combined.has());
    EXPECT_EQ(combined.filename(), "source.cpp");
    EXPECT_EQ(combined.start_line(), 5);
    EXPECT_EQ(combined.start_column(), 1);
    EXPECT_EQ(combined.end_line(), 15);
    EXPECT_EQ(combined.end_column(), 3);
}

