#include <iostream>
#include <string>
#include <stdio.h>
#include "stringwrapper.h"
#ifdef OLD_WPDS_INDICES
#   include "wpds.h"
#else
#   include "WPDS.h"
#endif

int main() {
    wpds::Semiring< StringWrapper > ring(StringWrapper::one());
    wpds::Semiring< StringWrapper > ringR(StringWrapper::one(), false);
    wpds::WPDS< StringWrapper > system1(ring);
    wpds::WPDS< StringWrapper > system2(ring);
    wpds::CA< StringWrapper > analyzer(ring);
    wpds::CA< StringWrapper > analyzer2(ring);

    /* WPDS declarations */
    wpds::wpds_key_t nt1 = str2key("p");
    wpds::wpds_key_t N1 = str2key("A");
    wpds::wpds_key_t N2 = str2key("B");
    wpds::wpds_key_t N3 = str2key("C");
    wpds::wpds_key_t N4 = str2key("D");
    wpds::wpds_key_t eps = str2key("lambda");
    wpds::wpds_key_t final_state = str2key("accept");

    system1.add_rule(nt1, eps, nt1, N1, new StringWrapper("a"));
    system1.add_rule(nt1, N1, nt1, N2, new StringWrapper("b"));
    system1.add_rule(nt1, N2, nt1, N3, new StringWrapper("c"));
    system1.add_rule(nt1, N3, nt1, N4, new StringWrapper("d"));
    system1.add_rule(nt1, N1, nt1, N1, N2, new StringWrapper("w"));

    /* Second WPDS setup */
    wpds::wpds_key_t nt1_prime = str2key("p'");
    wpds::wpds_key_t var_x  = str2key("x");
    wpds::wpds_key_t var_xp = str2key("x'");
    wpds::wpds_key_t var_x2p = str2key("x''");

    system2.add_rule( nt1_prime, var_x,      nt1,      N1,  StringWrapper::one());
    system2.add_rule( nt1_prime, var_xp,     nt1_prime, var_x,  N2,  StringWrapper::one());
    system2.add_rule( nt1_prime, var_x2p,    nt1_prime, var_xp, N2,  StringWrapper::one());

    analyzer.add(nt1, eps, final_state, StringWrapper::one());

    std::cout << "Final state weight is ";
    //analyzer.state_weight( final_state )->print(std::cout) << std::endl;
    std::cout << system1 << std::endl << std::endl;
    std::cout << "*** BEFORE ***\n" << analyzer << std::endl;

    analyzer2 = wpds::poststar< StringWrapper >( system1, analyzer, ring );
    std::cout << "*** AFTER  ***\n" << analyzer2 << std::endl;

    wpds::CA< StringWrapper > analyzer3 =
        wpds::prestar< StringWrapper >( system2, analyzer2, ringR );

    wpds::CA< StringWrapper >::catrans_t target;
    target = analyzer3.find( nt1_prime, var_x2p, final_state );

    std::cout << "\n\n AFTER PRESTAR ON SYSTEM2\n" << analyzer3 << std::endl;
    //std::cout << target << std::endl;
    target->print(std::cout) << std::endl;

#if 1
    analyzer3.add_final_state( final_state );
    std::cout << "Executing path_summary...\n";
    std::set< wpds::wpds_key_t > nonterm_set;
    nonterm_set.insert( N2 );
    //std::cout << "final_state's weight is " << analyzer3.state_weight( final_state ) << std::endl;
    analyzer3.path_summary( nonterm_set );
    std::cout << "Final state weight is ";
