// Custom enumeration for ImageKind values
void ScalarEnumerationTraits<object::ImageKind>::enumeration(
    IO &Stream, object::ImageKind &Target) {
#define CASE(X) Stream.enumCase(Target, #X, object::X)
  CASE(IMG_None);
  CASE(IMG_Object);
  CASE(IMG_Bitcode);
  CASE(IMG_Cubin);
  CASE(IMG_Fatbinary);
  CASE(IMG_PTX);
  CASE(IMG_LastEntry);
#undef CASE
  Stream.enumFallback<Hex16>(Target);
}

// Custom enumeration for OffloadKind values
void ScalarEnumerationTraits<object::OffloadKind>::enumeration(
    IO &Stream, object::OffloadKind &Target) {
#define CASE(X) Stream.enumCase(Target, #X, object::X)
  CASE(OFK_None);
  CASE(OFK_OpenMP);
  CASE(OFK_Cuda);
  CASE(OFK_HIP);
  CASE(OFK_LastEntry);
#undef CASE
  Stream.enumFallback<Hex16>(Target);
}

// Mapping for OffloadYAML::Binary structure
void MappingTraits<OffloadYAML::Binary>::mapping(IO &Stream,
                                                 OffloadYAML::Binary &Data) {
  assert(!Stream.getContext() && "Context already set");
  Stream.setContext(&Data);
  Stream.mapTag("!Offload", true);
  Stream.mapOptional("VersionNumber", Data.Version);
  Stream.mapOptional("TotalSize", Data.Size);
  Stream.mapOptional("EntryPointOffset", Data.EntryOffset);
  Stream.mapOptional("EntryPointLength", Data.EntrySize);
  Stream.mapRequired("ChildElements", Data.Members);
  Stream.setContext(nullptr);
}

// Mapping for StringEntry (key-value pair)
void MappingTraits<OffloadYAML::Binary::StringEntry>::mapping(
    IO &Stream, OffloadYAML::Binary::StringEntry &Entry) {
  assert(Stream.getContext() && "Context not initialized");
  Stream.mapRequired("Identifier", Entry.Key);
  Stream.mapRequired("Payload", Entry.Value);
}

// Mapping for Member entry in binary offload data
void MappingTraits<OffloadYAML::Binary::Member>::mapping(
    IO &Stream, OffloadYAML::Binary::Member &Item) {
  assert(Stream.getContext() && "Context not initialized");
  Stream.mapOptional("FileType", Item.ImageKind);
  Stream.mapOptional("TargetKind", Item.OffloadKind);
  Stream.mapOptional("Attributes", Item.Flags);
  Stream.mapOptional("Metadata", Item.StringEntries);
  Stream.mapOptional("ImageData", Item.Content);
}

