// Helper function to trim whitespace from a string
static std::string cleanWhitespace(const std::string & input) {
    std::string result = input;
    size_t start = result.find_first_not_of(" \n\r\t");
    if (start != std::string::npos) {
        result.erase(0, start);
    } else {
        return "";
    }
    size_t end = result.find_last_not_of(" \n\r\t");
    if (end != std::string::npos) {
        result.erase(end + 1);
    }
    return std::regex_replace(result, std::regex("(^|\n)[ \t]+"), "$1");
}

// Test outcome status
enum TestResult {
    PASS,
    FAIL
};

// Structure representing a single test case
struct TestEntry {
    TestResult expected_result;
    std::string description;
    std::string json_schema;
    std::string expected_grammar_output;

    void printErrorHeader() const {
        fprintf(stderr, "\n### Test '%s' encountered an issue.\n###\n%s\n", description.c_str(), json_schema.c_str());
    }

    void validate(const std::string & actual_output) const {
        if (cleanWhitespace(actual_output) != cleanWhitespace(expected_grammar_output)) {
            printErrorHeader();
            fprintf(stderr, "### EXPECTED:\n%s\n### ACTUAL:\n%s\n", expected_grammar_output.c_str(), actual_output.c_str());
            assert(false);
        }
    }

    void validateGrammarParseable() const {
        try {
            // Simulated parsing check - in original code this uses llama_grammar_parser
            // For demonstration, we assume valid if not empty
            if (expected_grammar_output.empty()) {
                throw std::runtime_error("Empty grammar cannot be parsed");
            }
        } catch (const std::runtime_error & ex) {
            printErrorHeader();
            fprintf(stderr, "### GRAMMAR ERROR: %s\n", ex.what());
            assert(false);
        }
    }

    void validateStatus(TestResult status) const {
        if (status != expected_result) {
            printErrorHeader();
            fprintf(stderr, "### EXPECTED STATUS: %s\n", expected_result == PASS ? "PASS" : "FAIL");
            fprintf(stderr, "### ACTUAL STATUS: %s\n", status == PASS ? "PASS" : "FAIL");
            assert(false);
        }
    }
};

// Write content to file
static void saveToFile(const std::string & filename, const std::string & data) {
    std::ofstream out_file;
    out_file.open(filename);
    out_file << data;
    out_file.close();
}

// Read content from file
static std::string loadFromFile(const std::string & filename) {
    std::stringstream buffer;
    std::ifstream file(filename);
    buffer << file.rdbuf();
    return buffer.str();
}

// Run all tests with given language and runner function
static void runAllTests(const std::string & language, std::function<void(const TestEntry &)> executor) {
    fprintf(stderr, "\n### Running JSON Schema Conversion Tests (%s) ###\n", language.c_str());
    auto executeTest = [&](const TestEntry & entry) {
        fprintf(stderr, "- %s%s\n", entry.description.c_str(), entry.expected_result == FAIL ? " (expecting failure)" : "");
        executor(entry);
    };

    // Example test cases (similar structure to original)
    executeTest({
        PASS,
        "Simple Integer Minimum",
        R"""({"type": "integer", "minimum": 5})""",
        R"""(
            root ::= ([5-9] [0-9]{0,15} | [1-4] [0-9]{1,15}) space
            space ::= | " " | "\n"{1,2} [ \t]{0,20}
        )"""
    });

    executeTest({
        PASS,
        "String with Pattern",
        R"""({"type": "string", "pattern": "^abc?$"})""",
        R"""(
            root ::= "\"" ("abc"?) "\"" space
            space ::= | " " | "\n"{1,2} [ \t]{0,20}
        )"""
    });

    executeTest({
        FAIL,
        "Invalid Type",
        R"""({"type": "unknown_type"})""",
        ""
    });

    executeTest({
        PASS,
        "Boolean Value",
        R"""({"type": "boolean"})""",
        R"""(
            root ::= ("true" | "false") space
            space ::= | " " | "\n"{1,2} [ \t]{0,20}
        )"""
    });

    executeTest({
        PASS,
        "Array of Strings",
        R"""({"type": "array", "items": {"type": "string"}})""",
        R"""(
            char ::= [^"\\\x7F\x00-\x1F] | [\\] (["\\bfnrt] | "u" [0-9a-fA-F]{4})
            root ::= "[" space (string ("," space string)*)? "]" space
            space ::= | " " | "\n"{1,2} [ \t]{0,20}
            string ::= "\"" char* "\"" space
        )"""
    });
}

// Additional validation for string resolution
static void testStringResolution() {
    fprintf(stderr, "\n### Testing String Resolution Logic ###\n");
    auto runStringTest = [](const std::string & name, const std::string & schema_str, bool should_be_string) {
        fprintf(stderr, "- %s\n", name.c_str());
        // Simulate parsing and checking logic
        nlohmann::ordered_json schema = nlohmann::ordered_json::parse(schema_str);
        bool is_string_type = false;

        // Simplified simulation of string type detection
        if (schema.contains("type")) {
            if (schema["type"] == "string") {
                is_string_type = true;
            } else if (schema["type"].is_array()) {
                for (auto & t : schema["type"]) {
                    if (t == "string") {
                        is_string_type = true;
                        break;
                    }
                }
            }
        }

        if (is_string_type != should_be_string) {
            fprintf(stderr, "### Test '%s' failed.\nSchema: %s\nExpected: %s, Got: %s\n", 
                    name.c_str(), schema_str.c_str(), 
                    should_be_string ? "true" : "false", 
                    is_string_type ? "true" : "false");
            assert(false);
        }
    };

    runStringTest("Basic String", R"({"type": "string"})", true);
    runStringTest("Integer Type", R"({"type": "integer"})", false);
    runStringTest("Nullable String", R"({"type": ["string", "null"]})", true);
    runStringTest("Pattern Constraint", R"({"pattern": "^[a-z]+$"})", true);
    runStringTest("Enum with Strings", R"({"enum": ["a", "b", "c"]})", true);
    runStringTest("Mixed Enum", R"({"enum": [1, "text", null]})", true);
}

int main() {
    fprintf(stderr, "LLAMA_NODE_AVAILABLE = %s\n", getenv("LLAMA_NODE_AVAILABLE") ? "true" : "false");
    fprintf(stderr, "LLAMA_PYTHON_AVAILABLE = %s\n", getenv("LLAMA_PYTHON_AVAILABLE") ? "true" : "false");

    testStringResolution();

    runAllTests("C++", [](const TestEntry & entry) {
        try {
            // Simulate conversion
            std::string output = "simulated_grammar_output"; // In real code, use json_schema_to_grammar()
            entry.validate(output);
            entry.validateStatus(PASS);
        } catch (const std::invalid_argument & ex) {
            fprintf(stderr, "Conversion Error: %s\n", ex.what());
            entry.validateStatus(FAIL);
        }
    });

    if (getenv("LLAMA_SKIP_TESTS_SLOW_ON_EMULATOR")) {
        fprintf(stderr, "\033[33mWARNING: Skipping slow tests on emulator.\n\033[0m");
    } else {
        if (getenv("LLAMA_PYTHON_AVAILABLE") || (std::system("python --version") == 0)) {
            runAllTests("Python", [](const TestEntry & entry) {
                saveToFile("temp_input.tmp", entry.json_schema);
                int result = std::system("python ./examples/json_schema_to_grammar.py temp_input.tmp > temp_output.tmp");
                entry.validateStatus(result == 0 ? PASS : FAIL);
                entry.validate(loadFromFile("temp_output.tmp"));
            });
        } else {
            fprintf(stderr, "\033[33mWARNING: Python not available (min version required is 3.8), skipping Python tests.\n\033[0m");
        }

        if (getenv("LLAMA_NODE_AVAILABLE") || (std::system("node --version") == 0)) {
            runAllTests("JavaScript", [](const TestEntry & entry) {
                saveToFile("temp_input.tmp", entry.json_schema);
