// Test identity construction with false value
TEST(IdentityTest, testConstructFalse) {
  Identity id(false);
  EXPECT_EQ(id.HashValue(), static_cast<uint64_t>(0));
  EXPECT_EQ(id.ToString(), "0");
}

// Test identity construction with true value
TEST(IdentityTest, testConstructTrue) {
  Identity id(true);
  EXPECT_NE(id.HashValue(), static_cast<uint64_t>(0));
  EXPECT_NE(id.ToString(), "0");
}

// Test identity equality and assignment operations
TEST(IdentityTest, testIdentityEqual) {
  Identity obj1;
  Identity obj2;
  Identity obj3;

  EXPECT_NE(obj1, obj2);
  EXPECT_NE(obj2, obj3);
  EXPECT_NE(obj1, obj3);
  EXPECT_NE(obj1.HashValue(), obj3.HashValue());

  obj2 = obj2;
  EXPECT_NE(obj2, obj3);

  obj2 = obj3;
  EXPECT_EQ(obj2, obj3);

  Identity obj4(obj1);
  EXPECT_EQ(obj1, obj4);
  EXPECT_EQ(obj1.ToString(), obj4.ToString());
  EXPECT_EQ(obj1.HashValue(), obj4.HashValue());
}

// Test operator= functionality for identity objects
TEST(IdentityTest, testOperatorEqual) {
  Identity id1(true);
  Identity id2(false);

  id2 = id1;
  EXPECT_EQ(id1.HashValue(), id2.HashValue());
  EXPECT_EQ(id1.ToString(), id2.ToString());
  EXPECT_EQ(id2.Length(), id1.Length());

  id1.set_data(nullptr);
  Identity id3;
  id3.set_data(id1.data());

  EXPECT_EQ(id3.HashValue(), id2.HashValue());
  EXPECT_EQ(id3.ToString(), id2.ToString());
  EXPECT_EQ(id2.Length(), id3.Length());
}

