#include <iostream>
#include "sophus/geometry.hpp"

int main() {
  // Compute the composition of three rotations around principal axes
  const double PI = Sophus::Constants<double>::pi();
  Sophus::SO3d rotXAxis = Sophus::SO3d::rotX(PI / 4);
  Sophus::SO3d rotYAxis = Sophus::SO3d::rotY(PI / 6);
  Sophus::SO3d rotZAxis = Sophus::SO3d::rotZ(-PI / 3);

  std::cout << "Rotation matrices:" << std::endl;
  std::cout << "R_x:\n" << rotXAxis.matrix() << std::endl;
  std::cout << "R_y:\n" << rotYAxis.matrix() << std::endl;
  std::cout << "R_z:\n" << rotZAxis.matrix() << std::endl;
  std::cout << "Combined rotation R_x * R_y * R_z:\n"
            << (rotXAxis * rotYAxis * rotZAxis).matrix() << std::endl;
  std::cout << std::endl;

  // Apply rotations to a 3D vector
  Eigen::Vector3d point;
  point << 0.0, 0.0, 1.0;
  std::cout << "Action of rotations on vectors:" << std::endl;
  std::cout << "Original vector:\n" << point << std::endl;
  std::cout << "R_y * point:\n" << rotYAxis * point << std::endl;
  std::cout << "R_x * (R_y * point):\n" << rotXAxis * (rotYAxis * point) << std::endl;
  std::cout << "(R_x * R_y) * point:\n" << (rotXAxis * rotYAxis) * point << std::endl;
  std::cout << std::endl;

  // Internal representation: SO(3) elements as unit quaternions
  std::cout << "R_x in matrix form:\n" << rotXAxis.matrix() << std::endl;
  std::cout << "R_x as unit quaternion (i, j, k, w):\n"
            << rotXAxis.unit_quaternion().coeffs() << std::endl;
  // Note: Eigen uses (imaginary_part_x, imaginary_part_y, imaginary_part_z, real_part)
  std::cout << std::endl;
}

