// Global verification function
static void __GXVerifyGlobalState(void)
{
}

// CP-specific verification
static void __GXVerifyCPUnit(GXVtxFmt fmt)
{
    u32 nrmCount = GET_REG_FIELD(__GXData->vatA[fmt], 1, 9);

    if (__gxVerificationPtr->verifyLevel >= GX_WARN_SEVERE)
    {
        if (__GXData->hasNrms && nrmCount != 0)
        {
            if (__gxVerificationPtr->verifyLevel >= __gxSeverityLevels[GXWARN_INVALID_VTX_FMT])
            {
                __GX_WARNF(GXWARN_INVALID_VTX_FMT, "GX_NRM_XYZ");
            }
        }
        else if (__GXData->hasBiNrms && nrmCount != 1)
        {
            if (__gxVerificationPtr->verifyLevel >= __gxSeverityLevels[GXWARN_INVALID_VTX_FMT])
            {
                __GX_WARNF(GXWARN_INVALID_VTX_FMT, "GX_NRM_NBT or GX_NRM_NBT3");
            }
        }
    }
}

// Main state verification entry point
void __GXVerifySystemState(GXVtxFmt vtxfmt)
{
    if (__gxVerificationPtr->verifyLevel != GX_WARN_NONE)
    {
        __GXVerifyGlobalState();
        __GXVerifyCPUnit(vtxfmt);
        __GXVerifyXF();
        __GXVerifySU();
        __GXVerifyBUMP();
        __GXVerifyTEX();
        __GXVerifyTEV();
        __GXVerifyPE();
    }
}

// Immediate VAT verification
void __GXVerifyImmediateVAT(GXAttr attr, GXCompCnt cnt, GXCompType type, u8 frac)
{
    if (__gxVerificationPtr->verifyLevel != GX_WARN_NONE)
    {
        // Color format validation
        if (attr == GX_VA_CLR0 || attr == GX_VA_CLR1)
        {
            switch (type)
            {
            case GX_RGB565:
            case GX_RGB8:
            case GX_RGBX8:
                if (cnt != GX_CLR_RGB && __gxVerificationPtr->verifyLevel >= __gxSeverityLevels[GXWARN_VAT_MISMATCH])
                {
                    __GX_WARNF(GXWARN_VAT_MISMATCH, "RGB format type", "GX_CLR_RGB");
                }
                break;
            case GX_RGBA4:
            case GX_RGBA6:
            case GX_RGBA8:
                if (cnt != GX_CLR_RGBA && __gxVerificationPtr->verifyLevel >= __gxSeverityLevels[GXWARN_VAT_MISMATCH])
                {
                    __GX_WARNF(GXWARN_VAT_MISMATCH, "RGBA format type", "GX_CLR_RGBA");
                }
                break;
            }
        }

        // Fractional bits validation
        if (frac != 0)
        {
            if (attr == GX_VA_CLR0 || attr == GX_VA_CLR1)
            {
                if (__gxVerificationPtr->verifyLevel >= __gxSeverityLevels[GXWARN_VAT_CLR_FRAC])
                {
                    __GX_WARN(GXWARN_VAT_CLR_FRAC);
                }
            }
            else if (type == GX_F32)
            {
                if (__gxVerificationPtr->verifyLevel >= __gxSeverityLevels[GXWARN_VAT_F32_FRAC])
                {
                    __GX_WARN(GXWARN_VAT_F32_FRAC);
                }
            }
        }

        // Normal format validation
        if (attr == GX_VA_NRM || attr == GX_VA_NBT)
        {
            switch (type)
            {
            case GX_S8:
                if (frac != 6 && __gxVerificationPtr->verifyLevel >= __gxSeverityLevels[GXWARN_VAT_NRM_FRAC])
                {
                    __GX_WARNF(GXWARN_VAT_NRM_FRAC, "GX_S8", 6);
                }
                break;
            case GX_S16:
                if (frac != 14 && __gxVerificationPtr->verifyLevel >= __gxSeverityLevels[GXWARN_VAT_NRM_FRAC])
                {
                    __GX_WARNF(GXWARN_VAT_NRM_FRAC, "GX_S16", 14);
                }
                break;
            case GX_F32:
                break;
            default:
                if (__gxVerificationPtr->verifyLevel >= __gxSeverityLevels[GXWARN_VAT_NRM_TYPE])
                {
                    __GX_WARN(GXWARN_VAT_NRM_TYPE);
                }
                break;
            }
        }
    }
}

// Level configuration functions
void GXSetVerifyLevel(GXWarningLevel level)
{
    __gxVerificationPtr->verifyLevel = level;
}

GXVerifyCallback GXSetVerifyCallback(GXVerifyCallback callback)
{
    GXVerifyCallback previousCallback = __gxVerificationPtr->cb;
    __gxVerificationPtr->cb = callback;
    return previousCallback;
}
