#include "urdf_parser/urdf_parser.h"
#include <fstream>
#include <iostream>

// Load and parse a URDF file in a continuous loop
int main(int argc, char** argv) {
  if (argc != 2) {
    fprintf(stderr, "Usage: %s <urdf_file>\n", argv[0]);
    return 1;
  }

  while (true) {
    std::string urdf_content;
    std::ifstream input_stream(argv[1], std::ifstream::in);

    while (input_stream.good()) {
      std::string line;
      std::getline(input_stream, line);
      urdf_content += (line + "\n");
    }

    input_stream.close();
    urdf::parseURDF(urdf_content);
  }

  return 0;
}

