#include <singleapplication.h>
#include "messagereceiver.h"

int main(int argc, char *argv[]) {
    QCoreApplication application(argc, argv);

    // Create a guard for single-instance behavior (allowing multiple instances)
    SingleApplication instance_guard(argc, argv, true);

    MessageReceiver receiver;

    // Check if this is a secondary instance
    if (instance_guard.isSecondary()) {
        QString args = application.arguments().join(" ");
        instance_guard.sendMessage(args.toUtf8());

        qDebug() << "Another instance is already running.";
        qDebug() << "Primary process ID: " << instance_guard.primaryPid();
        qDebug() << "Primary user: " << instance_guard.primaryUser();

        return 0;
    } else {
        QObject::connect(
            &instance_guard,
            &SingleApplication::receivedMessage,
            &receiver,
            &MessageReceiver::handleReceivedMessage
        );
    }

    return application.exec();
}

