  IO.bitSetCase(SectionTypeInfo, "SHT_SYMTAB", llvm::ELF::SHT_SYMTAB);
  IO.bitSetCase(SectionTypeInfo, "SHT_STRTAB", llvm::ELF::SHT_STRTAB);
  IO.bitSetCase(SectionTypeInfo, "SHT_RELA", llvm::ELF::SHT_RELA);
  IO.bitSetCase(SectionTypeInfo, "SHT_HASH", llvm::ELF::SHT_HASH);
  IO.bitSetCase(SectionTypeInfo, "SHT_DYNAMIC", llvm::ELF::SHT_DYNAMIC);
  IO.bitSetCase(SectionTypeInfo, "SHT_NOTE", llvm::ELF::SHT_NOTE);
  IO.bitSetCase(SectionTypeInfo, "SHT_NOBITS", llvm::ELF::SHT_NOBITS);
