void MappingTraits<std::shared_ptr<eld::LDYAML::Content>>::mapping(
    IO &IO, std::shared_ptr<eld::LDYAML::Content> &ContentPtr) {
  if (ContentPtr) {
    ContentPtr->mapping(IO);
    return;
  }
  std::vector<llvm::StringRef> Keys = IO.keys();
  if (llvm::find(Keys, "Contents") != Keys.end()) {
    ContentPtr = std::make_shared<eld::LDYAML::OutputSection>();
    ContentPtr->ContentKind = Content::Kind::OutputSection;
  } else if (llvm::find(Keys, "PostLTOFile") != Keys.end()) {
    ContentPtr = std::make_shared<eld::LDYAML::InputBitcodeSection>();
    ContentPtr->ContentKind = Content::Kind::InputSection;
  } else if (llvm::find(Keys, "Origin") != Keys.end()) {
    ContentPtr = std::make_shared<eld::LDYAML::InputSection>();
    ContentPtr->ContentKind = Content::Kind::InputSection;
  } else if (llvm::find(Keys, "Padding") != Keys.end()) {
    ContentPtr = std::make_shared<eld::LDYAML::Padding>();
    ContentPtr->ContentKind = Content::Kind::Padding;
  } else if (llvm::find(Keys, "LinkerScript") != Keys.end()) {
    ContentPtr = std::make_shared<eld::LDYAML::LinkerScriptRule>();
    ContentPtr->ContentKind = Content::Kind::LinkerScriptRule;
  } else {
    ContentPtr = std::make_shared<eld::LDYAML::Assignment>();
    ContentPtr->ContentKind = Content::Kind::Assignment;
  }
  ContentPtr->mapping(IO);
}

