template <class Scalar>
class Tests {
 public:
  using Sim3Type = Sim3<Scalar>;
  using RxSO3Type = RxSO3<Scalar>;
  using Point = typename Sim3<Scalar>::Point;
  using Vector4Type = Vector4<Scalar>;
  using Tangent = typename Sim3<Scalar>::Tangent;

  Scalar const kPi = Constants<Scalar>::pi();

  Tests() {
    sim3_group_elements_.push_back(
        Sim3Type(RxSO3Type::exp(Vector4Type(Scalar(0.2), Scalar(0.5),
                                            Scalar(0.0), Scalar(1.))),
                 Point(Scalar(0), Scalar(0), Scalar(0))));
    sim3_group_elements_.push_back(
        Sim3Type(RxSO3Type::exp(Vector4Type(Scalar(0.2), Scalar(0.5),
                                            Scalar(-1.0), Scalar(1.1))),
                 Point(Scalar(10), Scalar(0), Scalar(0))));
    sim3_group_elements_.push_back(
        Sim3Type(RxSO3Type::exp(Vector4Type(Scalar(0.), Scalar(0.), Scalar(0.),
                                            Scalar(0.))),
                 Point(Scalar(0), Scalar(10), Scalar(5))));
    sim3_group_elements_.push_back(
        Sim3Type(RxSO3Type::exp(Vector4Type(Scalar(0.), Scalar(0.), Scalar(0.),
                                            Scalar(1.1))),
                 Point(Scalar(0), Scalar(10), Scalar(5))));
    sim3_group_elements_.push_back(
        Sim3Type(RxSO3Type::exp(Vector4Type(Scalar(0.), Scalar(0.),
                                            Scalar(0.00001), Scalar(0.))),
                 Point(Scalar(0), Scalar(0), Scalar(0))));
    sim3_group_elements_.push_back(Sim3Type(
        RxSO3Type::exp(Vector4Type(Scalar(0.), Scalar(0.), Scalar(0.00001),
                                   Scalar(0.0000001))),
        Point(Scalar(1), Scalar(-1.00000001), Scalar(2.0000000001))));
    sim3_group_elements_.push_back(
        Sim3Type(RxSO3Type::exp(Vector4Type(Scalar(0.), Scalar(0.),
                                            Scalar(0.00001), Scalar(0))),
                 Point(Scalar(0.01), Scalar(0), Scalar(0))));
    sim3_group_elements_.push_back(Sim3Type(
        RxSO3Type::exp(Vector4Type(kPi, Scalar(0), Scalar(0), Scalar(0.9))),
        Point(Scalar(4), Scalar(-5), Scalar(0))));
    sim3_group_elements_.push_back(
        Sim3Type(RxSO3Type::exp(Vector4Type(Scalar(0.2), Scalar(0.5),
                                            Scalar(0.0), Scalar(0))),
                 Point(Scalar(0), Scalar(0), Scalar(0))) *
        Sim3Type(
            RxSO3Type::exp(Vector4Type(kPi, Scalar(0), Scalar(0), Scalar(0))),
            Point(Scalar(0), Scalar(0), Scalar(0))) *
        Sim3Type(RxSO3Type::exp(Vector4Type(Scalar(-0.2), Scalar(-0.5),
                                            Scalar(-0.0), Scalar(0))),
                 Point(Scalar(0), Scalar(0), Scalar(0))));
    sim3_group_elements_.push_back(
        Sim3Type(RxSO3Type::exp(Vector4Type(Scalar(0.3), Scalar(0.5),
                                            Scalar(0.1), Scalar(0))),
                 Point(Scalar(2), Scalar(0), Scalar(-7))) *
        Sim3Type(
            RxSO3Type::exp(Vector4Type(kPi, Scalar(0), Scalar(0), Scalar(0))),
            Point(Scalar(0), Scalar(0), Scalar(0))) *
        Sim3Type(RxSO3Type::exp(Vector4Type(Scalar(-0.3), Scalar(-0.5),
                                            Scalar(-0.1), Scalar(0))),
                 Point(Scalar(0), Scalar(6), Scalar(0))));

    Tangent tmp_tangent;
    tmp_tangent << Scalar(0), Scalar(0), Scalar(0), Scalar(0), Scalar(0), Scalar(0),
        Scalar(0);
    tangent_vectors_.push_back(tmp_tangent);

    tmp_tangent << Scalar(1), Scalar(0), Scalar(0), Scalar(0), Scalar(0), Scalar(0),
        Scalar(0);
    tangent_vectors_.push_back(tmp_tangent);

    tmp_tangent << Scalar(0), Scalar(1), Scalar(0), Scalar(1), Scalar(0), Scalar(0),
        Scalar(0.1);
    tangent_vectors_.push_back(tmp_tangent);

    tmp_tangent << Scalar(0), Scalar(0), Scalar(1), Scalar(0), Scalar(1), Scalar(0),
        Scalar(0.1);
    tangent_vectors_.push_back(tmp_tangent);

    tmp_tangent << Scalar(-1), Scalar(1), Scalar(0), Scalar(0), Scalar(0), Scalar(1),
        Scalar(-0.1);
    tangent_vectors_.push_back(tmp_tangent);

    tmp_tangent << Scalar(20), Scalar(-1), Scalar(0), Scalar(-1), Scalar(1), Scalar(0),
        Scalar(-0.1);
    tangent_vectors_.push_back(tmp_tangent);

    tmp_tangent << Scalar(30), Scalar(5), Scalar(-1), Scalar(20), Scalar(-1), Scalar(0),
        Scalar(1.5);
    tangent_vectors_.push_back(tmp_tangent);

    point_cloud_.push_back(Point(Scalar(1), Scalar(2), Scalar(4)));
    point_cloud_.push_back(Point(Scalar(1), Scalar(-3), Scalar(0.5)));
  }

  void runAll() {
    bool passed = testLieGroupProperties();
    passed &= testRawDataAccess();
    passed &= testConstructorBehavior();
    processTestResult(passed);
  }

 private:
  bool testLieGroupProperties() {
    LieGroupTests<Sim3Type> tests(sim3_group_elements_, tangent_vectors_, point_cloud_);
    return tests.doAllTestsPass();
  }

  bool testRawDataAccess() {
    bool passed = true;

    Eigen::Matrix<Scalar, 7, 1> raw_data;
    raw_data << Scalar(0), Scalar(1), Scalar(0), Scalar(0), Scalar(1), Scalar(3),
        Scalar(2);

    Eigen::Map<Sim3Type const> const_map(raw_data.data());
    SOPHUS_TEST_APPROX(passed, const_map.quaternion().coeffs().eval(),
                       raw_data.template head<4>().eval(),
                       Constants<Scalar>::epsilon());
    SOPHUS_TEST_APPROX(passed, const_map.translation().eval(),
                       raw_data.template tail<3>().eval(),
                       Constants<Scalar>::epsilon());
    SOPHUS_TEST_EQUAL(passed, const_map.quaternion().coeffs().data(),
                      raw_data.data());
    SOPHUS_TEST_EQUAL(passed, const_map.translation().data(),
                      raw_data.data() + 4);

    Eigen::Map<Sim3Type const> const_shallow_copy = const_map;
    SOPHUS_TEST_EQUAL(passed, const_shallow_copy.quaternion().coeffs().eval(),
                      const_map.quaternion().coeffs().eval());
    SOPHUS_TEST_EQUAL(passed, const_shallow_copy.translation().eval(),
                      const_map.translation().eval());

    Eigen::Matrix<Scalar, 7, 1> raw_data_2;
    raw_data_2 << Scalar(1), Scalar(0), Scalar(0), Scalar(0), Scalar(3), Scalar(2),
        Scalar(1);

    Eigen::Map<Sim3Type> mutable_map(raw_data.data());
    Eigen::Quaternion<Scalar> quaternion;
    quaternion.coeffs() = raw_data_2.template head<4>();
    mutable_map.setQuaternion(quaternion);
    mutable_map.translation() = raw_data_2.template tail<3>();

    SOPHUS_TEST_APPROX(passed, mutable_map.quaternion().coeffs().eval(),
                       raw_data_2.template head<4>().eval(),
                       Constants<Scalar>::epsilon());
    SOPHUS_TEST_APPROX(passed, mutable_map.translation().eval(),
                       raw_data_2.template tail<3>().eval(),
                       Constants<Scalar>::epsilon());
    SOPHUS_TEST_EQUAL(passed, mutable_map.quaternion().coeffs().data(),
                      raw_data.data());
    SOPHUS_TEST_EQUAL(passed, mutable_map.translation().data(), raw_data.data() + 4);
    SOPHUS_TEST_NEQ(passed, mutable_map.quaternion().coeffs().data(),
                    quaternion.coeffs().data());

    Eigen::Map<Sim3Type> shallow_copy = mutable_map;
    SOPHUS_TEST_EQUAL(passed, shallow_copy.quaternion().coeffs().eval(),
                      mutable_map.quaternion().coeffs().eval());
    SOPHUS_TEST_EQUAL(passed, shallow_copy.translation().eval(),
                      mutable_map.translation().eval());

    Eigen::Map<Sim3Type> const const_mapped_sim3 = mutable_map;
    SOPHUS_TEST_EQUAL(passed, const_mapped_sim3.quaternion().coeffs().eval(),
                      mutable_map.quaternion().coeffs().eval());
    SOPHUS_TEST_EQUAL(passed, const_mapped_sim3.translation().eval(),
                      mutable_map.translation().eval());

    Sim3Type const const_sim3(quaternion, raw_data_2.template tail<3>().eval());
    for (int idx = 0; idx < 7; ++idx) {
      SOPHUS_TEST_EQUAL(passed, const_sim3.data()[idx], raw_data_2.data()[idx]);
    }

    Sim3Type se3_instance(quaternion, raw_data_2.template tail<3>().eval());
    for (int idx = 0; idx < 7; ++idx) {
      SOPHUS_TEST_EQUAL(passed, se3_instance.data()[idx], raw_data_2.data()[idx]);
    }
    for (int idx = 0; idx < 7; ++idx) {
      SOPHUS_TEST_EQUAL(passed, se3_instance.data()[idx], raw_data.data()[idx]);
    }

    Eigen::Matrix<Scalar, 7, 1> data_a, data_b;
    data_a << Scalar(0), Scalar(2), Scalar(0), Scalar(0),
        Scalar(1), Scalar(2), Scalar(3);
    data_b << Scalar(0), Scalar(0), Scalar(2), Scalar(0),
        Scalar(3), Scalar(2), Scalar(1);

    Eigen::Map<Sim3Type> map_a(data_a.data()), map_b(data_b.data());

    // Map-to-map assignment
    map_b = map_a;
    SOPHUS_TEST_EQUAL(passed, map_a.matrix(), map_b.matrix());

    // Map-to-type assignment
    Sim3Type copy_obj;
    copy_obj = map_a;
    SOPHUS_TEST_EQUAL(passed, map_a.matrix(), copy_obj.matrix());

    // Type-to-map assignment
    copy_obj = Sim3Type(RxSO3Type::exp(Vector4Type(Scalar(0.2), Scalar(0.5),
                                                    Scalar(-1.0), Scalar(1.1))),
                        Point(Scalar(10), Scalar(0), Scalar(0)));
    map_a = copy_obj;
    SOPHUS_TEST_EQUAL(passed, map_a.matrix(), copy_obj.matrix());

    return passed;
  }

  bool testConstructorBehavior() {
    bool passed = true;

    Eigen::Matrix<Scalar, 4, 4> identity_matrix = Eigen::Matrix<Scalar, 4, 4>::Identity();
    SOPHUS_TEST_EQUAL(passed, Sim3Type().matrix(), identity_matrix);

    Sim3Type sim3_element = sim3_group_elements_.front();
    Point translation_vector = sim3_element.translation();
    RxSO3Type rxso3_component = sim3_element.rxso3();

    SOPHUS_TEST_APPROX(passed, Sim3Type(rxso3_component, translation_vector).matrix(),
                       sim3_element.matrix(), Constants<Scalar>::epsilon());
    SOPHUS_TEST_APPROX(passed,
                       Sim3Type(rxso3_component.quaternion(), translation_vector).matrix(),
                       sim3_element.matrix(), Constants<Scalar>::epsilon());
    SOPHUS_TEST_APPROX(passed, Sim3Type(sim3_element.matrix()).matrix(), sim3_element.matrix(),
                       Constants<Scalar>::epsilon());

    Scalar scale_factor(1.2);
    sim3_element.setScale(scale_factor);
    SOPHUS_TEST_APPROX(passed, scale_factor, sim3_element.scale(),
                       Constants<Scalar>::epsilon(), "setScale");

    sim3_element.setQuaternion(sim3_group_elements_[0].rxso3().quaternion());
    SOPHUS_TEST_APPROX(passed, sim3_group_elements_[0].rxso3().quaternion().coeffs(),
                       sim3_group_elements_[0].rxso3().quaternion().coeffs(),
                       Constants<Scalar>::epsilon(), "setQuaternion");

    return passed;
  }

  std::vector<Sim3Type, Eigen::aligned_allocator<Sim3Type>> sim3_group_elements_;
  std::vector<Tangent, Eigen::aligned_allocator<Tangent>> tangent_vectors_;
  std::vector<Point, Eigen::aligned_allocator<Point>> point_cloud_;
};

int test_sim3() {
  using std::cerr;
  using std::endl;

  cerr << "Test Sim3" << endl << endl;
  cerr << "Double precision tests: " << endl;
  Tests<double>().runAll();

  cerr << "Single precision (float) tests: " << endl;
  Tests<float>().runAll();

#if SOPHUS_CERES
  cerr << "ceres::Jet<double, 3> tests: " << endl;
  Tests<ceres::Jet<double, 3>>().runAll();
#endif

  return 0;
}

