#include "gmock/gmock.h"
#include "gtest/gtest.h"

namespace dap {

struct VariantTestObject {
  dap::integer val_i;
  dap::number val_n;
};

DAP_STRUCT_TYPEINFO(VariantTestObject,
                    "VariantTestObject",
                    DAP_FIELD(val_i, "val_i"),
                    DAP_FIELD(val_n, "val_n"));

}  // namespace dap

TEST(Variant, EmptyConstruct) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestObject> var;
  ASSERT_TRUE(var.is<dap::integer>());
  ASSERT_FALSE(var.is<dap::boolean>());
  ASSERT_FALSE(var.is<dap::VariantTestObject>());
}

TEST(Variant, Boolean) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestObject> var(
      dap::boolean(false));
  ASSERT_TRUE(var.is<dap::boolean>());
  ASSERT_EQ(var.get<dap::boolean>(), dap::boolean(false));
}

TEST(Variant, Integer) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestObject> var(
      dap::integer(42));
  ASSERT_TRUE(var.is<dap::integer>());
  ASSERT_EQ(var.get<dap::integer>(), dap::integer(42));
}

TEST(Variant, TestObject) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestObject> var(
      dap::VariantTestObject{7, 2.5});
  ASSERT_TRUE(var.is<dap::VariantTestObject>());
  ASSERT_EQ(var.get<dap::VariantTestObject>().val_i, 7);
  ASSERT_EQ(var.get<dap::VariantTestObject>().val_n, 2.5);
}

TEST(Variant, Assign) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestObject> var(
      dap::integer(100));

  var = dap::integer(200);
  ASSERT_TRUE(var.is<dap::integer>());
  ASSERT_FALSE(var.is<dap::boolean>());
  ASSERT_FALSE(var.is<dap::VariantTestObject>());
  ASSERT_EQ(var.get<dap::integer>(), dap::integer(200));

  var = dap::boolean(true);
  ASSERT_FALSE(var.is<dap::integer>());
  ASSERT_TRUE(var.is<dap::boolean>());
  ASSERT_FALSE(var.is<dap::VariantTestObject>());
  ASSERT_EQ(var.get<dap::boolean>(), dap::boolean(true));

  var = dap::VariantTestObject{15, 4.5};
  ASSERT_FALSE(var.is<dap::integer>());
  ASSERT_FALSE(var.is<dap::boolean>());
  ASSERT_TRUE(var.is<dap::VariantTestObject>());
  ASSERT_EQ(var.get<dap::VariantTestObject>().val_i, 15);
  ASSERT_EQ(var.get<dap::VariantTestObject>().val_n, 4.5);
}

TEST(Variant, Accepts) {
  using variant_type =
      dap::variant<dap::integer, dap::boolean, dap::VariantTestObject>;
  ASSERT_TRUE(variant_type::accepts<dap::integer>());
  ASSERT_TRUE(variant_type::accepts<dap::boolean>());
  ASSERT_TRUE(variant_type::accepts<dap::VariantTestObject>());
  ASSERT_FALSE(variant_type::accepts<dap::number>());
  ASSERT_FALSE(variant_type::accepts<dap::string>());
}

