    for (index = 0; index < size; index++) {
        printf("value %d address %u\n", *ptr, ptr);
        printf("%d\n", *ptr);
        accumulator = accumulator + *ptr;
        ptr++;
    }

    printf("enter total element");
    scanf("%d", &size);

    int data[100]; // Assuming maximum size of 100

    for (index = 0; index < size; index++) {
        printf("enter %d element ", index);
        scanf("%d", &data[index]);
    }

    displayArray(&data[0], size);
    return;
}

