#include <gtest/gtest.h>
#include <ocs2_ballbot/generated/forward_dynamics.h>
#include <ocs2_ballbot/generated/inertia_properties.h>
#include <ocs2_ballbot/generated/inverse_dynamics.h>
#include <ocs2_ballbot/generated/jsim.h>
#include <ocs2_ballbot/generated/transforms.h>
#include <ocs2_robotic_tools/rbd_libraries/robcogen/iit/rbd/rbd.h>
#include <ocs2_robotic_tools/rbd_libraries/robcogen/iit/rbd/traits/TraitSelector.h>

TEST(RobcogenModelTest, RobcogenModelValidation) {
  // initialize random joint state
  iit::Ballbot::tpl::JointState<double> jointPos, jointVel, jointAcc, jointTorque;
  jointPos << 0.5, 0.7, 3.0, 2.0, -1.0;
  jointVel << 0.5, 0.7, 3.0, 2.0, -1.0;
  jointAcc.setZero();
  jointTorque << 3.5, 4.5, 6.5;

  Eigen::Matrix<double, 5, 1> gravityTerms, coriolisTerms;
  gravityTerms.setZero();
  coriolisTerms.setZero();

  // define inertia properties, force transforms and Motion transform
  using trait_type = typename iit::rbd::tpl::TraitSelector<double>::Trait;
  iit::Ballbot::dyn::tpl::InertiaProperties<trait_type> inertialProps;
  iit::Ballbot::tpl::ForceTransforms<trait_type> forceXforms;
  iit::Ballbot::tpl::MotionTransforms<trait_type> motionXforms;

  // compute gravity terms, coriolis and centrifugal terms
  iit::Ballbot::dyn::tpl::InverseDynamics<trait_type> invDyn(inertialProps, motionXforms);
  invDyn.G_terms(gravityTerms, jointPos);
  invDyn.C_terms(coriolisTerms, jointPos, jointVel);

  // compute result of the forward dynamics method
  iit::Ballbot::dyn::tpl::ForwardDynamics<trait_type> fwdDyn(inertialProps, motionXforms);
  fwdDyn.fd(jointAcc, jointPos, jointVel, jointTorque);

  // print results
  std::cout << "accelerations from forward dynamics method: " << jointAcc.transpose() << std::endl;
  std::cout << "gravity terms: " << gravityTerms.transpose() << std::endl;

  // second test case with different inputs
  jointPos << 0.5, 0.7, 3.0, 2.0, -1.0;
  jointVel << 0.5, 0.7, 12.0, 2.0, -1.0;
  jointAcc.setZero();
  jointTorque << 10.5, 4.5, 6.5;

  fwdDyn.fd(jointAcc, jointPos, jointVel, jointTorque);
  std::cout << "accelerations from forward dynamics method (second test): " << jointAcc.transpose() << std::endl;
}

int main(int argc, char** argv) {
  testing::InitGoogleTest(&argc, argv);
  return RUN_ALL_TESTS();
}

