void FText3DEditorModule::StartupModule()
{
    // Locate the plugin's base directory and construct resource path
    FString PluginPath = IPluginManager::Get().FindPlugin("Text3D")->GetBaseDir() / TEXT("Assets");

    // Initialize the Slate style set with a unique name
    IconStyle = MakeUnique<FSlateStyleSet>(FName(TEXT("Text3DIcons")));
    IconStyle->SetContentRoot(PluginPath);

    // Register icons for the editor UI
    IconStyle->Set("ClassIcon.Text3DActor", new ICON_BRUSH("Text3DActor_16x", FVector2D(16.0f, 16.0f)));
    IconStyle->Set("ClassThumbnail.Text3DActor", new ICON_BRUSH("Text3DActor_64x", FVector2D(64.0f, 64.0f)));

    // Make the style set available globally
    FSlateStyleRegistry::RegisterSlateStyle(*IconStyle.Get());
}

void FText3DEditorModule::ShutdownModule()
{
    // Clean up registered styles when module shuts down
    FSlateStyleRegistry::UnRegisterSlateStyle(*IconStyle.Get());
    IconStyle.Reset();
}

