#include <iostream>
#include <nlohmann/json.hpp>

using json = nlohmann::json;
using namespace nlohmann::literals;

int main()
{
    // Initialize a JSON object with various data types
    json data =
    {
        {"value", 1}, {"text", "bar"}, {"list", {3, 4}}
    };

    std::cout << std::boolalpha
              << data.contains("/value"_json_pointer) << '\n'
              << data.contains("/text"_json_pointer) << '\n'
              << data.contains("/list"_json_pointer) << '\n'
              << data.contains("/list/1"_json_pointer) << '\n'
              << data.contains("/list/-"_json_pointer) << '\n'
              << data.contains("/list/4"_json_pointer) << '\n'
              << data.contains("/qux"_json_pointer) << std::endl;

    try
    {
        // Attempt to access array element using invalid index (leading zero)
        data.contains("/list/01"_json_pointer);
    }
    catch (const json::parse_error& err)
    {
        std::cout << err.what() << '\n';
    }

    try
    {
        // Attempt to access array element using non-numeric string
        data.contains("/list/two"_json_pointer);
    }
    catch (const json::parse_error& err)
    {
        std::cout << err.what() << '\n';
    }

    return 0;
}

