        common_regex_match result;
    };
    std::vector<sample> cases;
};

static std::string describe_match_type(common_regex_match_type t) {
    switch (t) {
        case COMMON_REGEX_MATCH_TYPE_NONE:
            return "COMMON_REGEX_MATCH_TYPE_NONE";
        case COMMON_REGEX_MATCH_TYPE_PARTIAL:
            return "COMMON_REGEX_MATCH_TYPE_PARTIAL";
        case COMMON_REGEX_MATCH_TYPE_FULL:
            return "COMMON_REGEX_MATCH_TYPE_FULL";
    }
    return "UNKNOWN";
}

static void run_tests() {
    printf("[%s]\n", __func__);
    auto execute = [](const test_entry& entry) {
        common_regex cr(entry.regex_pattern);
        std::cout << "Testing pattern: /" << entry.regex_pattern << "/\n";

        for (const auto& sample : entry.cases) {
            std::cout << "  Input: \"" << sample.text << "\"\n";
            auto match_result = cr.search(sample.text, 0);

            if (match_result != sample.result) {
                auto format_match = [&](const std::optional<common_regex_match>& m_opt) -> std::string {
                    std::ostringstream oss;
                    if (!m_opt.has_value() || m_opt->type == COMMON_REGEX_MATCH_TYPE_NONE) {
                        oss << "<no match>";
                    } else {
                        GGML_ASSERT(!sample.result.groups.empty());
                        std::vector<std::string> segment_strs;
                        for (const auto& g : m_opt->groups) {
                            segment_strs.push_back("{" + std::to_string(g.begin) + ", " + std::to_string(g.end) + "}");
                        }
                        oss << "{" << describe_match_type(m_opt->type) << ", {" << string_join(segment_strs, ", ") << "}}";
                    }
                    return oss.str();
                };

                std::cout << "    Expected: " << format_match(sample.result) << "\n";
                std::cout << "         Got: " << format_match(match_result) << "\n";
                std::cout << " Inverted pattern: /" << regex_to_reversed_partial_regex(entry.regex_pattern) << "/\n";
                throw std::runtime_error("Test case failed");
            }
        }
    };

    // Test single character pattern
    execute({
        "x",
        {
            {"x", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 1}}}},
