#include "common_utest.h"

void test_drotmg()
{
    double val_d1, ref_d1;
    double val_d2, ref_d2;
    double val_x1, ref_x1;
    double val_y1, ref_y1;
    double val_param[5];
    double ref_param[5];
    int idx = 0;

    val_d1 = ref_d1 = 0.21149573940783739;
    val_d2 = ref_d2 = 0.046892057172954082;
    val_x1 = ref_x1 = -0.42272687517106533;
    val_y1 = ref_y1 = 0.42211309121921659;

    for (idx = 0; idx < 5; idx++) {
        val_param[idx] = ref_param[idx] = 0.0;
    }

    // OpenBLAS implementation
    BLASFUNC(drotmg)(&val_d1, &val_d2, &val_x1, &val_y1, val_param);

    // Reference implementation
    BLASFUNC_REF(drotmg)(&ref_d1, &ref_d2, &ref_x1, &ref_y1, ref_param);

    CU_ASSERT_DOUBLE_EQUAL(val_d1, ref_d1, CHECK_EPS);
    CU_ASSERT_DOUBLE_EQUAL(val_d2, ref_d2, CHECK_EPS);
    CU_ASSERT_DOUBLE_EQUAL(val_x1, ref_x1, CHECK_EPS);
    CU_ASSERT_DOUBLE_EQUAL(val_y1, ref_y1, CHECK_EPS);

    for (idx = 0; idx < 5; idx++) {
        CU_ASSERT_DOUBLE_EQUAL(val_param[idx], ref_param[idx], CHECK_EPS);
    }
}

