template <typename T>
IGL_INLINE void igl::print_vector(std::vector<T>& data)
{
  using namespace std;
  for (int index = 0; index < data.size(); ++index)
    std::cerr << data[index] << " ";
  std::cerr << std::endl;
}

template <typename T>
IGL_INLINE void igl::print_vector(std::vector< std::vector<T> >& matrix)
{
  using namespace std;
  for (int row = 0; row < matrix.size(); ++row)
  {
    std::cerr << row << ": ";
    for (int col = 0; col < matrix[row].size(); ++col)
      std::cerr << matrix[row][col] << " ";
    std::cerr << std::endl;
  }
}

template <typename T>
IGL_INLINE void igl::print_vector(std::vector< std::vector< std::vector<T> > >& tensor)
{
  using namespace std;
  for (int depth = 0; depth < tensor.size(); ++depth)
  {
    std::cerr << "Matrix " << depth << std::endl;
    for (int row = 0; row < tensor[depth].size(); ++row)
    {
      std::cerr << row << ": ";
      for (int col = 0; col < tensor[depth][row].size(); ++col)
        std::cerr << tensor[depth][row][col] << " ";
      std::cerr << std::endl;
    }

    std::cerr << "---- end " << depth << std::endl;
  }
}

