#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    // 1. Setup: Convert S to I to initialize ^ marker
    cout << "S=I" << endl;

    // 2. Match Detection: If ? detects token (1,2,3) or start (^) on left, success
    cout << "1?=(return)1" << endl;
    cout << "2?=(return)1" << endl;
    cout << "3?=(return)1" << endl;
    cout << "^?=(return)1" << endl;

    // 3. Propagation: Shift uppercase letters (A,B,C) right over tokens (1,2,3)
    string upperChars = "XYZ";
    string digitTokens = "456";
    for(char u : upperChars) {
        for(char t : digitTokens) {
            cout << u << t << "=" << t << u << endl;
        }
    }

    // 4. Matching Logic: Upper ? Lower -> Token ?
    cout << "X?x=4?" << endl;
    cout << "Y?y=5?" << endl;
    cout << "Z?z=6?" << endl;

    // 5. Error Handling: Upper ? WrongLower -> % (Reset)
    string lowerSet = "xyz"; 
    string lowerWithEnd = "xyz$";
    for(char l : lowerWithEnd) {
        if(l == 'x') continue;
        cout << "X?" << l << "=%X" << l << endl;
    }
    for(char l : lowerWithEnd) {
        if(l == 'y') continue;
        cout << "Y?" << l << "=%Y" << l << endl;
    }
    for(char l : lowerWithEnd) {
        if(l == 'z') continue;
        cout << "Z?" << l << "=%Z" << l << endl;
    }

    // 6. Reset Mechanism: % shifts left, restoring tokens
    cout << "%X=X%" << endl;
    cout << "%Y=Y%" << endl;
    cout << "%Z=Z%" << endl;
    cout << "%4=X%x" << endl;
    cout << "%5=Y%y" << endl;
    cout << "%6=Z%z" << endl;

    // 7. Start Deletion: When % reaches beginning, transition to D
    cout << "^%=^D" << endl;

    // 8. Deletion Process: D moves right through T to erase first char of s
    cout << "DX=XD" << endl;
    cout << "DY=YD" << endl;
    cout << "DZ=ZD" << endl;
    cout << "Dx=?" << endl;
    cout << "Dy=?" << endl;
    cout << "Dz=?" << endl;
    cout << "D$=(return)0" << endl; // s empty

    // 9. Initialization Sequence Logic
    cout << "xI=Ix" << endl;
    cout << "yI=Iy" << endl;
    cout << "zI=Iz" << endl;
    cout << "I=^W" << endl;
    cout << "Wx=xW" << endl;
    cout << "Wy=yW" << endl;
    cout << "Wz=zW" << endl;
    cout << "W=P" << endl; // Becomes P (Partition Separator)

    // 10. Reverse T Phase: Pa -> ga P, move ga left, deposit X, return <
    cout << "Pa=gaP" << endl;
    cout << "Pb=gbP" << endl;
    cout << "Pc=gcP" << endl;
    cout << "aga=gaa" << endl; cout << "bga=gab" << endl; cout << "cga=gac" << endl;
    cout << "agb=gba" << endl; cout << "bgb=gbb" << endl; cout << "cgb=gbc" << endl;
    cout << "agc=gca" << endl; cout << "bgc=gcb" << endl; cout << "cgc=gcc" << endl;
    cout << "^ga=^X<" << endl;
    cout << "^gb=^Y<" << endl;
    cout << "^gc=^Z<" << endl;
    cout << "<x=x<" << endl; cout << "<y=y<" << endl; cout << "<z=z<" << endl;
    cout << "<P=P" << endl;

    // 11. End Reverse: P becomes $
    cout << "P=$" << endl;

    // 12. Insert ? at boundary (Upper-Lower and ^-Lower)
    for(char u : upperChars) {
        for(char l : lowerWithEnd) {
            cout << u << l << "=" << u << "?" << l << endl;
        }
    }
    for(char l : lowerSet) {
        cout << "^" << l << "=^?" << l << endl;
    }
    cout << "^$=(return)1" << endl;

    return 0;
}

