#define EXPECTED_CRC2 2532008468

MU_TEST(test_add_entries) {
  struct zip_t *archive = zip_open(ARCHIVE_NAME, ZIP_DEFAULT_COMPRESSION_LEVEL, 'a');
  mu_check(archive != NULL);

  mu_assert_int_eq(0, zip_entry_open(archive, "test\\test-2.txt"));
  mu_assert_int_eq(0, strcmp(zip_entry_name(archive), "test/test-2.txt"));
  mu_assert_int_eq(file_count, zip_entry_index(archive));

  mu_assert_int_eq(0, zip_entry_write(archive, SAMPLE_DATA_2, strlen(SAMPLE_DATA_2)));
  mu_assert_int_eq(strlen(SAMPLE_DATA_2), zip_entry_size(archive));
  mu_check(EXPECTED_CRC2 == zip_entry_crc32(archive));

  mu_assert_int_eq(0, zip_entry_close(archive));
  ++file_count;
  zip_close(archive);

  archive = zip_open(ARCHIVE_NAME, ZIP_DEFAULT_COMPRESSION_LEVEL, 'a');
  mu_assert_int_eq(0, zip_entry_open(archive, "test\\empty/"));
  mu_assert_int_eq(0, strcmp(zip_entry_name(archive), "test/empty/"));
  mu_assert_int_eq(0, zip_entry_size(archive));
  mu_assert_int_eq(0, zip_entry_crc32(archive));
  mu_assert_int_eq(file_count, zip_entry_index(archive));
  mu_assert_int_eq(0, zip_entry_close(archive));
  ++file_count;
  zip_close(archive);

  archive = zip_open(ARCHIVE_NAME, ZIP_DEFAULT_COMPRESSION_LEVEL, 'a');
  mu_assert_int_eq(0, zip_entry_open(archive, "empty/"));
  mu_assert_int_eq(0, strcmp(zip_entry_name(archive), "empty/"));
  mu_assert_int_eq(0, zip_entry_size(archive));
  mu_assert_int_eq(0, zip_entry_crc32(archive));
  mu_assert_int_eq(file_count, zip_entry_index(archive));
  mu_assert_int_eq(0, zip_entry_close(archive));
  ++file_count;

  mu_assert_int_eq(0, zip_entry_open(archive, "dotfiles/.test"));
  mu_assert_int_eq(0, strcmp(zip_entry_name(archive), "dotfiles/.test"));
  mu_assert_int_eq(0, zip_entry_size(archive));
  mu_assert_int_eq(0, zip_entry_crc32(archive));
  mu_assert_int_eq(0, zip_entry_write(archive, SAMPLE_DATA_2, strlen(SAMPLE_DATA_2)));
  mu_assert_int_eq(strlen(SAMPLE_DATA_2), zip_entry_size(archive));
  mu_check(EXPECTED_CRC2 == zip_entry_crc32(archive));
  mu_assert_int_eq(file_count, zip_entry_index(archive));
  mu_assert_int_eq(0, zip_entry_close(archive));
  ++file_count;

  mu_assert_int_eq(file_count, zip_entries_total(archive));
  zip_close(archive);
}

