// Helper macro for comparison functions
#define MAKE_COMPARATOR(type, op) \
  [](const type* a, const type* b) { return (*a) op (*b); }

// Helper macro for key-based comparison of structs
#define MAKE_KEY_COMPARATOR(struct_type, key_field, op) \
  [](const struct_type* a, const struct_type* b) { return (a->key_field) op (b->key_field); }

