// Helper function to suppress lookup failures and initialize trace file
static M3Result SuppressLookupFailure(M3Result result)
{
    if (result == m3Err_none) {
        // Open trace file only once when first successful link occurs
        if (!logFile) {
            logFile = fopen("wasm3_trace.csv", "w");
        }
    } else if (result == m3Err_functionLookupFailed) {
        // Ignore function lookup failures
        result = m3Err_none;
    }
    return result;
}

// Link all tracer functions to the module
M3Result m3_LinkTracer(IM3Module module)
{
    M3Result result = m3Err_none;
    const char* envNamespace = "env";

    // Link execution tracing functions
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "log_execution",       "v(i)",     &m3_env_log_execution)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "log_exec_enter",      "v(ii)",    &m3_env_log_exec_enter)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "log_exec_exit",       "v(ii)",    &m3_env_log_exec_exit)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "log_exec_loop",       "v(i)",     &m3_env_log_exec_loop)));

    // Link pointer operations tracing
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "load_ptr",            "i(iiii)",  &m3_env_load_ptr)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "store_ptr",           "i(iiii)",  &m3_env_store_ptr)));

    // Link value loading/storing tracing
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "load_val_i32",        "i(ii)",    &m3_env_load_val_i32)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "load_val_i64",        "I(iI)",    &m3_env_load_val_i64)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "load_val_f32",        "f(if)",    &m3_env_load_val_f32)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "load_val_f64",        "F(iF)",    &m3_env_load_val_f64)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "store_val_i32",       "i(ii)",    &m3_env_store_val_i32)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "store_val_i64",       "I(iI)",    &m3_env_store_val_i64)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "store_val_f32",       "f(if)",    &m3_env_store_val_f32)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "store_val_f64",       "F(iF)",    &m3_env_store_val_f64)));

    // Link local variable operations tracing
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "get_i32",             "i(iii)",   &m3_env_get_i32)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "get_i64",             "I(iiI)",   &m3_env_get_i64)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "get_f32",             "f(iif)",   &m3_env_get_f32)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "get_f64",             "F(iiF)",   &m3_env_get_f64)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "set_i32",             "i(iii)",   &m3_env_set_i32)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "set_i64",             "I(iiI)",   &m3_env_set_i64)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "set_f32",             "f(iif)",   &m3_env_set_f32)));
    _   (SuppressLookupFailure(m3_LinkRawFunction(module, envNamespace, "set_f64",             "F(iiF)",   &m3_env_set_f64)));

_catch:
    return result;
}
#endif // d_m3HasTracer

