// Function declarations for system call handling
void __OSSystemCallVectorStart(void);
void __OSSystemCallVectorEnd(void);

#ifdef __GEKKO__
static asm void SystemCallHandler(void) {
entry __OSSystemCallVectorStart
    nofralloc
    mfspr r8, HID0
    ori r11, r8, 0x8
    mtspr HID0, r11
    isync
    sync
    mtspr HID0, r8
    rfi
entry __OSSystemCallVectorEnd
    nop
}
#endif

void __OSInitializeSystemCall(void) {
    void* target = (void*)OSPhysicalToCached(0xC00);
    memcpy(target, __OSSystemCallVectorStart, (u32)&__OSSystemCallVectorEnd - (u32)&__OSSystemCallVectorStart);
    DCFlushRangeNoSync(target, 0x100);
    __sync();
    ICInvalidateRange(target, 0x100);
}

