#include <iostream>

void multiplyByValue(int& value, int factor)
{
    value = value * factor;
}

void addValue(int& value, int increment)
{
    value = value + increment;
}

void display(int& value)
{
    std::cout << value << ' ';
}

void applyFunction(int* data, int length, void (*operation)(int&))
{
    for (int index = 0; index < length; index++)
    {
        operation(data[index]);
    }
}

void applyFunctionWithParam(int* data, int length, void (*operation)(int&, int), int param)
{
    for (int index = 0; index < length; index++)
    {
        operation(data[index], param);
    }
}

int main()
{
    int numbers[5] = {1, 2, 3, 4, 5};

    applyFunctionWithParam(numbers, 5, multiplyByValue, 10);
    applyFunctionWithParam(numbers, 5, addValue, 1);
    applyFunction(numbers, 5, [](int& val){ val = val * 10; });
    applyFunction(numbers, 5, display);

    return 0;
}

