DisableProxyPluginDialog::DisableProxyPluginDialog(
    MOBase::IPlugin* pluginToDisable, std::vector<MOBase::IPlugin*> const& dependencies,
    QWidget* parentWidget)
    : QDialog(parentWidget), ui(new Ui::DisableProxyPluginDialog)
