void FDMXProtocolE131RootLayerPacket::Serialize(FArchive& Ar)
{
	Ar.SetByteSwapping(true);
	Ar << PreambleSize;
	Ar << PostambleSize;

	Ar.SetByteSwapping(false);
	Ar.Serialize(reinterpret_cast<void*>(ACNPacketIdentifier), ACN_IDENTIFIER_SIZE);

