	Ar << Vector;

	Ar.SetByteSwapping(false);
	Ar.Serialize(reinterpret_cast<void*>(SourceName), ACN_SOURCE_NAME_SIZE);

	Ar.SetByteSwapping(true);
	Ar << Priority;
