namespace {

// Address of the original function that retrieves tech use error messages
constexpr u32 Original_GetTechErrorMessage = 0x00491E80;

// Wrapper to intercept calls to the original function
void __declspec(naked) TechErrorMessageInterceptor() {
    // Local storage for intercepted parameters and result
    static CUnit* unitTarget;
    static s8 playerIndex;
    static u16 techIdentifier;
    static u16 errorResult;

    __asm {
        PUSHAD                  // Save all general-purpose registers
        LEA EBP, [ESP - 4]      // Adjust base pointer for local access
        MOV unitTarget, EAX     // First arg: target unit pointer
        MOVZX EBX, BL           // Second arg: casting player (zero-extend)
        MOV playerIndex, BL
        MOV ECX, ESP
        ADD ECX, 36             // Offset after PUSHAD (32 bytes) + CALL return address (4 bytes)
        MOVZX techIdentifier, WORD PTR [ECX]
    }

    // Invoke the hook logic to determine appropriate error message
    errorResult = hooks::interceptTechErrorMessage(unitTarget, static_cast<u8>(playerIndex), techIdentifier);

    __asm {
        POPAD                   // Restore registers
        MOVZX EAX, errorResult  // Prepare return value in AX
        RETN 4                  // Clean up 4 bytes from stack (caller cleanup)
    }
}

} // anonymous namespace

namespace hooks {

// Install hook at the target function entry point
void installTechTargetHooks() {
    jmpPatch(TechErrorMessageInterceptor, Original_GetTechErrorMessage);
}

// Direct call wrapper — used when invoking the original function directly
u16 interceptTechErrorMessage(const CUnit* unit, s8 player, u16 techId) {
    u32 techIdParam = techId;
    u16 result;

    __asm {
        PUSHAD                  // Preserve register state
        PUSH techIdParam        // Push third argument (tech ID)
        MOV BL, player          // Second argument: player index
        MOV EAX, unit           // First argument: target unit
        CALL Original_GetTechErrorMessage  // Call original function
        MOV result, AX          // Capture return value (error code)
        POPAD                   // Restore registers
    }

    return result;
}

} // namespace hooks

