// Display elements in a container using iterators
template<typename IteratorT>
void display_sequence(const IteratorT& start, const IteratorT& finish)
{
    for (auto iter = start; iter != finish; ++iter)
        std::cout << *iter << " ";
    std::cout << std::endl;
}

// Count elements between two iterators
template<typename IteratorT>
size_t count_elements(const IteratorT& start, const IteratorT& finish)
{
    size_t counter = 0;
    for (auto iter = start; iter != finish; ++iter)
        ++counter;
    return counter;
}

int main()
{
    // Initialize list with test data
    std::list<int> initial_data{ 3, 1, 4, 22, 31 };

    // Display full list content
    display_sequence(initial_data.begin(), initial_data.end());
    std::cout << "Element count: " << count_elements(initial_data.begin(), initial_data.end()) << std::endl;

    // Transfer to vector and work with subset
    std::vector<int> temp_storage;
    std::copy(initial_data.begin(), initial_data.end(), std::back_inserter(temp_storage));

    // Create view of first four elements
    auto end_iter = std::next(temp_storage.begin(), 4);
    display_sequence(temp_storage.begin(), end_iter);
    std::cout << "Subset element count: " << count_elements(temp_storage.begin(), end_iter) << std::endl;

    // Randomize and shuffle subset
    randomize();
    std::shuffle(temp_storage.begin(), end_iter, global_urng());

    // Output shuffled subset
    std::copy(temp_storage.begin(), end_iter, std::ostream_iterator<int>(std::cout, " "));
    std::cout << std::endl;

    // Output original list unchanged
    std::copy(initial_data.begin(), initial_data.end(), std::ostream_iterator<int>(std::cout, " "));
    std::cout << std::endl;

    return 0;
}

