  ros::NodeHandle private_nh("~");

  PatternPostureGenerator generator(private_nh);

  ros::spin();
  return 0;
}

PatternPostureGenerator::PatternPostureGenerator() {}

PatternPostureGenerator::PatternPostureGenerator(ros::NodeHandle& nh) {
  std::map<std::string, std::string> raw_patterns;
  if (!nh.getParam("pattern", raw_patterns)) {
    return;
  }

  for (const auto& pair : raw_patterns) {
    const std::string& key = pair.first;
    const std::string& value = pair.second;

    std::vector<double> posture_values;
    const std::string param_path = "pattern/" + value;

    if (!nh.getParam(param_path, posture_values)) {
      continue; // Skip invalid entries instead of returning early
    }

    // Store only non-empty postures
    if (!posture_values.empty()) {
      posture_datas[value] = posture_values;
    }
  }

  get_posture_service = nh.advertiseService("getPostureKey", &PatternPostureGenerator::handleGetPosture, this);
}

bool PatternPostureGenerator::handleGetPosture(pattern_posture_generator::PatternKeyPosture::Request& req,
                                               pattern_posture_generator::PatternKeyPosture::Response& res) {
  auto it = posture_datas.find(req.name);
  if (it == posture_datas.end() || it->second.empty()) {
    return false;
  }

  res.posture = it->second;
  return true;
}

