int main()
{
    // Define bounds for output dimensions and number of integrators
    Eigen::Vector2i output_dim_range( 2, 2 );
    Eigen::Vector2i integrator_count_range( 2, 2 );

    // Set state space bounds [y_min, y_max, dy_min, dy_max]
    Eigen::Vector4d Y_bounds;
    Y_bounds << -1, 10, -2, 10;

    // Set control input bounds [u_min, u_max, du_min, du_max]
    Eigen::Vector4d U_bounds;
    U_bounds << -1, 1, -1, 1;

    // Define period (time step) range
    Eigen::Vector2d time_step_range( 0.05, 0.1 );

    // Specify number of goals and obstacles ranges
    Eigen::Vector2i goal_count_range( 1, 2 );
    Eigen::Vector2i obstacle_count_range( 0, 1 );

    // Seed random number generator with current time
    std::srand( std::time( nullptr ) );

    // Generate a random problem instance using the defined bounds
    Problem *instance = Problem::random( output_dim_range,
                                         integrator_count_range,
                                         Y_bounds, U_bounds,
                                         goal_count_range,
                                         obstacle_count_range,
                                         time_step_range );

    // Print the generated problem to standard output
    std::cout << *instance << std::endl;

    // Output the logical formula representation to standard error
    instance->to_formula( std::cerr );
    std::cerr << std::endl;

    // Clean up dynamically allocated memory
    delete instance;

    return 0;
}

