// Test fixture for Engine functionality
class EngineEchoTest : public ::testing::Test {
protected:
    void SetUp() override {
        // Initialize engine components
        engine_ = std::make_unique<Engine>();
        stop_signal_ = false;

        // Set up signal handling mechanism
        signal_handler_ = [this]() { 
            std::lock_guard<std::mutex> lock(mutex_);
            stop_signal_ = true; 
            cv_.notify_one();
        };
    }

    void TearDown() override {
        // Cleanup resources
        if (engine_) {
            engine_->stop();
        }
    }

    std::unique_ptr<Engine> engine_;
    std::atomic<bool> stop_signal_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::function<void()> signal_handler_;
};

// Test echo server functionality
TEST_F(EngineEchoTest, EchoDataVerification) {
    // Start the engine and initialize server
    ASSERT_TRUE(engine_->start());

    // Create TCP client connection
    int client_socket = engine_->createClientConnection();
    ASSERT_NE(client_socket, -1);

    // Send test data to server
    const char* test_message = "Hello, Echo!";
    ssize_t bytes_sent = write(client_socket, test_message, strlen(test_message));
    ASSERT_EQ(bytes_sent, static_cast<ssize_t>(strlen(test_message)));

    // Read response from server
    char buffer[256] = {0};
    ssize_t bytes_received = read(client_socket, buffer, sizeof(buffer) - 1);
    ASSERT_GT(bytes_received, 0);

    // Verify echoed data matches original
    std::string received_data(buffer, bytes_received);
    EXPECT_STREQ(received_data.c_str(), test_message);

    // Clean up connection
    close(client_socket);
}

