#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <iterator>
using namespace std;

class IncrementAndDoubling {
public:
    int calculateMinOperations(vector<int> targetArray, int operationCount) {
        // Base case: all elements are zero
        if (all_of(targetArray.begin(), targetArray.end(), [](int val) { return val == 0; })) {
            return operationCount;
        }

        // Check if all numbers are even
        bool allEven = all_of(targetArray.begin(), targetArray.end(), [](int val) { return val % 2 == 0; });

        if (allEven) {
            // Perform division by 2 for all elements
            for (auto &value : targetArray) {
                value /= 2;
            }
            return calculateMinOperations(targetArray, operationCount + 1);
        } else {
            // Subtract 1 from all odd elements
            for (auto &value : targetArray) {
                if (value % 2 == 1) {
                    value -= 1;
                    operationCount++;
                }
            }
            return calculateMinOperations(targetArray, operationCount);
        }
    }

    int getMin(vector<int> DesiredArray) {
        int operations = 0;
        return calculateMinOperations(DesiredArray, operations);
    }
};

