#include "x_client.hpp"
#include "x_event_source.hpp"
#include "x_client_container.hpp"
#include "x_clients_preview.hpp"
#include "layout_t.hpp"
#include "grid.hpp"

int main(int argc, char ** argv) {
    // Establish connection to X server
    x_connection conn;

    // Grab the Tab key with Super (Mod4) modifier for window switching
    conn.grab_key(XCB_MOD_MASK_4, XK_Tab);

    // Create event source to handle X events
    x_event_source event_src(conn);

    // Initialize client container to manage windows
    x_client_container clients(conn, event_src);

    // Set up grid layout for window arrangement
    grid_t window_grid;

    // Create preview manager for showing clients in grid
    x_clients_preview preview(conn, &window_grid, clients);

    // Register handlers for event processing
    event_src.register_handler(&conn);
    event_src.register_handler(&preview);

    // Start the main event loop
    event_src.run_event_loop();

    return 0;
}

