// Write the main function declaration section in assembly
void MainDeclaration::write(AssemblyFileWriter& writer) {
    writer.stream() << ".text" << endl
                    << ".globl main" << endl
                    << "\t.type main, @function" << endl;
}

// Verify that a function exists before calling it
void FunctionCall::checkFunctions(Program& program) {
    if (!program.hasFunction(m_function)) {
        throw CompilerException("The function \"" + m_function + "()\" does not exist", token());
    }
}

// Generate assembly code for a function definition
void Function::write(AssemblyFileWriter& writer) {
    writer.stream() << endl << m_name << ":" << endl;

    writer.stream() << "pushl %ebp" << endl;
    writer.stream() << "movl %esp, %ebp" << endl;

    ParseNode::write(writer);
    writer.stream() << "leave" << endl;
    writer.stream() << "ret" << endl;
}

// Emit a function call instruction
void FunctionCall::write(AssemblyFileWriter& writer) {
    writer.stream() << "call " << m_function << endl;
}

