// Function to capture and return the blue-colored output of a string
std::string CaptureBlueOutput(const std::string& text) {
    // Write to temporary file instead of stdout
    std::ofstream file("temp_output.txt");
    std::streambuf* originalCoutBuffer = std::cout.rdbuf();

    // Redirect cout to the file
    std::cout.rdbuf(file.rdbuf());

    // Output with rang formatting (blue color)
    std::cout << "\033[34m" << text << "\033[0m";

    // Restore original cout buffer and close file
    std::cout.rdbuf(originalCoutBuffer);
    file.close();

    // Read back the content from the file
    std::ifstream readFile("temp_output.txt");
    std::string result;
    std::getline(readFile, result);
    readFile.close();

    return result;
}

