namespace base {

ThreadTestHelper::ThreadTestHelper(MessageLoopProxy* target_thread)
    : result_(false),
      worker_thread_(target_thread),
      completion_event_(false, false) {
}

bool ThreadTestHelper::Execute() {
  if (!worker_thread_->PostTask(
          FROM_HERE, base::Bind(&ThreadTestHelper::ExecuteOnWorker, this))) {
    return false;
  }
  completion_event_.Wait();
  return result_;
}

void ThreadTestHelper::PerformTest() { set_result(true); }

ThreadTestHelper::~ThreadTestHelper() {}

void ThreadTestHelper::ExecuteOnWorker() {
  PerformTest();
  completion_event_.Signal();
}

