#include <iostream>

using namespace std;

// Base class with a method and an integer member
class Root {
public:
    void display(int value) {
        cout << "Root::display(int)" << endl;
    }
protected:
    int number = 0;
};

// First derived class, inheriting virtually from Root
class Branch1 : virtual public Root {
public:
    void show(char symbol) {
        cout << "Branch1::show(char)" << endl;
    }
    void operate(char symbol) {
        cout << "Branch1::operate(char)" << endl;
    }
protected:
    char letter = 'x';
};

// Second derived class, also inheriting virtually from Root
class Branch2 : virtual public Root {
public:
    void operate(int value) {
        cout << "Branch2::operate(int)" << endl;
    }
protected:
    int number = 2;
    char letter = 'y';
};

// Final class combining both branches (VMI pattern)
class Combined : public Branch1, public Branch2 {
public:
    void print_number() {
        cout << Root::number << endl; // Explicitly access Root's number to avoid ambiguity
    }

    void print_letter() {
        cout << Branch1::letter << endl; // Must qualify since both branches define letter
    }
};

int main() {
    Combined obj;
    obj.print_number();
    obj.print_letter();
    obj.Branch1::operate('a'); // Qualify to call Branch1's version
    obj.display(5);            // Resolves to Branch1's inherited display (via Root)
    obj.display('b');          // Also resolves via Branch1's inheritance path
    obj.Root::display(10);     // Explicitly call Root's method

    return 0;
}

