// Move constructor: transfers ownership of OpenGL resources from 'other' to this instance
VertexBuffer::VertexBuffer(VertexBuffer&& other) noexcept 
    : vBO{other.vBO}, iBO{other.iBO}, nBO{other.nBO}, vao{other.vao}, 
      numIndices{other.numIndices}, extremes{other.extremes},
      bounds{std::exchange(other.bounds, nullptr)} {
    // Reset source object's handles to avoid double-delete or use-after-free
    other.vBO = 0;
    other.iBO = 0;
    other.nBO = 0;
    other.vao = 0;
}

// Constructor with explicit buffer IDs and bounding data
VertexBuffer::VertexBuffer(GLuint myVBO, GLuint myIBO, GLuint myNBO, 
                           unsigned int myNumIndices, 
                           std::tuple<glm::vec3, glm::vec3> myExtremes)
    : vBO(myVBO), iBO(myIBO), nBO(myNBO), numIndices(myNumIndices), 
      extremes(myExtremes), 
      bounds{std::make_unique<collisiondetection::AxisAlignedBoundingBox>(myExtremes)} {

    // Create and configure VAO
    glGenVertexArrays(1, &vao);
    glBindVertexArray(vao);

    // Set up position attribute (index 0)
    glBindBuffer(GL_ARRAY_BUFFER, vBO);
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 0, nullptr);
    glEnableVertexAttribArray(0);

    // Set up normal attribute (index 1)
    glBindBuffer(GL_ARRAY_BUFFER, nBO);
    glVertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE, 0, nullptr);
    glEnableVertexAttribArray(1);

    // Unbind VAO for safety
    glBindVertexArray(0);
}

// Bind the vertex array and element buffer for rendering
void VertexBuffer::bindBuffers() const {
    glBindVertexArray(vao);
    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, iBO);
}

#include <iostream>
#include <bitset>
#include <vector>

int main() {
    std::vector<int> numbers = {1, 2, 3, 5, 8, 13, 21};
    unsigned long value = 0UL;

    // Set bits using bitwise OR and left shift operations
    for (int index : numbers) {
        value |= (1UL << index);
    }

    std::cout << value << std::endl;

    // Create bitset from the computed value
    std::bitset<32> bits(value);
    std::cout << bits << std::endl;

    // Alternative method: directly set bits in a new bitset
    std::bitset<32> alternateBits;
    for (int pos : numbers) {
        alternateBits.set(pos);
    }
    std::cout << alternateBits << std::endl;

    // Compare both bitsets for equality
    if (bits == alternateBits) {
        std::cout << "bits == alternateBits" << std::endl;
    }

    return 0;
}

