namespace {
class Repl {
    std::istream& input_stream_;
    std::ostream& output_stream_;
    std::string prompt_text_ = "mclisp> ";

public:
    Repl(std::istream& in = std::cin, std::ostream& out = std::cout) 
        : input_stream_(in), output_stream_(out) {}

    int run();
};

int Repl::run() {
    std::string user_input;
    do {
        output_stream_ << prompt_text_;
        input_stream_ >> user_input;

        if (user_input == "quit") {
            break;
        }

        output_stream_ << user_input << std::endl;
    } while (true);

    return 0;
}
} // namespace

int main(int argc, const char** argv) {
    Repl repl_instance;
    return repl_instance.run();
}

