namespace vtx
{
    // Internal structure for Vortex private members - renamed for variety
    struct Vortex::PrivateData
    {
        std::unique_ptr<Application> appInstance;
    };

    // Constructor: Initialize logger and create private data container
    Vortex::Vortex() 
        : m_private{ new PrivateData{} }
    {
        Logger::createInstance();
        ldebug() << "Vortex library instance instantiated" << endline();
    }

    // Destructor: Clean up resources in proper order
    Vortex::~Vortex()
    {
        ldebug() << "Vortex library instance destruction initiated" << endline();

        // Explicitly clear the application before deleting private data
        if (m_private && m_private->appInstance) {
            m_private->appInstance.reset();
        }

        DELETE_PRIVATE_MPRIVATE_PIMPL(Vortex);

        ldebug() << "Vortex library instance fully destroyed" << endline();
    }

    // Set the application - using move assignment instead of reset
    void Vortex::setApplication(Application&& app)
    {
        if (m_private) {
            m_private->appInstance = std::make_unique<Application>(std::move(app));
        }
    }

    // Initialize method: Check application presence and prepare system
    void Vortex::initialize()
    {
        linfo() << "Starting Vortex library initialization..." << endline();

        // Verify application is properly set before proceeding
        if (!m_private || !m_private->appInstance) {
            lerror() << "Critical error: No application configured" << endline();
            return;
        }

        linfo() << "Vortex library initialization completed successfully" << endline();
    }

    // Deinitialize method: Perform cleanup procedures
    void Vortex::deinitialize()
    {
        linfo() << "Initiating Vortex library shutdown sequence..." << endline();

        // Clear application reference during shutdown
        if (m_private && m_private->appInstance) {
            m_private->appInstance.reset();
        }

        linfo() << "Vortex library shutdown completed" << endline();
    }
}

