// Flow control configuration macros
#define CONSOLE_FLOWCONTROL_RTS     1
#define CONSOLE_FLOWCONTROL_CTS     2
#define CONSOLE_FLOWCONTROL_RTSCTS  3

// Helper macros for token concatenation to resolve flow control setting
#define mbed_console_concat_(x) CONSOLE_FLOWCONTROL_##x
#define mbed_console_concat(x) mbed_console_concat_(x)
#define CONSOLE_FLOWCONTROL mbed_console_concat(MBED_CONF_TARGET_CONSOLE_UART_FLOW_CONTROL)

SingletonPtr<GreenteaSerial> greentea_serial;

GreenteaSerial::GreenteaSerial() 
    : mbed::RawSerial(USBTX, USBRX, MBED_CONF_PLATFORM_STDIO_BAUD_RATE) {

    // Configure serial flow control based on compile-time setting
    switch (CONSOLE_FLOWCONTROL) {
        case CONSOLE_FLOWCONTROL_RTS:
            set_flow_control(SerialBase::RTS, STDIO_UART_RTS, NC);
            break;
        case CONSOLE_FLOWCONTROL_CTS:
            set_flow_control(SerialBase::CTS, NC, STDIO_UART_CTS);
            break;
        case CONSOLE_FLOWCONTROL_RTSCTS:
            set_flow_control(SerialBase::RTSCTS, STDIO_UART_RTS, STDIO_UART_CTS);
            break;
        default:
            // No flow control if none of the expected values match
            set_flow_control(SerialBase::NONE, NC, NC);
            break;
    }
}

