namespace RosettaStone
{
Enchant Enchants::GetEnchantFromText(const std::string& cardID)
{
    std::vector<Effect> effectList;
    static const std::regex attackHealthPattern("\\+([[:digit:]]+)/\\+([[:digit:]]+)");
    static const std::regex attackOnlyPattern("\\+([[:digit:]]+) Attack");

    const std::string description = Cards::FindCardByID(cardID).text;
    std::smatch matchResults;

    if (std::regex_search(description, matchResults, attackHealthPattern))
    {
        int attackValue = std::stoi(matchResults[1].str());
        int healthValue = std::stoi(matchResults[2].str());

        effectList.push_back(Effects::AttackN(attackValue));
        effectList.push_back(Effects::HealthN(healthValue));
    }
    else if (std::regex_search(description, matchResults, attackOnlyPattern))
    {
        int attackValue = std::stoi(matchResults[1].str());
        effectList.push_back(Effects::AttackN(attackValue));
    }

    return Enchant(effectList);
}
}  // namespace RosettaStone

