// Benchmark function to measure FarmHash performance for different input sizes
static void BM_Farmhash(benchmark::State& state) {
  // Create a string filled with dots of size specified by the benchmark argument
  std::string payload(state.range(0), '.');

  // Run the benchmark loop
  for (auto _ : state) {
    // Compute the 64-bit hash of the payload string
    util::Hash64(payload);
  }

  // Update statistics: bytes processed = iterations * payload size
  state.SetBytesProcessed(static_cast<int64_t>(state.iterations()) * 
                          static_cast<int64_t>(state.range(0)));
}

// Register the benchmark with various input sizes
BENCHMARK(BM_Farmhash)
    ->Arg(4)
    ->Arg(11)
    ->Arg(25)
    ->Arg(100)
    ->Arg(1000)
    ->Arg(10000);

// Entry point for the benchmark suite
BENCHMARK_MAIN();

