// Function demonstrating nested local struct definitions
void f1() {
  // Outer local struct X with forward declaration of inner struct Y
  struct X {
    struct Y;  // Forward declaration
  };

  // Definition of the nested struct Y outside its scope
  struct X::Y {
    void f() {}
  };
}

// Function with nested struct defined inline
void f2() {
  // Local struct X containing both forward and full definition of Y
  struct X {
    struct Y;  // Forward declaration

    // Full definition of nested struct Y within same scope
    struct Y {
      void f() {}
    };
  };
}

// Function showing that nested local classes cannot access outer function's local variables
void f3(int a) { 
  struct X {
    struct Y {
      int f() { return a; } // Error: cannot access local variable 'a' from enclosing function
    };
  };
}

#include <gtest/gtest.h>
