namespace {

// A type with a noexcept move constructor
struct NonThrowingMoveCtor {
   NonThrowingMoveCtor(NonThrowingMoveCtor&&) noexcept = default;
};

// A type whose move constructor may throw
struct ThrowingMoveCtor {
   ThrowingMoveCtor(ThrowingMoveCtor&&) {};
};

// A type with a noexcept move assignment operator
struct NonThrowingMoveAssign {
   NonThrowingMoveAssign& operator=(NonThrowingMoveAssign&&) noexcept {
      return *this; 
   }
};

// A type whose move assignment operator may throw
struct ThrowingMoveAssign {
   ThrowingMoveAssign& operator=(ThrowingMoveAssign&&) {
      return *this;
   }
};

} // namespace

TEST(TestOfStdTypeTraits, VerifyNothrowMoveConstructibility) {
   static_assert(std2::is_nothrow_move_constructible_v<NonThrowingMoveCtor>,
      "NonThrowingMoveCtor should be nothrow move constructible");
   static_assert(!std2::is_nothrow_move_constructible_v<ThrowingMoveCtor>,
      "ThrowingMoveCtor should not be nothrow move constructible");
}

TEST(TestOfStdTypeTraits, VerifyNothrowMoveAssignability) {
   static_assert(std2::is_nothrow_move_assignable_v<NonThrowingMoveAssign>,
      "NonThrowingMoveAssign should be nothrow move assignable");
   static_assert(!std2::is_nothrow_move_assignable_v<ThrowingMoveAssign>,
      "ThrowingMoveAssign should not be nothrow move assignable");
}

