#include "runtime_internal.h"

// Helper macro to define inline functions with specific attributes
#define INLINE inline __attribute__((weak)) __attribute__((used)) __attribute__((always_inline)) __attribute__((nothrow)) __attribute__((pure))

extern "C" {

// Convert raw 32-bit representation to float using union-based type punning
INLINE float float_from_bits(uint32_t bits) {
    union {
        uint32_t as_uint;
        float as_float;
    } converter;

    converter.as_uint = bits;
    return converter.as_float;
}

// Return NaN (Not a Number) for 32-bit floats
INLINE float nan_f32() {
    return float_from_bits(0x7fc00000);
}

// Return negative infinity for 32-bit floats
INLINE float neg_inf_f32() {
    return float_from_bits(0xff800000);
}

// Return positive infinity for 32-bit floats
INLINE float inf_f32() {
    return float_from_bits(0x7f800000);
}

}

