// Constructor initializes the prefix with a given message
prefix::prefix(std::string msg)
    : message(msg) { }

// Register a handler function for a specific character key
void prefix::add_handler(char key, std::function<void(contents&, boost::optional<int>)> handler) {
    this->key_map[key] = handler;
}

// Execute the prefix command: show prompt, read input, dispatch handler
void prefix::invoke(contents& cont, boost::optional<int> opt) {
    show_message(message + "-");
    char input_char = getch();

    auto iter = key_map.find(input_char);
    if (iter == key_map.end()) {
        show_message(std::string("Unrecognized key sequence: '")
                     + message + '-' + input_char + '\'');
    } else {
        iter->second(cont, opt);
        showing_message = false;
    }
}

// Conversion operator to std::function for use as a callable object
prefix::operator std::function<void(contents&, boost::optional<int>)>() {
    return std::function<void(contents&, boost::optional<int>)>(
        [this](contents& cont, boost::optional<int> opt) {
            this->invoke(cont, opt);
        });
}

