namespace libport
{
  // Display error message and exit with usage status
  void
  report_cli_error(const std::string& flag, const std::string& problem)
  {
    std::cerr
      << program_name << ": " << flag << ": " << problem
      << std::endl
      << "For additional help, run: `" << program_name << " --help'"
      << std::endl;

    ::exit(EX_USAGE);
  }

  // Handle case where an option expects a value but none provided
  void
  arg_required(const std::string& flag)
  {
    report_cli_error(flag, "argument expected");
  }

  // Handle missing required argument
  void
  arg_missing(const std::string& flag)
  {
    report_cli_error(flag, "no argument supplied");
  }

  // Handle unrecognized command line option
  void
  unknown_option(const std::string& flag)
  {
    report_cli_error(flag, "unrecognized option");
  }

  // Handle invalid value for an option
  void
  bad_option_value(const std::string& flag, const std::string& value)
  {
    report_cli_error(flag, "invalid value: " + value);
  }
}

