      const auto torso_transform = transform_buffer.lookupTransform("openni_depth_frame", "torso_1", ros::Time(0));

      // Extract translation vectors
      const Eigen::Vector3d head_point = tf2::transformToEigen(head_transform).translation();
      const Eigen::Vector3d torso_point = tf2::transformToEigen(torso_transform).translation();

      // Compute direction vector from torso to head
      const Eigen::Vector3d direction_vector = head_point - torso_point;

      // Create orientation: align X-axis with direction vector
      const Eigen::Quaterniond orientation_quat = 
          Eigen::Quaterniond::FromTwoVectors(Eigen::Vector3d::UnitX(), direction_vector);

      // Clear previous markers and publish new arrow
      visualizer.deleteAllMarkers();

      Eigen::Affine3d arrow_pose = Eigen::Affine3d::Identity();
      arrow_pose.linear() = orientation_quat.toRotationMatrix();
      // Position arrow at torso location (optional; original code didn't specify origin)
      arrow_pose.translation() = torso_point;

      visualizer.publishArrow(arrow_pose);
      visualizer.trigger();

    } catch (const tf2::TransformException& ex) {
      ROS_WARN_STREAM("TF lookup failed: " << ex.what());
    }

    loop_rate.sleep();
  }

  return 0;
}

