namespace EPITOME
{
    template <typename T>
    Room<T>::Room() {}

    template <typename T>
    Room<T>::~Room()
    {
        Clear();
    }

    template <typename T>
    Room<T>::Room(Room&& other)
    {
        items = std::move(other.items);
        // Ensure the source room no longer owns the items
        other.items.clear();
    }

    template<typename T>
    void Room<T>::Add(T* item)
    {
        items.emplace_back(item);
    }

    template <typename T>
    void Room<T>::Clear()
    {
        for (auto* ptr : items)
        {
            if (ptr != nullptr)
            {
                ptr->Dispose();
                delete ptr;
            }
        }
        items.shrink_to_fit();
        items.clear();
    }

    template <typename T>
    Disposable<T>::Disposable(T value)
    {
        this->item = std::move(value);
    }

    template <typename T>
    void Disposable<T>::Dispose() {}
}

