// Constructor for frameGPUi - initializes GPU texture with specified parameters
frameGPUi::frameGPUi (int width, int height, bool highPrecision) {
    glGenTextures(1, &textureID);
    glBindTexture(GL_TEXTURE_2D, textureID);

    // Set texture filtering parameters
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);

    // Determine data format based on precision requirement
    GLenum internalFormat = highPrecision ? GL_RGBA32F : GL_RGBA16F;
    GLenum pixelType = highPrecision ? GL_FLOAT : GL_HALF_FLOAT;

    // Allocate texture memory
    glTexImage2D(GL_TEXTURE_2D, 0, internalFormat, width, height, 0, GL_RGBA, pixelType, NULL);

    timecode = 0;
}

// Destructor - cleans up GPU texture resources
frameGPUi::~frameGPUi() {
    glDeleteTextures(1, &textureID);
}

