// Custom comparator to sort by value in descending order
template<typename K, typename V>
struct compare_by_value_desc {
    bool operator()(const std::pair<K, V>& a, const std::pair<K, V>& b) const {
        return a.second > b.second;
    }
};

int main() {
    // Map to store word counts
    std::map<std::string, int> word_counts;
    std::string current_word;

    // Read words from standard input and count occurrences
    while (std::cin >> current_word) {
        ++word_counts[current_word];
    }

    // Convert map to vector of pairs for sorting
    std::vector<std::pair<std::string, int>> word_vector(word_counts.begin(), word_counts.end());

    // Sort by frequency in descending order (top 10)
    std::partial_sort(word_vector.begin(), 
                      word_vector.begin() + std::min(10, static_cast<int>(word_vector.size())), 
                      word_vector.end(),
                      compare_by_value_desc<std::string, int>());

    // Output top 10 words with their counts
    int count = 0;
    for (const auto& entry : word_vector) {
        if (count >= 10) break;
        std::cout << entry.second << ": " << entry.first << '\n';
        ++count;
    }

    return 0;
}

#include "threadpool.h"

ThreadPool::ThreadPool(size_t threadCount)
{
    for (size_t idx = 0; idx < threadCount; ++idx) {
        workers.emplace_back([this, idx] {
            while (true) {
                std::function<void()> task;
                {
                    std::unique_lock<std::mutex> guard(queue_mutex);
                    condition.wait(guard, [this] {
                        return m_stop || !tasks.empty();
                    });

                    if (m_stop && tasks.empty())
                        break;

                    task = std::move(tasks.front());
                    tasks.pop();
                }
                task();
            }
        });
    }
}

ThreadPool::~ThreadPool()
{
    {
        std::unique_lock<std::mutex> guard(queue_mutex);
        m_stop = true;
    }
    condition.notify_all();
    for (auto& worker : workers) {
        if (worker.joinable()) {
            worker.join();
        }
    }
}

