namespace {
class ListGraphUndirectedTest : public ::testing::Test {
protected:
    ListGraph<false, int> graph;
};

TEST_F(ListGraphUndirectedTest, test_add_vertex) {
    EXPECT_EQ(0, graph.vertex_num());

    // Add a new vertex with data value 2
    graph.add_vertex(Vertex<int>(2));
    EXPECT_EQ(3, graph.vertex_num());

    // Attempting to add another vertex should return -1 (indicating failure)
    EXPECT_EQ(-1, graph.add_vertex(Vertex<int>(2)));
}

TEST_F(ListGraphUndirectedTest, test_set_vertex) {
    EXPECT_EQ(0, graph.vertex_num());

    // Set vertex with id=1 and data=4; this creates two vertices (id 0 and 1)
    graph.set_vertex(Vertex<int>(1, 4));
    EXPECT_EQ(2, graph.vertex_num());

    // Verify the data of vertex 1 is 4
    EXPECT_EQ(4, graph.vertex(1).data());

    // Update vertex 1's data to 5 without changing the number of vertices
    graph.set_vertex(Vertex<int>(1, 5));
    EXPECT_EQ(2, graph.vertex_num());

    // Confirm updated data
    EXPECT_EQ(5, graph.vertex(1).data());
}

