#include "buffers.h"
#include "strutil.h"
#include "log.h"

void processQueue(ByteQueue* queue, bool (*handler)(uint8_t*)) {
    size_t len = queue_length(queue);
    uint8_t buffer[len];
    queue_snapshot(queue, buffer);

    if (handler == nullptr) {
        debug("Handler function pointer is null (%p) -- cannot process queue at %p\r\n",
                handler, queue);
        return;
    }

    if (handler(buffer)) {
        queue_init(queue);
    } else if (queue_full(queue)) {
        debug("Data incoming exceeds buffer capacity\r\n");
        queue_init(queue);
    } else if (strnchr(reinterpret_cast<char*>(buffer), len - 1, '\0') != nullptr) {
        debug("Buffered data stream appears corrupted (%s) -- resetting buffer\r\n",
                buffer);
        queue_init(queue);
    }
}

