// Define peer endpoints for the Raft cluster
std::vector<raft_node_endpoint_t> peers = {
    {1ul, "localhost", 12345, 13001},
    {2ul, "localhost", 12346, 13002},
    {3ul, "localhost", 12347, 13003}
};

int main(int argc, char* argv[]) {
    try {
        // Launch Raft nodes in separate threads
        std::vector<std::thread> node_threads;

        // Initialize each node with its configuration and start it
        for (const auto& peer : peers) {
            node_threads.emplace_back([&peer]() {
                raft_node node(peer.uuid, std::make_shared<raft::config>(peers));
                node.run();
            });
        }

        // Wait for all nodes to complete (in practice, they run indefinitely)
        for (auto& t : node_threads) {
            if (t.joinable()) {
                t.join();
            }
        }
    }
    catch (const std::exception& ex) {
        std::cerr << "Exception occurred: " << ex.what() << std::endl;
        return 1;
    }

    return 0;
}

