class InstructionParser
{
public:
  class InvalidInstruction : public std::runtime_error
  {
  public:
    InvalidInstruction(const std::string& msg) : std::runtime_error{msg}
    {}
  };

  void processCommand(const std::string& cmd)
  {
    // Define valid instructions using a different approach: direct comparison
    const std::vector<std::string> validCommands = {"ld a,", "out (0),a"};

    bool found = false;
    for (const auto& validCmd : validCommands) {
      if (cmd == validCmd) {
        found = true;
        break;
      }
    }

    if (!found) {
      throw InvalidInstruction{"Invalid command: " + cmd};
    }
  }
};

