template <class CharT, class Alloc>
void run_test(const Alloc& alloc)
{
    using MatchResult = std::match_results<const CharT*, Alloc>;

    // Verify that the move constructor is noexcept
    static_assert(std::is_nothrow_move_constructible<MatchResult>::value, 
                  "Move constructor should be noexcept");

    MatchResult m1(alloc);
    MatchResult m2(std::move(m1));

    // After move, m2 should have empty results
    assert(m2.size() == 0);
    assert(m2.str() == std::basic_string<CharT>());
    assert(m2.get_allocator() == alloc);
}

