#include "InputArgs.hpp"

InputArgs::InputArgs(int argc, char const *const *argv)
    : argstream(argv, argv + argc) {
  parse_arguments();
  validate_and_adjust_parameters();
}

void InputArgs::validate_and_adjust_parameters() {
  if (n_threads <= 0)
    n_threads = std::thread::hardware_concurrency();
}

void InputArgs::parse_arguments() {
  auto it = argstream.begin();
  ++it; // Skip program name

  if (it != argstream.end()) {
    *it >> n_threads;
    ++it;
  }

  if (it != argstream.end()) {
    *it >> stop_criteria;
    ++it;
  }

  if (it != argstream.end()) {
    *it >> precision;
    ++it;
  }

  if (it != argstream.end()) {
    *it >> angle;
    ++it;
  }

  if (it != argstream.end() && std::distance(it, argstream.end()) > 0) {
    *it >> debug_level;
  }
}

