#include <avr/io.h>
#include "lcd.h"

LCD5110 myGLCD;

void LCD_init(void)
{
    // Configure SPI pins: MOSI (PB3) and SCK (PB5) as outputs
    DDRB |= (1 << PB3) | (1 << PB5);

    // Initialize SPI in master mode with CPOL=1, CPHA=1
    // Prescaler set to fosc/4 (SPR0=1, SPR1=0), MSB first
    SPCR = (1 << SPE) | (1 << MSTR) | (1 << CPOL) | (1 << CPHA) | (1 << SPR0);

    // Set control pins: DC (PB0), RST (PB2), and LCD chip select (PC0) as outputs
    DDRB |= (1 << PB0) | (1 << PB2);
    DDRC |= (1 << PC0);

    // Initialize the LCD display with contrast value 0x46
    myGLCD.InitLCD(0x46);
}

