#define KEY_SIZE 60

QPieKey::QPieKey(QWidget *parent) : QWidget(parent)
{
    // Create a bitmap with double the base size
    QBitmap* maskBitmap = new QBitmap(KEY_SIZE * 2, KEY_SIZE * 2);
    QPainter painter(maskBitmap);

    // Set fixed size for the widget
    setFixedSize(KEY_SIZE * 2, KEY_SIZE * 2);

    // Clear the bitmap and draw the outer circle
    maskBitmap->clear();
    painter.setBrush(Qt::color1);
    painter.drawEllipse(1, 1, KEY_SIZE * 2 - 2, KEY_SIZE * 2 - 2);

    // Draw inner circle to create donut shape
    painter.setBrush(Qt::color0);
    painter.drawEllipse(KEY_SIZE / 2, KEY_SIZE / 2, KEY_SIZE, KEY_SIZE);

    // Apply the mask and initially hide the widget
    setMask(*maskBitmap);
    hide();

    // Clean up allocated memory
    delete maskBitmap;
}

QPieKey::~QPieKey()
{
}

void QPieKey::paintEvent(QPaintEvent *event)
{
