void SpriteSheetImporter::import(const ImportingAsset& asset, IAssetCollector& collector)
{
    SpriteSheet spriteSheet;

    // Load the sprite sheet data from the first input file's YAML configuration
    const auto& inputFile = asset.inputFiles.front();
    spriteSheet.load(YAMLConvert::parseConfig(inputFile.data).getRoot());

    // Prepare metadata with compression settings
    Metadata metadata = inputFile.metadata;
