using namespace Marble;

GpsdConnection::GpsdConnection(QObject* parent)
    : QObject(parent),
      m_timer(nullptr)
{
    gps_data_t* initialData = m_gpsd.open();
    if (initialData) {
#if GPSD_API_MAJOR_VERSION == 3
        m_gpsd.stream(WATCH_ENABLE);
#endif
        connect(&m_timer, &QTimer::timeout, this, &GpsdConnection::update);
        m_timer.start(1000);
    } else {
        mDebug() << "Failed to establish connection with gpsd; position data unavailable.";
    }
}

void GpsdConnection::update()
{
    gps_data_t* currentData;
#if GPSD_API_MAJOR_VERSION == 2
    currentData = m_gpsd.query("o");
#elif GPSD_API_MAJOR_VERSION == 3
    // Keep polling until a policy set is received or no more data available
    do {
        currentData = m_gpsd.poll();
    } while (currentData && !(currentData->set & POLICY_SET));
#endif

    if (currentData) {
        emit gpsdInfo(*currentData);
    }
}

