#include <map>
#include <common/buffer.h>
#include <common/endian.h>
#include <ssh/ssh_algorithm_negotiation.h>
#include <ssh/ssh_protocol.h>

namespace {
    static const uint8_t fixed_cookie[16] = {
        0x00, 0x10, 0x20, 0x30,
        0x40, 0x50, 0x60, 0x70,
        0x80, 0x90, 0xa0, 0xb0,
        0xc0, 0xd0, 0xe0, 0xf0
    };

    template<typename MapType>
    Buffer format_name_list(const MapType& name_map) {
        std::vector<Buffer> name_buffers;
        Buffer combined_names;
        uint32_t encoded_length;
        Buffer result;

        for (typename MapType::const_iterator iter = name_map.begin(); 
             iter != name_map.end(); ++iter) {
            name_buffers.push_back(iter->first);
        }

        combined_names = Buffer::join(name_buffers, ",");
        encoded_length = combined_names.length();
        encoded_length = BigEndian::encode(encoded_length);

        result.append(&encoded_length);
        result.append(combined_names);
        return result;
    }
}

bool
SSHAlgorithmNegotiation::input(Buffer *in)
{
    switch (in->peek()) {
    case SSH::Message::KeyExchangeInitializationMessage:
        DEBUG(log_) << "Ignoring key exchange initialization message.";
        return true;
    default:
        DEBUG(log_) << "Unsupported algorithm negotiation message received:" << std::endl 
                    << in->hexdump();
        return false;
    }
}

bool
SSHAlgorithmNegotiation::output(Buffer *out)
{
    ASSERT(out->empty());

    out->append(SSH::Message::KeyExchangeInitializationMessage);
    out->append(fixed_cookie, sizeof(fixed_cookie)); /* XXX Synchronous random byte generation? */

    out->append(format_name_list(key_exchange_map_));
    out->append(format_name_list(server_host_key_map_));
    out->append(format_name_list(encryption_client_to_server_map_));
    out->append(format_name_list(encryption_server_to_client_map_));
    out->append(format_name_list(mac_client_to_server_map_));
    out->append(format_name_list(mac_server_to_client_map_));
    out->append(format_name_list(compression_client_to_server_map_));
    out->append(format_name_list(compression_server_to_client_map_));
    out->append(format_name_list(language_client_to_server_map_));
    out->append(format_name_list(language_server_to_client_map_));

    out->append(SSH::Boolean::False);

    uint32_t padding_value = 0;
    out->append(&padding_value);

    return true;
}

