#include <ctx.hpp>
#include <cl.hpp>
#include <vector>

namespace opencl
{
using std::vector;
using cl::Platform;
using cl::Device;

// Context callback function for OpenCL error reporting
void contextErrorHandler(const char *errinfo, const void *private_info, size_t cb, void *user_data)
{
    printf("OpenCL Context Error: %s\n", errinfo);
    fflush(stdout);
}

// Retrieve the OpenCL context at specified index
const cl::Context&
getContextReference(unsigned char index)
{
    static vector<Platform> platformsList;
    static vector<cl::Context> contextList;

    if (contextList.empty()) {
        Platform::get(&platformsList);

        for (const auto& platform : platformsList) {
            vector<cl_context_properties> props = {
                CL_CONTEXT_PLATFORM,
                (cl_context_properties)platform(),
                0
            };

            contextList.emplace_back(
                CL_DEVICE_TYPE_DEFAULT,
                &props[0],
                contextErrorHandler
            );
        }
    }

    return contextList[index];
}

// Retrieve the OpenCL command queue at specified index
cl::CommandQueue&
getCommandQueueReference(unsigned char index)
{
    static vector<cl::CommandQueue> queueList;

    if (queueList.empty()) {
        queueList.emplace_back(getContextReference(0));
    }

    return queueList[index];
}
}

