int main(int argc, const char **argv) {
    // Parse command-line options using CommonOptionsParser
    cl::OptionCategory ToolCategory("custom tool options");
    CommonOptionsParser OptionsParser(argc, argv, ToolCategory);

    // Prepare source file list and compilation database
    std::vector<std::string> SourcePaths = OptionsParser.getSourcePathList();
    CompilationDatabase &Compilations = OptionsParser.getCompilations();

    // Create and run the ClangTool with a custom frontend action
    ClangTool Tool(Compilations, SourcePaths);

    // Define a simple frontend action that prints the input file name
    class PrintFileNameAction : public ASTFrontendAction {
    public:
        std::unique_ptr<ASTConsumer> CreateASTConsumer(CompilerInstance &CI, StringRef File) override {
            std::cout << File.str() << std::endl;
            return nullptr;
        }
    };

    // Run the tool with the custom action
    return Tool.run(newFrontendActionFactory<PrintFileNameAction>().get());
}

