#include <cstdint>

// Helper function template to test alignment properties of types
template <typename T, std::uintptr_t ExpectedAlignment>
void verify_type_alignment()
{
    // Check all cv-qualifier combinations for the type T
    static_assert(std::alignment_of<T>::value == ExpectedAlignment, "T alignment mismatch");
    static_assert(std::alignment_of<const T>::value == ExpectedAlignment, "const T alignment mismatch");
    static_assert(std::alignment_of<volatile T>::value == ExpectedAlignment, "volatile T alignment mismatch");
    static_assert(std::alignment_of<const volatile T>::value == ExpectedAlignment, "const volatile T alignment mismatch");
}

// Dummy class with destructor declared but not defined (ODR usage only)
class Class
{
public:
    ~Class();
};

int main()
{
    // Test reference alignment (typically same as pointer size or platform default)
    verify_type_alignment<int&, 4>();

    // Test class type alignment (minimal alignment)
    verify_type_alignment<Class, 1>();

    // Test pointer alignments (platform-dependent via sizeof(intptr_t))
    verify_type_alignment<int*, static_cast<unsigned>(sizeof(intptr_t))>();
    verify_type_alignment<const int*, static_cast<unsigned>(sizeof(intptr_t))>();

    // Test array type alignment
    verify_type_alignment<char[3], 1>();

    // Test basic integral types
    verify_type_alignment<int, 4>();
    verify_type_alignment<double, 8>();

    // Platform-specific bool alignment
#if (defined(__ppc__) && !defined(__ppc64__))
    verify_type_alignment<bool, 4>();  // 32-bit PowerPC uses 4-byte bool
#else
    verify_type_alignment<bool, 1>();  // Most platforms use 1-byte bool
#endif

    // Test unsigned integer alignment
    verify_type_alignment<unsigned, 4>();

    return 0;
}

