#include <QtTest/QtTest>
#include <gui/input.h>

class TestInput: public QObject
{
	Q_OBJECT
private slots:
	void specialKeys();
private:
	NeovimQt::InputConv input;
};

void TestInput::specialKeys()
{
	const auto keys = input.specialKeys.keys();
	for (int key : keys) {
		const QString base = input.specialKeys.value(key);

		// Test basic key conversion without modifiers
		QCOMPARE(input.convertKey("", key, Qt::NoModifier),
			QString("<%1>").arg(base));

		// Test Control modifier behavior
#ifdef Q_OS_MAC
		// On macOS, Control maps to Cmd in NeovimQt
		QCOMPARE(input.convertKey("", key, Qt::ControlModifier),
			QString("<D-%1>").arg(base));
#else
		// On other platforms, Control uses 'C-' prefix
		QCOMPARE(input.convertKey("", key, Qt::ControlModifier),
			QString("<C-%1>").arg(base));
#endif

		// Test Alt modifier
		QCOMPARE(input.convertKey("", key, Qt::AltModifier),
			QString("<A-%1>").arg(base));

		// Test Meta modifier
#ifdef Q_OS_MAC
		// On macOS, Meta corresponds to Control
		QCOMPARE(input.convertKey("", key, Qt::MetaModifier),
			QString("<C-%1>").arg(base));
#else
		// On non-macOS, Meta is currently unsupported and treated as unmodified
		QCOMPARE(input.convertKey("", key, Qt::MetaModifier),
			QString("<%1>").arg(base));
#endif
	}
}

