#include "item.h"
#include "macro.h"
#include "commentprocessor.h"
#include <herbs/intformat/intformat.h>
#include <herbs/exceptionmissing/exceptionmissing.h>

Herbs::String Doxymax::Item::expand(const Macro& macro, CommentProcessor& processor)
{
    if (macro.args.length() < 1)
    {
        throw Herbs::ExceptionMissing(___FILE__, __LINE__);
    }

    Herbs::String result(64);

    // Start building the list item with appropriate class and optional style
    result.append(STR("<li class=\"itemdoxmax\""));
    if (processor.macroExpansionDepth() == 1)
    {
        result.append(STR(" style=\"position:relative\""));
    }

    // Append opening tag and header content
    result.append(STR("><div class=\"itemhead\">"))
          .append(macro.args[0])
          .append(STR("</div>"));

    // Conditionally append comment section if third argument exists
    if (macro.args.length() > 2)
    {
        result.append(STR("<div class=\"itemcomment\">"))
              .append(macro.args[2])
              .append(STR("</div>"));
    }

    // Append body content if second argument exists
    if (macro.args.length() > 1)
    {
        result.append(macro.args[1]);
    }

    // Close the list item tag
    result.append(STR("</li>"));

    return std::move(result);
}

