// Convert string to double using C locale for consistent parsing
double atof_dot(const char *str)
{
#ifdef _MSC_VER
    // Use Microsoft-specific locale functions
    _locale_t loc = _create_locale(LC_NUMERIC, "C");
    double value = _atof_l(str, loc);
    _free_locale(loc);
    return value;
#else
    // Use standard C++ stream with C locale for parsing
    double value;
    std::istringstream converter(str);
    converter.imbue(std::locale("C"));
    converter >> value;
    return value;
#endif
}

