// Class to perform Caesar cipher decoding
class CCipher {
public:
  // Decodes the given cipher text by shifting each letter backward by 'shift' positions
  std::string decode(std::string cipherText, int shift) {
    std::string decoded;
    for (char c : cipherText) {
      // Normalize the character position (0-25), subtract shift, handle wrap-around with modulo
      int pos = (c - 'A' - shift % 26 + 26) % 26;
      decoded += static_cast<char>('A' + pos);
    }
    return decoded;
  }
};

int main() {
  CCipher cc;
  // Test case: decode "ABCDEFGHIJKLMNOPQRSTUVWXYZ" with shift 10
  std::string result = cc.decode("ABCDEFGHIJKLMNOPQRSTUVWXYZ", 10);
  assert(result == "QRSTUVWXYZABCDEFGHIJKLMNOP");

  // Optional: print result for verification
  std::cout << result << std::endl;
  return 0;
}

