#include <cassert>
#include <iostream>

struct A {};
A global_a;
const A const_global_a = A();

void run_test_one() {
    try {
        throw &global_a;
        // Should not reach here
        std::abort();
    }
    catch (const A* ptr) {
        // Expected handler: const pointer to const object
        static_cast<void>(ptr); // suppress unused warning
    }
    catch (A* non_const_ptr) {
        // Should not be reached due to const-correctness
        std::abort();
    }
}

void run_test_two() {
    try {
        throw &global_a;
        std::abort();
    }
    catch (A* non_const_ptr) {
        // This catches non-const pointers first
        static_cast<void>(non_const_ptr);
    }
    catch (const A* const_ptr) {
        // This branch should never execute for non-const objects
        std::abort();
    }
}

void run_test_three() {
    try {
        throw &const_global_a;
        std::abort();
    }
    catch (const A* const_ptr) {
        // Matches exactly: const pointer to const object
        static_cast<void>(const_ptr);
    }
    catch (A* non_const_ptr) {
        // Cannot bind non-const pointer to const object
        std::abort();
    }
}

void run_test_four() {
    try {
        throw &const_global_a;
        std::abort();
    }
    catch (A* non_const_ptr) {
        // Invalid conversion — this won't match
        std::abort();
    }
    catch (const A* const_ptr) {
        // Correct handler for const object
        static_cast<void>(const_ptr);
    }
}

int main() {
    run_test_one();
    run_test_two();
    run_test_three();
    run_test_four();
    return 0;
}

