// Process a single Humdrum file by analyzing non-null data tokens
void analyzeHumdrumData(HumdrumFile& dataFile);

int main(int argc, char** argv) {
    Options argOptions;
    argOptions.parseArguments(argc, argv);

    HumdrumFileStream inputStream(argOptions);
    HumdrumFile currentFile;

    while (inputStream.read(currentFile)) {
        analyzeHumdrumData(currentFile);
    }

    return 0;
}

//////////////////////////////
//
// analyzeHumdrumData --
//
void analyzeHumdrumData(HumdrumFile& dataFile) {
    dataFile.processNonNullTokens();

    int lineIndex = 0;
    int totalLines = dataFile.getLineCount();

    while (lineIndex < totalLines) {
        HTp tokenPtr = dataFile.getToken(lineIndex, 0);

        cerr << "LINE " << lineIndex << endl;

        // Output tab-separated: line content, next non-null data token
        cout << "\t" << dataFile[lineIndex] << "\t" 
             << tokenPtr->getNextNNDT() << endl;

        ++lineIndex;
    }
}

