    if (strerror_s(temp_buffer, sizeof(temp_buffer), error_code) != 0) 
        throw std::runtime_error("Failed to retrieve error message");
    return std::string(temp_buffer);
#else
    // Use the GNU-specific version of strerror_r that returns a string directly
    return std::string(strerror_r(error_code, temp_buffer, sizeof(temp_buffer)));
#endif
}

