#include "SimpleString.h"
#include <cstring>
#include <cstdio>
#include <cstdlib>

SimpleString::SimpleString()
    : buffer(new char[1])
{
    buffer[0] = '\0';
}

SimpleString::SimpleString(const char* src)
    : buffer(new char[std::strlen(src) + 1])
{
    // Manually copy characters instead of using strcpy
    const char* p = src;
    char* q = buffer;
    while (*p) {
        *q++ = *p++;
    }
    *q = '\0';
}

SimpleString::SimpleString(const SimpleString& other)
    : buffer(new char[other.size() + 1])
{
    const char* src = other.buffer;
    char* dst = buffer;
    while (*src) {
        *dst++ = *src++;
    }
    *dst = '\0';
}

SimpleString& SimpleString::operator=(const SimpleString& other)
{
    if (this != &other) {
        delete[] buffer;
        buffer = new char[other.size() + 1];
        const char* src = other.buffer;
        char* dst = buffer;
        while (*src) {
            *dst++ = *src++;
        }
        *dst = '\0';
    }
    return *this;
}

char* SimpleString::asCharString() const
{
    return buffer;
}

int SimpleString::size() const
{
    int len = 0;
    while (buffer[len] != '\0') {
        ++len;
    }
    return len;
}

SimpleString::~SimpleString()
{
    delete[] buffer;
}

bool operator==(const SimpleString& lhs, const SimpleString& rhs)
{
    const char* s1 = lhs.asCharString();
    const char* s2 = rhs.asCharString();
    while (*s1 && *s1 == *s2) {
        ++s1;
        ++s2;
    }
    return *s1 == *s2; // both null or mismatch at same position
}

