int getNumberOfThreads()
{
    // Determine the number of threads, ensuring at least 2 are used
    size_t hwThreads = std::thread::hardware_concurrency();
    size_t minThreads = static_cast<size_t>(2);

    // Use max to ensure we never return fewer than 2 threads
    return static_cast<int>(std::max(hwThreads, minThreads));
}
