// Error handling function for OpenCL calls
void handleError(cl_int code, const char* operation)
{
	if (code == CL_SUCCESS)
		return;
	std::cerr << "[ERROR] During " << operation << ", error code: " << code << std::endl;
	exit(1);
}

int main(int argc, char** argv)
{
	cl_int status;
	std::vector<cl::Platform> platforms;

	// Retrieve available OpenCL platforms
	cl::Platform::get(&platforms);
	handleError(platforms.empty() ? -1 : CL_SUCCESS, "cl::Platform::get");

	std::clog << "Found " << platforms.size() << " OpenCL platform(s)" << std::endl;

	// Query platform vendor information
	std::string vendorInfo;
	platforms[0].getInfo(CL_PLATFORM_VENDOR, &vendorInfo);
	std::clog << "Platform vendor: " << vendorInfo << std::endl;

	// Set up context properties linking to the selected platform
	cl_context_properties props[] = {
		CL_CONTEXT_PLATFORM,
		(cl_context_properties)(platforms[0])(),
		0
	};

	// Create OpenCL context with the specified device type
	cl::Context context(SELECT_DEVICE_TYPE, props, nullptr, nullptr, &status);
	handleError(status, "cl::Context constructor");

	return 0;
}

