#include <opencv2/opencv.hpp>
#include <iostream>
#include <string>
#include <cstdlib>

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: program <output_directory>\n";
        return 1;
    }

    cv::VideoCapture capture(CV_CAP_OPENNI);
    if (!capture.isOpened()) {
        std::cerr << "Failed to open OpenNI device.\n";
        return -1;
    }

    std::cout << "Initializing depth and RGB stream...\n";

    int frameCount = 0;
    const std::string dirPath = std::string(argv[1]) + "/";

    while (true) {
        cv::Mat depthFrame, colorFrame;

        // Delay for ~0.5 seconds between frames
        usleep(500000);

        // Capture synchronized frames
        if (!capture.grab()) {
            std::cerr << "Failed to grab frames.\n";
            break;
        }

        // Retrieve depth map
        if (!capture.retrieve(depthFrame, CV_CAP_OPENNI_DEPTH_MAP)) {
            std::cerr << "Failed to retrieve depth map.\n";
            continue;
        }

        // Retrieve RGB image
        if (!capture.retrieve(colorFrame, CV_CAP_OPENNI_BGR_IMAGE)) {
            std::cerr << "Failed to retrieve RGB image.\n";
            continue;
        }

        // Display streams
        cv::imshow("Depth Stream", depthFrame);
        cv::imshow("RGB Stream", colorFrame);

        // Save temporary files first
        std::string tempRgbPath = dirPath + "rgb_temp.png";
        std::string tempDepthPath = dirPath + "depth_temp.png";

        cv::imwrite(tempRgbPath, colorFrame);
        cv::imwrite(tempDepthPath, depthFrame);

        // Atomically replace final files using system rename
        std::string cmd = "mv " + tempRgbPath + " " + dirPath + "rgb.png && mv " + tempDepthPath + " " + dirPath + "depth.png";
        std::system(cmd.c_str());

        std::cout << "Frame captured: " << ++frameCount << "\n";

        // Exit on 'q' key press
        if (cv::waitKey(1) == 'q') {
            break;
        }
    }

    cv::destroyAllWindows();
    return 0;
}

