#include "cmbf.h"
#include <unordered_map>
#include <random>
#include <cstdint>
#include <cstdio>

int main(int argc, char *argv[]) {
    // Initialize two CMBF structures: one approximate (with 1 hash function) and one exact (with 5)
    sketch::cmbf::cmbf_exp_t approx_cmbf(4, 16, 1);
    sketch::cmbf::cmbf_t exact_cmbf(4, 16, 5);

    // Report memory usage
    auto [stack_usage, heap_usage] = approx_cmbf.est_memory_usage();
    std::fprintf(stderr, "Memory - stack: %zu bytes, heap: %zu bytes\n", stack_usage, heap_usage);

    // Determine number of items to process from command line or default to 100,000
    size_t item_count = (argc > 1) ? std::strtoull(argv[1], nullptr, 10) : 100000;

    // Generate random 64-bit integers using Mersenne Twister
    std::vector<uint64_t> input_items;
    std::mt19937_64 rng_engine;
    while (input_items.size() < item_count) {
        input_items.push_back(rng_engine());
    }

    // Verify initial state: all counters should be zero
    for (auto val : approx_cmbf.ref()) {
        if (val != 0) {
            // Safety check — though assert is more typical
            std::abort();
        }
    }

    // Add all items to both structures conservatively
    for (uint64_t item : input_items) {
        approx_cmbf.add_conservative(item);
        exact_cmbf.add_conservative(item);
    }

    // Build histograms of estimated counts
    std::unordered_map<uint64_t, uint64_t> exact_histogram;
    std::unordered_map<uint64_t, uint64_t> approx_histogram;

    for (uint64_t item : input_items) {
        ++exact_histogram[exact_cmbf.est_count(item)];
        ++approx_histogram[approx_cmbf.est_count(item)];
    }

    // Output exact histogram
    for (const auto &[count_val, freq] : exact_histogram) {
        std::fprintf(stderr, "Exact\t%lu\t%lu\n", static_cast<unsigned long>(count_val), 
                     static_cast<unsigned long>(freq));
    }

    // Output approximate histogram
    for (const auto &[count_val, freq] : approx_histogram) {
        std::fprintf(stderr, "Approx\t%lu\t%lu\n", static_cast<unsigned long>(count_val), 
                     static_cast<unsigned long>(freq));
    }

    return 0;
}

