namespace ql {

configured_limits_t
from_optargs(rdb_context_t *ctx, signal_t *interruptor, global_optargs_t *arguments)
{
    if (arguments->has_optarg("array_limit")) {
        // Construct a minimal environment with no user-defined functions to avoid recursion
        // This is necessary because this function is invoked during early initialization,
        // before any environments exist.
        std::map<std::string, wire_func_t> empty_funcs;
        env_t env(ctx, interruptor, empty_funcs, nullptr);

        datum_t limit_datum = arguments->get_optarg(&env, "array_limit");
        int64_t limit_value = limit_datum->as_int();

        rcheck_datum(limit_value > 1, base_exc_t::GENERIC,
                     strprintf("Illegal array size limit `%" PRIi64 "`.", limit_value));

        return configured_limits_t(limit_value);
    } else {
        return configured_limits_t{};
    }
}

RDB_IMPL_ME_SERIALIZABLE_1(configured_limits_t, array_size_limit_);
INSTANTIATE_SERIALIZABLE_SELF_FOR_CLUSTER(configured_limits_t);

const configured_limits_t configured_limits_t::unlimited(
    std::numeric_limits<size_t>::max()
);

