#include "../include/turing_machine.hpp"
using namespace turingmachine;

// A problem class that leaves the tape unchanged
class identity_transform final : public tm_abstract_problem {
public:
    const char* name() const override {
        return "Identity";
    }

    void configure() override {
        // No transitions defined, so machine halts immediately without modifying tape
    }

    void add_units() override {
        ADD_UNIT_TEST(">#01#", ">#01#");
        ADD_UNIT_TEST(">", ">");
        ADD_UNIT_TEST(">9$1#", ">9$1#");
    }
};

// A simple problem class with one transition rule
class single_step_processor final : public tm_abstract_problem {
public:
    const char* name() const override {
        return "SingleStep";
    }

    void configure() override {
        // Replace '#' with '0' and move right, then halt (state 1 is final)
        ADD_TRANSITION(0, '#', 1, '0', GO_RIGHT);
    }

    void add_units() override {
        ADD_UNIT_TEST(">#01#", ">001#");
    }
};

int main() {
    identity_transform{}.run();
    single_step_processor{}.run();
}

