void AbsPositionOverview::handleGpsRawInt(LinkInterface *conn, const mavlink_message_t &pkt, const mavlink_gps_raw_int_t &data)
{
    if (data.fix_type >= MAVLINK_GPS_FIX_TYPE_3D_FIX)
    {
        this->setLatitude(data.lat);
        this->setLongitude(data.lon);
        this->setAltitude(data.alt);
        this->setSpeed(data.vel);
    }
}

void AbsPositionOverview::handleGlobalPositionInt(LinkInterface *conn, const mavlink_message_t &pkt, const mavlink_global_position_int_t &data)
{
    // Convert millimeters to meters
    double altMeters = static_cast<double>(data.relative_alt) / 1000.0;
    this->setRelativeAltitude(altMeters);
}

void AbsPositionOverview::onMessageReceived(LinkInterface* conn, mavlink_message_t pkt)
{
    switch (pkt.msgid)
    {
        case MAVLINK_MSG_ID_GPS_RAW_INT:
        {
            mavlink_gps_raw_int_t gpsData;
            mavlink_msg_gps_raw_int_decode(&pkt, &gpsData);
            handleGpsRawInt(conn, pkt, gpsData);
            break;
        }
        case MAVLINK_MSG_ID_GLOBAL_POSITION_INT:
        {
            mavlink_global_position_int_t posData;
            mavlink_msg_global_position_int_decode(&pkt, &posData);
            handleGlobalPositionInt(conn, pkt, posData);
            break;
        }
        default:
            // Ignore other message types
            break;
    }
}

