#include "binarytree.h"
#include <iostream>
#include <stack>
using namespace std;

// Helper function to generate DOT notation for a binary tree using iterative DFS
template <class T>
void generateDotGraph(ostream& out, typename BinaryTree<T>::Inspector inspector, size_t rootId)
{
    // Stack stores pairs: (current inspector, current node id)
    stack<pair<typename BinaryTree<T>::Inspector, size_t>> traversalStack;
    traversalStack.push({inspector, rootId});

    while (!traversalStack.empty())
    {
        auto [currentInspector, nodeId] = traversalStack.top();
        traversalStack.pop();

        if (currentInspector.isEmpty())
        {
            out << nodeId << "[label=\"NULL\" shape=point];" << endl;
            continue;
        }

        // Output node definition
        out << nodeId << "[label=\"" << currentInspector.getData() << "\"];" << endl;

        // Process left child
        if (!currentInspector.left().isEmpty())
        {
            size_t leftId = 2 * nodeId + 1;
            out << nodeId << " -> " << leftId << ";" << endl;
            traversalStack.push({currentInspector.left(), leftId});
        }
        else
        {
            size_t leftId = 2 * nodeId + 1;
            out << nodeId << " -> " << leftId << ";" << endl;
            out << leftId << "[label=\"NULL\" shape=point];" << endl;
        }

        // Process right child
        if (!currentInspector.right().isEmpty())
        {
            size_t rightId = 2 * nodeId + 2;
            out << nodeId << " -> " << rightId << ";" << endl;
            traversalStack.push({currentInspector.right(), rightId});
        }
        else
        {
            size_t rightId = 2 * nodeId + 2;
            out << nodeId << " -> " << rightId << ";" << endl;
            out << rightId << "[label=\"NULL\" shape=point];" << endl;
        }
    }
}

// Main DOT generation function for a BinaryTree
template <class T>
void produceDotOutput(ostream& out, const BinaryTree<T>& tree)
{
    out << "digraph G\n{\n";
    generateDotGraph(out, tree.getInspector(), 0);
    out << "}\n";
}

int main()
{
    BinaryTree<int> sampleTree;
    auto transformer = sampleTree.getTransformer();

    // Build the tree structure:
    //       5
    //      / \
    //     2   3
    transformer.addData(5);
    transformer.goLeft();
    transformer.addData(2);
    transformer.goToParent();
    transformer.goRight();
    transformer.addData(3);

    // Generate and output DOT representation
    produceDotOutput(cout, sampleTree);
    return 0;
}

