// Configuration flags for the Dart VM initialization
static const char* const dartVMArgs[] = {
    "--enable_mirrors=false",
    "--load_deferred_eagerly=true",
};

void InitializeDartRuntime() {
  // Set VM-specific command-line arguments and verify success
  CHECK(Dart_SetVMFlags(arraysize(dartVMArgs), dartVMArgs));

  // Initialize the Dart runtime using the VM isolate snapshot
  // All optional parameters are set to nullptr as per original logic
  CHECK(
      Dart_Initialize(reinterpret_cast<uint8_t*>(&kDartVmIsolateSnapshotBuffer),
                      nullptr, nullptr, nullptr, nullptr, nullptr, nullptr,
                      nullptr, nullptr, nullptr, nullptr, nullptr) == nullptr);
}

Dart_Isolate InstantiateDartIsolate() {
  // Ensure the isolate snapshot buffer is available before proceeding
  CHECK(kDartIsolateSnapshotBuffer);

  char* errorMessage = nullptr;

  // Create a new Dart isolate using the provided snapshot
  Dart_Isolate createdIsolate = Dart_CreateIsolate(
      "dart:snapshot", "main",
      reinterpret_cast<uint8_t*>(&kDartIsolateSnapshotBuffer), 
      nullptr, nullptr, &errorMessage);

  // Verify that isolate creation succeeded
  CHECK(createdIsolate) << errorMessage;

  // Register the library tag handler and check for errors
  CHECK(!LogIfError(Dart_SetLibraryTagHandler(HandleLibraryTag)));

  // Exit the current isolate context before returning
  Dart_ExitIsolate();

  return createdIsolate;
}

