#include <pthread.h>
#include <unistd.h>

pthread_rwlock_t rwlock;
int GLOB;

void *Thread1(void *p) {
  (void)p;
  pthread_rwlock_wrlock(&rwlock);  // Changed from rdlock to wrlock
  usleep(100);
  GLOB++;
  pthread_rwlock_unlock(&rwlock);
  return 0;
}

int main(int argc, char *argv[]) {
  pthread_rwlock_init(&rwlock, NULL);

  // Acquire write lock in main thread for reading
  pthread_rwlock_wrlock(&rwlock);
  volatile int x = GLOB;
  (void)x;
  pthread_rwlock_unlock(&rwlock);

  pthread_t t;
  pthread_create(&t, 0, Thread1, 0);
  pthread_join(t, 0);

  pthread_rwlock_destroy(&rwlock);
  return 0;
}

