// Wrapper for the standard rand() function
NAN_METHOD(generateRandomValue) {
  NanScope();
  // Return a random integer from stdlib's rand()
  NanReturnValue(NanNew<Integer>(std::rand()));
}

// Wrapper for srand() with seed validation
NAN_METHOD(setRandomSeed) {
  NanScope();

  // Check if argument is provided
  if (args.Length() < 1) {
    NanThrowError("Usage: setRandomSeed(seedValue)");
    NanReturnUndefined();
  }

  // Extract and apply the seed value
  uint32_t seed = args[0]->Uint32Value();
  std::srand(seed);
  NanReturnValue(NanUndefined());
}

// Generate a floating-point random number in [0, 1)
NAN_METHOD(uniformRandom) {
  NanScope();
  double randomValue = static_cast<double>(std::rand()) / (RAND_MAX + 1.0);
  NanReturnValue(NanNew<Number>(randomValue));
}

// Initialize module exports
void initializeModule(Handle<Object> exports) {
  // Export functions with different names than original
  NODE_SET_METHOD(exports, "generate", generateRandomValue);
  NODE_SET_METHOD(exports, "setSeed", setRandomSeed);
  NODE_SET_METHOD(exports, "uniform", uniformRandom);

  // Export RAND_MAX constant
  NODE_SET_METHOD(exports, "getMaxRand", [](const Arguments& args) {
    NanScope();
    NanReturnValue(NanNew<Integer>(RAND_MAX));
  });
}

// Register the Node.js module
NODE_MODULE(random_utils, initializeModule)

