template <typename T>
T parseFromString(const std::string& input) {
    std::istringstream stream(input);
    T value;
    stream >> value;
    return value;
}

void display(double val) {
    // Reinterpret the double as an unsigned long long for bit-level representation
    unsigned long long* ptr = reinterpret_cast<unsigned long long*>(&val);
    printf("%.20f, %llX\n", val, *ptr);
}

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "Usage: program <number>" << std::endl;
        return 1;
    }

    double inputVal = parseFromString<double>(std::string(argv[1]));

    // Handle special cases for division by zero
    double inf = 1.0 / 0.0;  // Positive infinity
    double negInf = -1.0 / 0.0;  // Negative infinity
    double nan = 0.0 / 0.0;  // Not a Number

    print(sqrt(-1));           // NaN
    print(1.0 / inputVal);     // ±infinity depending on sign of input
    print(-1.0 / inputVal);    // ∓infinity
    print(0.0 / inputVal);     // +0.0
    print(-0.0 / inputVal);    // -0.0
    print((1.0 / inputVal) / (-1.0 / inputVal));  // -1.0
    print((1.0 / inputVal) + 3.0);                // ±infinity
    print((-1.0 / inputVal) + 3.0);               // ∓infinity
    print(3.0 / (1.0 / inputVal));                // original input value (inputVal), unless input is zero or infinity

    return 0;
}

