#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>

class Barrier {
private:
    std::mutex mtx;
    std::condition_variable cv;
    int count;
    int waiting;
    int generation;

public:
    explicit Barrier(int n) : count(n), waiting(n), generation(0) {}

    void wait() {
        std::unique_lock<std::mutex> lock(mtx);
        int gen = generation;
        if (--waiting == 0) {
            generation++;
            waiting = count;
            cv.notify_all();
        } else {
            cv.wait(lock, [this, gen] { return gen != generation; });
        }
    }
};

int main() {
    const int num_agents = 10;
    Barrier barrier(num_agents);

    std::vector<std::thread> threads;

    for (int i = 0; i < num_agents; ++i) {
        threads.emplace_back([&barrier, i]() {
            std::cout << "agent " << i << " arriving at barrier" << std::endl;
            barrier.wait();
            std::cout << "departing barrier" << std::endl;
        });
    }

    for (auto& t : threads) {
        t.join();
    }

    return 0;
}

