RecordTask::RecordTask(const Task& parent, skiagm::GM* gm, SkBitmap reference)
    : CpuTask(parent)
    , fName(UnderJoin(parent.name().c_str(), "skr"))
    , fGM(gm)
    , fReference(reference)
    {}

void RecordTask::draw() {
    // Capture the drawing commands using SkRecording
    EXPERIMENTAL::SkRecording recording(fReference.width(), fReference.height());

    // Apply transformation and render the GM content
    recording.canvas()->concat(fGM->getInitialTransform());
    fGM->draw(recording.canvas());

    // Obtain playback object from recording
    SkAutoTDelete<const EXPERIMENTAL::SkPlayback> playback(recording.releasePlayback());

    // Prepare target bitmap for playback
    SkBitmap outputBitmap;
    SetupBitmap(fReference.colorType(), fGM.get(), &outputBitmap);

    // Render the recorded commands to the bitmap
    SkCanvas renderTarget(outputBitmap);
    playback->draw(&renderTarget);

    // Verify the rendered output matches expected reference
    if (!BitmapsEqual(outputBitmap, fReference)) {
        this->fail();
        this->spawnChild(SkNEW_ARGS(WriteTask, (*this, outputBitmap)));
    }
}

bool RecordTask::shouldSkip() const {
    return !FLAGS_skr;
}

