#include <iostream>
#include <stack>
using std::cout;
using std::endl;
using std::stack;

class Queue {
    stack<int> inputStack, outputStack;

    void shiftElements() {
        while (!inputStack.empty()) {
            outputStack.push(inputStack.top());
            inputStack.pop();
        }
    }

public:
    bool isEmpty() const {
        return inputStack.empty() && outputStack.empty();
    }

    int peek() const {
        if (outputStack.empty()) {
            shiftElements();
        }
        return outputStack.top();
    }

    void enqueue(int value) {
        inputStack.push(value);
    }

    void dequeue() {
        if (outputStack.empty()) {
            shiftElements();
        }
        if (!outputStack.empty()) {
            outputStack.pop();
        }
    }
};

int main() {
    Queue q;
    q.enqueue(1);
    q.enqueue(2);
    cout << q.peek() << endl;
    q.dequeue();
    q.enqueue(3);
    cout << q.peek() << endl;
    q.dequeue();
    q.enqueue(4);
    q.enqueue(5);
    q.enqueue(6);
    cout << q.peek() << endl;
    q.dequeue();
    cout << q.peek() << endl;
    q.dequeue();
    cout << q.peek() << endl;
    q.dequeue();
    cout << q.peek() << endl;
    q.dequeue();

    return 0;
}

