// Redefine X with slightly different implementation
struct X
{
    explicit X(int val)
        : stored_value(val)
    {}

    int get() const { return stored_value; }

private:
    int stored_value;
};

// Alternative function implementations with different logic
int extract_value(const boost::shared_ptr<X>& ptr)
{
    return ptr ? ptr->get() : 0;
}

boost::shared_ptr<X> pass_through(const boost::shared_ptr<X>& input)
{
    return input;
}

void test_main(lua_State* L)
{
    using namespace luabind;

    // Bind with different syntax order and naming
    module(L) [
        class_<X>("X")
            .def(constructor<int>())
            .def("get", &X::get),
        def("extract_value", &extract_value),
        def("pass_through", &pass_through)
    ];

    // First test uses the new method name
    DOSTRING(L,
        "x = X(1)\n"
        "assert(extract_value(x) == 1)\n"
    );

    // Second test uses the renamed function
    DOSTRING(L,
        "assert(x == pass_through(x))\n"
    );
}

