char *dynamic_buffer;

// Allocate memory and copy a PROGMEM string to RAM, freeing previous allocation
char *copyPgmStringToRam(PROGMEM char *sourceStr) {
    // Free previously allocated buffer if any
    free(dynamic_buffer);

    // Compute required size and allocate new memory
    size_t len = strlen_P(sourceStr);
    dynamic_buffer = (char *) malloc(len + 1);

    // Copy the string from program memory to RAM
    strcpy_P(dynamic_buffer, sourceStr);

    return dynamic_buffer;
}

