// Function that uses placement new to initialize a char array
static void f0_a(char* buffer) {
    // Construct an array of 4 chars with value-initialized elements (zero-initialized)
    new (buffer) char[4]();
}

// Main function that creates a local array, initializes it, and sums its elements
char f0() {
    char local_buffer[4];
    f0_a(local_buffer);
    // Sum all elements of the initialized array
    return local_buffer[0] + local_buffer[1] + local_buffer[2] + local_buffer[3];
