void CancellationFlag::Set() {
#if !defined(NDEBUG)
  // Verify that the current thread is the one setting the flag
  DCHECK_EQ(set_on_, PlatformThread::CurrentId());
#endif
  // Atomically set the flag to 1 using release semantics
  base::subtle::Release_Store(&flag_, 1);
