// Constructor: Initialize the external commit helper with the parent coordinator
ExternalCommitHelper::ExternalCommitHelper(RealmCoordinator& coordinator)
{
    // Store reference to the parent coordinator
    m_parent = &coordinator;

    // Create client-side history for change tracking
    m_client_history = realm::make_client_history(
        coordinator.get_path(), 
        coordinator.get_encryption_key().data()
    );

    // Initialize shared group with appropriate durability settings
    SharedGroup::durability_mode durability = 
        coordinator.is_in_memory() ? 
            SharedGroup::durability_MemOnly : 
            SharedGroup::durability_Full;

    m_shared_group = std::make_unique<SharedGroup>(
        *m_client_history, 
        durability,
        coordinator.get_encryption_key().data()
    );

    // Start background monitoring thread for changes
    m_monitor_thread = std::async(std::launch::async, [this] {
        m_shared_group->begin_read();
        while (m_shared_group->wait_for_change()) {
            m_shared_group->end_read();
            m_shared_group->begin_read();
            m_parent->on_change();
        }
    });
}

// Destructor: Clean up resources when helper is destroyed
ExternalCommitHelper::~ExternalCommitHelper()
{
    // Release wait-for-change resources
    if (m_shared_group) {
        m_shared_group->wait_for_change_release();
    }

    // Ensure background thread completes before destruction
    if (m_monitor_thread.valid()) {
        m_monitor_thread.wait();
    }
}

