// Default constructor
PatternPostureGenerator::PatternPostureGenerator() {}

// Constructor that loads posture data from ROS parameter server
PatternPostureGenerator::PatternPostureGenerator(ros::NodeHandle& nh) {
  std::map<std::string, std::string> pattern_map;
  if (!nh.getParam("pattern", pattern_map)) {
    ROS_WARN("Parameter 'pattern' not found; no postures loaded.");
    return;
  }

  ROS_INFO("Loaded pattern mapping from parameter server.");

  for (auto& entry : pattern_map) {
    const std::string& key = entry.first;
    const std::string& pattern_name = entry.second;

    std::vector<double> joint_values;
    if (!nh.getParam("pattern/" + pattern_name, joint_values)) {
      ROS_WARN_STREAM("Failed to load posture data for pattern '" << pattern_name << "'. Skipping.");
      continue;
    }

    // Store the loaded posture under the pattern name
    posture_datas[pattern_name] = joint_values;
    ROS_INFO_STREAM("Loaded posture for pattern: " << pattern_name);
  }

  // Advertise the service to request posture by key/name
  key_service = nh.advertiseService("getPostureKey", &PatternPostureGenerator::handleGetPostureKey, this);
  ROS_INFO("Service 'getPostureKey' advertised successfully.");
}

// Service callback — retrieves stored posture by name
bool PatternPostureGenerator::handleGetPostureKey(
    pattern_posture_generator::PatternKeyPosture::Request& req,
    pattern_posture_generator::PatternKeyPosture::Response& res) {

  auto it = posture_datas.find(req.name);
  if (it == posture_datas.end()) {
    ROS_WARN("Requested posture '%s' not found.", req.name.c_str());
    return false;
  }

  res.posture = it->second;  // Direct copy instead of back_inserter for clarity
  return true;
}

