BadgeRegion::BadgeRegion(std::string badge_label, BadgeService* manager)
    : badge_service_(manager)
    , badge_name_(std::move(badge_label))
{
    SetCollidable(true);
    SetDatabasePersisted(false);
    SetInSnapshot(true);
}

BadgeRegion::~BadgeRegion() = default;

void BadgeRegion::OnCollisionEnter(std::shared_ptr<Object> other_obj)
{
    // First, check if the colliding object has an active controller
    if (other_obj->HasController())
    {
        badge_service_->GiveBadge(other_obj, badge_name_);
        return;
    }

    // If not directly controllable, scan its contained objects
    other_obj->ViewObjects(nullptr, 0, true,
        [this](const std::shared_ptr<Object>& candidate)
        {
            if (candidate->HasController())
            {
                badge_service_->GiveBadge(candidate, badge_name_);
            }
        });
}

