    LedRed::setOutput(xpcc::Gpio::High);
    LedBlue::setOutput(xpcc::Gpio::High);

    // Connect USART2 pins
    GpioOutputA2::connect(Usart2::Tx);
    GpioInputA3::connect(Usart2::Rx, Gpio::InputType::PullUp);

    // Initialize USART2 with given clock and baud rate
    Usart2::initialize<defaultSystemClock, 9600>(12);

    // Main loop: send characters cyclically
    while (true)
    {
        static char ch = 'A';

        // Visual feedback via LEDs
        LedRed::toggle();
        LedGreen::toggle();

        // Transmit current character
        Usart2::write(static_cast<uint8_t>(ch));

        // Advance to next character, wrap around after 'Z'
        ++ch;
        if (ch > 'Z') {
            ch = 'A';
        }

        // Delay before next transmission
        xpcc::delay_ms(500);
    }

    return 0;
}

