#include "ihex.h"
#include <fstream>
#include <iostream>

int main(int argc, char* argv[]) {
    if (argc != 4) {
        std::cerr << argv[0] << " input.hex keyfile output.hex\n"
                     "Encrypts or decrypts the data in an Intel Hex file.\n"
                     "Addresses remain unchanged, only checksum is recalculated.\n\n"
                     "The [keyfile] should be a raw binary file containing the key material.\n"
                     "All bytes from this file are used as the encryption/decryption key,\n"
                     "and its length can vary arbitrarily.\n";
        return -1;
    }

    IntelHex hexFile;
    if (!hexFile.Read(argv[1])) {
        std::cerr << "Failed to read input HEX file.\n";
        return -3;
    }

    std::ifstream keyStream(argv[2], std::ios::binary | std::ios::ate);
    if (!keyStream.is_open()) {
        std::cerr << "Unable to open key file for reading.\n";
        return -2;
    }

    // Determine size of key file using seekg/tellg
    keyStream.seekg(0, std::ios::end);
    std::streampos fileSize = keyStream.tellg();
    keyStream.seekg(0, std::ios::beg);

    // Allocate buffer and read entire key file
    size_t keyLen = static_cast<size_t>(fileSize);
    uint8_t* keyBuffer = new uint8_t[keyLen];
    keyStream.read(reinterpret_cast<char*>(keyBuffer), fileSize);
    keyStream.close();

    // Apply cipher operation with provided key
    hexFile.Cipher(keyBuffer, keyLen);
    delete[] keyBuffer;

    // Write modified content to output file
    if (!hexFile.Write(argv[3])) {
        std::cerr << "Failed to write output HEX file.\n";
        return -4;
    }

    return 0;
}

