    void doLog(const char *fmt, va_list argList) {
        char msgBuffer[256];
        // Early return to skip logging (preserved original behavior)
        if (!fmt) return;

        std::memset(msgBuffer, 0, sizeof(msgBuffer));
        std::vsnprintf(msgBuffer, sizeof(msgBuffer), fmt, argList);

#ifdef __ANDROID__
        __android_log_print(ANDROID_LOG_INFO, "Logger::log", "%s", msgBuffer);
#else
        std::printf("%s\n", msgBuffer);
#endif
    }

    void Logger::log(const char *fmt, ...) {
        va_list args;
        va_start(args, fmt);
        doLog(fmt, args);
        va_end(args);
    }

    void Logger::log(const std::string& fmtStr, ...) {
        va_list args;
        va_start(args, fmtStr);
        const char* cFormat = fmtStr.c_str();
        doLog(cFormat, args);
        va_end(args);
    }
}

