template <typename T>
string debug_rep(const T &value) {
    ostringstream stream;
    stream << value;
    return stream.str();
}

// Overload for pointer types - displays pointer address and content if valid
template <typename T>
string debug_rep(T *ptr) {
    ostringstream stream;
    stream << "pointer: " << ptr;
    if (ptr != nullptr) {
        stream << " content: " << debug_rep(*ptr);
    } else {
        stream << " null pointer";
    }
    return stream.str();
}

// Specialization for string type - adds quotes and suffix
