// Determine if the current execution context is the browser process.
// This implementation checks for active V8 locking, though this method
// may not be fully reliable in all scenarios.
inline bool IsBrowserProcess() {
  return v8::Locker::IsActive();
}

}  // namespace

v8::Local<v8::Value> CallEmitWithArgs(v8::Isolate* isolate,
                                      v8::Local<v8::Object> obj,
                                      ValueVector* args) {
  // Ensure microtask checkpoint occurs after JavaScript execution completes.
  scoped_ptr<blink::WebScopedRunV8Script> script_scope;
  if (!IsBrowserProcess()) {
    script_scope.reset(new blink::WebScopedRunV8Script(isolate));
  }

  // Delegate to Node.js's MakeCallback to invoke the 'emit' method,
  // which also processes any pending Node.js tasks.
  return node::MakeCallback(
      isolate, obj, "emit", args->size(), &args->front());
}
