// Main event loop implementation using non-blocking message polling
void ImwWindowManagerDX11::InternalRun()
{
    MSG oMessage;
    if (PeekMessage(&oMessage, nullptr, 0, 0, PM_REMOVE))
    {
        TranslateMessage(&oMessage);
        DispatchMessage(&oMessage);
    }
