// Custom matrix class to replace CMatrix::Matrix
template<typename T>
class Matrix {
private:
    T** data;
    int rows, cols;

public:
    Matrix(int r, int c) : rows(r), cols(c) {
        data = new T*[rows];
        for (int i = 0; i < rows; ++i) {
            data[i] = new T[cols];
        }
    }

    ~Matrix() {
        for (int i = 0; i < rows; ++i) {
            delete[] data[i];
        }
        delete[] data;
    }

    T& operator()(int r, int c) {
        return data[r][c];
    }

    const T& operator()(int r, int c) const {
        return data[r][c];
    }

    int getRows() const { return rows; }
    int getCols() const { return cols; }
};

// Functionoid class with modified logic
class testFunctionoid {
public:
    double operator()(double x, double y) const {
        // Equivalent mathematical expression: (sin(x * y) + 1.0) / 2.0
        return 0.5 * (std::sin(x * y) + 1.0);
    }
};

int main() {
    int dimension = 5;
    Matrix<double> matrix(dimension, dimension);

    // Create functionoid instance
    testFunctionoid func;

    // Calculate center offset and step size
    double centerX = dimension / 2.0;
    double centerY = dimension / 2.0;
    double stepX = 1.0 / dimension;
    double stepY = 1.0 / dimension;

    // Fill matrix using nested loops instead of fillByPosition
    for (int i = 0; i < dimension; ++i) {
        for (int j = 0; j < dimension; ++j) {
            double x = i * stepX + centerX;
            double y = j * stepY + centerY;
            matrix(i, j) = func(x, y);
        }
    }

    // Output the matrix elements
    for (int i = 0; i < dimension; ++i) {
        for (int j = 0; j < dimension; ++j) {
            std::cout << matrix(i, j);
            if (j < dimension - 1) std::cout << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}

