#include <bits/stdc++.h>
using namespace std;

void toBin(int x) {
    int position = 0;
    vector<int> bits;

    // Extract bits from LSB to MSB
    while (position < 32) {
        bits.push_back((x >> position) & 1);
        position++;
    }

    // Print in reverse order (MSB to LSB)
    for (int i = 31; i >= 0; --i) {
        cout << bits[i];
    }
}

