#include <tiramisu/tiramisu.h>
using namespace tiramisu;

// Generate a computation that adds two constants and stores it in a buffer
void create_computation(std::string func_name, int dim_size, int input_a, int input_b) {
    tiramisu::init(func_name);
    tiramisu::function* current_func = global::get_implicit_function();

    // Define constant dimension size
    tiramisu::constant N("N", tiramisu::expr((int32_t)dim_size), p_int32, true, nullptr, 0, current_func);

    // Declare loop variables with bounds [0,10)
    tiramisu::var x("x", 0, 10), y("y", 0, 10);
    // Tiling variables (unused but declared for consistency)
    tiramisu::var x0("x0"), y0("y0"), x1("x1"), y1("y1");

    // Create computation that computes the sum of the two input values
    tiramisu::computation comp(tiramisu::expr((uint8_t)(input_a + input_b)), x, y);

    // Mark outer loop dimension as parallelizable
    comp.tag_parallel_level(x);

    // Define output buffer
    tiramisu::buffer output_buf("output_buf", {dim_size, dim_size}, tiramisu::p_uint8, a_output, current_func);

    // Store result in buffer
    comp.store_in(&output_buf, {x, y});

    // Generate code
    current_func->codegen({&output_buf}, "build/generated_fct_test_114.o");
}

int main(int argc, char **argv) {
    // Call generator with parameters: function name, size=10, val0=3, val1=4
    create_computation("func", 10, 3, 4);
    return 0;
}

