using namespace llvm;

namespace {

// Test that timer accumulates time correctly across multiple start/stop cycles
TEST(Timer, Additivity) {
  Timer T1("T1");
  ASSERT_TRUE(T1.isInitialized());

  // First measurement cycle
  T1.startTimer();
  T1.stopTimer();
  auto elapsed1 = T1.getTotalTime();

  // Second measurement cycle with a delay
  T1.startTimer();
  std::this_thread::sleep_for(std::chrono::milliseconds(1));
  T1.stopTimer();
  auto elapsed2 = T1.getTotalTime();

  // Total time should increase after second cycle
  EXPECT_LT(elapsed1.count(), elapsed2.count());
}

// Verify the triggered state transitions of the timer
TEST(Timer, CheckIfTriggered) {
  Timer T1("T1");

  // Initially not triggered
  EXPECT_FALSE(T1.hasTriggered());

  // After starting, timer is considered triggered
  T1.startTimer();
  EXPECT_TRUE(T1.hasTriggered());

  // Still triggered after stopping
  T1.stopTimer();
  EXPECT_TRUE(T1.hasTriggered());

  // Clearing resets the triggered state
  T1.clear();
  EXPECT_FALSE(T1.hasTriggered());
}

