namespace cucumber {
namespace internal {

SocketServer::SocketServer(const ProtocolHandler* handler) 
    : protocolHandler(handler),
      ioContext(),
      socketAcceptor(ioContext) {
}

void SocketServer::startListening(port_type portNumber) {
    tcp::endpoint serverAddress(tcp::v4(), portNumber);
    socketAcceptor.open(serverAddress.protocol());
    socketAcceptor.set_option(tcp::acceptor::reuse_address(true));
    socketAcceptor.set_option(tcp::no_delay(true));
    socketAcceptor.bind(serverAddress);
    socketAcceptor.listen(1);
}

void SocketServer::handleSingleConnection() {
    tcp::iostream connectionStream;
    socketAcceptor.accept(*connectionStream.rdbuf());
    handleConnection(connectionStream);
}

void SocketServer::handleConnection(tcp::iostream& connection) {
    std::string incomingMessage;
    while (std::getline(connection, incomingMessage)) {
        connection << protocolHandler->process(incomingMessage) 
                   << std::endl 
                   << std::flush;
    }
}

}
