// Test adding child nodes to a TreeNode
TEST(TreeNodeTest, AddChild) {
    TreeNode<int> parent;
    TreeNode<int> firstChild;
    TreeNode<int> secondChild;

    parent.addChild(&firstChild);
    parent.addChild(&secondChild);

    ASSERT_EQ(parent.getChildren().size(), 2u);
}

// Test removing child nodes by index
TEST(TreeNodeTest, RemoveChild) {
    TreeNode<int> node;
    TreeNode<int> childA;
    TreeNode<int> childB;
    TreeNode<int> childC;

    node.addChild(&childA);
    node.addChild(&childB);
    node.addChild(&childC);

    // Remove middle child (index 1)
    node.removeChild(1);
    EXPECT_EQ(node.getChildren().size(), 2u);

    // Remove first child (now at index 0)
    node.removeChild(0);
    EXPECT_EQ(node.getChildren().size(), 1u);

    // Remove last remaining child
    node.removeChild(0);
    EXPECT_EQ(node.getChildren().size(), 0u);

    // Removing from empty list should not throw
    EXPECT_NO_THROW(node.removeChild(0));
}

// Test setting and retrieving parent pointer
TEST(TreeNodeTest, AddParent) {
    TreeNode<int> root;
    TreeNode<int> childNode;

    // Initially no parent
    EXPECT_EQ(childNode.getParent(), nullptr);

    // Set parent
    childNode.setParent(&root);
    EXPECT_EQ(childNode.getParent(), &root);
}

// Test removing parent relationship
TEST(TreeNodeTest, RemoveParent) {
    TreeNode<int> parent;
    TreeNode<int> child;

    // Establish parent-child relationship
    child.setParent(&parent);
    EXPECT_EQ(child.getParent(), &parent);

    // Remove parent
    child.removeParent();
    EXPECT_EQ(child.getParent(), nullptr);
}

