extern const char *TestMainArgv0;

// Helper function to locate the input directory for unit tests
SmallString<128> llvm::unittest::getInputFileDirectory() {
  // Start with the parent directory of the test executable
  SmallString<128> dirPath = sys::path::parent_path(TestMainArgv0);

  // Convert to absolute path
  sys::fs::make_absolute(dirPath);

  // Append the file name containing source directory info
  sys::path::append(dirPath, "llvm.srcdir.txt");

  // Verify that the file exists and is a regular file
  EXPECT_TRUE(sys::fs::is_regular_file(dirPath))
      << "Unit test source directory file does not exist.";

  // Attempt to open and read the file
  auto bufferOrError = MemoryBuffer::getFile(dirPath);
  EXPECT_TRUE(static_cast<bool>(bufferOrError))
      << "Could not open unit test source directory file.";

  // Clear the path variable to reuse it
  dirPath.clear();

  // Read the content (trim whitespace) and append 'Inputs' subdirectory
  dirPath.append(bufferOrError->get()->getBuffer().trim());
  sys::path::append(dirPath, "Inputs");

  // Normalize the path format
  sys::path::native(dirPath);

  return std::move(dirPath);
}

