using namespace llvm;

namespace {

// Test that timer accumulates time correctly across multiple start/stop cycles
TEST(Timer, Additivity) {
  Timer T("TimerInstance");
  ASSERT_TRUE(T.isInitialized());

  // First measurement cycle
  T.startTimer();
  T.stopTimer();
  auto Time1 = T.getTotalTime();

  // Second measurement cycle after a delay
  T.startTimer();
  std::this_thread::sleep_for(std::chrono::milliseconds(1));
  T.stopTimer();
  auto Time2 = T.getTotalTime();

  // Verify that accumulated time increased after the second cycle
  EXPECT_LT(Time1, Time2);
}

// Test the trigger state behavior of the timer
TEST(Timer, TriggerState) {
  Timer T("TriggerTest");

  // Initially, timer should not have been triggered
  EXPECT_FALSE(T.hasTriggered());

  // After starting, it should be considered triggered
  T.startTimer();
  EXPECT_TRUE(T.hasTriggered());

  // Even after stopping, trigger state should persist
  T.stopTimer();
  EXPECT_TRUE(T.hasTriggered());

  // Clearing the timer should reset the trigger state
  T.clear();
  EXPECT_FALSE(T.hasTriggered());
}

