// ========================
void LHomeButtonPlugin::showDesktop() {
    // Get list of all top-level windows
    QList<WId> windowList = LSession::handle()->XCB->WindowList();

    // Iterate through each window and minimize visible ones
    for (int index = 0; index < windowList.size(); ++index) {
        WId currentWindow = windowList[index];
        if (LXCB::WindowState(currentWindow) != LXCB::INVISIBLE) {
            LSession::handle()->XCB->MinimizeWindow(currentWindow);
        }
    }
}

