  auto extractValue = [&pt](const std::string& key, auto& target) {
    try {
      target = pt.get<std::decay_t<decltype(target)>>(key);
    } catch (...) {
      BOOST_LOG_TRIVIAL(debug) << "Missing or invalid value for: " << key;
    }
  };

  extractValue("type", type);
  extractValue("os", os);
  extractValue("sysroot", sysroot);
  extractValue("ostree_server", ostree_server);
  extractValue("packages_file", packages_file);
  extractValue("fake_need_reboot", fake_need_reboot);
}

void PackageConfig::writeToStream(std::ostream& out_stream) const {
  // Output configuration using range-based approach
  struct ConfigField {
    const char* name;
    std::string (*getter)(const PackageConfig&);
  };

  ConfigField fields[] = {
    {"type", [](const PackageConfig& c) { return c.type; }},
    {"os", [](const PackageConfig& c) { return c.os; }},
    {"sysroot", [](const PackageConfig& c) { return c.sysroot; }},
    {"ostree_server", [](const PackageConfig& c) { return c.ostree_server; }},
    {"packages_file", [](const PackageConfig& c) { return c.packages_file; }},
    {"fake_need_reboot", [](const PackageConfig& c) { return c.fake_need_reboot; }}
  };

  for (const auto& field : fields) {
    writeOption(out_stream, field.getter(*this), field.name);
  }
}

std::ostream& operator<<(std::ostream& os, PackageManager pm) {
  // Convert PackageManager to string using lookup table approach
  static const char* const pm_names[] = {
    "ostree",   // kOstree
    "debian",   // kDebian
    "none"      // kNone/default
  };

  int index = (pm == PackageManager::kNone) ? 2 : 
              (pm == PackageManager::kDebian) ? 1 : 0;

  os << '"' << pm_names[index] << '"';
  return os;
}

