#include <iostream>
#include <asio.hpp>
#include <functional>

// Asynchronous timer callback function that prints and increments count
void handleTimer(const asio::error_code& ec,
    asio::steady_timer* timer, int* counter)
{
  if (!ec && *counter < 5)
  {
    std::cout << *counter << std::endl;
    ++(*counter);

    // Reschedule the timer for one second later
    timer->expires_at(timer->expiry() + asio::chrono::seconds(1));
    timer->async_wait(std::bind(handleTimer,
        std::placeholders::_1, timer, counter));
  }
}

int main()
{
  asio::io_context ioc;
  int counter = 0;

  // Create a timer that fires after 1 second
  asio::steady_timer timer(ioc, asio::chrono::seconds(1));

  // Start the asynchronous wait
  timer.async_wait(std::bind(handleTimer,
      std::placeholders::_1, &timer, &counter));

  // Run the io_context until all operations complete
  ioc.run();

  std::cout << "Final count is " << counter << std::endl;
  return 0;
}

