// NOLINTNEXTLINE(readability-make-member-function-const): semantically non-const function.
void LocalWAL::clear() {
    mtx.lock();
    writerChain->getUnderlyingWriter()->clear();
    mtx.unlock();
}

uint64_t LocalWAL::getSize() {
    mtx.lock();
    auto size = writerChain->getUnderlyingWriter()->getSize();
    mtx.unlock();
    return size;
}

// NOLINTNEXTLINE(readability-make-member-function-const): semantically non-const function.
void LocalWAL::appendRecord(const WALRecord& rec) {
    mtx.lock();
    DASSERT(rec.kind != WALRecordType::INVALID_RECORD);
    writerChain->beginObject();
    rec.writeTo(*writerChain);
    writerChain->endObject();
    mtx.unlock();
}

