int main(int argc, char **argv) {
  using namespace mlir;
  using namespace mlir::equivalence;
  using namespace mlir::ematch;

  // Register timing command-line options for Tamagoyaki
  tamagoyaki::registerTimingCLOptions();

  // Load all standard MLIR passes and dialects
  mlir::registerAllPasses();

  // Register custom passes for equivalence and ematch dialects
  mlir::equivalence::registerEquivalencePasses();
  mlir::ematch::registerEmatchPasses();

  // Set up dialect registry with custom dialects
  mlir::DialectRegistry registry;
  registry.insert<mlir::equivalence::EquivalenceDialect,
                  mlir::ematch::EmatchDialect>();
  registerAllDialects(registry);

  // Run the optimization driver
  int exitCode = mlir::asMainReturnCode(
      mlir::MlirOptMain(argc, argv, "Tamagoyaki optimizer driver\n", registry));

  // Output timing statistics before exiting
  tamagoyaki::printTimingReport();
  return exitCode;
}

