#include <gtest/gtest.h>
#include "SmallVector.h"

// Test suite for SmallVector functionality with various scenarios
class SmallVectorFunctionalTest : public ::testing::Test {
};

// Verify basic push_back and clear operations
TEST_F(SmallVectorFunctionalTest, BasicOperations) {
    SmallVector<int, 3> container;
    container.push_back(10);
    container.push_back(20);
    container.push_back(30);
    container.push_back(40);
    container.push_back(50);

    EXPECT_EQ(container.size(), 5u);
    EXPECT_EQ(container[0], 10);
    EXPECT_EQ(container[1], 20);
    EXPECT_EQ(container[2], 30);
    EXPECT_EQ(container[3], 40);
    EXPECT_EQ(container[4], 50);

    container.clear();
    EXPECT_EQ(container.size(), 0u);
}

// Test behavior when elements fit within small capacity
TEST_F(SmallVectorFunctionalTest, WithinCapacity) {
    SmallVector<int, 4> container;
    container.push_back(7);
    container.push_back(14);

    EXPECT_EQ(container.size(), 2u);
    EXPECT_EQ(container[0], 7);
    EXPECT_EQ(container[1], 14);
}

// Verify empty state transitions
TEST_F(SmallVectorFunctionalTest, EmptyState) {
    SmallVector<int, 4> container;
    EXPECT_TRUE(container.empty());

    container.push_back(1);
    EXPECT_FALSE(container.empty());

    container.clear();
    EXPECT_TRUE(container.empty());
}

// Test vector growth beyond initial capacity
TEST_F(SmallVectorFunctionalTest, GrowthBehavior) {
    SmallVector<int, 4> container;

    // Initial fill
    container.push_back(1);
    container.push_back(2);
    EXPECT_EQ(container.size(), 2u);
    EXPECT_EQ(container[0], 1);
    EXPECT_EQ(container[1], 2);

    // Growth phase
    container.push_back(3);
    container.push_back(4);
    container.push_back(5);
    EXPECT_EQ(container.size(), 5u);
    EXPECT_EQ(container[0], 1);
    EXPECT_EQ(container[1], 2);
    EXPECT_EQ(container[2], 3);
    EXPECT_EQ(container[3], 4);
    EXPECT_EQ(container[4], 5);

    // Clear and re-grow
    container.clear();
    EXPECT_EQ(container.size(), 0u);

    container.push_back(6);
    container.push_back(7);
    container.push_back(8);
    EXPECT_EQ(container.size(), 3u);
    EXPECT_EQ(container[0], 6);
    EXPECT_EQ(container[1], 7);
    EXPECT_EQ(container[2], 8);

    // Further growth
    container.push_back(9);
    container.push_back(10);
    container.push_back(11);
    EXPECT_EQ(container.size(), 6u);
    EXPECT_EQ(container[0], 6);
    EXPECT_EQ(container[1], 7);
    EXPECT_EQ(container[2], 8);
    EXPECT_EQ(container[3], 9);
    EXPECT_EQ(container[4], 10);
    EXPECT_EQ(container[5], 11);

    container.clear();
    EXPECT_EQ(container.size(), 0u);
}

// Compare iterator behavior with std::vector
TEST_F(SmallVectorFunctionalTest, IteratorComparison) {
    constexpr size_t CAPACITY = 4;
    std::vector<int> referenceVec;
    SmallVector<int, CAPACITY> testVec;

    // Fill both containers
    for (size_t idx = 0; idx < CAPACITY; ++idx) {
        testVec.push_back(static_cast<int>(idx));
        referenceVec.push_back(static_cast<int>(idx));
    }

    EXPECT_EQ(testVec.size(), referenceVec.size());
    EXPECT_EQ(testVec, referenceVec);

    // Forward iteration check
    size_t idx = 0;
    for (auto iter = testVec.begin(); iter != testVec.end(); ++iter, ++idx) {
        EXPECT_EQ(*iter, referenceVec[idx]);
    }

    // Range-based loop check
    idx = 0;
    for (int value : testVec) {
        EXPECT_EQ(value, referenceVec[idx]);
        ++idx;
    }
}

// Test map operation on large dataset
TEST_F(SmallVectorFunctionalTest, MapFunctionality) {
    constexpr size_t ELEMENT_COUNT = 100000;
    SmallVector<int, 100> testVec;

    for (size_t i = 0; i < ELEMENT_COUNT; ++i) {
        testVec.push_back(static_cast<int>(i));
    }

    std::vector<int> referenceVec;
    testVec.map([&referenceVec](int x) {
        referenceVec.push_back(x);
    });

