using namespace tabulate;
using TableLine = Table::Row_t;

int main() {
    // Create a table without any padding
    Table no_space;
    no_space.format().font_style({FontStyle::bold}).padding(0);
    no_space.add_row(TableLine{"This cell has no padding"});
    std::cout << "Table with no padding:\n" << no_space << std::endl;

    // Create a table with top and bottom padding on individual cells
    Table vertical_spacing;
    vertical_spacing.format().font_style({FontStyle::bold}).padding(0);
    vertical_spacing.add_row(
        TableLine{"This cell has padding top = 1", "This cell has padding bottom = 1"});

    // Apply specific padding to individual cells
    vertical_spacing[0][0].format().padding_top(1);
    vertical_spacing[0][1].format().padding_bottom(1);

    std::cout << "\nTable with top/bottom padding:\n" << vertical_spacing << std::endl;

    return 0;
}

