// Test Duration construction with various input types
TEST(DurationTest, constructor) {
  Duration d1(100);
  EXPECT_EQ(100, d1.ToNanosecond());

  Duration d2(1.1);
  EXPECT_EQ(1100000000UL, d2.ToNanosecond());
  EXPECT_DOUBLE_EQ(1.1, d2.ToSecond());

  Duration d3(1, 1);
  EXPECT_EQ(1000000001UL, d3.ToNanosecond());
  EXPECT_DOUBLE_EQ(1.000000001, d3.ToSecond());

  Duration d4(d3);
  EXPECT_EQ(d3, d4);
}

// Test comparison and arithmetic operators for Duration
TEST(DurationTest, operators) {
  Duration a(100);
  Duration b(200);
  Duration c(300);

  EXPECT_NE(a, c);
  EXPECT_LT(a, c);
  EXPECT_LE(a, c);
  EXPECT_GT(c, a);
  EXPECT_GE(c, a);

  EXPECT_EQ(a + b, c);
  EXPECT_EQ(b, a * 2);
  EXPECT_EQ(c - b, a);

  Duration temp = a;
  temp += b;
  EXPECT_EQ(temp, c);
  EXPECT_GE(temp, c);
  EXPECT_LE(temp, c);

  temp -= b;
  EXPECT_EQ(Duration(100), temp);

  temp *= 2;
  EXPECT_EQ(b, temp);
}

// Test default-constructed Duration is zero
TEST(DurationTest, is_zero) {
  Duration zero_duration;
  EXPECT_TRUE(zero_duration.IsZero());
}

