    if(quiet_mode)
    {
        for(size_t idx = 0; idx < vaapi_gotcha_t::capacity(); ++idx)
        {
            auto* entry = vaapi_gotcha_t::at(idx);
            if(entry)
                entry->verbose = -1;
        }
    }

    vaapi_gotcha_t::get_initializer() = []() {
        // Helper lambda to reduce repetition
        auto setup_func = [](int index, const char* name, auto&&... args) {
            vaapi_gotcha_t::configure<index>(name, std::forward<decltype(args)>(args)...);
        };

        setup_func(0, "vaBeginPicture",
                   VAStatus{}, VADisplay{}, VAContextID{}, VASurfaceID{});
        setup_func(1, "vaCreateBuffer",
                   VAStatus{}, VADisplay{}, VAContextID{}, VABufferType{},
                   unsigned{}, unsigned{}, void*{}, VABufferID*{});
