// Generic handlers for functions that share same signature pattern
void
vaapi_gotcha::audit(const gotcha_data& info, audit::incoming, VADisplay dpy,
                    VAContextID ctx)
{
    const char* id = info.tool_id;
    if(std::string_view{id} == "vaDestroyBuffer")
        VA_API_REGION_START(id, "dpy", dpy, "buffer_id", ctx);
    else if(std::string_view{id} == "vaDestroyConfig")
        VA_API_REGION_START(id, "dpy", dpy, "config_id", ctx);
    else if(std::string_view{id} == "vaDestroyContext")
        VA_API_REGION_START(id, "dpy", dpy, "context", ctx);
    else if(std::string_view{id} == "vaEndPicture")
        VA_API_REGION_START(id, "dpy", dpy, "context", ctx);
    else if(std::string_view{id} == "vaSyncSurface")
        VA_API_REGION_START(id, "dpy", dpy, "render_target", ctx);
    else if(std::string_view{id} == "vaDestroyImage")
        VA_API_REGION_START(id, "dpy", dpy, "image_id", ctx);
    else if(std::string_view{id} == "vaUnmapBuffer" ||
            std::string_view{id} == "vaReleaseBufferHandle")
        VA_API_REGION_START(id, "dpy", dpy, "buffer_id", ctx);
    else
        VA_API_REGION_START(id, "dpy", dpy, "id", ctx);
}

