// google test
#include <gtest/gtest.h>
// std
#include <cstddef>
#include <cstdint>
#include <iterator>
#include <limits>
#include <string>

using sen::InputStream;
using sen::test::BufferedTestReader;

namespace
{

// Helper function to serialize data into buffer (byte-by-byte)
template <typename T>
void serializeToBuffer(BufferedTestReader& reader, const T& value)
{
  if constexpr (std::is_same_v<T, std::string>)
  {
    sen::test::TestWriter writer;
    sen::OutputStream out(writer);
    out.writeString(value);
    reader.getBuffer() = std::move(writer.getBuffer());
  }
  else
  {
    // reinterpret_cast is used for raw byte access — suppress Sonar warning
    const auto* bytes = reinterpret_cast<const uint8_t*>(&value);  // NOSONAR
    for (std::size_t idx = 0U; idx < sizeof(T); ++idx)
    {
      reader.getBuffer().emplace_back(bytes[idx]);
    }
  }
}

// Specialization for Duration: extract nanoseconds and serialize
void serializeToBuffer(BufferedTestReader& reader, const sen::Duration& dur)
{
  serializeToBuffer(reader, dur.getNanoseconds());
}

// Specialization for TimeStamp: serialize underlying duration
void serializeTimeStampToBuffer(BufferedTestReader& reader, const sen::TimeStamp& ts)
{
  serializeToBuffer(reader, ts.sinceEpoch());
}

// Test reading of unsigned 8-bit integer
void testReadUInt8()
{
  BufferedTestReader reader;
  const uint8_t input = 42U;
  serializeToBuffer(reader, input);
  InputStream in(reader.getBuffer());
  uint8_t output = 0U;
  in.readUInt8(output);
  EXPECT_EQ(output, input);
  EXPECT_EQ(sizeof(uint8_t), reader.getBuffer().size());
}

// Test reading of signed 8-bit integer
void testReadInt8()
{
  BufferedTestReader reader;
  const int8_t input = -17;
  serializeToBuffer(reader, input);
  InputStream in(reader.getBuffer());
  int8_t output = 0;
  in.readInt8(output);
  EXPECT_EQ(output, input);
  EXPECT_EQ(sizeof(int8_t), reader.getBuffer().size());
}

// Generic template for numeric type tests
template <typename T>
void testNumericType(const T& val)
{
  BufferedTestReader reader;
  serializeToBuffer(reader, val);
  InputStream in(reader.getBuffer());
  T result = T{};
  if constexpr (std::is_integral_v<T>)
  {
    if constexpr (std::is_signed_v<T>)
      in.readInt64(*reinterpret_cast<int64_t*>(&result));
    else
      in.readUInt64(*reinterpret_cast<uint64_t*>(&result));
  }
  else if constexpr (std::is_floating_point_v<T>)
  {
    if constexpr (sizeof(T) == sizeof(float))
      in.readFloat32(result);
    else
      in.readFloat64(result);
  }
  EXPECT_EQ(result, val);
  EXPECT_EQ(sizeof(T), reader.getBuffer().size());
}

// Test string serialization/deserialization
void testStringRoundTrip(const std::string& original)
{
  BufferedTestReader reader;
  serializeToBuffer(reader, original);
  InputStream in(reader.getBuffer());
  std::string decoded;
  in.readString(decoded);
  EXPECT_EQ(decoded, original);
}

// Test timestamp round-trip
void testTimestampRoundTrip(const sen::TimeStamp& ts)
{
  BufferedTestReader reader;
  serializeTimeStampToBuffer(reader, ts);
  InputStream in(reader.getBuffer());
  sen::TimeStamp decoded;
  in.readTimeStamp(decoded);
  EXPECT_EQ(decoded, ts);
  EXPECT_EQ(sizeof(int64_t), reader.getBuffer().size());
}

// Test boolean handling
void testBoolValue(bool input)
{
  BufferedTestReader reader;
  using BoolTransportType = sen::impl::BoolTransportType;
  serializeToBuffer(reader, static_cast<BoolTransportType>(input ? 1U : 0U));
  InputStream in(reader.getBuffer());
  bool output = !input;
  in.readBool(output);
  EXPECT_EQ(output, input);
  EXPECT_EQ(sizeof(bool), reader.getBuffer().size());
}

// Test numeric limits for a given type
template <typename T>
void testNumericLimits()
{
  testNumericType(T{});
  testNumericType(std::numeric_limits<T>::max());
  testNumericType(std::numeric_limits<T>::min());
  if constexpr (std::is_signed_v<T> || std::is_floating_point_v<T>)
  {
    testNumericType(std::numeric_limits<T>::lowest());
  }
}

}  // namespace

/// @test Basic read operations for various types
/// @requirements(SEN-1051)
TEST(InputStream, basics)
{
  testReadUInt8();
  testReadInt8();

  testNumericType(int16_t{-32768});
  testNumericType(uint16_t{65535U});
  testNumericType(int32_t{-2147483647});
  testNumericType(uint32_t{4294967295U});
  testNumericType(int64_t{9223372036854775807LL});
  testNumericType(uint64_t{18446744073709551615ULL});
  testNumericType(float32_t{-3.14159f});
  testNumericType(float64_t{2.718281828459045});
}

/// @test Read operations at numeric boundaries
/// @requirements(SEN-1051)
TEST(InputStream, numberLimits)
{
  testNumericLimits<int8_t>();
  testNumericLimits<uint8_t>();
  testNumericLimits<int16_t>();
  testNumericLimits<uint16_t>();
  testNumericLimits<int32_t>();
  testNumericLimits<uint32_t>();
  testNumericLimits<int64_t>();
  testNumericLimits<uint64_t>();
  testNumericLimits<float32_t>();
  testNumericLimits<float64_t>();
}

/// @test String I/O correctness
/// @requirements(SEN-1051)
TEST(InputStream, string)
{
  testStringRoundTrip("hello world this is me");
  testStringRoundTrip("");
  testStringRoundTrip(std::string("hello \0 world", 12));  // embedded null
  testStringRoundTrip(std::string("UPPER CASE minor \0 case\n", 24));  // embedded null + newline
  testStringRoundTrip("@#$$%^&*(){}!@#$$#@\\@");
}

/// @test Timestamp serialization/deserialization
/// @requirements(SEN-1051)
TEST(InputStream, timestamp)
{
  testTimestampRoundTrip(sen::TimeStamp{});
  testTimestampRoundTrip(sen::TimeStamp{sen::Duration{10}});
  testTimestampRoundTrip(sen::TimeStamp{sen::Duration{-10}});
  testTimestampRoundTrip(sen::TimeStamp{sen::Duration{10000000}});
  testTimestampRoundTrip(sen::TimeStamp{sen::Duration{-10000000}});
  testTimestampRoundTrip(sen::TimeStamp{sen::Duration{99999}});
  testTimestampRoundTrip(sen::TimeStamp{sen::Duration{}});
  testTimestampRoundTrip(sen::TimeStamp{sen::Duration{0.223}});
  testTimestampRoundTrip(
      sen::TimeStamp{sen::Duration{std::numeric_limits<sen::Duration::ValueType>::max()}});
  testTimestampRoundTrip(
      sen::TimeStamp{sen::Duration{std::numeric_limits<sen::Duration::ValueType>::min()}});
  testTimestampRoundTrip(
      sen::TimeStamp{sen::Duration{std::numeric_limits<sen::Duration::ValueType>::lowest()}});
}

/// @test Boolean I/O correctness
/// @requirements(SEN-1051)
TEST(InputStream, boolean)
{
  testBoolValue(true);
  testBoolValue(false);
}

/// @test Big-endian deserialization
/// @requirements(SEN-1051)
TEST(InputStream, BigEndian)
{
  // uint32_t
  {
    const uint32_t input = 93982U;
    BufferedTestReader reader;
    serializeToBuffer(reader, input);
    sen::InputStreamTemplate<sen::BigEndian> in(reader.getBuffer());
    uint32_t output = 0U;
    in.readUInt32(output);
    EXPECT_EQ(sen::impl::swapBytes(output), input);
    EXPECT_EQ(sizeof(uint32_t), reader.getBuffer().size());
  }

  // float64_t
  {
    const float64_t input = 6533.32;
    BufferedTestReader reader;
    serializeToBuffer(reader, input);
    sen::InputStreamTemplate<sen::BigEndian> in(reader.getBuffer());
    float64_t output = 0.0;
    in.readFloat64(output);
    EXPECT_EQ(sen::impl::swapBytes(output), input);
    EXPECT_EQ(sizeof(float64_t), reader.getBuffer().size());
  }
}

