  ros::Rate update_rate(1000);
  while (ros::ok()) {
    size_t bytes_ready = device.available();
    std::string buffer;
    if (bytes_ready > 0) {
      device.read(buffer, bytes_ready);
      parser.ProcessNewData(buffer);
    }
    ros::spinOnce();
    update_rate.sleep();
  }
  return EXIT_SUCCESS;
}

