int main() {
    std::cout << "======= SMTParser Test Program =======" << std::endl;

    // Boolean literals: true
    {
        std::cout << "\n--- Testing Boolean Value Parsing ---" << std::endl;
        auto parser = SMTParser::newParser();
        auto exprNode = parser->mkExpr("true");
        if (exprNode && exprNode->isTrue() && !exprNode->isFalse()) {
            std::cout << "Input: true" << std::endl;
            std::cout << "Result: " << parser->toString(exprNode) << std::endl;
            std::cout << "isTrue: yes" << std::endl;
        } else {
            std::cerr << "Assertion failed for 'true'" << std::endl;
            return 1;
        }
    }

    // Boolean literals: false
    {
        auto parser = SMTParser::newParser();
        auto exprNode = parser->mkExpr("false");
        if (exprNode && exprNode->isFalse() && !exprNode->isTrue()) {
            std::cout << "Input: false" << std::endl;
            std::cout << "Result: " << parser->toString(exprNode) << std::endl;
            std::cout << "isFalse: yes" << std::endl;
        } else {
            std::cerr << "Assertion failed for 'false'" << std::endl;
            return 1;
        }
    }

    // Integer parsing
    {
        std::cout << "\n--- Testing Integer Parsing ---" << std::endl;
        auto parser = SMTParser::newParser();
        auto exprNode = parser->mkExpr("42");
        if (exprNode && parser->toString(exprNode) == "42") {
            std::cout << "Input: 42" << std::endl;
            std::cout << "Result: " << parser->toString(exprNode) << std::endl;
        } else {
            std::cerr << "Assertion failed for integer '42'" << std::endl;
            return 1;
        }
    }

    // Real number parsing
    {
        std::cout << "\n--- Testing Real Number Parsing ---" << std::endl;
        auto parser = SMTParser::newParser();
        auto exprNode = parser->mkExpr("3.14");
        if (exprNode && parser->toString(exprNode) == "3.14") {
            std::cout << "Input: 3.14" << std::endl;
            std::cout << "Result: " << parser->toString(exprNode) << std::endl;
        } else {
            std::cerr << "Assertion failed for real '3.14'" << std::endl;
            return 1;
        }
    }

    // Expression parsing with logical AND
    {
        std::cout << "\n--- Testing Expression Parsing ---" << std::endl;
        auto parser = SMTParser::newParser();
        auto exprNode = parser->mkExpr("(and true false)");
        if (exprNode && exprNode->isFalse()) {
            std::cout << "Input: (and true false)" << std::endl;
            std::cout << "Result: " << parser->toString(exprNode) << std::endl;
        } else {
            std::cerr << "Assertion failed for expression '(and true false)'" << std::endl;
            return 1;
        }
    }

    return 0;
}

