  if (unpack_success) {
    printf("TOFSense-M Frame0 %d Pixel data unpack successfully:\r\n",
           g_ntsm_frame0.pixel_count);
    printf("id:%d, system_time:%d\r\n", g_ntsm_frame0.id,
           g_ntsm_frame0.system_time);

    // Loop through pixels using index-based access
    for (int idx = 0; idx < g_ntsm_frame0.pixel_count; ++idx) {
      ntsm_frame0_pixel_t *pixel_ptr = &g_ntsm_frame0.pixels[idx];
      printf("pixel %d: dis:%f, dis_status:%d, signal_strength:%d\r\n", idx,
             pixel_ptr->dis, pixel_ptr->dis_status, pixel_ptr->signal_strength);
    }
  } else {
    printf("parse error\n");
  }
}

