// RAII wrapper for a deferred SQL transaction using SQLite3
deferred_transaction::deferred_transaction(sqlite3* db_connection)
: m_conn{db_connection}
{
    // Log if the connection pointer is null
    ROCP_CI_LOG_IF(INFO, m_conn == nullptr) 
        << "rocprofiler::tool::sql::deferred_transaction "
           "initialized with a null sqlite3 handle";

    // Only proceed if the connection is valid
    if(m_conn)
    {
        execute_raw_sql_statements(m_conn, "BEGIN DEFERRED TRANSACTION");
    }
}

// Automatically commit or rollback on destruction (SQLite handles this via END TRANSACTION)
deferred_transaction::~deferred_transaction()
{
    if(m_conn)
    {
        execute_raw_sql_statements(m_conn, "END TRANSACTION");
    }
}
