	auto RegisterAxes = [&](int StartIndex) {
		for (int i = 0; i < 8; ++i) {
			EKeys::AddKey(FKeyDetails(
				FRawInputKeys::GenericUSBController_Axis1 + i,
				LOCTEXT(FString::Printf(TEXT("GenericUSBController_Axis%d", i + 1)).Get(), 
				         FString::Printf(TEXT("GenericUSBController Axis %d", i + 1)),
				         FKeyDetails::GamepadKey, DeviceCategory));
