// Tiling keys for dispatch mode selection
#define NO_QUANT_MODE_KEY 10000
#define QUANT_MODE_KEY    10002

extern "C" __global__ __aicore__ void cam_moe_dispatch_normal(
    GM_ADDR x,
    GM_ADDR expertIds,
    GM_ADDR send_offset,
    GM_ADDR send_token_idx,
    GM_ADDR recv_offset,
    GM_ADDR recv_count,
    GM_ADDR expert_global_offset,
    GM_ADDR srcrank_in_expert_offset,
    GM_ADDR r_in_srcrank_offset,
    GM_ADDR expandXOut,
    GM_ADDR dynamicScalesOut,
    GM_ADDR assist_info_for_combine,
    GM_ADDR waitRecvCostStatsOut,
    GM_ADDR workspaceGM,
    GM_ADDR tilingGM)
{
    REGISTER_TILING_DEFAULT(CamMoeDispatchNormalTilingData);
    TPipe pipe;

    bool processed = false;

#if (ORIG_DTYPE_RECV_X == DT_BF16 || ORIG_DTYPE_RECV_X == DT_FLOAT16)
    if (tilingKey == NO_QUANT_MODE_KEY) {
        GET_TILING_DATA_WITH_STRUCT(CamMoeDispatchNormalTilingData, tilingData, tilingGM);
        CamMoeDispatchNormal<DTYPE_X, DTYPE_RECV_X, false, false, false> dispatcher;
        dispatcher.Init(x, expertIds, send_offset, send_token_idx, recv_offset, recv_count,
                        expert_global_offset, srcrank_in_expert_offset, r_in_srcrank_offset,
                        expandXOut, dynamicScalesOut, assist_info_for_combine,
                        waitRecvCostStatsOut, workspaceGM, &pipe, tilingGM);
        dispatcher.Run();
        processed = true;
    }
#elif (ORIG_DTYPE_RECV_X == DT_INT8)
    if (tilingKey == QUANT_MODE_KEY) {
        GET_TILING_DATA_WITH_STRUCT(CamMoeDispatchNormalTilingData, tilingData, tilingGM);
        CamMoeDispatchNormal<DTYPE_X, DTYPE_RECV_X, true, false, false> quantDispatcher;
        quantDispatcher.Init(x, expertIds, send_offset, send_token_idx, recv_offset, recv_count,
                             expert_global_offset, srcrank_in_expert_offset, r_in_srcrank_offset,
                             expandXOut, dynamicScalesOut, assist_info_for_combine,
                             waitRecvCostStatsOut, workspaceGM, &pipe, tilingGM);
        quantDispatcher.Run();
        processed = true;
    }
#endif

    // Explicitly avoid fall-through; ensure only one path executes
    if (!processed) {
        // Optional: could add error handling or logging here
    }
}

