std::vector<SpecificAllocBase *> eld::SpecificAllocBase::Instances;

// Reset all specific allocators and the main bump pointer allocator
void eld::freeArena() {
  // Iterate over instances in reverse order and reset each
  for (auto It = SpecificAllocBase::Instances.rbegin(); 
       It != SpecificAllocBase::Instances.rend(); ++It) {
    (*It)->reset();
  }
  BAlloc.Reset();
}

// Allocate uninitialized buffer of given size
const char *eld::getUninitBuffer(uint32_t Size) {
  return BAlloc.Allocate<char>(Size);
}

