// Helper structure to represent double-precision floating point numbers
struct DoubleWord {
    uint32_t low;
    uint32_t high;
};

// Utility functions for handling floating point operations
inline void set_double_from_words(DoubleWord& dw, uint32_t low, uint32_t high) {
    dw.low = low;
    dw.high = high;
}

inline void get_double_words(const double& d, uint32_t& low, uint32_t& high) {
    const uint64_t* p = reinterpret_cast<const uint64_t*>(&d);
    low = static_cast<uint32_t>(*p & 0xFFFFFFFF);
    high = static_cast<uint32_t>((*p >> 32) & 0xFFFFFFFF);
}

inline double make_double(uint32_t low, uint32_t high) {
    uint64_t combined = (static_cast<uint64_t>(high) << 32) | low;
    return *reinterpret_cast<double*>(&combined);
}

// Denormal fix helper function
inline double fix_denormal(double value) {
    uint32_t low, high;
    get_double_words(value, low, high);

    // Check if exponent is zero or near-zero (denormal)
    uint32_t exp = (high >> 20) & 0x7FF;
    if (exp == 0 || exp == 1) {
        return 0.0;
    }
    return value;
}

// Basic arithmetic operations
double nseel_asm_add_op(double& dest, double src) {
    dest += src;
    return fix_denormal(dest);
}

double nseel_asm_sub_op(double& dest, double src) {
    dest -= src;
    return fix_denormal(dest);
}

double nseel_asm_mul_op(double& dest, double src) {
    dest *= src;
    return fix_denormal(dest);
}

double nseel_asm_div_op(double& dest, double src) {
    if (src != 0.0) {
        dest /= src;
    } else {
        dest = 0.0; // Handle division by zero
    }
    return fix_denormal(dest);
}

// Mathematical functions
double nseel_asm_sin(double x) {
    return sin(x);
}

double nseel_asm_cos(double x) {
    return cos(x);
}

double nseel_asm_tan(double x) {
    return tan(x);
}

double nseel_asm_sqrt(double x) {
    if (x < 0.0) return 0.0;
    return sqrt(x);
}

double nseel_asm_sqr(double x) {
    return x * x;
}

double nseel_asm_log(double x) {
    if (x <= 0.0) return 0.0;
    return log(x);
}

double nseel_asm_log10(double x) {
    if (x <= 0.0) return 0.0;
    return log10(x);
}

double nseel_asm_abs(double x) {
    return fabs(x);
}

double nseel_asm_uminus(double x) {
    return -x;
}

// Stack operations
class SimpleStack {
private:
    double data[1024];
    int top;

public:
    SimpleStack() : top(0) {}

    void push(double value) {
        if (top < 1024) {
            data[top++] = value;
        }
    }

    double pop() {
        if (top > 0) {
            return data[--top];
        }
        return 0.0;
    }

    double peek() {
        if (top > 0) {
            return data[top - 1];
        }
        return 0.0;
    }

    void swap() {
        if (top >= 2) {
            double temp = data[top-1];
            data[top-1] = data[top-2];
            data[top-2] = temp;
        }
    }

    bool empty() const { return top == 0; }
    int size() const { return top; }
};

// Comparison operations
int nseel_asm_equal(double a, double b) {
    const double epsilon = 1e-9;
    return fabs(a - b) < epsilon;
}

int nseel_asm_notequal(double a, double b) {
    const double epsilon = 1e-9;
    return fabs(a - b) >= epsilon;
}

int nseel_asm_above(double a, double b) {
    return a > b;
}

int nseel_asm_beloweq(double a, double b) {
    return a <= b;
}

// Bitwise operations on integers
int nseel_asm_shl(int value, int shift) {
    return value << shift;
}

int nseel_asm_shr(int value, int shift) {
    return value >> shift;
}

int nseel_asm_and(int a, int b) {
    return a & b;
}

int nseel_asm_or(int a, int b) {
    return a | b;
}

int nseel_asm_xor(int a, int b) {
    return a ^ b;
}

int nseel_asm_bnot(int value) {
    return ~value;
}

// Modulo operation
int nseel_asm_mod(int a, int b) {
    if (b == 0) return 0;
    return a % b;
}

// Boolean conversions
double nseel_asm_booltofp(int value) {
    return value ? 1.0 : 0.0;
}

int nseel_asm_fptobool(double value) {
    return (fabs(value) > 1e-9) ? 1 : 0;
}

// Min/Max operations
double nseel_asm_min(double a, double b) {
    return (a < b) ? a : b;
}

double nseel_asm_max(double a, double b) {
    return (a > b) ? a : b;
}

// Sign function
double nseel_asm_sign(double value) {
    if (value > 0.0) return 1.0;
    if (value < 0.0) return -1.0;
    return 0.0;
}

// Inverse square root approximation (similar to fast inverse sqrt)
double nseel_asm_invsqrt(double x) {
    if (x <= 0.0) return 0.0;

    // Simple Newton-Raphson iteration for 1/sqrt(x)
    double y = 1.0 / sqrt(x);
    // One iteration of Newton's method: y = y * (1.5 - 0.5 * x * y * y)
    y = y * (1.5 - 0.5 * x * y * y);
    return y;
}

// Generic function call simulation
typedef double (*FuncPtr)(double);
double nseel_asm_fcall(FuncPtr func, double arg) {
    return func(arg);
}

// Example usage demonstrating the cloned functionality
int main() {
    // Test basic arithmetic
    double a = 5.0, b = 3.0;
    std::cout << "Addition: " << nseel_asm_add_op(a, b) << std::endl;

    // Test mathematical functions
    std::cout << "Sin(PI/2): " << nseel_asm_sin(M_PI/2) << std::endl;
    std::cout << "Sqrt(16): " << nseel_asm_sqrt(16) << std::endl;

    // Test stack operations
    SimpleStack stack;
    stack.push(1.0);
    stack.push(2.0);
    std::cout << "Stack peek: " << stack.peek() << std::endl;

    // Test comparisons
    std::cout << "Equal test: " << nseel_asm_equal(1.0, 1.0) << std::endl;

    // Test bitwise operations
    std::cout << "Bitwise AND: " << nseel_asm_and(5, 3) << std::endl;

    return 0;
}

