// MD5 hash operator implementation
struct MD5Hasher {
    static void compute(const string_t& input, string_t& output, ValueVector& outputVector) {
        MD5 digestCalculator;
        digestCalculator.addToMD5(reinterpret_cast<const char*>(input.getData()), input.len);
        std::string hashResult = digestCalculator.finishMD5();
        StringVector::addString(&outputVector, output, hashResult);
    }
};

function_set MD5Function::getFunctionSet() {
    function_set availableFunctions;
    availableFunctions.push_back(
        std::make_unique<ScalarFunction>(name,
            std::vector<LogicalTypeID>{LogicalTypeID::STRING}, 
            LogicalTypeID::STRING,
            ScalarFunction::UnaryStringExecFunction<string_t, string_t, MD5Hasher>));
    return availableFunctions;
}

