class RocksDBFormatTest : public ::testing::Test {
 protected:
  std::string _buffer;
};

TEST_F(RocksDBFormatTest, little_endian_conversion) {
  // Test uint64_t with value 1
  rocksutils::UintToPersistentLittleEndian<uint64_t>(_buffer, 1);
  ASSERT_EQ(_buffer.length(), 8);
  ASSERT_EQ(rocksutils::UintFromPersistentLittleEndian<uint64_t>(_buffer.data()), 1);

  // Clear and test uint64_t with value 1337
  _buffer.clear();
  rocksutils::UintToPersistentLittleEndian<uint64_t>(_buffer, 1337);
  ASSERT_EQ(_buffer.length(), 8);
  ASSERT_EQ(rocksutils::UintFromPersistentLittleEndian<uint64_t>(_buffer.data()), 1337);

  // Clear and test uint64_t with value 1212321
  _buffer.clear();
  rocksutils::UintToPersistentLittleEndian<uint64_t>(_buffer, 1212321);
  ASSERT_EQ(_buffer.length(), 8);
  ASSERT_EQ(rocksutils::UintFromPersistentLittleEndian<uint64_t>(_buffer.data()), 1212321);

  // Clear and test uint32_t with value 88888
  _buffer.clear();
  rocksutils::UintToPersistentLittleEndian<uint32_t>(_buffer, 88888);
  ASSERT_EQ(_buffer.length(), 4);
  ASSERT_EQ(rocksutils::UintFromPersistentLittleEndian<uint32_t>(_buffer.data()), 88888);
}

TEST_F(RocksDBFormatTest, big_endian_conversion) {
  // Test uint64_t with value 1
  rocksutils::UintToPersistentBigEndian<uint64_t>(_buffer, 1);
  ASSERT_EQ(_buffer.length(), 8);
  ASSERT_EQ(rocksutils::UintFromPersistentBigEndian<uint64_t>(_buffer.data()), 1);

  // Clear and test uint64_t with value 1337
  _buffer.clear();
  rocksutils::UintToPersistentBigEndian<uint64_t>(_buffer, 1337);
  ASSERT_EQ(_buffer.length(), 8);
  ASSERT_EQ(rocksutils::UintFromPersistentBigEndian<uint64_t>(_buffer.data()), 1337);

  // Clear and test uint64_t with value 1212321
  _buffer.clear();
  rocksutils::UintToPersistentBigEndian<uint64_t>(_buffer, 1212321);
  ASSERT_EQ(_buffer.length(), 8);
  ASSERT_EQ(rocksutils::UintFromPersistentBigEndian<uint64_t>(_buffer.data()), 1212321);

  // Clear and test uint32_t with value 88888
  _buffer.clear();
  rocksutils::UintToPersistentBigEndian<uint32_t>(_buffer, 88888);
  ASSERT_EQ(_buffer.length(), 4);
  ASSERT_EQ(rocksutils::UintFromPersistentBigEndian<uint32_t>(_buffer.data()), 88888);
}

TEST_F(RocksDBFormatTest, specialized_endian_functions) {
  // Test Uint32ToPersistent / Uint32FromPersistent
  rocksutils::Uint32ToPersistent(_buffer, 1);
  ASSERT_EQ(_buffer.length(), 4);
  ASSERT_EQ(rocksutils::Uint32FromPersistent(_buffer.data()), 1);

  // Clear and test Uint16ToPersistent / Uint16FromPersistent
  _buffer.clear();
  rocksutils::Uint16ToPersistent(_buffer, 1337);
  ASSERT_EQ(_buffer.length(), 2);
  ASSERT_EQ(rocksutils::Uint16FromPersistent(_buffer.data()), 1337);

  // Clear and test Uint64ToPersistent / Uint64FromPersistent
  _buffer.clear();
  rocksutils::Uint64ToPersistent(_buffer, 1212321);
  ASSERT_EQ(_buffer.length(), 8);
  ASSERT_EQ(rocksutils::Uint64FromPersistent(_buffer.data()), 1212321);
}

