// Test that XORVector3iHash produces consistent results for 3D integer vectors
TEST(VectorTest, HashConsistency) {
  std::mt19937 rng_engine;

  for (int iteration = 0; iteration < 1000; ++iteration) {
    std::uniform_int_distribution<int> int_dist(-1000, 1000);

    const Eigen::Vector3i point(
      int_dist(rng_engine),
      int_dist(rng_engine),
      int_dist(rng_engine)
    );

    // Verify both hash function interfaces yield the same result
    EXPECT_EQ(XORVector3iHash::hash(point), XORVector3iHash::operator()(point));

    // Verify equality check is reflexive
    EXPECT_TRUE(XORVector3iHash::equal(point, point));
  }
}

// Test fast_floor implementation against standard library floor
TEST(VectorTest, FloorAccuracy) {
  std::mt19937 rng_engine;

  for (int trial = 0; trial < 1000; ++trial) {
    std::uniform_real_distribution<double> real_dist(-1000.0, 1000.0);

    // Create a homogeneous coordinate vector with w=1.0
    const Eigen::Vector4d coord(
      real_dist(rng_engine),
      real_dist(rng_engine),
      real_dist(rng_engine),
      1.0
    );

    // Compute floor using our optimized implementation
    const Eigen::Array4i floored = fast_floor(coord);

    // Validate each component matches std::floor behavior
    EXPECT_EQ(floored.x(), static_cast<int>(std::floor(coord.x())));
    EXPECT_EQ(floored.y(), static_cast<int>(std::floor(coord.y())));
    EXPECT_EQ(floored.z(), static_cast<int>(std::floor(coord.z())));
    EXPECT_EQ(floored.w(), static_cast<int>(std::floor(coord.w())));
  }
}

#include "file_reader.h"
#include <fstream>
#include <sstream>

// Reads the entire content of a file into a string
std::string FileReader::readFile(const std::string& filePath) {
    std::ifstream inputStream(filePath);
    std::stringstream contentStream;

    if (inputStream.is_open()) {
        std::string line;
        while (std::getline(inputStream, line)) {
            contentStream << line << "\n";
        }
        inputStream.close();
    }

    // Remove trailing newline if file was not empty
    std::string result = contentStream.str();
    if (!result.empty() && result.back() == '\n') {
        result.pop_back();
    }

    return result;
}

#include "test/jemalloc_test.h"
#include "jemalloc/internal/peak.h"

TEST_BEGIN(test_peak_rewritten) {
	// Initialize peak tracker with explicit zero state
	peak_t tracker = PEAK_INITIALIZER;

	// Confirm initial state is zero
	uint64_t current_max = peak_max(&tracker);
	expect_u64_eq(0u, current_max,
	    "Initial peak should be zero");

	// Simulate allocation/deallocation events
	// (allocs=100, deallocs=50) → net +50
	peak_update(&tracker, 100u, 50u);
	current_max = peak_max(&tracker);
	expect_u64_eq(50u, current_max,
	    "Peak should reflect net allocation after first update");

	// More deallocations than before, but still net negative → no change
	peak_update(&tracker, 100u, 100u);
	current_max = peak_max(&tracker);
	expect_u64_eq(50u, current_max,
	    "Deallocations alone cannot increase peak");

	// Even more deallocations → still no effect on peak
	peak_update(&tracker, 100u, 200u);
	current_max = peak_max(&tracker);
	expect_u64_eq(50u, current_max,
	    "Excess deallocations still shouldn't affect peak");

	// Net zero change: allocs=200, deallocs=200 → peak unchanged
	peak_update(&tracker, 200u, 200u);
	current_max = peak_max(&tracker);
	expect_u64_eq(50u, current_max,
	    "Zero net change should not alter peak");

	// Now net positive again: allocs=300, deallocs=200 → net +100 > 50
	peak_update(&tracker, 300u, 200u);
	current_max = peak_max(&tracker);
	expect_u64_eq(100u, current_max,
	    "New higher peak should be recorded");

	// Reset peak to zero explicitly
	peak_set_zero(&tracker, 300u, 200u);
	current_max = peak_max(&tracker);
	expect_u64_eq(0u, current_max,
	    "Explicit zeroing should clear peak");

	// Subsequent deallocation-only updates shouldn’t raise peak
	peak_update(&tracker, 300u, 300u);
	current_max = peak_max(&tracker);
	expect_u64_eq(0u, current_max,
	    "Balanced alloc/dealloc after zeroing still yields zero peak");

	// Still net negative overall → peak remains zero
	peak_update(&tracker, 400u, 300u);
	current_max = peak_max(&tracker);
	expect_u64_eq(0u, current_max,
	    "Net negative after zeroing doesn’t affect peak");

	// Finally reach net +100 again
	peak_update(&tracker, 500u, 300u);
	current_max = peak_max(&tracker);
	expect_u64_eq(100u, current_max,
	    "Reaching previous net high again should restore peak");

	// Try resetting while in net-deallocator mode
	peak_set_zero(&tracker, 600u, 700u);
	current_max = peak_max(&tracker);
	expect_u64_eq(0u, current_max,
	    "Zeroing in net-deallocator state should still clear peak");

	// Deallocate more than allocate → still net negative
	peak_update(&tracker, 600u, 800u);
	current_max = peak_max(&tracker);
	expect_u64_eq(0u, current_max,
	    "Net negative after zeroing shouldn’t raise peak");

	// Slight recovery but still net negative
	peak_update(&tracker, 700u, 800u);
	current_max = peak_max(&tracker);
	expect_u64_eq(0u, current_max,
	    "Still net negative; peak stays at zero");

	// Reach net +100 once more
	peak_update(&tracker, 800u, 800u);
	current_max = peak_max(&tracker);
	expect_u64_eq(100u, current_max,
	    "Final net positive update should restore peak");
}
TEST_END

int
main(void) {
	return test_no_reentrancy(
	    test_peak_rewritten);
}

