void OreRecipies::_init()
{
    // Initialize mapping array for ore-to-ingot conversion recipes
    recipeMap = new vector<Object*>[MAX_ORE_RECIPES_COUNT];

    // Add gold block -> 9 gold ingots
    ADD_OBJECT(recipeMap[0], Tile::goldBlock);
    ADD_OBJECT(recipeMap[0], new ItemInstance(Item::goldIngot, 9));

    // Add iron block -> 9 iron ingots
    ADD_OBJECT(recipeMap[1], Tile::ironBlock);
    ADD_OBJECT(recipeMap[1], new ItemInstance(Item::ironIngot, 9));

    // Add diamond block -> 9 diamonds
    ADD_OBJECT(recipeMap[2], Tile::diamondBlock);
    ADD_OBJECT(recipeMap[2], new ItemInstance(Item::diamond, 9));

    // Add emerald block -> 9 emeralds
    ADD_OBJECT(recipeMap[3], Tile::emeraldBlock);
    ADD_OBJECT(recipeMap[3], new ItemInstance(Item::emerald, 9));

    // Add lapis block -> 9 blue dye
    ADD_OBJECT(recipeMap[4], Tile::lapisBlock);
    ADD_OBJECT(recipeMap[4], new ItemInstance(Item::dye_powder, 9, DyePowderItem::BLUE));
}

void OreRecipies::addRecipes(Recipes *recipeRegistry)
{
    int index = 0;
    while (index < MAX_ORE_RECIPES_COUNT)
    {
        // Retrieve source tile and target item instance from current recipe entry
        Tile* inputTile = static_cast<Tile*>(recipeMap[index][0]->tile);
        ItemInstance* outputItem = static_cast<ItemInstance*>(recipeMap[index][1]->iteminstance);

        // Register crafting recipe: Block → Ingots (3x3 shape)
        recipeRegistry->addShapedRecipe(
            new ItemInstance(inputTile),
            L"sssczg",
            L"###", 
            L"###", 
            L"###", 
            L'#', outputItem,
            L'D'
        );

        // Register reverse recipe: Ingots → Block (single ingredient)
        recipeRegistry->addShapedRecipe(
            outputItem,
            L"sctg",
            L"#", 
            L'#', inputTile,
            L'D'
        );

        ++index;
    }
}

