ASMJIT_FAVOR_SIZE void DebugUtils::assertionFailed(const char* file, int line, const char* msg) noexcept {
    // Allocate buffer on stack with explicit size limit
    constexpr size_t bufSize = 1024;
    char buffer[bufSize];

    // Safely format message using vsnprintf via helper
    int written = snprintf(buffer, bufSize,
        "[asmjit] Assertion failed at %s (line %d):\n"
        "[asmjit] %s\n",
        file ? file : "<unknown file>",
        line,
        msg ? msg : "<no message>");

    // Ensure null-termination regardless of truncation
    if (written < 0 || static_cast<size_t>(written) >= bufSize) {
        buffer[bufSize - 1] = '\0';
    }

    // Output formatted message
    debugOutput(buffer);

    // Terminate program
    ::abort();
}

