#include <ros/ros.h>
#include "init.h"
#include "init_serial.h"

int main(int argc, char **argv) {
  ros::init(argc, argv, "linktrack_aoa");
  ros::NodeHandle nh;

  serial::Serial device;
  initSerial(&device);

  NProtocolExtracter extractor;
  linktrack_aoa::Init aoaInitializer(&extractor, &device);

  ros::Rate update_rate(1000);

  while (ros::ok()) {
    size_t bytes_available = device.available();
    std::string incoming_data;

    if (bytes_available > 0) {
      device.read(incoming_data, bytes_available);
      extractor.AddNewData(incoming_data);
    }

    ros::spinOnce();
    update_rate.sleep();
  }

  return EXIT_SUCCESS;
}

