// Helper function to construct image brush paths
static FString ConstructIconPath(const FString& RelativePath)
{
    static const FString PluginContentDir = []() -> FString {
        auto Plugin = IPluginManager::Get().FindPlugin(TEXT("ModelingToolsEditorMode"));
        return Plugin ? Plugin->GetContentDir() : FString();
    }();

    return PluginContentDir / RelativePath + TEXT(".png");
}

// Helper function to create image brushes consistently
static FSlateImageBrush MakeIconBrush(const FString& IconName, FVector2D Size)
{
    return FSlateImageBrush(ConstructIconPath(IconName), Size);
}

// Helper for core content icons
static FSlateImageBrush MakeCoreIconBrush(const FString& RelativePath, FVector2D Size)
{
    return FSlateImageBrush(FPaths::EngineContentDir() / TEXT("Slate") / RelativePath, Size);
}

