namespace snap::utils::crypto {

void logCryptoErrors() {
#ifndef NDEBUG
    // In debug builds, log all OpenSSL errors
    while (uint32_t error = ERR_get_error()) {
        std::array<char, 120> buffer;
        ERR_error_string_n(error, buffer.data(), buffer.size());
        SCLOGE("[utils][CryptoHelpers]", "OpenSSL error: {}", buffer.data());
    }
#else
    // In release builds, silently consume all OpenSSL errors
    while (ERR_get_error() != 0u) {
        // Do nothing - just drain the error queue
    }
#endif
}

} // namespace snap::utils::crypto

