// Helper template for static arrays with dynamic allocation
template<typename ElementType, typename SizeType>
struct ArrayHolder {
    ElementType* buffer = nullptr;
    SizeType count = 0;

    ~ArrayHolder() {
        delete[] buffer;
    }

    void AllocateFrom(BinaryReader& stream) {
        stream.ReadLE(count);
        delete[] buffer;
        if (count > 0)
            buffer = new ElementType[count];
    }

    void LoadFrom(BinaryReader& stream) {
        SizeType idx = 0;
        while (idx < count) {
            buffer[idx].Load(stream);
            ++idx;
        }
    }

    void AllocateAndLoad(BinaryReader& stream) {
        AllocateFrom(stream);
        LoadFrom(stream);
    }
};

// Lightweight string wrapper for binary loading
struct InlineString {
    uint32_t size = 0;
    const char* chars = nullptr;

    void Load(BinaryReader& stream) {
        assert(stream.ReadLE(size));
        assert(stream.ReadBytes(chars, size));
    }
};

using StringArray = ArrayHolder<InlineString, uint32_t>;

void DisplayTable(StringArray& list) {
    for (uint32_t i = 0; i < list.count; ++i)
        printf("\"%.*s\"\n", list.buffer[i].size, list.buffer[i].chars);
}

// Header entry: fixed-size record with 8 unsigned 32-bit fields
struct RecordHeader {
    uint32_t field0;
    uint32_t field1;
    uint32_t field2;
    uint32_t field3;
    uint32_t field4;
    uint32_t field5;
    uint32_t field6;
    uint32_t field7;

    void Load(BinaryReader& stream) {
        stream.ReadLE(field0);
        stream.ReadLE(field1);
        stream.ReadLE(field2);
        stream.ReadLE(field3);
        stream.ReadLE(field4);
        stream.ReadLE(field5);
        stream.ReadLE(field6);
        stream.ReadLE(field7);
    }
};

// Top-level header chunk containing metadata and records
struct MetaBlock {
    ArrayHolder<RecordHeader, uint32_t> entries;
    uint32_t zeroMarker;
    uint32_t worldEntityId;
    uint32_t primaryTableSize;

    void Load(BinaryReader& stream) {
        entries.AllocateFrom(stream);
        stream.ReadLE(zeroMarker);
        assert(zeroMarker == 0);
        stream.ReadLE(worldEntityId);
        stream.ReadLE(primaryTableSize);
        entries.LoadFrom(stream);
    }
};

void FatalError(BinaryReader& stream) {
    printf("%zu\n", stream.GetPosition());
    assert(false);
}

// Main section parser: loads header, string tables, and validates padding
struct StaticDataSection {
    MetaBlock meta;
    StringArray stringsA;
    StringArray stringsB;

    void Load(BinaryReader& stream) {
        meta.Load(stream);
        stringsA.AllocateAndLoad(stream);
        assert(stringsA.count == meta.primaryTableSize);

        while (true) {
            uint32_t opcode, pad0, pad1;
            assert(stream.ReadLE(opcode));
            if (opcode == 0) {
                stream.ReadLE(pad0);
                stream.ReadLE(pad1);
                assert(pad0 == 0 && pad1 == 0);
            } else {
                FatalError(stream);
            }
        }
    }
};

void StaticsParser::Parse(BinaryReader& reader) {
    StaticDataSection data;
    data.Load(reader);
}

