class Solution {
public:
    uint32_t reverseBits(uint32_t n) {
        uint32_t result = 0;
        int position = 0;
        while (position < 32) {
            result <<= 1;
            result |= (n & 1);
            n >>= 1;
            position++;
        }
        return result;
    }
};

