#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <string.h>

void printUsage() {
    fprintf(stderr, "tone <frequency_Hz>,[<amplitude>] [<frequency_Hz>,[<amplitude>]...]\n");
    exit(1);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printUsage();
    }

    int count = argc - 1;
    double *frequencies = static_cast<double*>(alloca(sizeof(double) * count));
    double *amplitudes = static_cast<double*>(alloca(sizeof(double) * count));

    int index = 0;
    while (index < count) {
        char *commaPos = strchr(argv[index + 1], ',');

        frequencies[index] = atof(argv[index + 1]);
        if (commaPos != nullptr) {
            amplitudes[index] = atof(commaPos + 1) * 32767.0;
        } else {
            amplitudes[index] = 32767.0;
        }
        fprintf(stderr, "%g Hz, %g amp\n", frequencies[index], amplitudes[index]);
        index++;
    }

    const int sampleRate = 44100;
    const int durationSeconds = 10;
    const int totalSamples = sampleRate * durationSeconds;

    for (int sample = 0; sample < totalSamples; ++sample) {
        double combinedValue = 0.0;
        for (int toneIndex = 0; toneIndex < count; ++toneIndex) {
            combinedValue += amplitudes[toneIndex] * 
                sin(sample / static_cast<double>(sampleRate) * 
                    frequencies[toneIndex] * 2.0 * M_PI);
        }

        int integerValue = static_cast<int>(rint(combinedValue));
        if (integerValue > 32767) {
            integerValue = 32767;
        }
        if (integerValue < -32768) {
            integerValue = -32768;
        }

        // Output as little-endian 16-bit PCM samples (repeated pattern)
        fprintf(stdout, "%c%c%c%c",
                static_cast<char>(integerValue & 0xFF),
                static_cast<char>((integerValue >> 8) & 0xFF),
                static_cast<char>(integerValue & 0xFF),
                static_cast<char>((integerValue >> 8) & 0xFF));
    }

    return 0;
}

