// Helper function to locate environment variable in vector
static std::string
locate_env_entry(const std::vector<char*>& env_list, std::string_view key_name)
{
    std::string search_prefix = std::string(key_name) + "=";
    for(auto* entry : env_list)
    {
        if(!entry) continue;
        std::string_view current{ entry };
        if(current.substr(0, search_prefix.size()) == search_prefix)
        {
            return std::string{ entry };
        }
    }
    return "";
}

class EnvironmentModificationTest : public ::testing::Test
{
protected:
    void SetUp() override
    {
        test_env_vars.clear();
        modified_keys.clear();
        original_entries.clear();
    }

    void TearDown() override
    {
        for(auto* ptr : test_env_vars)
        {
            if(ptr) free(ptr);
        }
    }

    std::vector<char*>                   test_env_vars;
    std::unordered_set<std::string_view> modified_keys;
    std::unordered_set<std::string>      original_entries;
};

TEST_F(EnvironmentModificationTest, InsertNewKey_ReplaceMode)
{
    update_env(test_env_vars, "NEW_KEY", "new_value", update_mode::REPLACE, ":",
               modified_keys, original_entries);
    ASSERT_EQ(test_env_vars.size(), 1);
    EXPECT_STREQ(test_env_vars[0], "NEW_KEY=new_value");
    EXPECT_EQ(modified_keys.count("NEW_KEY"), 1);
}

TEST_F(EnvironmentModificationTest, UpdateExistingKey_ReplaceMode)
{
    test_env_vars.push_back(strdup("EXISTING_KEY=old_data"));
    original_entries.insert("EXISTING_KEY=old_data");
    update_env(test_env_vars, "EXISTING_KEY", "updated_data", update_mode::REPLACE, ":",
               modified_keys, original_entries);
    ASSERT_EQ(test_env_vars.size(), 1);
    EXPECT_STREQ(test_env_vars[0], "EXISTING_KEY=updated_data");
    EXPECT_EQ(modified_keys.count("EXISTING_KEY"), 1);
}

TEST_F(EnvironmentModificationTest, AppendToMissingKey_AppendMode)
{
    update_env(test_env_vars, "PATH_VAR", "/added/path", update_mode::APPEND, ":",
               modified_keys, original_entries);
    ASSERT_EQ(test_env_vars.size(), 1);
    EXPECT_STREQ(test_env_vars[0], "PATH_VAR=/added/path");
}

TEST_F(EnvironmentModificationTest, AppendToExistingKey_AppendMode)
{
    test_env_vars.push_back(strdup("PATH_VAR=/base/path"));
    original_entries.insert("PATH_VAR=/base/path");
    update_env(test_env_vars, "PATH_VAR", "/extra/path", update_mode::APPEND, ":",
               modified_keys, original_entries);
    ASSERT_EQ(test_env_vars.size(), 1);
    EXPECT_STREQ(test_env_vars[0], "PATH_VAR=/base/path:/extra/path");
    EXPECT_EQ(modified_keys.count("PATH_VAR"), 1);
}

TEST_F(EnvironmentModificationTest, PrependToExistingKey_PrependMode)
{
    test_env_vars.push_back(strdup("LIB_PATH=/existing/lib"));
    original_entries.insert("LIB_PATH=/existing/lib");
    update_env(test_env_vars, "LIB_PATH", "/new/lib", update_mode::PREPEND, ":",
               modified_keys, original_entries);
    ASSERT_EQ(test_env_vars.size(), 1);
    EXPECT_STREQ(test_env_vars[0], "LIB_PATH=/new/lib:/existing/lib");
}

TEST_F(EnvironmentModificationTest, WeakMode_OriginalValuePreserved)
{
    test_env_vars.push_back(strdup("WEAK_KEY=original_val"));
    original_entries.insert("WEAK_KEY=original_val");
    update_env(test_env_vars, "WEAK_KEY", "new_val", update_mode::WEAK, ":",
