#include <tabulate/table.hpp>
#include <iostream>

using namespace tabulate;
using TableRow = Table::Row_t;

int main() {
    Table styledTable;

    // Add rows with color-related text
    styledTable.add_row(TableRow{"Font Color is Red", "Font Color is Blue", "Font Color is Green"});
    styledTable.add_row(TableRow{"Everything is Red", "Everything is Blue", "Everything is Green"});
    styledTable.add_row(TableRow{"Font Background is Red", "Font Background is Blue", "Font Background is Green"});

    // Apply formatting to first row: colored and bold font
    styledTable[0][0].format().font_color(Color::red).font_style({FontStyle::bold});
    styledTable[0][1].format().font_color(Color::blue).font_style({FontStyle::bold});
    styledTable[0][2].format().font_color(Color::green).font_style({FontStyle::bold});

    // Apply comprehensive formatting to second row: border, background, and font colors
    styledTable[1][0]
        .format()
        .border_left_color(Color::red)
        .border_left_background_color(Color::red)
        .font_background_color(Color::red)
        .font_color(Color::red);

    styledTable[1][1]
        .format()
        .border_left_color(Color::blue)
        .border_left_background_color(Color::blue)
        .font_background_color(Color::blue)
        .font_color(Color::blue);

    styledTable[1][2]
        .format()
        .border_left_color(Color::green)
        .border_left_background_color(Color::green)
        .font_background_color(Color::green)
        .font_color(Color::green)
        .border_right_color(Color::green)
        .border_right_background_color(Color::green);

    // Apply background color and bold style to third row
    styledTable[2][0].format().font_background_color(Color::red).font_style({FontStyle::bold});
    styledTable[2][1].format().font_background_color(Color::blue).font_style({FontStyle::bold});
    styledTable[2][2].format().font_background_color(Color::green).font_style({FontStyle::bold});

    std::cout << styledTable << std::endl;
    return 0;
}

