#include <stdlib.h>
#include <stdio.h>
#include "../include/blasfeo_target.h"
#include "../include/blasfeo_common.h"
#include "../include/blasfeo_d_aux.h"
#include "../include/blasfeo_d_kernel.h"
#include "../include/blasfeo_d_blas.h"

#if defined(FORTRAN_BLAS_API)
#define blas_dsyrk dsyrk_
#endif

// Helper to determine block size based on target architecture
inline int get_block_size() {
#if defined(TARGET_X64_INTEL_HASWELL)
    return 12;
#elif defined(TARGET_X64_INTEL_SANDY_BRIDGE) || defined(TARGET_ARMV8A_ARM_CORTEX_A57)
    return 8;
#else
    return 4;
#endif
}

// Helper to check if stack-based algorithm should be used
inline bool use_stack_algorithm(int m, int k) {
    const int bs = get_block_size();
#if defined(TARGET_X64_INTEL_HASWELL)
    return (m <= 300 && k <= 300 && k <= K_MAX_STACK);
#elif defined(TARGET_X64_INTEL_SANDY_BRIDGE)
    return (m <= 64 && k <= 64 && k <= K_MAX_STACK);
#elif defined(TARGET_ARMV8A_ARM_CORTEX_A57)
    return (m <= 32 && k <= 32 && k <= K_MAX_STACK);
#elif defined(TARGET_ARMV8A_ARM_CORTEX_A53)
    return (m <= 16 && k <= 16 && k <= K_MAX_STACK);
#else
    return (m <= 12 && k <= 12 && k <= K_MAX_STACK);
#endif
}

static void blasfeo_dsyrk3(char uplo, char ta, int m, int k, double alpha, double *A, int lda, double beta, double *C, int ldc, double *D, int ldd)
{
#if defined(PRINT_NAME)
    printf("\nblasfeo_dsyrk3 %c %c %d %d %f %p %d %f %p %d %p %d\n", uplo, ta, m, k, alpha, A, lda, beta, C, ldc, D, ldd);
#endif

    if (m <= 0) return;

    // Determine block size and allocate aligned stack memory
    const int bs = get_block_size();
    void* mem = nullptr;
    char* mem_align = nullptr;
    double* pU = nullptr;
    int sdu = 0;

    // Stack-allocated buffer for small problems
    double* local_buffer = nullptr;
    int buffer_capacity = 0;

#if defined(TARGET_X64_INTEL_HASWELL)
    ALIGNED(double local_mem[3 * bs * K_MAX_STACK], 64);
    buffer_capacity = 3 * bs * K_MAX_STACK;
#elif defined(TARGET_X64_INTEL_SANDY_BRIDGE) || defined(TARGET_ARMV8A_ARM_CORTEX_A57)
    ALIGNED(double local_mem[2 * bs * K_MAX_STACK], 64);
    buffer_capacity = 2 * bs * K_MAX_STACK;
#elif defined(TARGET_ARMV8A_ARM_CORTEX_A53)
    ALIGNED(double local_mem[2 * bs * K_MAX_STACK], 64);
    buffer_capacity = 2 * bs * K_MAX_STACK;
#else
    double local_mem[1 * bs * K_MAX_STACK];
    buffer_capacity = 1 * bs * K_MAX_STACK;
#endif

    // Decide whether to use stack or heap allocation
    const int sdu0 = ((k + bs - 1) / bs) * bs;
    const int effective_k = (sdu0 < K_MAX_STACK) ? sdu0 : K_MAX_STACK;

    if (use_stack_algorithm(m, k)) {
        pU = local_mem;
        sdu = effective_k;
    } else {
        // Heap allocation path
        int k1 = ((k + 127) / 128) * 128;
        int m1 = ((m + 127) / 128) * 128;
        struct blasfeo_dmat sA;
        int sA_size = blasfeo_memsize_dmat(m1, k1);
        mem = malloc(sA_size + 64);
        blasfeo_align_64_byte(mem, (void**)&mem_align);
        blasfeo_create_dmat(m, k, &sA, mem_align);

        if (ta == 'n' || ta == 'N')
            blasfeo_pack_dmat(m, k, A, lda, &sA, 0, 0);
        else
            blasfeo_pack_tran_dmat(k, m, A, lda, &sA, 0, 0);

        pU = sA.pA;
        sdu = sA.cn;
    }

    int row_idx = 0;
    const int block_size = get_block_size();

    // Main computation logic based on uplo and ta
    if (uplo == 'l' || uplo == 'L') {
        if (ta == 'n' || ta == 'N') {
            // Lower triangular, no transpose
            while (row_idx < m) {
                int remaining = m - row_idx;
                int current_block = (remaining >= block_size) ? block_size : remaining;

                // Pack current panel
                if (current_block == 4) {
                    kernel_dpack_nn_4_lib4(k, A + row_idx, lda, pU);
                } else if (current_block == 8) {
                    kernel_dpack_nn_8_lib4(k, A + row_idx, lda, pU, sdu);
                } else if (current_block == 12) {
                    kernel_dpack_nn_12_lib4(k, A + row_idx, lda, pU, sdu);
                } else {
                    kernel_dpack_nn_4_vs_lib4(k, A + row_idx, lda, pU, current_block);
                }

                // Process columns before diagonal block
                int col_idx = 0;
                while (col_idx < row_idx) {
                    int col_remaining = row_idx - col_idx;
                    int col_block = (col_remaining >= 4) ? 4 : col_remaining;

                    if (block_size == 12) {
                        kernel_dgemm_nt_12x4_lib4ccc(k, &alpha, pU, sdu, A + col_idx, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    } else if (block_size == 8) {
                        kernel_dgemm_nt_8x4_lib4ccc(k, &alpha, pU, sdu, A + col_idx, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    } else {
                        kernel_dgemm_nt_4x4_lib4ccc(k, &alpha, pU, A + col_idx, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    }
                    col_idx += 4;
                }

                // Diagonal block: symmetric rank-k update
                if (block_size == 12) {
                    kernel_dsyrk_nt_l_12x4_lib44cc(k, &alpha, pU, sdu, pU, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    if (current_block > 4) {
                        kernel_dsyrk_nt_l_8x8_lib44cc(k, &alpha, pU + 4 * sdu, sdu, pU + 4 * sdu, sdu, &beta, C + (row_idx + 4) + (col_idx + 4) * ldc, ldc, D + (row_idx + 4) + (col_idx + 4) * ldd, ldd);
                    }
                } else if (block_size == 8) {
                    kernel_dsyrk_nt_l_8x4_lib44cc(k, &alpha, pU, sdu, pU, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    if (current_block > 4) {
                        kernel_dsyrk_nt_l_4x4_lib44cc(k, &alpha, pU + 4 * sdu, pU + 4 * sdu, &beta, C + (row_idx + 4) + (col_idx + 4) * ldc, ldc, D + (row_idx + 4) + (col_idx + 4) * ldd, ldd);
                    }
                } else {
                    kernel_dsyrk_nt_l_4x4_lib44cc(k, &alpha, pU, pU, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                }

                row_idx += current_block;
            }
        } else if (ta == 't' || ta == 'T' || ta == 'c' || ta == 'C') {
            // Lower triangular, transpose
            while (row_idx < m) {
                int remaining = m - row_idx;
                int current_block = (remaining >= block_size) ? block_size : remaining;

                // Pack transposed panels
                for (int i = 0; i < current_block; i += 4) {
                    if (i + 4 <= current_block) {
                        kernel_dpack_tn_4_lib4(k, A + (row_idx + i) * lda, lda, pU + i * sdu);
                    } else {
                        kernel_dpack_tn_4_vs_lib4(k, A + (row_idx + i) * lda, lda, pU + i * sdu, current_block - i);
                    }
                }

                int col_idx = 0;
                while (col_idx < row_idx) {
                    int col_remaining = row_idx - col_idx;
                    int col_block = (col_remaining >= 4) ? 4 : col_remaining;

                    if (block_size == 12) {
                        kernel_dgemm_nn_12x4_lib4ccc(k, &alpha, pU, sdu, A + col_idx * lda, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    } else if (block_size == 8) {
                        kernel_dgemm_nn_8x4_lib4ccc(k, &alpha, pU, sdu, A + col_idx * lda, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    } else {
                        kernel_dgemm_nn_4x4_lib4ccc(k, &alpha, pU, A + col_idx * lda, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    }
                    col_idx += 4;
                }

                // Diagonal block
                if (block_size == 12) {
                    kernel_dsyrk_nt_l_12x4_lib44cc(k, &alpha, pU, sdu, pU, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    if (current_block > 4) {
                        kernel_dsyrk_nt_l_8x8_lib44cc(k, &alpha, pU + 4 * sdu, sdu, pU + 4 * sdu, sdu, &beta, C + (row_idx + 4) + (col_idx + 4) * ldc, ldc, D + (row_idx + 4) + (col_idx + 4) * ldd, ldd);
                    }
                } else if (block_size == 8) {
                    kernel_dsyrk_nt_l_8x4_lib44cc(k, &alpha, pU, sdu, pU, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    if (current_block > 4) {
                        kernel_dsyrk_nt_l_4x4_lib44cc(k, &alpha, pU + 4 * sdu, pU + 4 * sdu, &beta, C + (row_idx + 4) + (col_idx + 4) * ldc, ldc, D + (row_idx + 4) + (col_idx + 4) * ldd, ldd);
                    }
                } else {
                    kernel_dsyrk_nt_l_4x4_lib44cc(k, &alpha, pU, pU, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                }

                row_idx += current_block;
            }
        } else {
            fprintf(stderr, "BLASFEO: dsyrk: invalid value for ta\n");
            return;
        }
    } else if (uplo == 'u' || uplo == 'U') {
        if (ta == 'n' || ta == 'N') {
            // Upper triangular, no transpose
            while (row_idx < m) {
                int remaining = m - row_idx;
                int current_block = (remaining >= block_size) ? block_size : remaining;

                // Pack current panel
                if (current_block == 4) {
                    kernel_dpack_nn_4_lib4(k, A + row_idx, lda, pU);
                } else if (current_block == 8) {
                    kernel_dpack_nn_8_lib4(k, A + row_idx, lda, pU, sdu);
                } else if (current_block == 12) {
                    kernel_dpack_nn_12_lib4(k, A + row_idx, lda, pU, sdu);
                } else {
                    kernel_dpack_nn_4_vs_lib4(k, A + row_idx, lda, pU, current_block);
                }

                // Diagonal block first
                if (block_size == 12) {
                    kernel_dsyrk_nt_u_8x8_lib44cc(k, &alpha, pU, sdu, pU, sdu, &beta, C + row_idx + row_idx * ldc, ldc, D + row_idx + row_idx * ldd, ldd);
                    kernel_dsyrk_nt_u_12x4_lib44cc(k, &alpha, pU, sdu, pU + 8 * sdu, &beta, C + row_idx + (row_idx + 8) * ldc, ldc, D + row_idx + (row_idx + 8) * ldd, ldd);
                } else if (block_size == 8) {
                    kernel_dsyrk_nt_u_4x4_lib44cc(k, &alpha, pU, pU, &beta, C + row_idx + row_idx * ldc, ldc, D + row_idx + row_idx * ldd, ldd);
                    kernel_dsyrk_nt_u_8x4_lib44cc(k, &alpha, pU, sdu, pU + 4 * sdu, &beta, C + row_idx + (row_idx + 4) * ldc, ldc, D + row_idx + (row_idx + 4) * ldd, ldd);
                } else {
                    kernel_dsyrk_nt_u_4x4_lib44cc(k, &alpha, pU, pU, &beta, C + row_idx + row_idx * ldc, ldc, D + row_idx + row_idx * ldd, ldd);
                }

                // Off-diagonal blocks
                int col_idx = row_idx + current_block;
                while (col_idx < m - 3) {
                    int col_block = 4;
                    if (block_size == 12) {
                        kernel_dgemm_nt_12x4_lib4ccc(k, &alpha, pU, sdu, A + col_idx, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    } else if (block_size == 8) {
                        kernel_dgemm_nt_8x4_lib4ccc(k, &alpha, pU, sdu, A + col_idx, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    } else {
                        kernel_dgemm_nt_4x4_lib4ccc(k, &alpha, pU, A + col_idx, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    }
                    col_idx += 4;
                }

                // Handle remaining rows in column loop
                if (col_idx < m) {
                    int col_remaining = m - col_idx;
                    if (block_size == 12) {
                        kernel_dgemm_nt_12x4_vs_lib4ccc(k, &alpha, pU, sdu, A + col_idx, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd, m - row_idx, m - col_idx);
                    } else if (block_size == 8) {
                        kernel_dgemm_nt_8x4_vs_lib4ccc(k, &alpha, pU, sdu, A + col_idx, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd, m - row_idx, m - col_idx);
                    } else {
                        kernel_dgemm_nt_4x4_vs_lib4ccc(k, &alpha, pU, A + col_idx, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd, m - row_idx, m - col_idx);
                    }
                }

                row_idx += current_block;
            }
        } else if (ta == 't' || ta == 'T' || ta == 'c' || ta == 'C') {
            // Upper triangular, transpose
            while (row_idx < m) {
                int remaining = m - row_idx;
                int current_block = (remaining >= block_size) ? block_size : remaining;

                // Pack transposed panels
                for (int i = 0; i < current_block; i += 4) {
                    if (i + 4 <= current_block) {
                        kernel_dpack_tn_4_lib4(k, A + (row_idx + i) * lda, lda, pU + i * sdu);
                    } else {
                        kernel_dpack_tn_4_vs_lib4(k, A + (row_idx + i) * lda, lda, pU + i * sdu, current_block - i);
                    }
                }

                // Diagonal block
                if (block_size == 12) {
                    kernel_dsyrk_nt_u_8x8_lib44cc(k, &alpha, pU, sdu, pU, sdu, &beta, C + row_idx + row_idx * ldc, ldc, D + row_idx + row_idx * ldd, ldd);
                    kernel_dsyrk_nt_u_12x4_lib44cc(k, &alpha, pU, sdu, pU + 8 * sdu, &beta, C + row_idx + (row_idx + 8) * ldc, ldc, D + row_idx + (row_idx + 8) * ldd, ldd);
                } else if (block_size == 8) {
                    kernel_dsyrk_nt_u_4x4_lib44cc(k, &alpha, pU, pU, &beta, C + row_idx + row_idx * ldc, ldc, D + row_idx + row_idx * ldd, ldd);
                    kernel_dsyrk_nt_u_8x4_lib44cc(k, &alpha, pU, sdu, pU + 4 * sdu, &beta, C + row_idx + (row_idx + 4) * ldc, ldc, D + row_idx + (row_idx + 4) * ldd, ldd);
                } else {
                    kernel_dsyrk_nt_u_4x4_lib44cc(k, &alpha, pU, pU, &beta, C + row_idx + row_idx * ldc, ldc, D + row_idx + row_idx * ldd, ldd);
                }

                // Off-diagonal blocks
                int col_idx = row_idx + current_block;
                while (col_idx < m - 3) {
                    int col_block = 4;
                    if (block_size == 12) {
                        kernel_dgemm_nn_12x4_lib4ccc(k, &alpha, pU, sdu, A + col_idx * lda, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    } else if (block_size == 8) {
                        kernel_dgemm_nn_8x4_lib4ccc(k, &alpha, pU, sdu, A + col_idx * lda, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    } else {
                        kernel_dgemm_nn_4x4_lib4ccc(k, &alpha, pU, A + col_idx * lda, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd);
                    }
                    col_idx += 4;
                }

                // Handle remaining rows in column loop
                if (col_idx < m) {
                    int col_remaining = m - col_idx;
                    if (block_size == 12) {
                        kernel_dgemm_nn_12x4_vs_lib4ccc(k, &alpha, pU, sdu, A + col_idx * lda, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd, m - row_idx, m - col_idx);
                    } else if (block_size == 8) {
                        kernel_dgemm_nn_8x4_vs_lib4ccc(k, &alpha, pU, sdu, A + col_idx * lda, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd, m - row_idx, m - col_idx);
                    } else {
                        kernel_dgemm_nn_4x4_vs_lib4ccc(k, &alpha, pU, A + col_idx * lda, lda, &beta, C + row_idx + col_idx * ldc, ldc, D + row_idx + col_idx * ldd, ldd, m - row_idx, m - col_idx);
                    }
                }

                row_idx += current_block;
            }
        } else {
            fprintf(stderr, "BLASFEO: dsyrk: invalid value for ta\n");
            return;
        }
    } else {
        fprintf(stderr, "BLASFEO: dsyrk: invalid value for uplo\n");
        return;
    }

    // Cleanup heap memory if used
    if (mem != nullptr) {
        free(mem);
    }
}

void blas_dsyrk(char *uplo, char *ta, int *m, int *k, double *alpha, double *A, int *lda, double *beta, double *C, int *ldc)
{
    blasfeo_dsyrk3(*uplo, *ta, *m, *k, *alpha, A, *lda, *beta, C, *ldc, C, *ldc);
}

