#include <gtest/gtest.h>
#include "chromaprint3d/vec3.h"
using namespace ChromaPrint3D;

// Test default construction of Vec3i initializes components to zero
TEST(Vec3i, DefaultConstruction) {
    Vec3i v;
    EXPECT_EQ(v.x, 0);
    EXPECT_EQ(v.y, 0);
    EXPECT_EQ(v.z, 0);
}

// Test vector addition component-wise
TEST(Vec3i, Addition) {
    Vec3i p(1, 2, 3), q(4, 5, 6);
    Vec3i r = p + q;
    EXPECT_EQ(r.x, 5);
    EXPECT_EQ(r.y, 7);
    EXPECT_EQ(r.z, 9);
}

// Test vector subtraction component-wise
TEST(Vec3i, Subtraction) {
    Vec3i base(10, 20, 30), offset(3, 5, 7);
    Vec3i diff = base - offset;
    EXPECT_EQ(diff.x, 7);
    EXPECT_EQ(diff.y, 15);
    EXPECT_EQ(diff.z, 23);
}

// Test scalar multiplication (both left and right)
TEST(Vec3i, ScalarMultiply) {
    Vec3i vec(2, 3, 4);
    Vec3i resRight = vec * 3;
    EXPECT_EQ(resRight.x, 6);
    EXPECT_EQ(resRight.y, 9);
    EXPECT_EQ(resRight.z, 12);

    Vec3i resLeft = 3 * vec;
    EXPECT_EQ(resLeft.x, 6);
    EXPECT_EQ(resLeft.y, 9);
    EXPECT_EQ(resLeft.z, 12);
}

// Test dot product computation
TEST(Vec3i, DotProduct) {
    Vec3i u(1, 0, 0), v(0, 1, 0);
    EXPECT_EQ(u.Dot(v), 0);

    Vec3i w(1, 2, 3);
    EXPECT_EQ(w.Dot(w), 1*1 + 2*2 + 3*3); // 14
}

// Test array-style indexing and member access
TEST(Vec3i, Indexing) {
    Vec3i pt(10, 20, 30);
    EXPECT_EQ(pt[0], 10);
    EXPECT_EQ(pt[1], 20);
    EXPECT_EQ(pt[2], 30);

    pt[1] = 99;
    EXPECT_EQ(pt.y, 99);
}

// Test default construction of Vec3f initializes components to zero
TEST(Vec3f, DefaultConstruction) {
    Vec3f v;
    EXPECT_FLOAT_EQ(v.x, 0.0f);
    EXPECT_FLOAT_EQ(v.y, 0.0f);
    EXPECT_FLOAT_EQ(v.z, 0.0f);
}

// Test length calculation and normalization
TEST(Vec3f, LengthAndNormalize) {
    Vec3f vec(3.0f, 4.0f, 0.0f);
    EXPECT_FLOAT_EQ(vec.Length(), 5.0f);

    Vec3f norm = vec.Normalized();
    EXPECT_NEAR(norm.Length(), 1.0f, 1e-6f);
}

// Test linear interpolation between two vectors
TEST(Vec3f, Lerp) {
    Vec3f start(0.0f, 0.0f, 0.0f), end(10.0f, 10.0f, 10.0f);
    Vec3f mid = Vec3f::Lerp(start, end, 0.5f);
    EXPECT_NEAR(mid.x, 5.0f, 1e-6f);
    EXPECT_NEAR(mid.y, 5.0f, 1e-6f);
    EXPECT_NEAR(mid.z, 5.0f, 1e-6f);
}

// Test clamping values to [0, 1] range
TEST(Vec3f, Clamp01) {
    Vec3f input(-0.5f, 0.5f, 1.5f);
    Vec3f clamped = Vec3f::Clamp01(input);
    EXPECT_FLOAT_EQ(clamped.x, 0.0f);
    EXPECT_FLOAT_EQ(clamped.y, 0.5f);
    EXPECT_FLOAT_EQ(clamped.z, 1.0f);
}

// Test approximate equality comparison with epsilon
TEST(Vec3f, NearlyEqual) {
    Vec3f a(1.0f, 2.0f, 3.0f);
    Vec3f b(1.0f + 1e-7f, 2.0f, 3.0f);
    EXPECT_TRUE(a.NearlyEqual(b));

    Vec3f c(1.1f, 2.0f, 3.0f);
    EXPECT_FALSE(a.NearlyEqual(c));
}

// Test Euclidean distance between two points
TEST(Vec3f, Distance) {
    Vec3f p1(0.0f, 0.0f, 0.0f), p2(1.0f, 0.0f, 0.0f);
    EXPECT_FLOAT_EQ(Vec3f::Distance(p1, p2), 1.0f);
}

// Test compound assignment operators
TEST(Vec3f, CompoundAssignment) {
    Vec3f v(1.0f, 2.0f, 3.0f);
    v += Vec3f(1.0f, 1.0f, 1.0f);
    EXPECT_FLOAT_EQ(v.x, 2.0f);
    EXPECT_FLOAT_EQ(v.y, 3.0f);
    EXPECT_FLOAT_EQ(v.z, 4.0f);

    v *= 2.0f;
    EXPECT_FLOAT_EQ(v.x, 4.0f);
    EXPECT_FLOAT_EQ(v.y, 6.0f);
    EXPECT_FLOAT_EQ(v.z, 8.0f);
}

