#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
#include "jemalloc/internal/prof_stats.h"

bool opt_prof_stats = false;
malloc_mutex_t prof_stats_mtx;

static prof_stats_t live_stats[PROF_SC_NSIZES];
static prof_stats_t accum_stats[PROF_SC_NSIZES];

static void
enter_prof_stats(tsd_t *tsd, szind_t bin) {
	assert(opt_prof && opt_prof_stats);
	assert(bin < SC_NSIZES);
	malloc_mutex_lock(tsd_tsdn(tsd), &prof_stats_mtx);
}

static void
leave_prof_stats(tsd_t *tsd) {
	malloc_mutex_unlock(tsd_tsdn(tsd), &prof_stats_mtx);
}

void
prof_stats_add(tsd_t *tsd, szind_t bin, size_t bytes) {
	cassert(config_prof);
	enter_prof_stats(tsd, bin);
	live_stats[bin].req_sum += bytes;
	live_stats[bin].count++;
	accum_stats[bin].req_sum += bytes;
	accum_stats[bin].count++;
	leave_prof_stats(tsd);
}

void
prof_stats_subtract(tsd_t *tsd, szind_t bin, size_t bytes) {
	cassert(config_prof);
	enter_prof_stats(tsd, bin);
	live_stats[bin].req_sum -= bytes;
	live_stats[bin].count--;
	leave_prof_stats(tsd);
}

void
prof_stats_current(tsd_t *tsd, szind_t bin, prof_stats_t *result) {
	cassert(config_prof);
	enter_prof_stats(tsd, bin);
	memcpy(result, &live_stats[bin], sizeof(prof_stats_t));
	leave_prof_stats(tsd);
}

void
prof_stats_total(tsd_t *tsd, szind_t bin, prof_stats_t *result) {
	cassert(config_prof);
	enter_prof_stats(tsd, bin);
	memcpy(result, &accum_stats[bin], sizeof(prof_stats_t));
	leave_prof_stats(tsd);
}

