#include "datetime.h"
#include <library/cpp/testing/unittest/registar.h>
#include <util/string/builder.h>

Y_UNIT_TEST_SUITE(TSimpleTMTest) {
    // Helper function to generate test marker string
    TString GenerateTestMarker(const TString& testName, int lineNumber) {
        return TStringBuilder() << "test case: " << testName << ", line " << lineNumber;
    }

    // Append timestamp to existing marker
    TString AttachTimestamp(const TString& baseMarker, time_t timestamp) {
        return TStringBuilder() << baseMarker << " [timestamp=" << timestamp << "]";
    }

    // Overload for generating full marker with timestamp
    TString GenerateFullMarker(const TString& testName, int lineNumber, time_t timestamp) {
        return AttachTimestamp(GenerateTestMarker(testName, lineNumber), timestamp);
    }

    // Compare struct tm and TSimpleTM fields
    void ValidateTmFields(const TString& context, const struct tm& reference, const NDatetime::TSimpleTM& target) {
        UNIT_ASSERT_VALUES_EQUAL_C((int)target.Sec, reference.tm_sec, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)target.Min, reference.tm_min, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)target.Hour, reference.tm_hour, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)target.WDay, reference.tm_wday, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)target.MDay, reference.tm_mday, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)target.Mon, reference.tm_mon, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)target.YDay, reference.tm_yday, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)target.Year, reference.tm_year, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)target.IsDst, reference.tm_isdst, context);
#ifndef _win_
        UNIT_ASSERT_VALUES_EQUAL_C((int)target.GMTOff, reference.tm_gmtoff, context);
#endif
    }

    // Comprehensive validation of TSimpleTM against expected values
    void ValidateSimpleTM(const TString& label,
                          const NDatetime::TSimpleTM& instance,
                          time_t expectedTimestamp,
                          ui32 expectedYear,
                          ui32 expectedMonth,
                          ui32 expectedDay,
                          ui32 expectedHour,
                          ui32 expectedMinute,
                          ui32 expectedSecond) {
        TString context = AttachTimestamp(label, expectedTimestamp);
        struct tm referenceTime;
        Zero(referenceTime);
        GmTimeR(&expectedTimestamp, &referenceTime);

        // Validate against UTC struct tm
        ValidateTmFields(context, referenceTime, instance);

        // Round-trip conversion check
        struct tm reconstructed = instance.AsStructTmUTC();
        time_t convertedBack = TimeGM(&reconstructed);
        UNIT_ASSERT_VALUES_EQUAL_C(expectedTimestamp, convertedBack, context);
        UNIT_ASSERT_VALUES_EQUAL_C(expectedTimestamp, instance.AsTimeT(), context);

        // Field value checks
        UNIT_ASSERT_VALUES_EQUAL_C((int)instance.RealYear(), expectedYear, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)instance.RealMonth(), expectedMonth, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)instance.MDay, expectedDay, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)instance.Hour, expectedHour, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)instance.Min, expectedMinute, context);
        UNIT_ASSERT_VALUES_EQUAL_C((int)instance.Sec, expectedSecond, context);
    }

    Y_UNIT_TEST(TestLeapYearLogic) {
        using namespace NDatetime;

        // Known leap years
        UNIT_ASSERT(LeapYearAD(2000));
        UNIT_ASSERT(LeapYearAD(2012));
        UNIT_ASSERT(LeapYearAD(2004));

        // Non-leap years
        UNIT_ASSERT(!LeapYearAD(1999));
        UNIT_ASSERT(!LeapYearAD(1900));
    }

    Y_UNIT_TEST(TestDayOfYearConversion) {
        using namespace NDatetime;

        ui32 month, day;
        // Test non-leap year conversions
        for (ui32 yday = 0; yday < 365; ++yday) {
            YDayToMonthAndDay(yday, false, &month, &day);
            UNIT_ASSERT_VALUES_EQUAL(yday, YDayFromMonthAndDay(month, day, false));
        }

        // Test leap year conversions
        for (ui32 yday = 0; yday < 366; ++yday) {
            YDayToMonthAndDay(yday, true, &month, &day);
            UNIT_ASSERT_VALUES_EQUAL(yday, YDayFromMonthAndDay(month, day, true));
        }

        // Boundary condition tests
        UNIT_ASSERT_EXCEPTION(YDayToMonthAndDay(365, false, &month, &day), yexception);
        UNIT_ASSERT_EXCEPTION(YDayToMonthAndDay(366, true, &month, &day), yexception);
    }

    Y_UNIT_TEST(SimpleTMFunctionality) {
        using namespace NDatetime;
        tzset();

        // Basic construction tests
        TSimpleTM::New(-1); // Should not crash
        UNIT_ASSERT_VALUES_EQUAL((ui32)0, (ui32)TSimpleTM::New(0));
        UNIT_ASSERT((ui32)TSimpleTM::New(0).IsUTC());

        time_t currentTime = time(nullptr);

        // UTC time handling
        {
            struct tm utcTime;
            Zero(utcTime);
            gmtime_r(&currentTime, &utcTime);

            // Verify round-trip conversions
            UNIT_ASSERT_VALUES_EQUAL_C((i64)currentTime, (i64)TSimpleTM::New(currentTime).AsTimeT(), ToString(currentTime));
            UNIT_ASSERT_VALUES_EQUAL_C((i64)currentTime, (i64)TSimpleTM::New(utcTime).AsTimeT(), ToString(currentTime));

            // Field validation
            ValidateTmFields(GenerateFullMarker("UTC_from_time_t", __LINE__, currentTime), utcTime, TSimpleTM::New(currentTime));
            ValidateTmFields(GenerateFullMarker("UTC_from_tm", __LINE__, currentTime), utcTime, TSimpleTM::New(utcTime));

            // UTC flag verification
            UNIT_ASSERT(TSimpleTM::New(currentTime).IsUTC());
            UNIT_ASSERT(TSimpleTM::New(utcTime).IsUTC());
        }

        // Local time handling
        {
            struct tm localTime;
            Zero(localTime);
            localtime_r(&currentTime, &localTime);

            // Verify round-trip conversions
            UNIT_ASSERT_VALUES_EQUAL((i64)currentTime, (i64)TSimpleTM::NewLocal(currentTime).AsTimeT());
            UNIT_ASSERT_VALUES_EQUAL((i64)currentTime, (i64)TSimpleTM::New(localTime).AsTimeT());

            // Field validation
            ValidateTmFields(GenerateFullMarker("local_from_time_t", __LINE__, currentTime), localTime, TSimpleTM::NewLocal(currentTime));
            ValidateTmFields(GenerateFullMarker("local_from_tm", __LINE__, currentTime), localTime, TSimpleTM::New(localTime));
            ValidateTmFields(GenerateFullMarker("local_regenerated", __LINE__, currentTime), localTime, TSimpleTM::New(localTime).RegenerateFields());
            ValidateTmFields(GenerateFullMarker("local_setdate", __LINE__, currentTime), localTime,
                             TSimpleTM::NewLocal(currentTime).SetRealDate(localTime.tm_year + 1900,
                                                                          localTime.tm_mon + 1,
                                                                          localTime.tm_mday,
                                                                          localTime.tm_hour,
                                                                          localTime.tm_min,
                                                                          localTime.tm_sec,
                                                                          localTime.tm_isdst));
        }

        // Date arithmetic tests
        {
            TSimpleTM dateObj = TSimpleTM::New(0);

            // Set initial date and validate
            dateObj.SetRealDate(2012, 3, 30, 5, 6, 7);
            ValidateSimpleTM(GenerateFullMarker("UTC_SetInitial", __LINE__), dateObj, 1333083967, 2012, 3, 30, 5, 6, 7);

            // Modify and validate subsequent dates
            dateObj.SetRealDate(2012, 3, 8, 5, 6, 7);
            ValidateSimpleTM(GenerateFullMarker("UTC_SetMarch8", __LINE__), dateObj, 1331183167, 2012, 3, 8, 5, 6, 7);

            dateObj.SetRealDate(2010, 10, 4, 5, 6, 7);
            ValidateSimpleTM(GenerateFullMarker("UTC_SetOct2010", __LINE__), dateObj, 1286168767, 2010, 10, 4, 5, 6, 7);

            // Month addition
            dateObj.Add(TSimpleTM::F_MON);
            ValidateSimpleTM(GenerateFullMarker("UTC_AddMonth", __LINE__), dateObj, 1288847167, 2010, 11, 4, 5, 6, 7);

            // Day addition
            dateObj.Add(TSimpleTM::F_DAY);
            ValidateSimpleTM(GenerateFullMarker("UTC_AddDay", __LINE__), dateObj, 1288933567, 2010, 11, 5, 5, 6, 7);

            // Year addition
            dateObj.Add(TSimpleTM::F_YEAR);
            ValidateSimpleTM(GenerateFullMarker("UTC_AddYear", __LINE__), dateObj, 1320469567, 2011, 11, 5, 5, 6, 7);

            // Add 365 days
            for (ui32 i = 0; i < 365; ++i) {
                dateObj.Add(TSimpleTM::F_DAY);
            }
            ValidateSimpleTM(GenerateFullMarker("UTC_365Days", __LINE__), dateObj, 1352005567, 2012, 11, 4, 5, 6, 7);

            // Negative month adjustment
            dateObj.Add(TSimpleTM::F_MON, -10);
            ValidateSimpleTM(GenerateFullMarker("UTC_SubtractMonths", __LINE__), dateObj, 1325653567, 2012, 1, 4, 5, 6, 7);

            // Negative hour adjustment
            dateObj.Add(TSimpleTM::F_HOUR, -24 * 4 - 6);
            ValidateSimpleTM(GenerateFullMarker("UTC_SubtractHours", __LINE__), dateObj, 1325286367, 2011, 12, 30, 23, 6, 7);
        }

        // Multiple date setting tests
        {
            TSimpleTM dateObj = TSimpleTM::New();

            // Various dates including leap year
            dateObj.SetRealDate(2012, 2, 29);
            ValidateSimpleTM(GenerateFullMarker("UTC_LeapDay", __LINE__), dateObj, 1330473600, 2012, 2, 29, 0, 0, 0);

            dateObj.SetRealDate(2013, 12, 28);
            ValidateSimpleTM(GenerateFullMarker("UTC_Dec2013", __LINE__), dateObj, 1388188800, 2013, 12, 28, 0, 0, 0);

            dateObj.SetRealDate(2012, 10, 23);
            ValidateSimpleTM(GenerateFullMarker("UTC_Oct2012", __LINE__), dateObj, 1350950400, 2012, 10, 23, 0, 0, 0);

            dateObj.SetRealDate(2013, 3, 16);
            ValidateSimpleTM(GenerateFullMarker("UTC_Mar2013", __LINE__), dateObj, 1363392000, 2013, 3, 16, 0, 0, 0);

            dateObj.SetRealDate(2013, 2, 17);
            ValidateSimpleTM(GenerateFullMarker("UTC_Feb2013", __LINE__), dateObj, 1361059200, 2013, 2, 17, 0, 0, 0);

            dateObj.SetRealDate(2012, 12, 23);
            ValidateSimpleTM(GenerateFullMarker("UTC_Dec2012", __LINE__), dateObj, 1356220800, 2012, 12, 23, 0, 0, 0);

            dateObj.SetRealDate(2012, 5, 17);
            ValidateSimpleTM(GenerateFullMarker("UTC_May2012", __LINE__), dateObj, 1337212800, 2012, 5, 17, 0, 0, 0);

            dateObj.SetRealDate(2012, 6, 15);
            ValidateSimpleTM(GenerateFullMarker("UTC_Jun2012", __LINE__), dateObj, 1339718400, 2012, 6, 15, 0, 0, 0);

            dateObj.SetRealDate(2009, 3, 17);
            ValidateSimpleTM(GenerateFullMarker("UTC_Mar2009", __LINE__), dateObj, 1237248000, 2009, 3, 17, 0, 0, 0);

            dateObj.SetRealDate(2013, 8, 12);
            ValidateSimpleTM(GenerateFullMarker("UTC_Aug2013", __LINE__), dateObj, 1376265600, 2013, 8, 12, 0, 0, 0);

            // With time components
            dateObj.SetRealDate(2015, 12, 11, 10, 9, 8);
            ValidateSimpleTM(GenerateFullMarker("UTC_DetailedTime", __LINE__), dateObj, 1449828548, 2015, 12, 11, 10, 9, 8);
        }
    }
