extern "C" {
// On Windows, linking against the static library means LBUG_STATIC_DEFINE is implicitly set,
// preventing symbol export via LBUG_API; thus, we explicitly define our own export macro.
#if defined(_WIN32)
#define EXPORT_SYMBOL __declspec(dllexport)
#else
#define EXPORT_SYMBOL __attribute__((visibility("default")))
#endif

EXPORT_SYMBOL void install(const std::string& repository, lbug::main::ClientContext& context) {
    // Prepare extension installation parameters
    lbug::extension::InstallExtensionInfo params{
        "iceberg", 
        repository, 
        false  // do not force re-installation if already present
    };

    // Instantiate and invoke the installer
    lbug::duckdb_extension::DuckDBInstaller installer{params, context};
    installer.install();
}
}

