int main(int argc, char *argv[]) {
    std::string input_file  = "parameters.xml";
    std::string output_file = "tiered_parameters.xml";

    // Parse the input XML file into a parameter list
    auto parsed_list = ROL::getParametersFromXmlFile(input_file);

    // Create an empty output parameter list
    ROL::ParameterList result_list;

    // Apply tiered parameter processing
    ROL::tierParameterList(result_list, *parsed_list);

    // Write the processed list to the output XML file
    ROL::writeParameterListToXmlFile(result_list, output_file);

    return 0;
}

