  single_heap_.malloc(&result, req_size);
  EXPECT_EQ(result, nullptr);
  EXPECT_EQ(single_heap_.get_used(), before_used);
  single_heap_.free(result);
  EXPECT_EQ(single_heap_.get_used(), before_used);
}

