#include <cstdint>
#include <cstdio>
#include "ckernel.h"
#include "llk_defs.h"

// Global state variables for kernel execution context
std::uint32_t unpack_config_context     = 0;
std::uint32_t pack_sync_dst_ptr         = 0;
std::uint32_t math_sync_dst_tile_idx    = 0;

#ifdef LLK_TRISC_UNPACK
#include "llk_unpack_AB.h"
#include "llk_unpack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Configure unpacker hardware with source/destination formats and face dimensions
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        fmts.unpack_A_src,
        fmts.unpack_B_src,
        fmts.unpack_A_dst,
        fmts.unpack_B_dst,
        FACE_R_DIM,
        FACE_R_DIM,
        4 /* number of faces per tile */,
        4 /* number of faces per tile */);

    // Initialize unpacker state machine
    _llk_unpack_AB_init_<>();

    // Process each input tile pair
    for (int tile_index = 0; tile_index < params->TILE_CNT; ++tile_index)
    {
        _llk_unpack_AB_<>(L1_ADDRESS(params->buffer_A[tile_index]), L1_ADDRESS(params->buffer_B[tile_index]));
    }
}
#endif

#ifdef LLK_TRISC_MATH
#include "llk_math_common.h"
#include "llk_math_eltwise_binary.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Setup synchronization and configuration for math operations
    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(fmts.math, fmts.math);
    _llk_math_eltwise_binary_init_<ELTWISE_BINARY_OP, BroadcastType::NONE, MATH_FIDELITY>(4, 0);

    // Wait until destination buffer has space for at least one tile
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Iterate over all tiles to perform binary element-wise operation
    for (int tile_id = 0; tile_id < params->TILE_CNT; ++tile_id)
    {
        // Safety check: ensure we don't exceed destination capacity
        LLK_ASSERT(
            tile_id < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");

        _llk_math_eltwise_binary_<
            ELTWISE_BINARY_OP,
            BroadcastType::NONE,
            DstSync::SyncHalf,
            is_fp32_dest_acc_en,
            MATH_FIDELITY,
            EltwiseBinaryReuseDestType::NONE>(4, tile_id, false);
    }

    // Signal completion of current destination section
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Hardware configuration differs slightly on Blackhole architecture
#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(fmts.pack_src, fmts.pack_dst, 16 * 16 * 4);
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(fmts.pack_src, fmts.pack_dst, 16 * 16 * 4);
#endif

    // Initialize packer module
    _llk_pack_init_<false, false>(fmts.pack_dst);

#ifdef ARCH_BLACKHOLE
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>();
#endif

    // Ensure math unit has finished writing results before packing starts
    _llk_packer_wait_for_math_done_();

    // Pack output tiles into L1 memory
    for (int out_tile = 0; out_tile < params->TILE_CNT; ++out_tile)
    {
        LLK_ASSERT(
            out_tile < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");

        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(out_tile, L1_ADDRESS(params->buffer_Res[out_tile]));
    }

    // Mark end of destination section
    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

