#include <stdexcept>
#include <stream.h>
#include <string>
#include <variant>

std::shared_ptr<Stream::stream<std::shared_ptr<Nat>>>
Stream::nats_from(std::shared_ptr<Nat> n) {
    // Create a lambda that captures the current number by value
    auto generator = [current = n](void) mutable -> std::shared_ptr<Stream::stream<std::shared_ptr<Nat>>> {
        // Store the current value for this step
        auto current_value = current;
        // Advance to the next natural number for subsequent calls
        current = Nat::ctor::S_(current);
        // Construct the stream node with current value and recursive call
        return stream<std::shared_ptr<Nat>>::ctor::scons_(
            current_value,
            stream<std::shared_ptr<Nat>>::ctor::lazy_(
                [generator]() mutable -> std::shared_ptr<Stream::stream<std::shared_ptr<Nat>>> {
                    return generator();
                }
            )
        );
    };

    // Return a lazy stream constructed from the generator
    return stream<std::shared_ptr<Nat>>::ctor::lazy_(generator);
}

