    // Helper function to determine if a PathStatusReceivedEvent is successful
    inline bool IsPathSuccess(const llarp::LR_StatusRecord::Status status)
    {
        return status == llarp::LR_StatusRecord::SUCCESS;
    }

    void RouterEvent_Init(py::module& module)
    {
        py::class_<RouterEvent>(module, "RouterEvent")
            .def("__repr__", &RouterEvent::ToString)
            .def("__str__", &RouterEvent::ToString)
            .def_readonly("routerID", &RouterEvent::routerID)
            .def_readonly("triggered", &RouterEvent::triggered);

        py::class_<PathAttemptEvent, RouterEvent>(module, "PathAttemptEvent")
            .def_readonly("hops", &PathAttemptEvent::hops);

        py::class_<PathRequestReceivedEvent, RouterEvent>(module, "PathRequestReceivedEvent")
            .def_readonly("prevHop", &PathRequestReceivedEvent::prevHop)
            .def_readonly("nextHop", &PathRequestReceivedEvent::nextHop)
            .def_readonly("txid", &PathRequestReceivedEvent::txid)
            .def_readonly("rxid", &PathRequestReceivedEvent::rxid)
            .def_readonly("isEndpoint", &PathRequestReceivedEvent::isEndpoint);

        py::class_<PathStatusReceivedEvent, RouterEvent>(module, "PathStatusReceivedEvent")
            .def_readonly("rxid", &PathStatusReceivedEvent::rxid)
            .def_readonly("status", &PathStatusReceivedEvent::status)
            .def_property_readonly("Successful", [](const PathStatusReceivedEvent* eventPtr) {
                return IsPathSuccess(eventPtr->status);
