using namespace lbug::common;

// Helper to check if expected exception is thrown and message matches
void expectConversionException(const std::function<void()>& func, const char* expectedMsg) {
    try {
        func();
        FAIL() << "Expected ConversionException but none was thrown.";
    } catch (const ConversionException& e) {
        ASSERT_STREQ(e.what(), expectedMsg);
    } catch (const std::exception&) {
        FAIL() << "Unexpected exception type thrown.";
    }
}

TEST(TimestampTests, FromDatetime) {
    // Day out of range: December 42 is invalid
    expectConversionException(
        []() { Timestamp::fromDateTime(Date::fromDate(1968, 12, 42), Time::fromTime(21, 32, 51)); },
        "Conversion exception: Date out of range: 1968-12-42.");

    // February 29 in non-leap year 2021
    expectConversionException(
        []() { Timestamp::fromDateTime(Date::fromDate(2021, 2, 29), Time::fromTime(21, 32, 51)); },
        "Conversion exception: Date out of range: 2021-2-29.");

    // Hour out of range: 25 hours
    expectConversionException(
        []() { Timestamp::fromDateTime(Date::fromDate(1968, 12, 22), Time::fromTime(25, 32, 51)); },
        "Conversion exception: Time field value out of range: 25:32:51[.0].");

    // Seconds out of range: 70 seconds
    expectConversionException(
        []() { Timestamp::fromDateTime(Date::fromDate(2021, 2, 28), Time::fromTime(5, 52, 70)); },
        "Conversion exception: Time field value out of range: 5:52:70[.0].");

    // Microseconds out of range: > 999999
    expectConversionException(
        []() {
            Timestamp::fromDateTime(Date::fromDate(2021, 2, 28),
                Time::fromTime(5, 52, 42, 1000002));
        },
        "Conversion exception: Time field value out of range: 5:52:42[.1000002].");

    // Valid timestamps
    EXPECT_EQ(
        Timestamp::fromDateTime(Date::fromDate(2020, 10, 22), Time::fromTime(21, 32, 51)).value,
        1603402371000000);

    EXPECT_EQ(
        Timestamp::fromDateTime(Date::fromDate(1978, 5, 22), Time::fromTime(0, 54, 32, 7891)).value,
        264646472007891);
}

TEST(TimestampTests, Convert) {
    date_t dt_out;
    dtime_t tm_out;

    // Test conversion of timestamp 1603402371000000 → 2020-10-22 21:32:51
    Timestamp::convert(timestamp_t(1603402371000000), dt_out, tm_out);
    EXPECT_EQ(dt_out.days, 18557);
    EXPECT_EQ(tm_out.micros, 77571000000);

    // Test conversion of timestamp 4501210883005612 → 2112-08-21 08:21:23.005612
    Timestamp::convert(timestamp_t(4501210883005612), dt_out, tm_out);
    EXPECT_EQ(dt_out.days, 52097);
    EXPECT_EQ(tm_out.micros, 30083005612);
}

TEST(TimestampTests, FromCString) {
    EXPECT_EQ(
        Timestamp::fromCString("2112-08-21 08:21:23.005612", strlen("2112-08-21 08:21:23.005612")).value,
        4501210883005612);

    EXPECT_EQ(
        Timestamp::fromCString("1992-04-28T09:22:56", strlen("1992-04-28T09:22:56")).value,
        704452976000000);

    EXPECT_EQ(
        Timestamp::fromCString("2023-08-12", strlen("2023-08-12")).value,
        1691798400000000);

    // With timezone 'Z'
    EXPECT_EQ(
        Timestamp::fromCString("2112-08-21 08:21:23.005612Z", strlen("2112-08-21 08:21:23.005612Z")).value,
        4501210883005612);

    // With explicit +00:00 offset
    EXPECT_EQ(
        Timestamp::fromCString("2112-08-21 08:21:23.005612Z+00:00",
            strlen("2112-08-21 08:21:23.005612Z+00:00")).value,
        4501210883005612);

    // With +02:00 offset (should subtract 2 hours)
    EXPECT_EQ(
        Timestamp::fromCString("2112-08-21 08:21:23.005612Z+02:00",
            strlen("2112-08-21 08:21:23.005612Z+02:00")).value,
        4501203683005612);

    // With -09:00 offset
    EXPECT_EQ(
        Timestamp::fromCString("1992-04-28T09:22:56-09:00", strlen("1992-04-28T09:22:56-09:00")).value,
        704485376000000);

    // Shortened timezone format (-09 instead of -09:00)
    EXPECT_EQ(
        Timestamp::fromCString("1992-04-28T09:22:56-09", strlen("1992-04-28T09:22:56-09")).value,
        704485376000000);

    // Trailing whitespace should be ignored
    EXPECT_EQ(
        Timestamp::fromCString("1992-04-28T09:22:56-09:00   ",
            strlen("1992-04-28T09:22:56-09:00   ")).value,
        704485376000000);

    // With -06:30 offset
    EXPECT_EQ(
