#include "cam_moe_combine_normal.h"
#include "cam_moe_combine_normal_multi_round.h"
#include "cam_moe_combine_normal_tiling.h"

using namespace AscendC;

// Alternative tiling identifiers to avoid hard-coded duplication
constexpr uint32_t MULTI_ROUND_MODE = 20001;
constexpr uint32_t SINGLE_ROUND_MODE = 20000;

extern "C" __global__ __aicore__ void cam_moe_combine_normal(
    GM_ADDR recvX,
    GM_ADDR tokenSrcInfo,
    GM_ADDR epRecvCount,
    GM_ADDR topkWeights,
    GM_ADDR tokenIdx,
    GM_ADDR tpRecvCount,
    GM_ADDR XOut,
    GM_ADDR sendCostStatsOut,
    GM_ADDR workspaceGM,
    GM_ADDR tilingGM)
{
    // Register default tiling structure
    REGISTER_TILING_DEFAULT(CamMoeCombineNormalTilingData);

    TPipe pipe;

#if (ORIG_DTYPE_RECV_X == DT_BF16 || ORIG_DTYPE_RECV_X == DT_FLOAT16)
    CamMoeCombineNormalTilingData tilingConfig;
    GET_TILING_DATA_WITH_STRUCT(CamMoeCombineNormalTilingData, tilingConfig, tilingGM);

    const uint32_t modeFlag = GetTilingKey();

    if (modeFlag != MULTI_ROUND_MODE && modeFlag != SINGLE_ROUND_MODE) {
        return; // Unsupported mode — early exit
    }

    if (modeFlag == MULTI_ROUND_MODE) {
        CamMoeCombineNormalMultiRoundImpl::CamMoeCombineNormalMultiRound<DTYPE_RECV_X, DTYPE_X, int32_t> operation;
        operation.Init(recvX, tokenSrcInfo, epRecvCount, topkWeights, tokenIdx, tpRecvCount, XOut, sendCostStatsOut,
                       workspaceGM, &pipe, &tilingConfig);
        operation.Run();
    } else { // must be SINGLE_ROUND_MODE
        CamMoeCombineNormalImpl::CamMoeCombineNormal<DTYPE_RECV_X, DTYPE_X, int32_t> operation;
        operation.Init(recvX, tokenSrcInfo, epRecvCount, topkWeights, tokenIdx, tpRecvCount, XOut, sendCostStatsOut,
                       workspaceGM, &pipe, &tilingConfig);
        operation.Run();
    }
#endif
}

