#include <library/cpp/testing/unittest/registar.h>
#include "spinlock.h"

Y_UNIT_TEST_SUITE(TSpinLockTests) {
    template <typename TLockType>
    void ValidateLockBehavior() {
        TLockType mutex;

        // Initial state check
        UNIT_ASSERT(!mutex.IsLocked());

        // Acquire and verify locked state
        mutex.Acquire();
        UNIT_ASSERT(mutex.IsLocked());

        // Release and verify unlocked state
        mutex.Release();
        UNIT_ASSERT(!mutex.IsLocked());

        // TryAcquire test sequence
        UNIT_ASSERT(mutex.TryAcquire());
        UNIT_ASSERT(mutex.IsLocked());

        // Second try should fail while locked
        UNIT_ASSERT(!mutex.TryAcquire());
        UNIT_ASSERT(mutex.IsLocked());

        // Release after try-acquire
        mutex.Release();
        UNIT_ASSERT(!mutex.IsLocked());

        // Standard lockable interface compliance
        mutex.lock();
        UNIT_ASSERT(mutex.IsLocked());

        // try_lock should fail when already locked
        UNIT_ASSERT(!mutex.try_lock());

        mutex.unlock();
        UNIT_ASSERT(!mutex.IsLocked());
    }

    Y_UNIT_TEST(TSpinLock_Functionality) {
        ValidateLockBehavior<TSpinLock>();
    }

    Y_UNIT_TEST(TAdaptiveLock_Functionality) {
        ValidateLockBehavior<TAdaptiveLock>();
    }
} // Y_UNIT_TEST_SUITE(TSpinLockTests)

