TEST_CASE("enum/read-only-iteration", "verify iteration over read-only tables functions correctly") {
    sol::state lua;
    lua.open_libraries(sol::lib::base);

#define ENUM_VALUES() "FIRST", 1, "SECOND", 2, "THIRD", 3, "NOT-FOURTH", 5
    lua.create_named_table("Check", ENUM_VALUES());
    lua.new_enum("Enum", ENUM_VALUES());
#undef ENUM_VALUES

    SECTION("without global next function available") {
        sol::optional<sol::error> maybe_error = lua.safe_script(
            "for k, v in pairs(Enum) do assert(Check[k] == v) end", 
            sol::script_pass_on_error
        );
        REQUIRE_FALSE(maybe_error.has_value());
    }

    SECTION("with global next function enabled") {
        lua.open_libraries(sol::lib::table);
        sol::optional<sol::error> maybe_error = lua.safe_script(
            "for k, v in pairs(Enum) do assert(Check[k] == v) end", 
            sol::script_pass_on_error
        );
        REQUIRE_FALSE(maybe_error.has_value());
    }
}

