    TEST(archive_pathmatch_sim("abc[\\d-f]gh", "abcggh", 0) == 0);
    TEST(archive_pathmatch_sim("abc[\\d-f]gh", "abc\\gh", 0) == 0);
    TEST(archive_pathmatch_sim("abc[d-\\f]gh", "abcegh", 0) == 1);
    TEST(archive_pathmatch_sim("abc[\\d-\\f]gh", "abcegh", 0) == 1);

    // Backslash-quoted hyphen
    TEST(archive_pathmatch_sim("abc[d\\-f]gh", "abcegh", 0) == 0);
    TEST(archive_pathmatch_sim("abc[d\\-f]gh", "abc-gh", 0) == 1);

    // Negated character classes
    TEST(archive_pathmatch_sim("abc[!d]", "abcd", 0) == 0);
    TEST(archive_pathmatch_sim("abc[!d]", "abce", 0) == 1);
    TEST(archive_pathmatch_sim("abc[!d]", "abcc", 0) == 1);
    TEST(archive_pathmatch_sim("abc[!d-z]", "abcq", 0) == 0);
    TEST(archive_pathmatch_sim("abc[!d-gi-z]", "abch", 0) == 1);
    TEST(archive_pathmatch_sim("abc[!fgijkl]", "abch", 0) == 1);
    TEST(archive_pathmatch_sim("abc[!fghijkl]", "abch", 0) == 0);

    // Backslash quoting
    TEST(archive_pathmatch_sim("abc\\[def]", "abc\\d", 0) == 0);
    TEST(archive_pathmatch_sim("abc\\[def]", "abc[def]", 0) == 1);
    TEST(archive_pathmatch_sim("abc\\\\[def]", "abc[def]", 0) == 0);
    TEST(archive_pathmatch_sim("abc\\\\[def]", "abc\\[def]", 0) == 0);
    TEST(archive_pathmatch_sim("abc\\\\[def]", "abc\\d", 0) == 1);
    TEST(archive_pathmatch_sim("abcd\\", "abcd\\", 0) == 1);
    TEST(archive_pathmatch_sim("abcd\\", "abcd\\[", 0) == 0);
    TEST(archive_pathmatch_sim("abcd\\", "abcde", 0) == 0);
    TEST(archive_pathmatch_sim("abcd\\[", "abcd\\", 0) == 0);

    // Path normalization tests
    TEST(archive_pathmatch_sim("a/b/", "a/bc", 0) == 0);
    TEST(archive_pathmatch_sim("a/./b", "a/b", 0) == 1);
    TEST(archive_pathmatch_sim("a\\/./b", "a/b", 0) == 0);
