    TEST(archive_pathmatch_sim("./abc/./def", "abc/def/", 0) == 1);
    TEST(archive_pathmatch_sim("./abc/./def", "abc/def/./", 0) == 1);
    TEST(archive_pathmatch_sim("./abc*/./def", "abc/def/.", 0) == 1);

    // Non-anchored match tests
    TEST(archive_pathmatch_sim("bcd", "abcd", PATHMATCH_NO_ANCHOR_START) == 0);
    TEST(archive_pathmatch_sim("abcd", "abcd", PATHMATCH_NO_ANCHOR_START) == 1);
    TEST(archive_pathmatch_sim("^bcd", "abcd", PATHMATCH_NO_ANCHOR_START) == 0);
    TEST(archive_pathmatch_sim("b/c/d", "a/b/c/d", PATHMATCH_NO_ANCHOR_START) == 1);
