    TEST(archive_pathmatch_sim("b/c/d", "/a/b/c/d", PATHMATCH_NO_ANCHOR_START) == 1);

    // No anchor at end
    TEST(archive_pathmatch_sim("bcd", "abcd", PATHMATCH_NO_ANCHOR_END) == 0);
