                     .SetExtendCfgInfo("jitCompile.flag", "static_true")
                     .SetExtendCfgInfo("multiKernelSupportDynamicGraph.value", "multi_kernel");

        OpAICoreConfig config_910b;
        config_910b.SetDynamicCompileStaticFlag(true)
                    .SetDynamicFormatFlag(true)
                    .SetDynamicRankSupportFlag(true)
                    .SetDynamicShapeSupportFlag(true)
                    .SetNeedCheckSupportFlag(false)
