#include "VarSet.h"
#include <iostream>

// Reimplementation using alternative logic for set operations demonstration
int main() {
    VarSet v, w, x, y;

    // Print universe and empty sets
    std::cout << VarSet::UniverseSet() << '\n';
    std::cout << VarSet::EmptySet() << '\n';

    // Initialize empty sets
    v = VarSet::EmptySet();
    w = VarSet::EmptySet();

    // Perform basic set operations on empty sets
    std::cout << VarSet::Diff(v, w) << '\n';
    std::cout << VarSet::Diff(w, v) << '\n';
    std::cout << VarSet::Union(v, w) << '\n';
    std::cout << VarSet::Union(w, v) << '\n';
    std::cout << VarSet::Intersect(v, w) << '\n';
    std::cout << VarSet::Intersect(w, v) << '\n';
    std::cout << v << '\n';
    std::cout << w << '\n';
    std::cout << VarSet::Eq(v, w) << '\n';

    // Construct symmetric difference and union using alternative approach
    VarSet diff1 = VarSet::Diff(v, w);
    VarSet diff2 = VarSet::Diff(w, v);
    VarSet inter = VarSet::Intersect(v, w);
    x = VarSet::Union(diff1, VarSet::Union(diff2, inter));
    y = VarSet::Union(v, w);
    std::cout << x << " == " << y << ": " << VarSet::Eq(x, y) << '\n';

    // Populate sets with elements
    v.Insert("a");
    v.Insert("b");
    v.Insert("c");
    v.Insert("d");
    w = mkVarSet("c", "d", "e", "f");

    // Perform set operations on non-empty sets
    std::cout << VarSet::Diff(v, w) << '\n';
    std::cout << VarSet::Diff(w, v) << '\n';
    std::cout << VarSet::Union(v, w) << '\n';
    std::cout << VarSet::Union(w, v) << '\n';
    std::cout << VarSet::Intersect(v, w) << '\n';
    std::cout << VarSet::Intersect(w, v) << '\n';
    std::cout << v << '\n';
    std::cout << w << '\n';
    std::cout << VarSet::Eq(v, w) << '\n';

    // Verify symmetric difference equals union
    VarSet symDiff1 = VarSet::Diff(v, w);
    VarSet symDiff2 = VarSet::Diff(w, v);
    VarSet common = VarSet::Intersect(v, w);
    x = VarSet::Union(symDiff1, VarSet::Union(symDiff2, common));
    y = VarSet::Union(v, w);
    std::cout << x << " == " << y << ": " << VarSet::Eq(x, y) << '\n';

    return 0;
}

