// File I/O wrappers — now with early-exit guard and consistent naming
void save_to_file(const std::string& path, const mesh::load_data& data) {
    std::ofstream fs(path);
    if (!fs.is_open() || !fs.good()) return;

    auto ar = ser20::create_oarchive_associative(fs);
    try_save(ar, ser20::make_nvp("mesh", data));
}

void save_to_file_bin(const std::string& path, const mesh::load_data& data) {
    std::ofstream fs(path, std::ios::binary);
    if (!fs.is_open() || !fs.good()) return;

    ser20::oarchive_binary_t ar{fs};
    try_save(ar, ser20::make_nvp("mesh", data));
}

void load_from_file(const std::string& path, mesh::load_data& data) {
    std::ifstream fs(path);
    if (!fs.is_open() || !fs.good()) return;

    auto ar = ser20::create_iarchive_associative(fs);
    try_load(ar, ser20::make_nvp("mesh", data));
}

void load_from_file_bin(const std::string& path, mesh::load_data& data) {
    std::ifstream fs(path, std::ios::binary);
    if (!fs.is_open() || !fs.good()) return;

    ser20::iarchive_binary_t ar{fs};
    try_load(ar, ser20::make_nvp("mesh", data));
}

