    expectEq$(Io::atoi("+100"s), 100);
    expectEq$(Io::atoi("-1"s), -1);
    expectEq$(Io::atoi("-10"s), -10);
    expectEq$(Io::atoi("-100"s), -100);
    expectEq$(Io::atoi("+"s), NONE);
