#include "test.h"
// Unit tests for the Text and Utf16 string classes in apLib
TEST_CASE("string::Str") {
    SECTION("Text") {
        SECTION("Implicit conversion") {
            Text sample = "sample";
            REQUIRE(!Txtcmp(sample, "sample"));
            REQUIRE(static_cast<bool>(sample));
        }
        SECTION("Move assignment") {
            Text original = "Hello";
            Text assigned;
            assigned = std::move(original);
            REQUIRE(assigned == "Hello");
            REQUIRE(original.empty());
            Text reassigned;
            reassigned = std::move(assigned);
            REQUIRE(assigned.empty());
            REQUIRE(reassigned == "Hello");
        }
        SECTION("Move construction") {
            Text source("World");
            Text target(std::move(source));
            REQUIRE(target == "World");
            REQUIRE(source.empty());
            Text another(std::move(target));
            REQUIRE(target.empty());
            REQUIRE(another == "World");
        }
        SECTION("Relational operators") {
            Text t1("hello"), t2("hello"), t3("hello!");
            REQUIRE(t1 < t3);
            REQUIRE(t3 > t1);
            REQUIRE_FALSE(t1 > t2);
            REQUIRE_FALSE(t1 < t2);
        }
        SECTION("Case conversion") {
            REQUIRE(Text("STOP SHOUTING").lowerCase() == "stop shouting");
            REQUIRE(Text("i am whispering").upperCase() == "I AM WHISPERING");
        }
        SECTION("Whitespace handling") {
            REQUIRE(Text("   trim me   ").trim() == "trim me");
        }
        SECTION("Quote removal") {
            REQUIRE(Text("\"quoted\"").removeQuotes() == "quoted");
        }
        SECTION("Splitting") {
            auto parts = Text(",a,b,c,").split(',');
            REQUIRE(parts == std::vector<Text>{"a", "b", "c"});
            parts = Text(",a,b,c,").split(',', true);
            REQUIRE(parts == std::vector<Text>{"", "a", "b", "c", ""});
        }
        SECTION("Joining") {
            REQUIRE(join(std::vector<Text>{"1","2","3"}, ",") == "1,2,3");
            REQUIRE(join(std::vector<Text>{"1","2","3"}, "") == "123");
            REQUIRE(join(std::vector<Text>{"1","2","","3"}, ",", false) == "1,2,3");
            REQUIRE(join(std::vector<Text>{"1","2","","3"}, ",", true) == "1,2,,3");
        }
        SECTION("Suffix check") {
            Text phrase("There once was a");
            REQUIRE(phrase.endsWith("once was a"));
            REQUIRE(phrase.endsWith("e was a"));
            REQUIRE(phrase.endsWith("a"));
            REQUIRE_FALSE(phrase.endsWith(""));
            REQUIRE(phrase.endsWith("ONCE WAS A", false));
            REQUIRE_FALSE(phrase.endsWith("ONCE WAS A", true));
        }
        SECTION("Prefix check") {
            Text phrase("There once was a");
            REQUIRE(phrase.startsWith("There "));
            REQUIRE(phrase.startsWith("T"));
            REQUIRE_FALSE(phrase.startsWith(""));
            REQUIRE(phrase.startsWith("there ", false));
            REQUIRE_FALSE(phrase.startsWith("there ", true));
        }
        SECTION("String deletion") {
            REQUIRE(Text("REMOVE THIS").remove("THIS ") == "REMOVE ");
            REQUIRE(Text("A B C D").remove("A ", "B ") == "C D");
        }
        SECTION("Substring replacement") {
            REQUIRE(Text("OLD TEXT").replace("OLD", "NEW") == "NEW TEXT");
            REQUIRE(Text("X Y Z").replace("X ", "") == "Y Z");
        }
        SECTION("Character substitution") {
            REQUIRE(Text("ABCDEF").replaceAnyOf("ACF", 'X') == "XBXDEX");
        }
        SECTION("Append with move semantics") {
            Text left;
            Text right("value");
            left.append(std::move(right));
            REQUIRE(left == "value");
            REQUIRE(right.empty());
        }
        SECTION("Operator += with move semantics") {
            Text left;
            Text right("value");
            left += std::move(right);
            REQUIRE(left == "value");
            REQUIRE(right.empty());
        }
        SECTION("Substring extraction") {
            using string::npos;
            Text text("outstanding");
            auto check = [&](size_t pos, size_t len, TextView expected) {
                REQUIRE(text.substr(pos, len) == expected);
                REQUIRE(text.substrView(pos, len) == expected);
            };
            check(0, 0, {});
            check(0, npos, text);
            check(text.length(), 10, {});
            check(0, 5, "outst"_tv);
            check(2, 4, "tsta"_tv);
            check(7, 3, "ing"_tv);
        }
    }
#if WIN32
    SECTION("Utf16") {
        SECTION("Implicit conversion") {
            Utf16 sample = L"sample";
            REQUIRE(Utf16eql(static_cast<const Utf16Chr*>(sample), L"sample"));
            REQUIRE(static_cast<bool>(sample));
        }
        SECTION("Move assignment") {
