// Helper macros for platform-specific behavior simulation
#if defined(_WIN32) || defined(_WIN64)
    #define PLATFORM_WINDOWS 1
#else
    #define PLATFORM_WINDOWS 0
#endif

// Simulate path splitting logic with equivalent behavior
struct TPathSplit {
    std::vector<std::string> parts;
    bool IsAbsolute = false;
    std::string Drive; // Only used on Windows

    void Clear() {
        parts.clear();
        IsAbsolute = false;
        Drive.clear();
    }

    void Parse(const std::string& input) {
        Clear();

        if (input.empty()) return;

        size_t i = 0;

        // Handle drive letter on Windows
        if (PLATFORM_WINDOWS && input.size() >= 2 && std::isalpha(input[0]) && input[1] == ':') {
            Drive = input.substr(0, 2);
            i = 2;
        }

        // Check absolute path indicators
        if (i < input.size()) {
            if (input[i] == '/' || (PLATFORM_WINDOWS && input[i] == '\\')) {
                IsAbsolute = true;
                ++i;
            }
        }

        // Normalize separators and split
        std::string segment;
        while (i < input.size()) {
            char c = input[i];
            if (c == '/' || (PLATFORM_WINDOWS && c == '\\')) {
                if (!segment.empty()) {
                    if (segment == ".") {
                        // Skip current directory marker
                    } else if (segment == "..") {
                        if (!parts.empty() && parts.back() != "..") {
                            parts.pop_back();
                        } else if (!IsAbsolute) {
                            parts.push_back("..");
                        }
                    } else {
                        parts.push_back(segment);
                    }
                    segment.clear();
                }
            } else {
                segment += c;
            }
            ++i;
        }

        // Process last segment
        if (!segment.empty()) {
            if (segment == ".") {
                // Ignore
            } else if (segment == "..") {
                if (!parts.empty() && parts.back() != "..") {
                    parts.pop_back();
                } else if (!IsAbsolute) {
                    parts.push_back("..");
                }
            } else {
                parts.push_back(segment);
            }
        }

        // Special case: root only
        if (parts.empty() && IsAbsolute && !Drive.empty()) {
            parts.emplace_back();
        }
    }

    std::string Reconstruct() const {
        if (parts.empty()) {
            return "";
        }

        std::string result;
        if (IsAbsolute) {
            if (PLATFORM_WINDOWS && !Drive.empty()) {
                result += Drive;
            }
            if (parts[0].empty() || parts[0] == ".") {
                // Already handled by IsAbsolute
            } else {
                result += (PLATFORM_WINDOWS ? "\\" : "/");
            }
        }

        for (size_t idx = 0; idx < parts.size(); ++idx) {
            if (idx > 0 || !IsAbsolute) {
                result += (PLATFORM_WINDOWS ? "\\" : "/");
            }
            result += parts[idx];
        }

        return result;
    }

    void ParsePart(const std::string& part) {
        std::string combined;
        if (part.empty()) return;

        if (part[0] == '/' || (PLATFORM_WINDOWS && part[0] == '\\')) {
            // Absolute part resets context
            if (part.size() > 1 && PLATFORM_WINDOWS && std::isalpha(part[1]) && part[2] == ':') {
                Drive = part.substr(0, 2);
                combined = part.substr(3);
            } else {
                combined = part.substr(1);
            }
        } else {
            combined = part;
        }

        // Temporarily store original state
        auto originalParts = parts;
        auto originalIsAbsolute = IsAbsolute;
        auto originalDrive = Drive;

        // Merge with existing path
        if (!originalParts.empty() && originalParts.back() == "..") {
            // Keep original structure if ending in ..
        }

        // Simulate concatenation and re-parse
        std::string full;
        if (originalIsAbsolute) {
            if (PLATFORM_WINDOWS && !originalDrive.empty()) {
                full += originalDrive + "\\";
            } else {
                full += "/";
            }
        }
        for (const auto& seg : originalParts) {
            if (!seg.empty()) {
                full += seg + (PLATFORM_WINDOWS ? "\\" : "/");
            }
        }
        full += combined;

        Parse(full);
    }

    void ParseFirstPart(const std::string& first) {
        Parse(first);
    }

    TPathSplit& operator=(const TPathSplit& other) = default;
};

// Utility function to compare vectors of strings
bool AreEqual(const std::vector<std::string>& lhs, const std::vector<std::string>& rhs) {
    if (lhs.size() != rhs.size()) return false;
    for (size_t i = 0; i < lhs.size(); ++i) {
        if (lhs[i] != rhs[i]) return false;
    }
    return true;
}

// Simple unit test framework stubs
#define UNIT_ASSERT_EQUAL(cond) do { \
    if (!(cond)) { std::cerr << "Assertion failed: " << #cond << "\n"; return false; } \
} while(0)

#define UNIT_ASSERT_STRINGS_EQUAL(a, b) do { \
    if ((a) != (b)) { std::cerr << "String mismatch: '" << (a) << "' != '" << (b) << "'\n"; return false; } \
} while(0)

// Test suite runner
bool RunTests() {
    // Empty test
    {
        TPathSplit ps;
        ps.Parse("");
        std::vector<std::string> expected = {};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));
        UNIT_ASSERT_EQUAL(ps.IsAbsolute, false);
    }

    // Relative path
    {
        TPathSplit ps;
        ps.Parse("some/usual/path");
        std::vector<std::string> expected = {"some", "usual", "path"};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));
        UNIT_ASSERT_EQUAL(ps.IsAbsolute, false);
    }

    // Absolute path
    {
        TPathSplit ps;
        ps.Parse("/some/usual/path");
        std::vector<std::string> expected = {"some", "usual", "path"};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));
        UNIT_ASSERT_EQUAL(ps.IsAbsolute, true);
    }

    // Self reference
    {
        TPathSplit ps;
        ps.Parse(".");
        std::vector<std::string> expected = {"."};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));
        UNIT_ASSERT_EQUAL(ps.IsAbsolute, false);
    }

    // Parent reference
    {
        TPathSplit ps;
        ps.Parse("..");
        std::vector<std::string> expected = {".."};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));
        UNIT_ASSERT_EQUAL(ps.IsAbsolute, false);
    }

    // Root only
    {
        TPathSplit ps;
        ps.Parse("/");
        std::vector<std::string> expected = {};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));
        UNIT_ASSERT_EQUAL(ps.IsAbsolute, true);
    }

    // Reconstruct tests
    {
        TPathSplit ps;
        ps.Parse("some/usual/path/../../other/././//path");
        std::string reconstructed = ps.Reconstruct();
        std::string expected = PLATFORM_WINDOWS ? "some\\other\\path" : "some/other/path";
        UNIT_ASSERT_STRINGS_EQUAL(reconstructed, expected);

        ps.Parse("/some/usual/path/../../other/././//path");
        reconstructed = ps.Reconstruct();
        expected = PLATFORM_WINDOWS ? "\\some\\other\\path" : "/some/other/path";
        UNIT_ASSERT_STRINGS_EQUAL(reconstructed, expected);
    }

    // Win-specific tests
    {
        TPathSplit ps;
        ps.Parse("some\\usual\\path");
        std::vector<std::string> expectedWin = {"some", "usual", "path"};
        std::vector<std::string> expectedUnix = {"some\\usual\\path"};
        if (PLATFORM_WINDOWS) {
            UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expectedWin));
        } else {
            UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expectedUnix));
        }
        UNIT_ASSERT_EQUAL(ps.IsAbsolute, false);

        TPathSplit psDrive;
        psDrive.Parse("C:\\some\\usual\\path");
        if (PLATFORM_WINDOWS) {
            UNIT_ASSERT_EQUAL(psDrive.Drive, "C:");
        }
    }

    // Mixed separators
    {
        TPathSplit ps;
        ps.Parse("some\\usual/path");
        std::vector<std::string> expectedWin = {"some", "usual", "path"};
        std::vector<std::string> expectedUnix = {"some\\usual", "path"};
        if (PLATFORM_WINDOWS) {
            UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expectedWin));
        } else {
            UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expectedUnix));
        }
    }

    // Begin with self or parent
    {
        TPathSplit ps;
        ps.Parse("./some/usual/path");
        std::vector<std::string> expected = {"some", "usual", "path"};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));

        ps.Parse("../some/usual/path");
        expected = {"..", "some", "usual", "path"};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));
    }

    // InOut / OutIn
    {
        TPathSplit ps;
        ps.Parse("path/..");
        std::vector<std::string> expected = {};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));
        UNIT_ASSERT_STRINGS_EQUAL(ps.Reconstruct(), "");

        ps.Parse("../path");
        expected = {"..", "path"};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));
    }

    // ParsePart tests
    {
        TPathSplit ps("some/usual/path");
        ps.ParsePart("sub/path");
        std::vector<std::string> expected = {"some", "usual", "path", "sub", "path"};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));
    }

    // ParsePartParent
    {
        TPathSplit ps("some/usual/path");
        ps.ParsePart("..");
        std::vector<std::string> expected = {"some", "usual"};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));
    }

    // Overflow handling
    {
        TPathSplit ps("some/usual/path");
        ps.ParsePart("../../../../..");
        std::vector<std::string> expected = {"..", ".."};
        UNIT_ASSERT_EQUAL(AreEqual(ps.parts, expected));
    }

    return true;
}

int main() {
    if (RunTests()) {
        std::cout << "All tests passed!" << std::endl;
    } else {
        std::cout << "Some tests failed." << std::endl;
    }
    return 0;
}

