// Compute absolute value for 64-bit integers with masking to ensure int63 range
int64_t Int63Arith::i_abs(const int64_t x) {
    // Handle negative values by computing two's complement and masking
    if (x < 0) {
        // Use subtraction from zero and apply mask to keep within signed 63-bit range
        return ((-x) & 0x7FFFFFFFFFFFFFFFLL);
    }
    // For non-negative values, return as-is (already in valid range)
    return x;
}

