void StaticResponseProcessorWS::Process(SpectreWebsocketRequest& packet, SpectreWebsocket& sock) {
    // Obtain base JSON response from the incoming packet
    std::shared_ptr<json> response = packet.GetBaseJsonResponse();

    // Assign the stored response payload to the "payload" field
    (*response)["payload"] = m_res;

    // Send the constructed response back via the websocket
    sock.SendPacket(response);
