using namespace mscclpp;

// Helper macro to register exception translators for custom error types
#define BIND_ERROR_TRANSLATOR(type_name)                                                                             \
  nb::register_exception_translator(                                                                                 \
      [](const std::exception_ptr &exc_ptr, void *user_data) {                                                       \
        try {                                                                                                        \
          std::rethrow_exception(exc_ptr);                                                                           \
        } catch (const type_name &err) {                                                                             \
          PyObject* py_tuple = PyTuple_Pack(2,                                                                       \
              PyLong_FromLong(static_cast<long>(err.getErrorCode())),                                                \
              PyUnicode_FromString(err.what()));                                                                     \
          PyErr_SetObject(reinterpret_cast<PyObject*>(user_data), py_tuple);                                         \
        }                                                                                                            \
      },                                                                                                             \
      m.attr(#type_name).ptr());

void register_error(nb::module_ &m) {
  // Define the ErrorCode enumeration in Python
  nb::enum_<ErrorCode>(m, "ErrorCode")
      .value("SystemError", ErrorCode::SystemError)
      .value("InternalError", ErrorCode::InternalError)
      .value("RemoteError", ErrorCode::RemoteError)
      .value("InvalidUsage", ErrorCode::InvalidUsage)
      .value("Timeout", ErrorCode::Timeout)
      .value("Aborted", ErrorCode::Aborted)
      .value("ExecutorError", ErrorCode::ExecutorError);

  // Register base and derived exception types
  nb::exception<BaseError>(m, "BaseError");
  BIND_ERROR_TRANSLATOR(BaseError);

  nb::exception<Error>(m, "Error", m.attr("BaseError").ptr());
  BIND_ERROR_TRANSLATOR(Error);

  nb::exception<SysError>(m, "SysError", m.attr("BaseError").ptr());
  BIND_ERROR_TRANSLATOR(SysError);

  nb::exception<CudaError>(m, "CudaError", m.attr("BaseError").ptr());
  BIND_ERROR_TRANSLATOR(CudaError);

  nb::exception<CuError>(m, "CuError", m.attr("BaseError").ptr());
  BIND_ERROR_TRANSLATOR(CuError);

  nb::exception<IbError>(m, "IbError", m.attr("BaseError").ptr());
  BIND_ERROR_TRANSLATOR(IbError);
}

