#include "syscall.h"

// Wrapper function to change ownership of a symbolic link without following it
int lchown(const char *path, uid_t uid, gid_t gid)
{
#ifdef SYS_lchown
	// Use the direct lchown system call if available
	return syscall(SYS_lchown, path, uid, gid);
#else
	// Fallback: use fchownat with AT_SYMLINK_NOFOLLOW flag on current working directory
	return syscall(SYS_fchownat, AT_FDCWD, path, uid, gid, AT_SYMLINK_NOFOLLOW);
#endif
}

