  std::ostringstream out;
  Slice s = b->slice();
  out << HexDump(s);
  ASSERT_EQ("0x86 0x66 0x6f 0x6f 0x62 0x61 0x72", out.str());
  ASSERT_EQ("0x86 0x66 0x6f 0x6f 0x62 0x61 0x72",
            HexDump(b->slice()).toString());
}

