/**
 * Swap endianness of a 16-bit unsigned integer
 * Input: in - original value
 * Output: out - pointer to store the swapped result
 */
void nlSwapEndian(unsigned short in, unsigned short* out) {
    // Clear the output first
    *out = 0;

    // Extract the high byte and move it to low position, then mask to 8 bits
    unsigned short lowByte = (in >> 8U) & 0xFFU;

    // Extract the low byte and move it to high position
    unsigned short highByte = (in & 0xFFU) << 8U;

    // Combine both bytes to form the swapped value
    *out = lowByte | highByte;
}

