// Helper lambda: convert bool to "true"/"false"
auto to_bool_string = [](bool val) -> std::string {
    return val ? "true" : "false";
};

// Helper lambda: write vector or matrix transpose as space-separated values
template<typename Derived>
void write_transpose(std::ostream& os, const Eigen::MatrixBase<Derived>& vec) {
    os << vec.transpose().format(Eigen::IOFormat(Eigen::StreamPrecision, 0, ", ", "\n"));
}

// Generic helper for writing enum-like string mappings
std::string map_enum_to_string(int value, const std::pair<int, std::string>* mapping, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (mapping[i].first == value) {
            return mapping[i].second;
        }
    }
    return "";
}

