TEST(PythonVersionParsing, AlternativeTryScanVersionTests) {
    struct TestCaseData {
        TString InputString;
        bool ExpectedSuccess;
        TPythonVersion TargetVersion;
    };

    TVector<TestCaseData> testCases = {
        {"Python 3.10.0", true, {3, 10, 0}},
        {"Python 3.10.1", true, {3, 10, 1}},
        {"Python 2.7", true, {2, 7, 0}},
        {"Python 2.7.10", true, {2, 7, 10}},
        {"Python 3.8.15", true, {3, 8, 15}},
        {"Python 3.12.0", true, {3, 12, 0}},
        {"Python 3.12.1", true, {3, 12, 1}},
        {"Python 2.8.3", true, {2, 8, 3}},
        {"Python version 3.10.0, 64 bit", true, {3, 10, 0}},
        {"Version: Python 2.7.15", true, {2, 7, 15}},
        {"Python 4.0.0", false, {}},  // Invalid major version
        {"No version here", false, {}},
        {"Python v9.8.7", false, {}},
    };

    for (const auto& testCase : testCases) {
        TMaybe<TPythonVersion> parsedResult = TryScanVersion(
            TConstArrayRef<char>{testCase.InputString.data(), testCase.InputString.size()}
        );

        if (testCase.ExpectedSuccess) {
            ASSERT_TRUE(parsedResult.Defined()) 
                << "Expected successful parsing of '" << testCase.InputString << "' but failed";

            TString expectedVerStr = std::to_string(testCase.TargetVersion.MajorVersion) + "." +
                                     std::to_string(testCase.TargetVersion.MinorVersion) + "." +
                                     std::to_string(testCase.TargetVersion.MicroVersion);

            TString actualVerStr = std::to_string(parsedResult->MajorVersion) + "." +
                                   std::to_string(parsedResult->MinorVersion) + "." +
                                   std::to_string(parsedResult->MicroVersion);

            EXPECT_EQ(parsedResult->MajorVersion, testCase.TargetVersion.MajorVersion)
                << "Major version mismatch for input: '" << testCase.InputString
                << "', expected: " << expectedVerStr << ", got: " << actualVerStr;

            EXPECT_EQ(parsedResult->MinorVersion, testCase.TargetVersion.MinorVersion)
                << "Minor version mismatch for input: '" << testCase.InputString
                << "', expected: " << expectedVerStr << ", got: " << actualVerStr;

            EXPECT_EQ(parsedResult->MicroVersion, testCase.TargetVersion.MicroVersion)
                << "Micro version mismatch for input: '" << testCase.InputString
                << "', expected: " << expectedVerStr << ", got: " << actualVerStr;
        } else {
            EXPECT_FALSE(parsedResult.Defined())
                << "Unexpectedly parsed version from string: '" << testCase.InputString << "'";
        }
    }
}

#include <vector>
#include <algorithm>

class Solution {
public:
    void rotate(std::vector<std::vector<int>>& matrix) {
        int size = matrix.size();

        // Transpose the matrix by swapping elements across the main diagonal
        for (int row = 0; row < size; ++row) {
            for (int col = row + 1; col < size; ++col) {
                std::swap(matrix[row][col], matrix[col][row]);
            }
        }

        // Reverse each row to complete the 90-degree clockwise rotation
        for (int i = 0; i < size; ++i) {
            int left = 0;
            int right = size - 1;
            while (left < right) {
                std::swap(matrix[i][left], matrix[i][right]);
                ++left;
                --right;
            }
        }
    }
};

