// Perform system reboot using ACPI-compliant hardware reset
Void ACPIFactoryInterface::Reboot() {
  // Disable interrupts and prepare for hardware reset
  asm volatile(
      ".intel_syntax noprefix\n"
      "reboot_hardware:\n"
      "cli\n"
      "poll_kbd_status:\n"
      "in al, 0x64\n"
      "test al, 0x02\n"
      "jnz poll_kbd_status\n"
      "mov al, 0xD1\n"
      "out 0x64, al\n"
      "poll_output_buffer:\n"
      "in al, 0x64\n"
      "test al, 0x02\n"
      "jnz poll_output_buffer\n"
      "mov al, 0xFE\n"
      "out 0x60, al\n"
      "xor rax, rax\n"
      "lidt [rax]\n"
      "infinite_loop:\n"
      "jmp infinite_loop\n"
      ".att_syntax\n"
  );
}
