// Verify truth values of boolean literals
void validate_boolean_literals(SMTParser::ParserPtr& parser) {
    std::cout << "=== Validating Boolean Literals ===" << std::endl;

    auto trueNode = parser->mkExpr("true");
    assert(trueNode && trueNode->isTrue() && !trueNode->isFalse());
    std::cout << "Literal: true" << std::endl;
    std::cout << "  Output: " << parser->toString(trueNode) << std::endl;
    std::cout << "  True? : yes" << std::endl;
    std::cout << "  False?: no" << std::endl << std::endl;

    auto falseNode = parser->mkExpr("false");
    assert(falseNode && falseNode->isFalse() && !falseNode->isTrue());
    std::cout << "Literal: false" << std::endl;
    std::cout << "  Output: " << parser->toString(falseNode) << std::endl;
    std::cout << "  True? : no" << std::endl;
    std::cout << "  False?: yes" << std::endl << std::endl;
}

// Validate logical connectives with expected outcomes
void validate_logical_connectives(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> testCases = {
        {"(not true)", false},
        {"(not false)", true},
        {"(and true true)", true},
        {"(and true false)", false},
        {"(and false false)", false},
        {"(or true true)", true},
        {"(or true false)", true},
        {"(or false false)", false},
        {"(=> true true)", true},
        {"(=> true false)", false},
        {"(=> false true)", true},
        {"(=> false false)", true},
        {"(xor true true)", false},
        {"(xor true false)", true},
        {"(xor false false)", false}
    };

    std::cout << "=== Validating Logical Connectives ===" << std::endl;
    for (const auto& testCase : testCases) {
        std::cout << "Expression: " << testCase.first << std::endl;
        auto node = parser->mkExpr(testCase.first);
        assert(node);
        bool expectedTrue = testCase.second;
        bool actualTrue = node->isTrue();
        bool actualFalse = node->isFalse();
        assert(actualTrue == expectedTrue || actualFalse == !expectedTrue);
        std::cout << "  Output: " << parser->toString(node) << std::endl;
        std::cout << std::endl;
    }
}

// Validate compound boolean expressions
void validate_compound_expressions(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> compoundTests = {
        {"(and (or true false) (not false))", true},
        {"(or (and true false) (not true))", false},
        {"(=> (or true false) (and true true))", true},
        {"(xor (not false) (and true false))", true},
        {"(and (=> true false) (or false true))", false},
        {"(not (and (or true false) (=> false true)))", false}
    };

    std::cout << "=== Validating Compound Expressions ===" << std::endl;
    for (const auto& test : compoundTests) {
        std::cout << "Expression: " << test.first << std::endl;
        auto resultNode = parser->mkExpr(test.first);
        assert(resultNode);
        bool expectedTrueVal = test.second;
        bool actualTrueVal = resultNode->isTrue();
        bool actualFalseVal = resultNode->isFalse();
        assert(actualTrueVal == expectedTrueVal || actualFalseVal == !expectedTrueVal);
        std::cout << "  Output: " << parser->toString(resultNode) << std::endl;
        std::cout << std::endl;
    }
}

int main() {
    std::cout << "======= Boolean Logic Validation Suite =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    validate_boolean_literals(parser);
    validate_logical_connectives(parser);
    validate_compound_expressions(parser);

    return 0;
}

