#include <vector>
#include <algorithm>

class Solution {
public:
    double findMaxAverage(std::vector<int>& nums, int k) {
        int total = 0;
        // Calculate sum of first k elements
        for (int index = 0; index < k; ++index) {
            total += nums[index];
        }

        double bestSum = static_cast<double>(total);

        // Slide the window across the array
        for (int position = k; position < nums.size(); ++position) {
            total = total - nums[position - k] + nums[position];
            bestSum = std::max(static_cast<double>(total), bestSum);
        }

        return bestSum / k;
    }
};

