#include <stdio.h>
#include <stdlib.h>
#include "lbug.h"

int main() {
    lbug_database database;
    lbug_connection connection;

    // Initialize database with default config
    lbug_database_init("" /* db path */, lbug_default_system_config(), &database);
    lbug_connection_init(&database, &connection);

    // Define schema for Person node
    lbug_query_result query_result;
    lbug_connection_query(
        &connection,
        "CREATE NODE TABLE Person(name STRING, age INT64, PRIMARY KEY(name));",
        &query_result);
    lbug_query_result_destroy(&query_result);

    // Insert sample nodes
    lbug_connection_query(&connection, "CREATE (:Person {name: 'Alice', age: 25});", &query_result);
    lbug_query_result_destroy(&query_result);
    lbug_connection_query(&connection, "CREATE (:Person {name: 'Bob', age: 30});", &query_result);
    lbug_query_result_destroy(&query_result);

    // Run MATCH query to retrieve data
    lbug_connection_query(&connection, "MATCH (p:Person) RETURN p.name AS NAME, p.age AS AGE;", &query_result);

    // Process each row in result set
    lbug_flat_tuple current_tuple;
    lbug_value field_value;

    do {
        if (!lbug_query_result_has_next(&query_result)) break;

        lbug_query_result_get_next(&query_result, &current_tuple);

        // Extract name (string)
        lbug_flat_tuple_get_value(&current_tuple, 0, &field_value);
        char* person_name = nullptr;
        lbug_value_get_string(&field_value, &person_name);

        // Extract age (int64)
        lbug_flat_tuple_get_value(&current_tuple, 1, &field_value);
        int64_t person_age = 0;
        lbug_value_get_int64(&field_value, &person_age);

        printf("name: %s, age: %" PRIi64 " \n", person_name, person_age);

        // Clean up allocated string
        lbug_destroy_string(person_name);
    } while (true);

    // Cleanup tuple and value objects
    lbug_value_destroy(&field_value);
    lbug_flat_tuple_destroy(&current_tuple);

    // Output full result as string (for debugging/logging)
    char* output_str = lbug_query_result_to_string(&query_result);
    printf("%s", output_str);
    lbug_destroy_string(output_str);

    // Final cleanup
    lbug_query_result_destroy(&query_result);
    lbug_connection_destroy(&connection);
    lbug_database_destroy(&database);

    return 0;
}

class Solution {
public:
    bool isStrictlyPalindromic(int n) {
        // For any n >= 4, n in base (n-2) is "12", which is not palindromic
        // So no number can be strictly palindromic
        if (n < 4) {
            return false;
        }

        // Since we know mathematically no number > 4 can be strictly palindromic,
        // and numbers 1,2,3 don't have enough bases to check, return false
        return false;
    }
};

