#include <gtest/gtest.h>
#include <jonssonic/core/common/circular_audio_buffer.h>

using namespace jnsc;

// Test basic resize and simple write/read operations
TEST(CircularAudioBufferTest, BasicWriteRead) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(2, 8);

    ASSERT_EQ(audioBuffer.getNumChannels(), 2u);
    ASSERT_EQ(audioBuffer.getBufferSize(), 8u);

    // Write sample values to each channel
    audioBuffer.write(0, 1.0f);
    audioBuffer.write(1, 2.0f);

    // Verify the most recent samples are read correctly
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 1.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 0), 2.0f);
}

// Test buffer wrap-around behavior when writing beyond capacity
TEST(CircularAudioBufferTest, WrapBehavior) {
    CircularAudioBuffer<float> ringBuffer;
    ringBuffer.resize(1, 4);

    // Overwrite buffer with more samples than capacity
    for (int idx = 0; idx < 6; ++idx)
        ringBuffer.write(0, static_cast<float>(idx));

    // After 6 writes into size-4 buffer: [2,3,4,5] oldest->newest
    EXPECT_FLOAT_EQ(ringBuffer.read(0, 0), 5.0f); // newest
    EXPECT_FLOAT_EQ(ringBuffer.read(0, 1), 4.0f);
    EXPECT_FLOAT_EQ(ringBuffer.read(0, 2), 3.0f);
    EXPECT_FLOAT_EQ(ringBuffer.read(0, 3), 2.0f); // oldest retained
}

// Test clear functionality resets buffer state
TEST(CircularAudioBufferTest, ResetBuffer) {
    CircularAudioBuffer<float> circularBuffer;
    circularBuffer.resize(1, 4);

    circularBuffer.write(0, 1.0f);
    circularBuffer.write(0, 2.0f);
    circularBuffer.clear();

    // After clearing, only new data should be present
    circularBuffer.write(0, 3.0f);
    EXPECT_FLOAT_EQ(circularBuffer.read(0, 0), 3.0f);
}

// Test multi-channel operation with interleaved writes
TEST(CircularAudioBufferTest, MultiChannelSupport) {
    CircularAudioBuffer<float> multiChanBuffer;
    multiChanBuffer.resize(2, 4);

    // Fill buffer with alternating channel writes
    for (int step = 0; step < 4; ++step) {
        multiChanBuffer.write(0, static_cast<float>(step));
        multiChanBuffer.write(1, static_cast<float>(step + 10));
    }

    // Verify latest values per channel
    EXPECT_FLOAT_EQ(multiChanBuffer.read(0, 0), 3.0f);
    EXPECT_FLOAT_EQ(multiChanBuffer.read(1, 0), 13.0f);

    // Verify older values at different offsets
    EXPECT_FLOAT_EQ(multiChanBuffer.read(0, 3), 0.0f);
    EXPECT_FLOAT_EQ(multiChanBuffer.read(1, 3), 10.0f);
}

