        UNIT_ASSERT(segment2.Open(segment1.GetId(), segment1.GetSize()));

        // Write a test value to the first memory segment
        *(ui32*)segment1.GetPtr() = 123;

        // Verify that the second segment sees the same value
        UNIT_ASSERT_VALUES_EQUAL(*(ui32*)segment2.GetPtr(), 123);
    }
} // Y_UNIT_TEST_SUITE(TTestSharedMemory)

