#include "autolink/time/time.hpp"
#include <iostream>
#include "autolink/time/duration.hpp"
#include "gtest/gtest.h"

namespace autolink {

TEST(TimeTest, constructor) {
  Time t1(100UL);
  EXPECT_EQ(100UL, t1.ToNanosecond());

  t1 = Time(1.1);
  EXPECT_EQ(1100000000UL, t1.ToNanosecond());
  EXPECT_DOUBLE_EQ(1.1, t1.ToSecond());

  t1 = Time(1, 1);
  EXPECT_EQ(1000000001UL, t1.ToNanosecond());
  EXPECT_DOUBLE_EQ(1.000000001, t1.ToSecond());

  Time t2(t1);
  EXPECT_EQ(t1, t2);
}

TEST(TimeTest, operators) {
  Time base(100);
  Duration delta(200);
  Time target(300);

  EXPECT_NE(base, target);
  EXPECT_LT(base, target);
  EXPECT_LE(base, target);
  EXPECT_GT(target, base);
  EXPECT_GE(target, base);

  EXPECT_EQ(base + delta, target);
  EXPECT_EQ(target - delta, base);
  EXPECT_EQ((base += delta), target);
  EXPECT_GE(base, target);
  EXPECT_LE(base, target);
  EXPECT_EQ(Time(100), (base -= delta));
}

TEST(TimeTest, to_string) {
  Time high_res1(1531225311123456789UL);
  std::cout << high_res1.ToString().c_str() << std::endl;

  Time high_res2(1531225311000006789UL);
  std::cout << high_res2.ToString().c_str() << std::endl;
}

TEST(TimeTest, now) {
  std::cout << "Current Time: " << Time::Now() << std::endl;
}

TEST(TimeTest, is_zero) {
  Time default_time;
  EXPECT_TRUE(default_time.IsZero());
  EXPECT_FALSE(Time::MAX.IsZero());
  EXPECT_TRUE(Time::MIN.IsZero());
}

