// clang-format off

// Union for FPSCR access — unchanged structure, just renamed fields for clarity
union FpscrRegister {
    f64 full;
    struct {
        u32 padding;
        u32 value;
    } parts;
};

// Helper macros for bit manipulation
#define SET_BIT(reg, bit)   ((reg) |= (1u << (bit)))
#define CLEAR_BIT(reg, bit) ((reg) &= ~(1u << (bit)))

// Inline assembly helpers — renamed for readability
asm u32 read_msr() {
    nofralloc
    mfmsr r3
    blr
}

asm void write_msr(u32 new_val) {
    nofralloc
    mtmsr new_val
    blr
}

asm u32 or_msr(u32 bits) {
    nofralloc
    mfmsr r4
    or r3, r4, bits
    blr
}

asm u32 and_msr(u32 bits) {
    nofralloc
    mfmsr r4
    and r3, r4, bits
    blr
}

asm u32 andc_msr(u32 mask) {
    nofralloc
    mfmsr r4
    andc r3, r4, mask
    blr
}

// HID0 register accessors
asm u32 read_hid0() {
    nofralloc
    mfspr r3, HID0
    blr
}

asm void write_hid0(u32 val) {
    nofralloc
    mtspr HID0, val
    blr
}

// HID1 & L2 cache registers
asm u32 read_hid1() {
    nofralloc
    mfspr r3, HID1
    blr
}

asm u32 read_l2cr() {
    nofralloc
    mfspr r3, L2CR
    blr
}

asm void write_l2cr(u32 val) {
    nofralloc
    mtspr L2CR, val
    blr
}

// DEC timer
asm void write_dec(u32 val) {
    nofralloc
    mtdec val
    blr
}

asm u32 read_dec() {
    nofralloc
    mfdec r3
    blr
}

// Synchronization primitives
asm void do_sync() {
    nofralloc
    sc
    blr
}

// Enhanced I/O barrier — rewritten with clearer step-by-step ordering
asm void io_barrier() {
    nofralloc
    mfmsr r5
    rlwinm r6, r5, 0, 17, 15   // clear EE bit
    mtmsr r6                    // disable interrupts temporarily
    mfspr r3, HID0
    ori r4, r3, 0x8             // set EIEIO enable bit
    mtspr HID0, r4
    isync
    eieio
    isync
    mtspr HID0, r3              // restore original HID0
    mtmsr r5                    // restore MSR
    isync
    blr
}

// Halt loop — identical behavior, slightly reordered instructions
asm void cpu_halt() {
    nofralloc
    sync
halt_loop:
    nop
    li r3, 0
    nop
    b halt_loop
}

// Performance monitor registers
asm u32 read_mmcr0() {
    nofralloc
    mfspr r3, MMCR0
    blr
}

asm void write_mmcr0(u32 val) {
    nofralloc
    mtspr MMCR0, val
    blr
}

asm u32 read_mmcr1() {
    nofralloc
    mfspr r3, MMCR1
    blr
}

asm void write_mmcr1(u32 val) {
    nofralloc
    mtspr MMCR1, val
    blr
}

asm u32 read_pmc1() {
    nofralloc
    mfspr r3, PMC1
    blr
}

asm void write_pmc1(u32 val) {
    nofralloc
    mtspr PMC1, val
    blr
}

asm u32 read_pmc2() {
    nofralloc
    mfspr r3, PMC2
    blr
}

asm void write_pmc2(u32 val) {
    nofralloc
    mtspr PMC2, val
    blr
}

asm u32 read_pmc3() {
    nofralloc
    mfspr r3, PMC3
    blr
}

asm void write_pmc3(u32 val) {
    nofralloc
    mtspr PMC3, val
    blr
}

asm u32 read_pmc4() {
    nofralloc
    mfspr r3, PMC4
    blr
}

asm void write_pmc4(u32 val) {
    nofralloc
    mtspr PMC4, val
    blr
}

// System instruction address registers
asm u32 read_sia() {
    nofralloc
    mfspr r3, SIA
    blr
}

asm void write_sia(u32 val) {
    nofralloc
    mtspr SIA, val
    blr
}

// Floating-point status/control register
u32 read_fpscr() {
    FpscrRegister reg;
    asm {
        mffs fp31
        stfd fp31, reg.full
    }
    return reg.parts.value;
}

void write_fpscr(u32 val) {
    FpscrRegister reg;
    asm {
        li r4, 0
        stw r4, reg.parts.padding
        stw val, reg.parts.value
        lfd fp31, reg.full
        mtfsf 0xff, fp31
    }
}

// Additional SPRs
asm u32 read_hid2() {
    nofralloc
    mfspr r3, HID2
    blr
}

asm void write_hid2(u32 val) {
    nofralloc
    mtspr HID2, val
    blr
}

asm u32 read_wpar() {
    nofralloc
    sync
    mfspr r3, WPAR
    blr
}

asm void write_wpar(u32 val) {
    nofralloc
    mtspr WPAR, val
    blr
}

// DMA registers
asm u32 read_dma_upper() {
    nofralloc
    mfspr r3, DMA_U
    blr
}

asm u32 read_dma_lower() {
    nofralloc
    mfspr r3, DMA_L
    blr
}

asm void write_dma_upper(u32 val) {
    nofralloc
    mtspr DMA_U, val
    blr
}

asm void write_dma_lower(u32 val) {
    nofralloc
    mtspr DMA_L, val
    blr
}

// Processor version register
asm u32 read_pvr() {
    nofralloc
    mfspr r3, PVR
    blr
}

// High-level CPU feature toggles
void enable_speculation() {
    u32 hid0 = read_hid0();
    CLEAR_BIT(hid0, HID0_SPD);
    write_hid0(hid0);
}

void disable_speculation() {
    u32 hid0 = read_hid0();
    SET_BIT(hid0, HID0_SPD);
    write_hid0(hid0);
}

// IEEE vs non-IEEE floating-point mode
asm void set_fp_ieee_mode() {
    nofralloc
    mtfsb0 29
    blr
}

asm void set_fp_non_ieee_mode() {
    nofralloc
    mtfsb1 29
    blr
}

