                       entt::attribute{"name", "speed"},
                       entt::attribute{"pretty_name", "Speed"},
                       entt::attribute{"tooltip", "Playback rate multiplier. 1.0 is normal, 2.0 double speed, 0.5 half speed."},
                       entt::attribute{"min", 0.0f},
                       entt::attribute{"max", 10.0f}
                   })

                   // Property: retargeting_mode
                   .data<&animation_component::set_retargeting_mode, &animation_component::get_retargeting_mode>("retargeting_mode"_hs)
                   .custom<entt::attributes>(entt::attributes{
                       entt::attribute{"name", "retargeting_mode"},
                       entt::attribute{"pretty_name", "Retargeting Mode"},
                       entt::attribute{"tooltip", "Bone matching strategy: index-based (fast, strict match), or name-based (flexible, skeleton-agnostic)."}
                   });
    }

    // Serialization helpers
    template<typename Archive>
    void serialize_fields(Archive& ar, animation_component& obj)
    {
        auto anim = obj.get_animation();
        if constexpr (Archive::is_loading_v) {
            asset_handle<animation_clip> tmp;
            if (ar.has("animation")) {
                ar(ser20::make_nvp("animation", tmp));
                obj.set_animation(tmp);
            }
        } else {
            ar(ser20::make_nvp("animation", anim));
        }

        auto autoplay = obj.get_autoplay();
        if constexpr (Archive::is_loading_v) {
            bool val{};
            if (ar.has("auto_play")) {
                ar(ser20::make_nvp("auto_play", val));
                obj.set_autoplay(val);
            }
        } else {
            ar(ser20::make_nvp("auto_play", autoplay));
        }

        auto cull_mode = obj.get_culling_mode();
        if constexpr (Archive::is_loading_v) {
            animation_component::culling_mode mode{};
            if (ar.has("culling_mode")) {
                ar(ser20::make_nvp("culling_mode", mode));
                obj.set_culling_mode(mode);
            }
        } else {
            ar(ser20::make_nvp("culling_mode", cull_mode));
        }

        auto root_motion = obj.get_apply_root_motion();
        if constexpr (Archive::is_loading_v) {
            bool flag{};
            if (ar.has("apply_root_motion")) {
                ar(ser20::make_nvp("apply_root_motion", flag));
                obj.set_apply_root_motion(flag);
            }
        } else {
            ar(ser20::make_nvp("apply_root_motion", root_motion));
        }

        auto playback_speed = obj.get_speed();
        if constexpr (Archive::is_loading_v) {
            float spd{1.0f};
            if (ar.has("speed")) {
                ar(ser20::make_nvp("speed", spd));
                obj.set_speed(spd);
            }
        } else {
            ar(ser20::make_nvp("speed", playback_speed));
        }

        auto retarget_mode = obj.get_retargeting_mode();
        if constexpr (Archive::is_loading_v) {
            animation_retargeting_mode rm{animation_retargeting_mode::name_based};
            if (ar.has("retargeting_mode")) {
                ar(ser20::make_nvp("retargeting_mode", rm));
                obj.set_retargeting_mode(rm);
            }
        } else {
            ar(ser20::make_nvp("retargeting_mode", retarget_mode));
        }
    }

    SAVE(animation_component)
    {
        serialize_fields(ar, obj);
    }

    SAVE_INSTANTIATE(animation_component, ser20::oarchive_associative_t);
    SAVE_INSTANTIATE(animation_component, ser20::oarchive_binary_t);

    LOAD(animation_component)
    {
        serialize_fields(ar, obj);
    }

    LOAD_INSTANTIATE(animation_component, ser20::iarchive_associative_t);
    LOAD_INSTANTIATE(animation_component, ser20::iarchive_binary_t);
} // namespace unravel

