// Copy the sign of y to x using bitwise operations
float custom_copysign(float x, float y)
{
    union { float f; uint32_t i; } u_x = {x}, u_y = {y};

    // Clear the sign bit of x (keep magnitude)
    u_x.i &= 0x7FFFFFFF;

    // Set the sign bit from y
    u_x.i |= (u_y.i & 0x80000000);

    return u_x.f;
}

