int main() {
    // Initialize semiring and WPDS structures
    wpds::Semiring< StringWrapper > ring(StringWrapper::one());
    wpds::WPDS< StringWrapper > system(ring);
    wpds::CA< StringWrapper > automaton1(ring);
    wpds::CA< StringWrapper > automaton2(ring);

    // Define state and symbol identifiers
    wpds::WPDSKey p = str2key("p");
    wpds::WPDSKey A = str2key("A");
    wpds::WPDSKey B = str2key("B");
    wpds::WPDSKey q_start = str2key("q1");
    wpds::WPDSKey q_mid = str2key("q2");
    wpds::WPDSKey final_state = str2key("accept");

    // Add production rules to the WPDS
    system.add_rule(p, A, p, B, new StringWrapper("a"));
    system.add_rule(p, A, p, A, B, new StringWrapper("b"));

    std::cout << system << std::endl;

    // Configure the initial automaton with transitions
    automaton1.add(p, A, q_start, new StringWrapper("a"));
