    automaton1.add(q_mid, B, final_state, StringWrapper::one());

    std::cout << "*** BEFORE ***\n" << automaton1 << std::endl;

    // Apply prestar operation to compute reachability
    automaton2 = wpds::prestar< StringWrapper >(system, automaton1, ring);

