#include <iostream>

// Calculator program that supports addition, subtraction, square, and cube operations
int main() {
    int choice;
    char continueChoice;

    do {
        std::cout << "Make a choice:\n";
        std::cout << "1. Addition of two numbers\n";
        std::cout << "2. Difference of two numbers\n";
        std::cout << "3. Square of a number\n";
        std::cout << "4. Cube of a number\n";
        std::cout << "Enter your choice: ";
        std::cin >> choice;

        switch (choice) {
            case 1: {
                int num1, num2, result;
                std::cout << "Enter two numbers: ";
                std::cin >> num1 >> num2;
                result = num1 + num2;
                std::cout << "Sum of two numbers = " << result << "\n";
                break;
            }

            case 2: {
                int num1, num2, result;
                std::cout << "Enter two numbers: ";
                std::cin >> num1 >> num2;
                result = num1 - num2;
                std::cout << "Difference of two numbers = " << result << "\n";
                break;
            }

            case 3: {
                int number, result;
                std::cout << "Enter a number: ";
                std::cin >> number;
                result = number * number;
                std::cout << "Square of the number = " << result << "\n";
                break;
            }

            case 4: {
                int number, result;
                std::cout << "Enter a number: ";
                std::cin >> number;
                result = number * number * number;
                std::cout << "Cube of the number = " << result << "\n";
                break;
            }

            default:
                std::cout << "Invalid choice!\n";
                break;
        }

        std::cout << "Do you want to continue? (y/n): ";
        std::cin >> continueChoice;

    } while (continueChoice == 'y' || continueChoice == 'Y');

    return 0;
}

