class ListenerNode : public rclcpp::Node
{
public:
  ListenerNode()
  : Node("minimal_subscriber")
  {
    // Create subscription with a lambda wrapper to bind the callback
    subscription_ = this->create_subscription<std_msgs::msg::String>(
      "topic", 
      10, 
      [this](const std_msgs::msg::String::SharedPtr msg) -> void {
        this->message_handler(msg);
      });
  }

private:
  // Helper method to process incoming messages
  void message_handler(const std_msgs::msg::String::SharedPtr msg) const
  {
    RCLCPP_INFO(this->get_logger(), "I heard: '%s'", msg->data.c_str());
  }

  rclcpp::Subscription<std_msgs::msg::String>::SharedPtr subscription_;
};

int main(int argc, char * argv[])
{
  // Initialize ROS 2 communication
  rclcpp::init(argc, argv);

  // Create node instance and spin it
  auto node = std::make_shared<ListenerNode>();
  rclcpp::spin(node);

  // Clean shutdown
  rclcpp::shutdown();
  return 0;
}

