// Helper macros for symbol name prefixing
#define _STRINGIFY2_(x) #x
#define _STRINGIFY_(x) _STRINGIFY2_(x)
#define GOSYM_PREFIX _STRINGIFY_(__USER_LABEL_PREFIX__)

// Structure to hold syscall return value and error code
struct syscall_result {
    uintptr_t value;
    uintptr_t error_code;
};

// Wrapper function that captures both result and errno
syscall_result gccgoRealSyscall(uintptr_t syscall_num,
                                uintptr_t arg1, uintptr_t arg2, uintptr_t arg3,
                                uintptr_t arg4, uintptr_t arg5, uintptr_t arg6,
                                uintptr_t arg7, uintptr_t arg8, uintptr_t arg9)
    __asm__(GOSYM_PREFIX GOPKGPATH ".realSyscall");

syscall_result
gccgoRealSyscall(uintptr_t syscall_num,
                 uintptr_t arg1, uintptr_t arg2, uintptr_t arg3,
                 uintptr_t arg4, uintptr_t arg5, uintptr_t arg6,
                 uintptr_t arg7, uintptr_t arg8, uintptr_t arg9)
{
    syscall_result result;
    errno = 0;
    result.value = syscall(syscall_num, arg1, arg2, arg3, arg4, arg5, arg6, arg7, arg8, arg9);
    result.error_code = errno;
    return result;
}

// Wrapper function that returns only the syscall result (no error info)
uintptr_t gccgoRealSyscallNoError(uintptr_t syscall_num,
                                  uintptr_t arg1, uintptr_t arg2, uintptr_t arg3,
                                  uintptr_t arg4, uintptr_t arg5, uintptr_t arg6,
                                  uintptr_t arg7, uintptr_t arg8, uintptr_t arg9)
    __asm__(GOSYM_PREFIX GOPKGPATH ".realSyscallNoError");

uintptr_t
gccgoRealSyscallNoError(uintptr_t syscall_num,
                        uintptr_t arg1, uintptr_t arg2, uintptr_t arg3,
                        uintptr_t arg4, uintptr_t arg5, uintptr_t arg6,
                        uintptr_t arg7, uintptr_t arg8, uintptr_t arg9)
{
    return syscall(syscall_num, arg1, arg2, arg3, arg4, arg5, arg6, arg7, arg8, arg9);
}

