#include "Misc/AutomationTest.h"

BEGIN_DEFINE_SPEC(AutomationSpec, "System.Automation.Spec", EAutomationTestFlags::EngineFilter | EAutomationTestFlags::ApplicationContextMask)
	bool bCondition;
	FString ExecutionSequence; 
END_DEFINE_SPEC

void AutomationSpec::Define()
{
	Describe("A Describe 1", [this]()
	{
		It("contains a spec with an expectation", [this]()
		{
			bCondition = true;
			TestEqual("bCondition", bCondition, true);
		});
	});

	Describe("A Describe 2", [this]()
	{
		BeforeEach([&]()
		{
			bCondition = false;
		});
		xIt("will not run disabled specs", [this]()
		{
			TestEqual("bCondition", bCondition, true);
		});
		xDescribe("with disabled nested Describes", [this]()
		{
			It("will not run specs within those Describes", [this]()
			{
				TestEqual("bCondition", bCondition, true);
			});
		});
	});

	Describe("A spec using BeforeEach and AfterEach", [this]()
	{
		BeforeEach([this]()
		{
			ExecutionSequence = TEXT("A");
		});
		It("will run code before each spec in the Describe and after each spec in the Describe", [this]()
		{
			TestEqual("ExecutionSequence", ExecutionSequence, TEXT("A"));
		});
		AfterEach([this]()
		{
			ExecutionSequence += TEXT("Z");
			TestEqual("ExecutionSequence", ExecutionSequence, TEXT("AZ"));
		});
	});

	Describe("Another spec using BeforeEach and AfterEach", [this]()
	{
		AfterEach([this]()
		{
			ExecutionSequence += TEXT("Z");
			TestEqual("ExecutionSequence", ExecutionSequence, TEXT("ABYZ"));
		});
		Describe("while nested inside another Describe", [this]()
		{
			It("will run all BeforeEach blocks and all AfterEach blocks", [this]()
			{
				TestEqual("ExecutionSequence", ExecutionSequence, TEXT("AB"));
			});
			AfterEach([this]()
			{
				ExecutionSequence += TEXT("Y");
			});
			BeforeEach([this]()
			{
				ExecutionSequence += TEXT("B");
			});
		});
		BeforeEach([this]()
		{
			ExecutionSequence = TEXT("A");
		});
	});

	Describe("Third spec using BeforeEach and AfterEach", [this]()
	{
		BeforeEach([this]()
		{
			ExecutionSequence = TEXT("A");
		});
		AfterEach([this]()
		{
			ExecutionSequence += TEXT("Z");
			TestEqual("ExecutionSequence", ExecutionSequence, TEXT("ABCDXYZ"));
		});
		BeforeEach([this]()
		{
			ExecutionSequence += TEXT("B");
		});
		Describe("while nested inside another Describe", [this]()
		{
			AfterEach([this]()
			{
				ExecutionSequence += TEXT("Y");
			});
			BeforeEach([this]()
			{
				ExecutionSequence += TEXT("C");
			});
			Describe("while nested inside yet another Describe", [this]()
			{
				It("will run all BeforeEach blocks and all AfterEach blocks", [this]()
				{
					TestEqual("ExecutionSequence", ExecutionSequence, TEXT("ABCD"));
				});
				AfterEach([this]()
				{
					ExecutionSequence += TEXT("X");
				});
				BeforeEach([this]()
				{
					ExecutionSequence += TEXT("D");
				});
			});
		});
	});
}

