/// @test
/// Verify that adding a subscriber before any object exists results in empty interest maps
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, processANewRemoteSubscriptionWhenThereAreNoObjects_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;

  handler.addSubscriber(InterestId{42}, &participant, true);

  const auto& remotesBM = handler.remotesUpdatesBMMap;
  const auto& remoteToInterests = handler.remotesToInterestsUpdatesMap;
  const auto& remoteInterests = handler.remotesInterestsBMMap;

  ASSERT_EQ(remotesBM.size<RemoteParticipant*>(), 0u);
  ASSERT_EQ(remoteToInterests.size(), 0u);
  ASSERT_TRUE(remoteInterests.contains(&participant));
}

/// @test
/// Ensure addObject correctly registers updates when a subscriber already exists
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, processANewObjectWhenASubscriberWasAdded_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;

  handler.addSubscriber(InterestId{7}, &participant);
  handler.addObject(InterestId{7}, &update);

  const auto* objPtr = handler.interestsUpdatesBMMap.tryGet(InterestId{7});
  const auto* remPtr = handler.remotesUpdatesBMMap.tryGet(&participant);

  ASSERT_NE(nullptr, objPtr);
  ASSERT_NE(nullptr, remPtr);
  EXPECT_EQ(handler.remotesToInterestsUpdatesMap.size(), 1u);
}

/// @test
/// Validate handling of multiple objects under same interest ID with one subscriber
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, processTwoObjectWhenASubscriberWasAdded_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate objA;
  ObjectUpdate objB;

  handler.addSubscriber(InterestId{10}, &participant);
  handler.addObject(InterestId{10}, &objA);
  handler.addObject(InterestId{10}, &objB);

  const auto* updatesForInterest = handler.interestsUpdatesBMMap.tryGet(InterestId{10});
  const auto* updatesForRemote = handler.remotesUpdatesBMMap.tryGet(&participant);

  ASSERT_NE(nullptr, updatesForInterest);
  ASSERT_NE(nullptr, updatesForRemote);
  EXPECT_EQ(updatesForInterest->size(), 2u);
  EXPECT_EQ(updatesForRemote->size(), 2u);
}

/// @test
/// Confirm subscription registration after object addition (reverse order)
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, registersANewRemoteSubscriptionAfterObjectWasAdded_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;

  handler.addObject(InterestId{15}, &update);
  handler.addSubscriber(InterestId{15}, &participant);

  const auto& remoteMap = handler.remotesUpdatesBMMap;
  const auto& interestMap = handler.remotesToInterestsUpdatesMap;

  EXPECT_TRUE(remoteMap.contains(&participant));
  EXPECT_TRUE(interestMap.at(&participant).contains(InterestId{15}));
}

/// @test
/// Test dual-subscriber scenario after object registration
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, registersTwoSubscriptionsAfterObjectWasAdded_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant p1;
  RemoteParticipant p2;
  ObjectUpdate update;

  handler.addObject(InterestId{20}, &update);
  handler.addSubscriber(InterestId{20}, &p1);
  handler.addSubscriber(InterestId{20}, &p2);

  EXPECT_EQ(handler.remotesUpdatesBMMap.size<RemoteParticipant*>(), 2u);
  EXPECT_EQ(handler.remotesToInterestsUpdatesMap.size(), 2u);
}

/// @test
/// Check cleanup of all interest-related structures upon subscriber removal
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, removesSubscriptionWithUpdates_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;

  handler.addObject(InterestId{25}, &update);
  handler.addSubscriber(InterestId{25}, &participant);
  handler.removeSubscriber(InterestId{25}, &participant);

  EXPECT_TRUE(handler.remotesUpdatesBMMap.empty());
  EXPECT_TRUE(handler.remotesToInterestsUpdatesMap.empty());
}

/// @test
/// Ensure remaining subscribers retain interest data after one subscriber removal
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, keepsTheObjectInterestWhenAInterestedSubscriptionRemains_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant sub1;
  RemoteParticipant sub2;
  ObjectUpdate update;

  handler.addObject(InterestId{30}, &update);
  handler.addSubscriber(InterestId{30}, &sub1);
  handler.addSubscriber(InterestId{30}, &sub2);
  handler.removeSubscriber(InterestId{30}, &sub1);

  EXPECT_TRUE(handler.remotesUpdatesBMMap.contains(&sub2));
  EXPECT_FALSE(handler.remotesUpdatesBMMap.contains(&sub1));
  EXPECT_EQ(handler.remotesToInterestsUpdatesMap.size(), 1u);
  EXPECT_TRUE(handler.interestsUpdatesBMMap.contains(InterestId{30}));
}

/// @test
/// Verify complete deregistration of all interest mappings after object removal
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, deregistersObjectAfterObjectRemoval_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant s1;
  RemoteParticipant s2;
  ObjectUpdate obj;

  handler.addObject(InterestId{35}, &obj);
  handler.addSubscriber(InterestId{35}, &s1);
  handler.addSubscriber(InterestId{35}, &s2);
  handler.removeObject(&obj);

  EXPECT_TRUE(handler.remotesUpdatesBMMap.empty());
  EXPECT_TRUE(handler.remotesToInterestsUpdatesMap.empty());
  EXPECT_TRUE(handler.interestsUpdatesBMMap.empty());
}

/// @test
/// Confirm partial object removal leaves correct state for remaining objects
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, deregistersOneOfTwoObjectFromInterestedRemotes_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant r1;
  RemoteParticipant r2;
  ObjectUpdate o1;
  ObjectUpdate o2;

  handler.addObject(InterestId{40}, &o1);
  handler.addObject(InterestId{40}, &o2);
  handler.addSubscriber(InterestId{40}, &r1);
  handler.addSubscriber(InterestId{40}, &r2);

  {
    const auto* ptr = handler.interestsUpdatesBMMap.tryGet(InterestId{40});
    ASSERT_NE(nullptr, ptr);
    EXPECT_EQ(ptr->size(), 2u);
  }

  handler.removeObject(&o1);

  EXPECT_EQ(handler.remotesUpdatesBMMap.size<RemoteParticipant*>(), 2u);
  EXPECT_EQ(handler.remotesToInterestsUpdatesMap.size(), 2u);

  {
    const auto* ptr = handler.interestsUpdatesBMMap.tryGet(InterestId{40});
    ASSERT_NE(nullptr, ptr);
    EXPECT_EQ(ptr->size(), 1u);
  }
}

/// @test
/// Validate multiple interests referencing same object
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, registerTwoInterestsToTheSameObject_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;

  handler.addObject(InterestId{50}, &update);
  handler.addObject(InterestId{51}, &update);
  handler.addSubscriber(InterestId{50}, &participant);
  handler.addSubscriber(InterestId{51}, &participant);

  auto& registered = handler.remotesToInterestsUpdatesMap.at(&participant);
  EXPECT_TRUE(registered.contains(InterestId{50}));
  EXPECT_TRUE(registered.contains(InterestId{51}));
}

/// @test
/// Ensure object remains registered if at least one interest persists
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, keepsObjectForRemoteWhenAInterestRemains_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;

  handler.addObject(InterestId{60}, &update);
  handler.addObject(InterestId{61}, &update);
  handler.addSubscriber(InterestId{60}, &participant);
  handler.addSubscriber(InterestId{61}, &participant);
  handler.removeSubscriber(InterestId{60}, &participant);

  auto& registered = handler.remotesToInterestsUpdatesMap.at(&participant);
  EXPECT_TRUE(registered.contains(InterestId{61}));
  EXPECT_FALSE(registered.contains(InterestId{60}));
  EXPECT_TRUE(handler.remotesUpdatesBMMap.contains(&update));
}

/// @test
/// Confirm full cleanup after all interests removed from a remote
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, deregisterObjectForRemoteAfterNoInterestsRemain_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;

  handler.addObject(InterestId{70}, &update);
  handler.addObject(InterestId{71}, &update);
  handler.addSubscriber(InterestId{70}, &participant);
  handler.addSubscriber(InterestId{71}, &participant);
  handler.removeSubscriber(InterestId{70}, &participant);
  handler.removeSubscriber(InterestId{71}, &participant);

  EXPECT_TRUE(handler.remotesUpdatesBMMap.empty());
  EXPECT_TRUE(handler.remotesToInterestsUpdatesMap.empty());
}

/// @test
/// Full cleanup including remote's interest map when entire remote is removed
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, deregistersRemoteAndItsReferencesWhenRemoved_Variant)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate obj1;
  ObjectUpdate obj2;

  handler.addObject(InterestId{80}, &obj1);
  handler.addObject(InterestId{81}, &obj2);
  handler.addSubscriber(InterestId{80}, &participant);
  handler.addSubscriber(InterestId{81}, &participant);
  handler.removeSubscriber(&participant);

  EXPECT_TRUE(handler.remotesUpdatesBMMap.empty());
  EXPECT_TRUE(handler.remotesToInterestsUpdatesMap.empty());
  EXPECT_TRUE(handler.remotesInterestsBMMap.empty());
  EXPECT_FALSE(handler.interestsUpdatesBMMap.empty());
}

