// Unit tests for DebugInfo class functionality
TEST(DebugInfoTest, Empty) {
    DebugInfo info;
    EXPECT_FALSE(info.is_valid());
    EXPECT_EQ(info.get_filename(), "");
    EXPECT_EQ(info.get_start_line(), 0);
    EXPECT_EQ(info.get_start_column(), 0);
    EXPECT_EQ(info.get_end_line(), 0);
    EXPECT_EQ(info.get_end_column(), 0);
}

TEST(DebugInfoTest, Basic) {
    DebugInfo info("example.cpp", 10, 2, 20, 4);
    EXPECT_TRUE(info.is_valid());
    EXPECT_EQ(info.get_filename(), "example.cpp");
    EXPECT_EQ(info.get_start_line(), 10);
    EXPECT_EQ(info.get_start_column(), 2);
    EXPECT_EQ(info.get_end_line(), 20);
    EXPECT_EQ(info.get_end_column(), 4);
}

TEST(DebugInfoTest, Merge_Left) {
    DebugInfo left_info;
    DebugInfo right_info("example.cpp", 10, 2, 20, 4);
    auto combined = DebugInfo::combine(left_info, right_info);
    EXPECT_TRUE(combined.is_valid());
    EXPECT_EQ(combined.get_filename(), "example.cpp");
    EXPECT_EQ(combined.get_start_line(), 10);
    EXPECT_EQ(combined.get_start_column(), 2);
    EXPECT_EQ(combined.get_end_line(), 20);
    EXPECT_EQ(combined.get_end_column(), 4);
}

TEST(DebugInfoTest, Merge_Right) {
    DebugInfo right_info;
    DebugInfo left_info("example.cpp", 10, 2, 20, 4);
    auto combined = DebugInfo::combine(left_info, right_info);
    EXPECT_TRUE(combined.is_valid());
    EXPECT_EQ(combined.get_filename(), "example.cpp");
    EXPECT_EQ(combined.get_start_line(), 10);
    EXPECT_EQ(combined.get_start_column(), 2);
    EXPECT_EQ(combined.get_end_line(), 20);
    EXPECT_EQ(combined.get_end_column(), 4);
}

TEST(DebugInfoTest, Merge_BothNonEmpty) {
    DebugInfo left_info("example.cpp", 10, 2, 20, 4);
    DebugInfo right_info("example.cpp", 15, 3, 25, 5);
    auto combined = DebugInfo::combine(left_info, right_info);
    EXPECT_TRUE(combined.is_valid());
    EXPECT_EQ(combined.get_filename(), "example.cpp");
    EXPECT_EQ(combined.get_start_line(), 10);
    EXPECT_EQ(combined.get_start_column(), 2);
    EXPECT_EQ(combined.get_end_line(), 25);
    EXPECT_EQ(combined.get_end_column(), 5);
}

TEST(DebugInfoTest, Merge_ReverseOrder) {
    DebugInfo right_info("example.cpp", 10, 2, 20, 4);
    DebugInfo left_info("example.cpp", 15, 3, 25, 5);
    auto combined = DebugInfo::combine(left_info, right_info);
    EXPECT_TRUE(combined.is_valid());
    EXPECT_EQ(combined.get_filename(), "example.cpp");
    EXPECT_EQ(combined.get_start_line(), 10);
    EXPECT_EQ(combined.get_start_column(), 2);
    EXPECT_EQ(combined.get_end_line(), 25);
    EXPECT_EQ(combined.get_end_column(), 5);
}

