#include <iostream>
#include <string>
#include <stdio.h>
#include "stringwrapper.h"
#ifdef OLD_WPDS_INDICES
#   include "wpds.h"
#else
#   include "WPDS.h"
#endif

int main() {
    using namespace wpds;

    // Initialize semirings: one for forward analysis, one for reverse (dual)
    Semiring<StringWrapper> srForward(StringWrapper::one());
    Semiring<StringWrapper> srReverse(StringWrapper::one(), false);

    // Construct two WPDS instances
    WPDS<StringWrapper> wpdsFwd(srForward);
    WPDS<StringWrapper> wpdsRev(srForward);  // Note: same semiring type as forward for simplicity

    // Build context automata for reachability/analysis
    CA<StringWrapper> caFwd(srForward);
    CA<StringWrapper> caRev(srForward);

    /* Define symbols/states for first WPDS */
    wpds_key_t stateP      = str2key("p");
    wpds_key_t symLambda   = str2key("lambda");
    wpds_key_t symAccept   = str2key("accept");
    wpds_key_t symA        = str2key("A");
    wpds_key_t symB        = str2key("B");
    wpds_key_t symC        = str2key("C");
    wpds_key_t symD        = str2key("D");

    /* Add rules to forward WPDS */
    wpdsFwd.add_rule(stateP, symLambda, stateP, symA, new StringWrapper("a"));
    wpdsFwd.add_rule(stateP, symA,      stateP, symB, new StringWrapper("b"));
    wpdsFwd.add_rule(stateP, symB,      stateP, symC, new StringWrapper("c"));
    wpdsFwd.add_rule(stateP, symC,      stateP, symD, new StringWrapper("d"));
    wpdsFwd.add_rule(stateP, symA,      stateP, symA, symB, new StringWrapper("w"));

    /* Define symbols/states for second (reverse) WPDS */
    wpds_key_t statePPrime = str2key("p'");
    wpds_key_t symX        = str2key("x");
    wpds_key_t symXPrime   = str2key("x'");
    wpds_key_t symX2Prime  = str2key("x''");

    /* Add rules to reverse WPDS */
    wpdsRev.add_rule(statePPrime, symX,       stateP,     symA, StringWrapper::one());
    wpdsRev.add_rule(statePPrime, symXPrime,  statePPrime, symX, symB, StringWrapper::one());
    wpdsRev.add_rule(statePPrime, symX2Prime, statePPrime, symXPrime, symB, StringWrapper::one());

    /* Set up initial condition: accept state has weight 1 */
    caFwd.add(stateP, symLambda, symAccept, StringWrapper::one());

    std::cout << "accept's weight is ";
    // caFwd.state_weight(symAccept)->print(std::cout) << std::endl;

    std::cout << wpdsFwd << std::endl << std::endl;
    std::cout << "*** BEFORE ***\n" << caFwd << std::endl;

    // Compute post* image under wpdsFwd
    CA<StringWrapper> caAfterPost = poststar<StringWrapper>(wpdsFwd, caFwd, srForward);
    std::cout << "*** AFTER  ***\n" << caAfterPost << std::endl;

    // Compute pre* image under wpdsRev using dual semiring
    CA<StringWrapper> caAfterPre = prestar<StringWrapper>(wpdsRev, caAfterPost, srReverse);

    // Query specific configuration: (statePPrime, symX2Prime, symAccept)
    CA<StringWrapper>::catrans_t goalTransition = caAfterPre.find(statePPrime, symX2Prime, symAccept);

    std::cout << "\n\n AFTER PRESTAR ON WPDS2\n" << caAfterPre << std::endl;
    // Output transition weight if found
    if (goalTransition) {
        goalTransition->print(std::cout) << std::endl;
    }

#if 1
    // Augment final automaton with accept state explicitly
    caAfterPre.add_final_state(symAccept);

    std::cout << "Calling path_summary...\n";

    // Restrict summary to paths involving 'symB'
    std::set<wpds_key_t> relevantRules;
    relevantRules.insert(symB);

    caAfterPre.path_summary(relevantRules);

    std::cout << "accept's weight is ";
    caAfterPre.state_weight(symAccept)->print(std::cout) << std::endl;

    std::cout << "p's weight is ";
    caAfterPre.state_weight(stateP)->print(std::cout) << std::endl;
#endif

    return 0;
}

