using namespace Valdi;

namespace {
// Test initialization with a single package component
TEST(FullyQualifiedName, canInitWithSinglePackage) {
    Protobuf::FullyQualifiedName fq_name("com");
    EXPECT_EQ("", fq_name.getLeadingComponents());
    EXPECT_EQ("com", fq_name.getLastComponent());
}

// Test initialization with nested packages and type names
TEST(FullyQualifiedName, canInitWithNestedPackage) {
    Protobuf::FullyQualifiedName fq_name("com.valdi");
    EXPECT_EQ("com", fq_name.getLeadingComponents());
    EXPECT_EQ("valdi", fq_name.getLastComponent());

    fq_name = Protobuf::FullyQualifiedName("com.valdi.MyType");
    EXPECT_EQ("com.valdi", fq_name.getLeadingComponents());
    EXPECT_EQ("MyType", fq_name.getLastComponent());
}

// Test appending components to an existing fully qualified name
TEST(FullyQualifiedName, canAppend) {
    Protobuf::FullyQualifiedName fq_name;
    EXPECT_EQ("", fq_name.getLeadingComponents());
    EXPECT_EQ("", fq_name.getLastComponent());

    fq_name.append("com");
    EXPECT_EQ("", fq_name.getLeadingComponents());
    EXPECT_EQ("com", fq_name.getLastComponent());

    fq_name.append("valdi");
    EXPECT_EQ("com", fq_name.getLeadingComponents());
    EXPECT_EQ("valdi", fq_name.getLastComponent());

    fq_name.append("nested.MyType");
    EXPECT_EQ("com.valdi.nested", fq_name.getLeadingComponents());
    EXPECT_EQ("MyType", fq_name.getLastComponent());
}

// Test removal of the last component from a fully qualified name
TEST(FullyQualifiedName, canRemoveLastComponent) {
    Protobuf::FullyQualifiedName fq_name("com.valdi.MyType");
    EXPECT_EQ("com.valdi", fq_name.getLeadingComponents());
    EXPECT_EQ("MyType", fq_name.getLastComponent());
    EXPECT_TRUE(fq_name.canRemoveLastComponent());

    fq_name = fq_name.removingLastComponent();
    EXPECT_EQ("com", fq_name.getLeadingComponents());
    EXPECT_EQ("valdi", fq_name.getLastComponent());
    EXPECT_TRUE(fq_name.canRemoveLastComponent());

    fq_name = fq_name.removingLastComponent();
    EXPECT_EQ("", fq_name.getLeadingComponents());
    EXPECT_EQ("com", fq_name.getLastComponent());
    EXPECT_FALSE(fq_name.canRemoveLastComponent());
}

// Test string representation of fully qualified names
TEST(FullyQualifiedName, canOutputAsString) {
    Protobuf::FullyQualifiedName fq_name("com.valdi.MyType");
    EXPECT_EQ("com.valdi.MyType", fq_name.toString());

    fq_name = Protobuf::FullyQualifiedName("MyType");
    EXPECT_EQ("MyType", fq_name.toString());
}
