// Mapping for OffloadYAML::Binary structure
void MappingTraits<OffloadYAML::Binary>::mapping(
    IO &IO, OffloadYAML::Binary &Bin) {
  assert(!IO.getContext() && "IO context already set");
  IO.setContext(&Bin);
  IO.mapTag("!Offload", true);
  IO.mapOptional("Version", Bin.Version);
  IO.mapOptional("Size", Bin.Size);
  IO.mapOptional("EntryOffset", Bin.EntryOffset);
  IO.mapOptional("EntrySize", Bin.EntrySize);
  IO.mapRequired("Members", Bin.Members);
  IO.setContext(nullptr);
}

// Mapping for StringEntry (key-value pair)
void MappingTraits<OffloadYAML::Binary::StringEntry>::mapping(
    IO &IO, OffloadYAML::Binary::StringEntry &Entry) {
  assert(IO.getContext() && "IO context not initialized");
  IO.mapRequired("Key", Entry.Key);
  IO.mapRequired("Value", Entry.Value);
}

// Mapping for Member (individual offload binary component)
void MappingTraits<OffloadYAML::Binary::Member>::mapping(
    IO &IO, OffloadYAML::Binary::Member &Member) {
  assert(IO.getContext() && "IO context not initialized");
  IO.mapOptional("ImageKind", Member.ImageKind);
  IO.mapOptional("OffloadKind", Member.OffloadKind);
  IO.mapOptional("Flags", Member.Flags);
  IO.mapOptional("String", Member.StringEntries);
  IO.mapOptional("Content", Member.Content);
}

