#include "autolink/transport/common/identity.hpp"
#include "gtest/gtest.h"

namespace autolink {
namespace transport {

// Test that an Identity constructed with false yields zero hash and string "0"
TEST(IdentityTest, ConstructWithFalse) {
  Identity id(false);
  ASSERT_EQ(id.HashValue(), static_cast<uint64_t>(0));
  ASSERT_STREQ(id.ToString().c_str(), "0");
}

// Test that an Identity constructed with true yields non-zero hash and non-"0" string
TEST(IdentityTest, ConstructWithTrue) {
  Identity id(true);
  ASSERT_NE(id.HashValue(), static_cast<uint64_t>(0));
  ASSERT_STRNE(id.ToString().c_str(), "0");
}

// Test identity object equality semantics: distinct default instances differ,
// copy assignment and copy construction preserve equality
TEST(IdentityTest, EqualitySemantics) {
  Identity a;
  Identity b;
  Identity c;

  // All default-constructed identities should be pairwise unequal
  EXPECT_FALSE(a == b);
  EXPECT_FALSE(b == c);
  EXPECT_FALSE(a == c);

  // Hash values should also differ
  EXPECT_NE(a.HashValue(), c.HashValue());

  // Self-assignment should not change behavior
  b = b;
  EXPECT_FALSE(b == c);

  // Assignment from another identity should make them equal
  b = c;
  EXPECT_TRUE(b == c);

  // Copy construction should yield identical identity
  Identity d(a);
  EXPECT_TRUE(a == d);
  EXPECT_STREQ(a.ToString().c_str(), d.ToString().c_str());
  EXPECT_EQ(a.HashValue(), d.HashValue());
}

// Test operator= and data manipulation for identity objects
TEST(IdentityTest, AssignmentAndDataHandling) {
  Identity src(true);
  Identity dst(false);

  // Assign src to dst; they should now match
  dst = src;
  EXPECT_EQ(src.HashValue(), dst.HashValue());
  EXPECT_STREQ(src.ToString().c_str(), dst.ToString().c_str());
  EXPECT_EQ(src.Length(), dst.Length());

  // Clear src's internal data and create new identity from it
  src.set_data(nullptr);
  Identity third;
  third.set_data(src.data());

  // After clearing, src and dst no longer match, but third matches dst
  EXPECT_EQ(third.HashValue(), dst.HashValue());
  EXPECT_STREQ(third.ToString().c_str(), dst.ToString().c_str());
  EXPECT_EQ(dst.Length(), third.Length());
}

