// Helper function to perform composition with optional output display list capture
static CompositorPlaneList executeComposition(DisplayListBuilder& builder,
                                              Ref<DisplayList>* outputRef = nullptr) {
    CompositorPlaneList planeList;
    Compositor compositor(ConsoleLogger::getLogger());
    auto generatedDisplayList = compositor.performComposition(*builder.displayList, planeList);

    if (outputRef != nullptr) {
        *outputRef = std::move(generatedDisplayList);
    }

    return planeList;
}

// Test: No external surfaces means single drawable layer
TEST(Compositor, doesNothingWhenNoExternalSurfacesArePresent) {
    DisplayListBuilder builder(100, 100);
    builder.context(Vector(0, 0), 1.0, [&]() {
        builder.rectangle(Size(50, 50), 1.0);
        builder.context(Vector(25, 25), 1.0, [&]() { builder.rectangle(Size(10, 10), 1.0); });
        builder.context(Vector(35, 35), 1.0, [&]() { builder.rectangle(Size(50, 50), 1.0); });
        builder.rectangle(Size(25, 25), 1.0);
    });

    Ref<DisplayList> capturedList;
    auto resultPlanes = executeComposition(builder, &capturedList);

    ASSERT_EQ(static_cast<size_t>(1), resultPlanes.getPlanesCount());
    ASSERT_EQ(CompositorPlaneTypeDrawable, resultPlanes.getPlaneAtIndex(0).getType());
    ASSERT_TRUE(resultPlanes.getPlaneAtIndex(0).getExternalSurface() == nullptr);
    ASSERT_EQ(builder.displayList, capturedList);
}

// Test: Single external surface creates dedicated layer
TEST(Compositor, emitsDedicatedLayerWhenAnExternalSurfaceIsPresent) {
    DisplayListBuilder builder(100, 100);
    builder.context(Vector(0, 0), 1.0, [&]() {
        builder.rectangle(Size(50, 50), 1.0);
        builder.context(Vector(25, 25), 1.0, [&]() { builder.rectangle(Size(10, 10), 1.0); });
        builder.context(Vector(35, 35), 1.0, [&]() { builder.rectangle(Size(50, 50), 1.0); });
        builder.rectangle(Size(25, 25), 1.0);
        builder.externalSurface(Size(50, 50), 1.0);
    });

    auto resultPlanes = executeComposition(builder);
    ASSERT_EQ(static_cast<size_t>(2), resultPlanes.getPlanesCount());
    ASSERT_EQ(CompositorPlaneTypeDrawable, resultPlanes.getPlaneAtIndex(0).getType());
    ASSERT_EQ(CompositorPlaneTypeExternal, resultPlanes.getPlaneAtIndex(1).getType());
    ASSERT_TRUE(resultPlanes.getPlaneAtIndex(1).getExternalSurface() != nullptr);
}

// Test: External surface display state resolution with nested transforms
TEST(Compositor, resolvesDisplayStateOfExternalSurface) {
    DisplayListBuilder builder(100, 100);
    builder.context(Vector(0, 0), 1.0, [&]() {
        builder.context(Vector(10, 20), 0.75, [&]() {
            builder.context(Vector(0, 0), 1.0, [&]() {
                builder.context(Vector(30, 40), 0.5, [&]() { builder.externalSurface(Size(50, 50), 0.25); });
            });
        });
    });

    auto resultPlanes = executeComposition(builder);
    ASSERT_EQ(static_cast<size_t>(1), resultPlanes.getPlanesCount());

    const auto& plane = resultPlanes.getPlaneAtIndex(0);
    ASSERT_EQ(CompositorPlaneTypeExternal, plane.getType());
    ASSERT_TRUE(plane.getExternalSurface() != nullptr);

