#include <iostream>
#include "sophus/geometry.hpp"

int main() {
  // Compute the combined rotation from three elementary rotations
  const double pi = Sophus::Constants<double>::pi();

  // Define individual rotations around coordinate axes
  Sophus::SO3d Rx = Sophus::SO3d::rotX(pi / 4.0);
  Sophus::SO3d Ry = Sophus::SO3d::rotY(pi / 6.0);
  Sophus::SO3d Rz = Sophus::SO3d::rotZ(-pi / 3.0);

  std::cout << "Elementary rotation matrices:" << std::endl;
  std::cout << "Rx (x-axis, 45 degrees):\n" << Rx.matrix() << std::endl;
  std::cout << "Ry (y-axis, 30 degrees):\n" << Ry.matrix() << std::endl;
  std::cout << "Rz (z-axis, -60 degrees):\n" << Rz.matrix() << std::endl;

  // Compose rotations: first z, then y, then x
  Sophus::SO3d R_total = Rx * Ry * Rz;
  std::cout << "\nCombined rotation R = Rx * Ry * Rz:\n" 
            << R_total.matrix() << std::endl;

  // Demonstrate action on a vector
  Eigen::Vector3d point(0.0, 0.0, 1.0);
  std::cout << "\nVector transformation demonstration:" << std::endl;
  std::cout << "Original vector: [" << point.transpose() << "]" << std::endl;

  // Apply rotations sequentially vs. as composition
  Eigen::Vector3d result_sequential = Rx * (Ry * (Rz * point));
  Eigen::Vector3d result_composed = R_total * point;

  std::cout << "After Rz -> Ry -> Rx: [" << result_sequential.transpose() << "]" << std::endl;
  std::cout << "After combined R:     [" << result_composed.transpose() << "]" << std::endl;

  // Show internal representation
  std::cout << "\nSO(3) internal representation:" << std::endl;
  std::cout << "Matrix form of Rx:\n" << Rx.matrix() << std::endl;
  std::cout << "Quaternion form of Rx (i, j, k, w): " 
            << Rx.unit_quaternion().coeffs().transpose() << std::endl;

  return 0;
}

