// Global verification routine
static void __verifyGlobalState(void)
{
    // Empty implementation - placeholder for future global checks
}

// CP-specific verification
static void __verifyCP(GXVtxFmt fmt)
{
    u32 nrmCnt = GET_REG_FIELD(__GXData->vatA[fmt], 1, 9);

    if (__gxVerify->verifyLevel >= GX_WARN_SEVERE)
    {
        if (__GXData->hasNrms && nrmCnt != 0)
        {
            if (__gxVerify->verifyLevel >= __getWarningLevel(GXWARN_INVALID_VTX_FMT))
            {
                __GX_WARNF(GXWARN_INVALID_VTX_FMT, "GX_NRM_XYZ");
            }
        }
        else if (__GXData->hasBiNrms && nrmCnt != 1)
        {
            if (__gxVerify->verifyLevel >= __getWarningLevel(GXWARN_INVALID_VTX_FMT))
            {
                __GX_WARNF(GXWARN_INVALID_VTX_FMT, "GX_NRM_NBT or GX_NRM_NBT3");
            }
        }
    }
}

// Main state verification dispatcher
void __GXVerifyState(GXVtxFmt vtxfmt)
{
    if (__gxVerify->verifyLevel != GX_WARN_NONE)
    {
        __verifyGlobalState();
        __verifyCP(vtxfmt);
        __GXVerifyXF();
        __GXVerifySU();
        __GXVerifyBUMP();
        __GXVerifyTEX();
        __GXVerifyTEV();
        __GXVerifyPE();
    }
}

// Immediate VAT verification
void __GXVerifyVATImm(GXAttr attr, GXCompCnt cnt, GXCompType type, u8 frac)
{
    if (__gxVerify->verifyLevel != GX_WARN_NONE)
    {
        // Check color formats
        if (attr == GX_VA_CLR0 || attr == GX_VA_CLR1)
        {
            switch (type)
            {
                case GX_RGB565:
                case GX_RGB8:
                case GX_RGBX8:
                    if (cnt != GX_CLR_RGB && __gxVerify->verifyLevel >= __getWarningLevel(GXWARN_VAT_MISMATCH))
                    {
                        __GX_WARNF(GXWARN_VAT_MISMATCH, "RGB format type", "GX_CLR_RGB");
                    }
                    break;
                case GX_RGBA4:
                case GX_RGBA6:
                case GX_RGBA8:
                    if (cnt != GX_CLR_RGBA && __gxVerify->verifyLevel >= __getWarningLevel(GXWARN_VAT_MISMATCH))
                    {
                        __GX_WARNF(GXWARN_VAT_MISMATCH, "RGBA format type", "GX_CLR_RGBA");
                    }
                    break;
            }
        }

        // Check fractional bits usage
        if (frac != 0)
        {
            if (attr == GX_VA_CLR0 || attr == GX_VA_CLR1)
            {
                if (__gxVerify->verifyLevel >= __getWarningLevel(GXWARN_VAT_CLR_FRAC))
                {
                    __GX_WARN(GXWARN_VAT_CLR_FRAC);
                }
            }
            else if (type == GX_F32)
            {
                if (__gxVerify->verifyLevel >= __getWarningLevel(GXWARN_VAT_F32_FRAC))
                {
                    __GX_WARN(GXWARN_VAT_F32_FRAC);
                }
            }
        }

        // Check normal formats
        if (attr == GX_VA_NRM || attr == GX_VA_NBT)
        {
            switch (type)
            {
                case GX_S8:
                    if (frac != 6 && __gxVerify->verifyLevel >= __getWarningLevel(GXWARN_VAT_NRM_FRAC))
                    {
                        __GX_WARNF(GXWARN_VAT_NRM_FRAC, "GX_S8", 6);
                    }
                    break;
                case GX_S16:
                    if (frac != 14 && __gxVerify->verifyLevel >= __getWarningLevel(GXWARN_VAT_NRM_FRAC))
                    {
                        __GX_WARNF(GXWARN_VAT_NRM_FRAC, "GX_S16", 14);
                    }
                    break;
                case GX_F32:
                    break;
                default:
                    if (__gxVerify->verifyLevel >= __getWarningLevel(GXWARN_VAT_NRM_TYPE))
                    {
                        __GX_WARN(GXWARN_VAT_NRM_TYPE);
                    }
                    break;
            }
        }
    }
}

// Set verification level
void GXSetVerifyLevel(GXWarningLevel level)
{
    __gxVerify->verifyLevel = level;
}

// Set verification callback
GXVerifyCallback GXSetVerifyCallback(GXVerifyCallback cb)
{
    GXVerifyCallback old_cb = __gxVerify->cb;
    __gxVerify->cb = cb;
    return old_cb;
}
