// Pre-load phase: deserialize resource directory name
void MiniLeaderboardDisplay::PrepareForLoad(BinStream &stream) {
    LOAD_REVS(stream)
    ASSERT_REVS(0, 0)
    UIComponent::PreLoad(stream);
    stream >> mResourceDir;
}

// Post-load phase: finalize loading and refresh display
void MiniLeaderboardDisplay::FinalizeLoad(BinStream &stream) {
    mResourceDir.PostLoad(nullptr);
    UIComponent::PostLoad(stream);
    TriggerRefresh();
}

// Rendering method — delegates to resource directory if available
void MiniLeaderboardDisplay::DrawShowing() {
    if (mResourceDir) {
        mResourceDir->SetWorldXfm(WorldXfm());
        mResourceDir->DrawShowing();
    } else {
        MILO_NOTIFY_ONCE("MiniLeaderboardDisplay: %s missing resource dir", Name());
    }
}

