namespace tooling
{
    void RouterHive_Init(py::module& mod)
    {
        using Hive_ptr = std::shared_ptr<RouterHive>;
        using Ctx_ptr = RouterHive::Context_ptr;
        using VisitorFunc = std::function<void(Ctx_ptr)>;

        py::class_<RouterHive, Hive_ptr>(mod, "RouterHive")
            .def(py::init<>())
            .def("AddRelay", &RouterHive::AddRelay)
            .def("AddClient", &RouterHive::AddClient)
            .def("StartRelays", &RouterHive::StartRelays)
            .def("StartClients", &RouterHive::StartClients)
            .def("StopAll", &RouterHive::StopRouters)

            // Wrapper for iterating over relays
            .def(
                "ForEachRelay",
                [](RouterHive& hive, VisitorFunc visitor) {
                    hive.ForEachRelay([&visitor](Ctx_ptr ctx) {
                        py::gil_scoped_acquire lock;
                        visitor(std::move(ctx));
                    });
                })

            // Wrapper for iterating over clients
            .def(
                "ForEachClient",
                [](RouterHive& hive, VisitorFunc visitor) {
                    hive.ForEachClient([&visitor](Ctx_ptr ctx) {
                        py::gil_scoped_acquire lock;
                        visitor(std::move(ctx));
                    });
                })

            // Wrapper for iterating over all routers (relays + clients)
            .def(
                "ForEachRouter",
                [](RouterHive& hive, VisitorFunc visitor) {
                    hive.ForEachRouter([&visitor](Ctx_ptr ctx) {
                        py::gil_scoped_acquire lock;
                        visitor(std::move(ctx));
                    });
                })

            .def("GetNextEvent", &RouterHive::GetNextEvent)
            .def("GetAllEvents", &RouterHive::GetAllEvents)
            .def("RelayConnectedRelays", &RouterHive::RelayConnectedRelays)
            .def("GetRelayRCs", &RouterHive::GetRelayRCs)
            .def("GetRelay", &RouterHive::GetRelay);
    }
}  // namespace tooling

