#include "urdf_parser/urdf_parser.h"
#include <fstream>
#include <iostream>

// Read URDF file and parse it repeatedly in a loop
int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <urdf_file>" << std::endl;
        return 1;
    }

    const char* filename = argv[1];

    while (true) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            std::cerr << "Failed to open file: " << filename << std::endl;
            break;
        }

        std::string content;
        std::string line;

        // Read file line by line and accumulate content
        while (std::getline(file, line)) {
            content += line + "\n";
        }

        file.close();

        // Parse the URDF content
        urdf::parseURDF(content);
    }

    return 0;
}

