#include <singleapplication.h>
#include "messagereceiver.h"
#include <QDebug>

int main(int argc, char *argv[])
{
    QCoreApplication core_app(argc, argv);

    // Initialize the single-instance manager with secondary instance support
    SingleApplication app_guard(argc, argv, true);

    MessageReceiver receiver;

    // Check if current instance is not the first one
    if (app_guard.isSecondary()) {
        // Send command line arguments to the primary instance
        QString message = core_app.arguments().join(" ");
        app_guard.sendMessage(message.toUtf8());

        qDebug() << "Application already running.";
        qDebug() << "Primary process ID:" << app_guard.primaryPid();
        qDebug() << "Primary user account:" << app_guard.primaryUser();

        return 0;
    } else {
        // Connect signal from single application to receiver slot
        QObject::connect(
            &app_guard,
            &SingleApplication::receivedMessage,
            &receiver,
            &MessageReceiver::handleReceivedMessage
        );
    }

    return core_app.exec();
}

