  }

  auto keys = IO.keys();
  if (std::find(keys.begin(), keys.end(), "Contents") != keys.end()) {
    C = std::make_shared<OutputSection>();
    C->ContentKind = Content::Kind::OutputSection;
  } else if (std::find(keys.begin(), keys.end(), "PostLTOFile") != keys.end()) {
    C = std::make_shared<InputBitcodeSection>();
    C->ContentKind = Content::Kind::InputSection;
  } else if (std::find(keys.begin(), keys.end(), "Origin") != keys.end()) {
    C = std::make_shared<InputSection>();
    C->ContentKind = Content::Kind::InputSection;
  } else if (std::find(keys.begin(), keys.end(), "Padding") != keys.end()) {
    C = std::make_shared<Padding>();
    C->ContentKind = Content::Kind::Padding;
  } else if (std::find(keys.begin(), keys.end(), "LinkerScript") != keys.end()) {
    C = std::make_shared<LinkerScriptRule>();
    C->ContentKind = Content::Kind::LinkerScriptRule;
  } else {
    C = std::make_shared<Assignment>();
    C->ContentKind = Content::Kind::Assignment;
  }
  C->mapping(IO);
}

void LoadRegion::mapping(IO &IO) {
  MappingTraits<LoadRegion>::mapping(IO, *this);
}

void MappingTraits<LoadRegion>::mapping(IO &IO, LoadRegion &LR) {
  IO.mapOptional("Name", LR.SegmentName);
  IO.mapRequired("Type", LR.Type);
  IO.mapRequired("Permissions", LR.SegPermission);
  IO.mapRequired("FileOffset", LR.FileOffset);
  IO.mapRequired("VirtualAddress", LR.VirtualAddress);
  IO.mapRequired("PhysicalAddress", LR.PhysicalAddress);
  IO.mapRequired("FileSize", LR.FileSize);
  IO.mapRequired("MemorySize", LR.MemorySize);
  IO.mapRequired("Alignment", LR.Alignment);
  IO.mapOptional("Sections", LR.Sections);
}

void CRef::mapping(IO &IO) {
  MappingTraits<CRef>::mapping(IO, *this);
}

void MappingTraits<CRef>::mapping(IO &IO, CRef &CR) {
  IO.mapRequired("Symbol", CR.SymbolName);
  IO.mapRequired("ReferencedBy", CR.FileRefs);
}

void ScalarBitSetTraits<SegmentType>::bitset(IO &IO, SegmentType &ST) {
  using namespace llvm::ELF;
  makeBitSetMapper(IO, ST, "PT_PHDR", PT_PHDR);
  makeBitSetMapper(IO, ST, "PT_INTERP", PT_INTERP);
  makeBitSetMapper(IO, ST, "PT_LOAD", PT_LOAD);
  makeBitSetMapper(IO, ST, "PT_NOTE", PT_NOTE);
  makeBitSetMapper(IO, ST, "PT_DYNAMIC", PT_DYNAMIC);
  makeBitSetMapper(IO, ST, "PT_TLS", PT_TLS);
}

void ScalarBitSetTraits<SegmentPermissions>::bitset(
    IO &IO, SegmentPermissions &SP) {
  using namespace llvm::ELF;
  makeBitSetMapper(IO, SP, "READ", PF_R);
  makeBitSetMapper(IO, SP, "WRITE", PF_W);
  makeBitSetMapper(IO, SP, "EXECUTE", PF_X);
  makeBitSetMapper(IO, SP, "OS_SPECIFIC", PF_MASKOS);
  makeBitSetMapper(IO, SP, "PROCESSOR_SPECIFIC", PF_MASKPROC);
}

void ScalarEnumerationTraits<InputUsed>::enumeration(
    IO &IO, InputUsed &IU) {
  IO.enumCase(IU, "NotUsed", false);
  IO.enumCase(IU, "Used", true);
}

void MappingTraits<std::shared_ptr<InputFile>>::mapping(
    IO &IO, std::shared_ptr<InputFile> &IF) {
  if (IF) {
    IF->mapping(IO);
    return;
  }

  auto keys = IO.keys();
  if (std::find(keys.begin(), keys.end(), "Members") == keys.end()) {
    IF = std::make_shared<RegularInput>();
  } else {
    IF = std::make_shared<Archive>();
  }
  IF->mapping(IO);
}

void RegularInput::mapping(IO &IO) {
  MappingTraits<RegularInput>::mapping(IO, *this);
}

void MappingTraits<RegularInput>::mapping(IO &IO, RegularInput &RI) {
  IO.mapRequired("Path", RI.Name);
  IO.mapRequired("Used", RI.Used);
}

void Archive::mapping(IO &IO) {
  MappingTraits<Archive>::mapping(IO, *this);
}

void MappingTraits<Archive>::mapping(IO &IO, Archive &A) {
  IO.mapRequired("Path", A.Name);
  IO.mapRequired("Used", A.Used);
  IO.mapOptional("Members", A.ArchiveMembers);
}

void TrampolineInfo::mapping(IO &IO) {
  MappingTraits<TrampolineInfo>::mapping(IO, *this);
}

void MappingTraits<TrampolineInfo>::mapping(
    IO &IO, TrampolineInfo &TI) {
  IO.mapRequired("OutputSection", TI.OutputSectionName);
  IO.mapRequired("Trampolines", TI.Trampolines);
}

void MappingTraits<Trampoline>::mapping(IO &IO, Trampoline &T) {
  IO.mapRequired("Name", T.Name);
  IO.mapRequired("From", T.From);
  IO.mapOptional("FromSymbols", T.FromSymbols);
  IO.mapRequired("Origin", T.FromFile);
  IO.mapRequired("To", T.To);
  IO.mapRequired("ToSection", T.ToSection);
  IO.mapOptional("ToSymbols", T.ToSymbols);
  IO.mapRequired("Destination", T.ToFile);
  IO.mapOptional("Addend", T.Addend);
  IO.mapOptional("Uses", T.Uses);
}

void MappingTraits<Reuse>::mapping(IO &IO, Reuse &R) {
  IO.mapRequired("From", R.From);
  IO.mapOptional("Symbols", R.Symbols);
  IO.mapRequired("Origin", R.FromFile);
  IO.mapOptional("Addend", R.Addend);
}

