int main() {
    Programming parser;
    Initialize();

    std::string inputLine;
    int index = 0;

    while (true) {
        try {
            Console::SetColor(Console::White);
            Console::SetBold(false);
            std::getline(std::cin, inputLine);
            std::cout << std::endl;

            if (inputLine == "!q") {
                parser.Finalize();
                return 0;
            }

            parser.Compile(inputLine, 1);

            for (; index < static_cast<int>(parser.List.size()); ++index) {
                std::cout << Disassemble(&parser.List[index]) << std::endl;
            }

            Console::SetColor(Console::Black);
            Console::SetBold();
            std::cout << std::endl << std::endl 
                      << "---------------------------------" << std::endl;
        }
        catch (const char* msg) {
            Console::SetColor(Console::Red);
            std::cout << msg << std::endl;
        }
    }

    return 0;
}

