// Helper to build a Sim3 from RxSO3 and translation
template <class Scalar>
Sim3<Scalar> constructSim3(RxSO3<Scalar> const& r, typename Sim3<Scalar>::Point const& t) {
    return Sim3<Scalar>(r, t);
}

// Helper to create tangent vector
template <class Scalar>
typename Sim3<Scalar>::Tangent makeTangent(Scalar x1, Scalar x2, Scalar x3,
                                           Scalar y1, Scalar y2, Scalar y3,
                                           Scalar s) {
    typename Sim3<Scalar>::Tangent t;
    t << x1, x2, x3, y1, y2, y3, s;
    return t;
}

template <class Scalar>
class ValidationSuite {
 public:
    using Group = Sim3<Scalar>;
    using Algebra = typename Group::Tangent;
    using RotationLike = RxSO3<Scalar>;
    using Vec4 = Vector4<Scalar>;
    using Vec3 = typename Group::Point;

    Scalar const pi_val = Constants<Scalar>::pi();

    ValidationSuite() {
        // Initialize group elements
        group_list.emplace_back(
            constructSim3(RotationLike::exp(Vec4{Scalar(0.2), Scalar(0.5),
                                                Scalar(0.0), Scalar(1.)}),
                          Vec3{Scalar(0), Scalar(0), Scalar(0)}));
        group_list.emplace_back(
            constructSim3(RotationLike::exp(Vec4{Scalar(0.2), Scalar(0.5),
                                                Scalar(-1.), Scalar(1.1)}),
                          Vec3{Scalar(10), Scalar(0), Scalar(0)}));
        group_list.emplace_back(
            constructSim3(RotationLike::exp(Vec4{Scalar(0.), Scalar(0.), Scalar(0.),
                                                Scalar(0.)}),
                          Vec3{Scalar(0), Scalar(10), Scalar(5)}));
        group_list.emplace_back(
            constructSim3(RotationLike::exp(Vec4{Scalar(0.), Scalar(0.), Scalar(0.),
                                                Scalar(1.1)}),
                          Vec3{Scalar(0), Scalar(10), Scalar(5)}));
        group_list.emplace_back(
            constructSim3(RotationLike::exp(Vec4{Scalar(0.), Scalar(0.),
                                                Scalar(0.00001), Scalar(0.)}),
                          Vec3{Scalar(0), Scalar(0), Scalar(0)}));
        group_list.emplace_back(
            constructSim3(RotationLike::exp(Vec4{Scalar(0.), Scalar(0.), Scalar(0.00001),
                                                Scalar(0.0000001)}),
                          Vec3{Scalar(1), Scalar(-1.00000001), Scalar(2.0000000001)}));
        group_list.emplace_back(
            constructSim3(RotationLike::exp(Vec4{Scalar(0.), Scalar(0.),
                                                Scalar(0.00001), Scalar(0.)}),
                          Vec3{Scalar(0.01), Scalar(0), Scalar(0)}));
        group_list.emplace_back(
            constructSim3(RotationLike::exp(Vec4{pi_val, Scalar(0), Scalar(0), Scalar(0.9)}),
                          Vec3{Scalar(4), Scalar(-5), Scalar(0)}));
        group_list.emplace_back(
            constructSim3(RotationLike::exp(Vec4{Scalar(0.2), Scalar(0.5), Scalar(0.0), Scalar(0.)}),
                          Vec3{Scalar(0), Scalar(0), Scalar(0)}) *
            constructSim3(RotationLike::exp(Vec4{pi_val, Scalar(0), Scalar(0), Scalar(0)}),
                          Vec3{Scalar(0), Scalar(0), Scalar(0)}) *
            constructSim3(RotationLike::exp(Vec4{Scalar(-0.2), Scalar(-0.5), Scalar(-0.0), Scalar(0.)}),
                          Vec3{Scalar(0), Scalar(0), Scalar(0)}));
        group_list.emplace_back(
            constructSim3(RotationLike::exp(Vec4{Scalar(0.3), Scalar(0.5), Scalar(0.1), Scalar(0.)}),
                          Vec3{Scalar(2), Scalar(0), Scalar(-7)}) *
            constructSim3(RotationLike::exp(Vec4{pi_val, Scalar(0), Scalar(0), Scalar(0)}),
                          Vec3{Scalar(0), Scalar(0), Scalar(0)}) *
            constructSim3(RotationLike::exp(Vec4{Scalar(-0.3), Scalar(-0.5), Scalar(-0.1), Scalar(0.)}),
                          Vec3{Scalar(0), Scalar(6), Scalar(0)}));

        // Tangents
        auto add_tangent = [&](Scalar a, Scalar b, Scalar c,
                               Scalar d, Scalar e, Scalar f, Scalar g) {
            tangent_list.push_back(makeTangent<Scalar>(a, b, c, d, e, f, g));
        };
        add_tangent(Scalar(0), Scalar(0), Scalar(0), Scalar(0), Scalar(0), Scalar(0), Scalar(0));
        add_tangent(Scalar(1), Scalar(0), Scalar(0), Scalar(0), Scalar(0), Scalar(0), Scalar(0));
        add_tangent(Scalar(0), Scalar(1), Scalar(0), Scalar(1), Scalar(0), Scalar(0), Scalar(0.1));
        add_tangent(Scalar(0), Scalar(0), Scalar(1), Scalar(0), Scalar(1), Scalar(0), Scalar(0.1));
        add_tangent(Scalar(-1), Scalar(1), Scalar(0), Scalar(0), Scalar(0), Scalar(1), Scalar(-0.1));
        add_tangent(Scalar(20), Scalar(-1), Scalar(0), Scalar(-1), Scalar(1), Scalar(0), Scalar(-0.1));
        add_tangent(Scalar(30), Scalar(5), Scalar(-1), Scalar(20), Scalar(-1), Scalar(0), Scalar(1.5));

        // Points
        point_list.emplace_back(Scalar(1), Scalar(2), Scalar(4));
        point_list.emplace_back(Scalar(1), Scalar(-3), Scalar(0.5));
    }

    void executeAll() {
        bool success = checkLieAlgebraAxioms();
        success &= checkMemoryLayout();
        success &= checkConstructionSemantics();
        finalizeTest(success);
    }

 private:
    std::vector<Group, Eigen::aligned_allocator<Group>> group_list;
    std::vector<Algebra, Eigen::aligned_allocator<Algebra>> tangent_list;
    std::vector<Vec3, Eigen::aligned_allocator<Vec3>> point_list;

    bool checkLieAlgebraAxioms() {
        LieGroupTests<Group> tester(group_list, tangent_list, point_list);
        return tester.doAllTestsPass();
    }

    bool checkMemoryLayout() {
        bool ok = true;

        Eigen::Matrix<Scalar, 7, 1> buffer1;
        buffer1 << Scalar(0), Scalar(1), Scalar(0), Scalar(0), Scalar(1), Scalar(3), Scalar(2);

        Eigen::Map<Group const> view_on_const(buffer1.data());
        SOPHUS_TEST_APPROX(ok, view_on_const.quaternion().coeffs().eval(),
                           buffer1.template head<4>().eval(),
                           Constants<Scalar>::epsilon());
        SOPHUS_TEST_APPROX(ok, view_on_const.translation().eval(),
                           buffer1.template tail<3>().eval(),
                           Constants<Scalar>::epsilon());

        SOPHUS_TEST_EQUAL(ok, view_on_const.quaternion().coeffs().data(), buffer1.data());
        SOPHUS_TEST_EQUAL(ok, view_on_const.translation().data(), buffer1.data() + 4);

        Eigen::Map<Group const> alias_view = view_on_const;
        SOPHUS_TEST_EQUAL(ok, alias_view.quaternion().coeffs().eval(),
                          view_on_const.quaternion().coeffs().eval());
        SOPHUS_TEST_EQUAL(ok, alias_view.translation().eval(),
                          view_on_const.translation().eval());

        Eigen::Matrix<Scalar, 7, 1> buffer2;
        buffer2 << Scalar(1), Scalar(0), Scalar(0), Scalar(0), Scalar(3), Scalar(2), Scalar(1);

        Eigen::Quaternion<Scalar> q;
        q.coeffs() = buffer2.template head<4>();

        Eigen::Map<Group> writable_view(buffer1.data());
        writable_view.setQuaternion(q);
        writable_view.translation() = buffer2.template tail<3>();

        SOPHUS_TEST_APPROX(ok, writable_view.quaternion().coeffs().eval(),
                           buffer2.template head<4>().eval(),
                           Constants<Scalar>::epsilon());
        SOPHUS_TEST_APPROX(ok, writable_view.translation().eval(),
                           buffer2.template tail<3>().eval(),
                           Constants<Scalar>::epsilon());

        SOPHUS_TEST_EQUAL(ok, writable_view.quaternion().coeffs().data(), buffer1.data());
        SOPHUS_TEST_EQUAL(ok, writable_view.translation().data(), buffer1.data() + 4);
        SOPHUS_TEST_NEQ(ok, writable_view.quaternion().coeffs().data(), q.coeffs().data());

        Eigen::Map<Group> copied_map = writable_view;
        SOPHUS_TEST_EQUAL(ok, copied_map.quaternion().coeffs().eval(),
                          writable_view.quaternion().coeffs().eval());
        SOPHUS_TEST_EQUAL(ok, copied_map.translation().eval(),
                          writable_view.translation().eval());

        Eigen::Map<Group const> immutable_copy = writable_view;
        SOPHUS_TEST_EQUAL(ok, immutable_copy.quaternion().coeffs().eval(),
                          writable_view.quaternion().coeffs().eval());
        SOPHUS_TEST_EQUAL(ok, immutable_copy.translation().eval(),
                          writable_view.translation().eval());

        Group literal_group(q, buffer2.template tail<3>().eval());
        for (int idx = 0; idx < 7; ++idx) {
            SOPHUS_TEST_EQUAL(ok, literal_group.data()[idx], buffer2.data()[idx]);
        }

        Group mutable_group(q, buffer2.template tail<3>().eval());
        for (int idx = 0; idx < 7; ++idx) {
            SOPHUS_TEST_EQUAL(ok, mutable_group.data()[idx], buffer2.data()[idx]);
            SOPHUS_TEST_EQUAL(ok, mutable_group.data()[idx], buffer1.data()[idx]);
        }

        Eigen::Matrix<Scalar, 7, 1> src_data, dst_data;
        src_data << Scalar(0), Scalar(2), Scalar(0), Scalar(0), Scalar(1), Scalar(2), Scalar(3);
        dst_data << Scalar(0), Scalar(0), Scalar(2), Scalar(0), Scalar(3), Scalar(2), Scalar(1);

        Eigen::Map<Group> map_src(src_data.data()), map_dst(dst_data.data());
        map_dst = map_src;
        SOPHUS_TEST_EQUAL(ok, map_src.matrix(), map_dst.matrix());

        Group temp_obj;
        temp_obj = map_src;
        SOPHUS_TEST_EQUAL(ok, map_src.matrix(), temp_obj.matrix());

        temp_obj = Group{
            RotationLike::exp(Vec4{Scalar(0.2), Scalar(0.5), Scalar(-1.), Scalar(1.1)}),
            Vec3{Scalar(10), Scalar(0), Scalar(0)}
        };
        map_src = temp_obj;
        SOPHUS_TEST_EQUAL(ok, map_src.matrix(), temp_obj.matrix());

        return ok;
    }

    bool checkConstructionSemantics() {
        bool ok = true;
        SOPHUS_TEST_EQUAL(ok, Group().matrix(), makeIdentity4x4<Scalar>());

        Group const& sample = group_list.front();
        Vec3 trans = sample.translation();
        RotationLike rot = sample.rxso3();

        SOPHUS_TEST_APPROX(ok, Group(rot, trans).matrix(), sample.matrix(),
                           Constants<Scalar>::epsilon());
        SOPHUS_TEST_APPROX(ok, Group(rot.quaternion(), trans).matrix(), sample.matrix(),
                           Constants<Scalar>::epsilon());
        SOPHUS_TEST_APPROX(ok, Group(sample.matrix()).matrix(), sample.matrix(),
                           Constants<Scalar>::epsilon());

        Scalar scale_factor = Scalar(1.2);
        sample.setScale(scale_factor);
        SOPHUS_TEST_APPROX(ok, scale_factor, sample.scale(),
                           Constants<Scalar>::epsilon(), "setScale");

        sample.setQuaternion(group_list[0].rxso3().quaternion());
        SOPHUS_TEST_APPROX(ok, group_list[0].rxso3().quaternion().coeffs(),
                           group_list[0].rxso3().quaternion().coeffs(),
                           Constants<Scalar>::epsilon(), "setQuaternion");

        return ok;
    }
};

