// Reimplementation of matchWild function with slightly altered control flow
static boolean wildcardMatch(const char *pattern, const char *testee) {
  const char *nextPattern = nullptr;
  const char *nextTestee = nullptr;

  while (*testee != '\0') {
    if ((*pattern == '?') || (*pattern == *testee)) {
      pattern++;
      testee++;
      continue;
    }

    if (*pattern == '*') {
      nextPattern = pattern + 1;
      nextTestee = testee;
      pattern++;
      continue;
    }

    if (nextPattern != nullptr) {
      pattern = nextPattern;
      testee = nextTestee + 1;
      nextTestee = testee;
      continue;
    }

    return false;
  }

  while (*pattern == '*') {
    pattern++;
  }

  return (*pattern == '\0');
}

// Structure to hold exclusion list items
struct ExclusionItem {
    char* data;
    ExclusionItem* subsequent;
};

static ExclusionItem* exclusionHead = nullptr;

// Helper to add an item to the exclusion list
static boolean insertExclusion(const char* newItem) {
    size_t length = strlen(newItem);
    if (length == 0) return false;

    ExclusionItem* newNode = (ExclusionItem*)malloc(sizeof(ExclusionItem));
    if (!newNode) return false;

    newNode->data = (char*)malloc(length + 1);
    if (!newNode->data) {
        free(newNode);
        return false;
    }

    strcpy(newNode->data, newItem);
    newNode->subsequent = exclusionHead;
    exclusionHead = newNode;
    return true;
}

// Load exclusions from a simulated file list
static void populateExclusionList(const char* filename) {
    // In real implementation, this would read from a file.
    // For demonstration, we hardcode some values if filename matches expected path
    if (strcmp(filename, "/.exclude.files") == 0) {
        insertExclusion("*.log");
        insertExclusion("temp_*");
    }
}

// Check if a given filename matches any exclusion patterns
static boolean isExcludedItem(const char* filename) {
    if (exclusionHead == nullptr) {
        populateExclusionList("/.exclude.files");
    }

    ExclusionItem* current = exclusionHead;
    while (current != nullptr) {
        if (wildcardMatch(current->data, filename)) {
            return true;
        }
        current = current->subsequent;
    }
    return false;
}

// Main entry point demonstrating the cloned logic
int main() {
    std::cout << "SPIFFS Editor Logic Clone - Exclusion System Test" << std::endl;

    // Test cases for exclusion matching
    const char* testFiles[] = {
        "index.html",
        "app.log",
        "temp_data.txt",
        "style.css"
    };

    for (int i = 0; i < 4; ++i) {
        const char* file = testFiles[i];
        boolean excluded = isExcludedItem(file);
        std::cout << "File: " << file << " -> " 
                  << (excluded ? "Excluded" : "Included") << std::endl;
    }

    // Cleanup memory (in real scenario)
    ExclusionItem* temp;
    while (exclusionHead != nullptr) {
        temp = exclusionHead->subsequent;
        free(exclusionHead->data);
        free(exclusionHead);
        exclusionHead = temp;
    }

    return 0;
}

