namespace dap {

// Redefine the test structure with same fields but different naming
struct VariantTestCase {
  dap::integer value;
  dap::number decimal;
};

// Update the type info registration accordingly
DAP_STRUCT_TYPEINFO(VariantTestCase,
                    "VariantTestCase",
                    DAP_FIELD(value, "value"),
                    DAP_FIELD(decimal, "decimal"));

}  // namespace dap

// Test: variant constructed without initialization defaults to first type (integer)
TEST(Variant, DefaultInitialization) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestCase> var;
  EXPECT_TRUE(var.is<dap::integer>());
  EXPECT_FALSE(var.is<dap::boolean>());
  EXPECT_FALSE(var.is<dap::VariantTestCase>());
}

// Test: variant holding a boolean value
TEST(Variant, BooleanValue) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestCase> var(dap::boolean(false));
  EXPECT_TRUE(var.is<dap::boolean>());
  EXPECT_EQ(var.get<dap::boolean>(), dap::boolean(false));
}

// Test: variant holding an integer value
TEST(Variant, IntegerValue) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestCase> var(dap::integer(42));
  EXPECT_TRUE(var.is<dap::integer>());
  EXPECT_EQ(var.get<dap::integer>(), dap::integer(42));
}

// Test: variant holding a custom struct
TEST(Variant, StructValue) {
  dap::variant<dap::integer, dap::boolean, dap::VariantTestCase> var(
      dap::VariantTestCase{7, 2.5});
  EXPECT_TRUE(var.is<dap::VariantTestCase>());
  EXPECT_EQ(var.get<dap::VariantTestCase>().value, 7);
  EXPECT_EQ(var.get<dap::VariantTestCase>().decimal, 2.5);
}

// Test: assignment between different types in variant
TEST(Variant, TypeAssignment) {
  using V = dap::variant<dap::integer, dap::boolean, dap::VariantTestCase>;
  V var(dap::integer(100));

  // Assign integer again
  var = dap::integer(200);
  EXPECT_TRUE(var.is<dap::integer>());
  EXPECT_EQ(var.get<dap::integer>(), dap::integer(200));

  // Assign boolean
  var = dap::boolean(true);
  EXPECT_TRUE(var.is<dap::boolean>());
  EXPECT_EQ(var.get<dap::boolean>(), dap::boolean(true));

  // Assign struct
  var = dap::VariantTestCase{13, 9.8};
  EXPECT_TRUE(var.is<dap::VariantTestCase>());
  EXPECT_EQ(var.get<dap::VariantTestCase>().value, 13);
  EXPECT_EQ(var.get<dap::VariantTestCase>().decimal, 9.8);
}

// Test: compile-time type acceptance check
TEST(Variant, AcceptsTypeCheck) {
  using V = dap::variant<dap::integer, dap::boolean, dap::VariantTestCase>;
  static_assert(V::accepts<dap::integer>(), "Should accept integer");
  static_assert(V::accepts<dap::boolean>(), "Should accept boolean");
  static_assert(V::accepts<dap::VariantTestCase>(), "Should accept VariantTestCase");
  static_assert(!V::accepts<dap::number>(), "Should not accept number directly");
  static_assert(!V::accepts<dap::string>(), "Should not accept string");
}

