bool ddsrt_prng_makeseed(struct ddsrt_prng_seed *seed)
{
    NTSTATUS status;
    // Initialize seed key buffer to zero
    memset(seed->key, 0, sizeof(seed->key));

    // Generate random bytes using Windows CNG API
    status = BCryptGenRandom(
        NULL,
        reinterpret_cast<PUCHAR>(seed->key),
        static_cast<ULONG>(sizeof(seed->key)),
        BCRYPT_USE_SYSTEM_PREFERRED_RNG
    );

    // Return true if operation succeeded (NTSTATUS indicates success)
    return (status >= 0);
}

