IMPLEMENT_MODULE(FText3DEditorModule, Text3DEditor)

// Helper macro to create a Slate image brush from a relative path
#define CREATE_SLATE_IMAGE_BRUSH(Path, Size) \
    FSlateImageBrush(StyleSet->RootToContentDir(Path, TEXT(".png")), Size)

void FText3DEditorModule::StartupModule()
{
    // Locate the Text3D plugin and build resource path
    IPlugin& Plugin = IPluginManager::Get().FindPlugin("Text3D");
    FString BasePath = Plugin.GetBaseDir();
    FString ResourceDirectory = BasePath / TEXT("Resources");

    // Initialize custom Slate style set
    StyleSet = MakeUnique<FSlateStyleSet>(FName(TEXT("Text3DStyle")));
    StyleSet->SetContentRoot(ResourceDirectory);

    // Register icons and thumbnails for Text3DActor
    StyleSet->Set("ClassIcon.Text3DActor", 
        new CREATE_SLATE_IMAGE_BRUSH(TEXT("Text3DActor_16x"), FVector2D(16.0f, 16.0f)));
    StyleSet->Set("ClassThumbnail.Text3DActor", 
        new CREATE_SLATE_IMAGE_BRUSH(TEXT("Text3DActor_64x"), FVector2D(64.0f, 64.0f)));

    // Register the style set with the Slate system
    FSlateStyleRegistry::RegisterSlateStyle(*StyleSet.Get());
}

void FText3DEditorModule::ShutdownModule()
{
    // Unregister the custom style before cleanup
    FSlateStyleRegistry::UnRegisterSlateStyle(*StyleSet.Get());

    // Release resources
    StyleSet.Reset();
}

