template <typename T>
static void verify_equal(const T & expected_val, const T & actual_val) {
    if (expected_val != actual_val) {
        std::cerr << "Expected: " << expected_val << "\n";
        std::cerr << "  Actual: " << actual_val << "\n";
        std::cerr.flush();
        throw std::runtime_error("Assertion failed");
    }
}

struct test_scenario {
    std::string pattern_expr;
    struct case_data {
        std::string test_input;
        common_regex_match expected_result;
    };
    std::vector<case_data> cases;
};

static std::string describe_match_type(common_regex_match_type t) {
    switch (t) {
        case COMMON_REGEX_MATCH_TYPE_NONE:
            return "COMMON_REGEX_MATCH_TYPE_NONE";
        case COMMON_REGEX_MATCH_TYPE_PARTIAL:
            return "COMMON_REGEX_MATCH_TYPE_PARTIAL";
        case COMMON_REGEX_MATCH_TYPE_FULL:
            return "COMMON_REGEX_MATCH_TYPE_FULL";
    }
    return "UNKNOWN";
}

static void run_tests() {
    printf("[%s]\n", __func__);

    auto execute_test = [&](const test_scenario & scenario) {
        common_regex engine(scenario.pattern_expr);
        std::cout << "Pattern under test: /" << scenario.pattern_expr << "/\n";

        for (const auto & [input_str, expected] : scenario.cases) {
            std::cout << "  Input: '" << input_str << "'\n";
            auto result = engine.search(input_str, 0);

            if (result != expected) {
                auto format_match = [&](const std::optional<common_regex_match> & m_opt) -> std::string {
                    std::ostringstream oss;
                    if (!m_opt.has_value() || m_opt->type == COMMON_REGEX_MATCH_TYPE_NONE) {
                        oss << "<no match>";
                    } else {
                        GGML_ASSERT(!expected.groups.empty());
                        std::vector<std::string> segment_list;
                        for (const auto & seg : m_opt->groups) {
                            segment_list.push_back("{" + std::to_string(seg.begin) + ", " + std::to_string(seg.end) + "}");
                        }
                        oss << "{" << describe_match_type(m_opt->type) << ", {" << string_join(segment_list, ", ") << "}}";
                    }
                    return oss.str();
                };

                std::cout << "    Expected: " << format_match(expected) << '\n';
                std::cout << "         Got: " << format_match(result) << '\n';
                std::cout << " Inverted pattern: /" << regex_to_reversed_partial_regex(scenario.pattern_expr) << "/\n";
                throw std::runtime_error("Test case failed");
            }
        }
    };

    // Basic single-character tests
    execute_test({
        "x",
        {
            {"x", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 1}}}},
            {"y", {COMMON_REGEX_MATCH_TYPE_NONE, {}}},
            {"xy", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 1}}}},
            {"yx", {COMMON_REGEX_MATCH_TYPE_FULL, {{1, 2}}}},
        }
    });

    // Multi-character prefix matching
    execute_test({
        "wxyz",
        {
            {"wxyz", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 4}}}},
            {"wxyza", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 4}}}},
            {"wxy", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 3}}}},
            {"wx", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 2}}}},
            {"w", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 1}}}},
            {"x", {}},
            {"xyz", {}},
            {"yza", {}},
            {"yz", {}},
            {"hello wx", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{6, 8}}}},
            {"wxx", {}},
            {"", {}},
        }
    });

    // Non-greedy quantifiers
    execute_test({
        ".*?xy",
        {
            {"xy", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 2}}}},
            {"xyz", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 2}}}},
            {"zxy", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 3}}}},
            {"zxyz", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 3}}}},
            {"z", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 1}}}},
        }
    });

    // Greedy with boundary
    execute_test({
        "x.*?y",
        {
            {"xy", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 2}}}},
            {"xyz", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 2}}}},
            {"x y", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 3}}}},
            {"x", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 1}}}},
            {"xray", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 4}}}},
            {"z", {}},
            {"y", {}},
        }
    });

    // Repetition with alternation
    execute_test({
        "xy(?:zz){2,4}ab",
        {
            {"xy", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 2}}}},
            {"xyz", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 3}}}},
            {"xyzz", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 4}}}},
            {"xyzzz", {}},
            {"xyzzzz", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 6}}}},
            {"xyzzzza", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 7}}}},
            {"xyzzzzab", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 8}}}},
            {"xyzzzzzzzzab", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 12}}}},
            {"xyzzzzzzzzzab", {}},
            {"xyzzz", {}},
            {"hi xy", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{3, 5}}}},
        }
    });

    // Alternation inside group
    execute_test({
        "(?:ex(?:ct|plicit) )?fact",
        {
            {"f", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 1}}}},
            {"exp", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 3}}}},
            {"explicitf", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 9}}}},
            {"fact", {}},
            {"an explicit", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{3, 12}}}},
            {"explicit fact", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 15}}}},
            {"an explicit fact", {COMMON_REGEX_MATCH_TYPE_FULL, {{3, 20}}}},
            {"ex fact", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 7}}}},
            {"ex fact ", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 8}}}},
            {"it's ex fact", {COMMON_REGEX_MATCH_TYPE_FULL, {{5, 14}}}},
            {"" , {}},
            {"fact", {}},
            {"explicit", {}},
        }
    });

    // Simple sequence
    execute_test({
        "pqr",
        {
            {" pqr", {COMMON_REGEX_MATCH_TYPE_FULL, {{1, 4}}}},
            {"pq", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 2}}}},
            {"pqr", {COMMON_REGEX_MATCH_TYPE_FULL, {{0, 3}}}},
            {" pq", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{1, 3}}}},
            {"p", {COMMON_REGEX_MATCH_TYPE_PARTIAL, {{0, 1}}}},
            {"q", {}},
            {"r", {}},
            {"", {}},
        }
    });

    // Optional prefix and whitespace
    execute_test({
        "(?:pqr)?\\s*stu",
