void AvgEncodeDecodeCore(size_t step, size_t count) {
  std::vector<uint64_t> original_values;
  original_values.reserve(count);

  // Generate values using while loop instead of for loop
  size_t index = 0;
  while (index < count) {
    original_values.push_back((index + 1) * step);
    ++index;
  }

  // Create encoded copy
  std::vector<uint64_t> encoded_values = original_values;

  // Perform average encoding
  const auto encoding_stats =
    irs::encode::avg::encode(encoded_values.data(), encoded_values.data() + encoded_values.size());

  // Verify encoding results
  ASSERT_EQ(original_values[0], std::get<0>(encoding_stats));
  ASSERT_EQ(step, std::get<1>(encoding_stats));
  ASSERT_EQ(irs::irstd::AllEqual(std::begin(encoded_values), std::end(encoded_values)),
            std::get<2>(encoding_stats));

  // Check all encoded values are zero
  ASSERT_TRUE(std::all_of(encoded_values.begin(), encoded_values.end(),
                          [](uint64_t v) { return 0 == v; }));

  // Test decoding with visitor pattern
  bool verification_success = true;
  auto value_iterator = original_values.begin();
  irs::encode::avg::visit(std::get<0>(encoding_stats), std::get<1>(encoding_stats),
                          encoded_values.data(), encoded_values.data() + encoded_values.size(),
                          [&value_iterator, &verification_success](uint64_t decoded_value) {
                            verification_success = verification_success && (decoded_value == *value_iterator);
                            ++value_iterator;
                          });

  ASSERT_TRUE(verification_success);
  ASSERT_EQ(original_values.end(), value_iterator);

  // Test full decode cycle
  std::vector<uint64_t> decoded_values = encoded_values;
  irs::encode::avg::decode(std::get<0>(encoding_stats), std::get<1>(encoding_stats),
                           decoded_values.data(), decoded_values.data() + decoded_values.size());
  ASSERT_EQ(original_values, decoded_values);
}

