#include "common_utest.h"

void test_drotmg()
{
    double te_d1, tr_d1;
    double te_d2, tr_d2;
    double te_x1, tr_x1;
    double te_y1, tr_y1;
    double te_param[5];
    double tr_param[5];

    // Initialize all variables with identical values for both test and reference
    te_d1 = tr_d1 = 0.21149573940783739;
    te_d2 = tr_d2 = 0.046892057172954082;
    te_x1 = tr_x1 = -0.42272687517106533;
    te_y1 = tr_y1 = 0.42211309121921659;

    // Initialize parameter arrays to zero
    for (int idx = 0; idx < 5; ++idx) {
        te_param[idx] = tr_param[idx] = 0.0;
    }

    // Compute using OpenBLAS implementation
    BLASFUNC(drotmg)(&te_d1, &te_d2, &te_x1, &te_y1, te_param);

    // Compute using reference implementation
    BLASFUNC_REF(drotmg)(&tr_d1, &tr_d2, &tr_x1, &tr_y1, tr_param);

    // Verify results match within tolerance
    CU_ASSERT_DOUBLE_EQUAL(te_d1, tr_d1, CHECK_EPS);
    CU_ASSERT_DOUBLE_EQUAL(te_d2, tr_d2, CHECK_EPS);
    CU_ASSERT_DOUBLE_EQUAL(te_x1, tr_x1, CHECK_EPS);
    CU_ASSERT_DOUBLE_EQUAL(te_y1, tr_y1, CHECK_EPS);

    // Check each element of the parameter array
    for (int idx = 0; idx < 5; ++idx) {
        CU_ASSERT_DOUBLE_EQUAL(te_param[idx], tr_param[idx], CHECK_EPS);
    }
}

