// Overload for 1D vector: prints elements separated by spaces
template <typename T>
IGL_INLINE void igl::print_vector(std::vector<T>& v)
{
  using namespace std;
  int len = static_cast<int>(v.size());
  for (int idx = 0; idx < len; ++idx)
    cerr << v[idx] << " ";
  cerr << endl;
}

// Overload for 2D vector: prints each row with its index prefix
template <typename T>
IGL_INLINE void igl::print_vector(std::vector<std::vector<T>>& v)
{
  using namespace std;
  int rows = static_cast<int>(v.size());
  for (int row_idx = 0; row_idx < rows; ++row_idx)
  {
    cerr << row_idx << ": ";
    int cols = static_cast<int>(v[row_idx].size());
    for (int col_idx = 0; col_idx < cols; ++col_idx)
      cerr << v[row_idx][col_idx] << " ";
    cerr << endl;
  }
}

// Overload for 3D vector: prints each 2D matrix with headers and separators
template <typename T>
IGL_INLINE void igl::print_vector(std::vector<std::vector<std::vector<T>>>& v)
{
  using namespace std;
  int matrices = static_cast<int>(v.size());
  for (int mat_idx = 0; mat_idx < matrices; ++mat_idx)
  {
    cerr << "Matrix " << mat_idx << endl;
    int rows = static_cast<int>(v[mat_idx].size());
    for (int row_idx = 0; row_idx < rows; ++row_idx)
    {
      cerr << row_idx << ": ";
      int cols = static_cast<int>(v[mat_idx][row_idx].size());
      for (int col_idx = 0; col_idx < cols; ++col_idx)
        cerr << v[mat_idx][row_idx][col_idx] << " ";
      cerr << endl;
    }
    cerr << "---- end " << mat_idx << endl;
  }
}

