#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    // Phase 1: Setup initial configuration with S=I marker
    cout << "S=I" << endl;

    // Phase 2: Termination conditions - when ? detects specific patterns
    cout << "1?=(return)1" << endl;
    cout << "2?=(return)1" << endl;
    cout << "3?=(return)1" << endl;
    cout << "^?=(return)1" << endl;

    // Phase 3: Bubble uppercase letters (A,B,C) through tokens (1,2,3)
    string upper_chars = "ABC";
    string token_chars = "123";
    for (char u : upper_chars) {
        for (char t : token_chars) {
            cout << u << t << "=" << t << u << endl;
        }
    }

    // Phase 4: Matching rules for uppercase-lowercase pairs
    cout << "A?a=1?" << endl;
    cout << "B?b=2?" << endl;
    cout << "C?c=3?" << endl;

    // Phase 5: Mismatch handling - uppercase with wrong lowercase triggers reset (%)
    string lower_case = "abc";
    string special_lower = "abc$";

    // Process A mismatches (skip 'a')
    for (char c : special_lower) {
        if (c == 'a') continue;
        cout << "A?" << c << "=%A" << c << endl;
    }

    // Process B mismatches (skip 'b')
    for (char c : special_lower) {
        if (c == 'b') continue;
        cout << "B?" << c << "=%B" << c << endl;
    }

    // Process C mismatches (skip 'c')
    for (char c : special_lower) {
        if (c == 'c') continue;
        cout << "C?" << c << "=%C" << c << endl;
    }

    // Phase 6: Reset mechanism - % moves left and restores state
    cout << "%A=A%" << endl;
    cout << "%B=B%" << endl;
    cout << "%C=C%" << endl;
    cout << "%1=A%a" << endl;
    cout << "%2=B%b" << endl;
    cout << "%3=C%c" << endl;

    // Phase 7: Start deletion transition - % at start becomes D
    cout << "^%=^D" << endl;

    // Phase 8: Deletion process - D removes first character of input
    cout << "DA=AD" << endl;
    cout << "DB=BD" << endl;
    cout << "DC=CD" << endl;
    cout << "Da=?" << endl;
    cout << "Db=?" << endl;
    cout << "Dc=?" << endl;
    cout << "D$=(return)0" << endl; // Empty string case

    // Phase 9: Initialization phase transformations
    cout << "aI=Ia" << endl;
    cout << "bI=Ib" << endl;
    cout << "cI=Ic" << endl;
    cout << "I=^J" << endl;
    cout << "Ja=aJ" << endl;
    cout << "Jb=bJ" << endl;
    cout << "Jc=cJ" << endl;
    cout << "J=R" << endl;

    // Phase 10: Reverse processing phase
    cout << "Ra=faR" << endl;
    cout << "Rb=fbR" << endl;
    cout << "Rc=fcR" << endl;

    // fa movement rules
    cout << "afa=faa" << endl;
    cout << "bfa=fab" << endl;
    cout << "cfa=fac" << endl;
    cout << "afb=fba" << endl;
    cout << "bfb=fbb" << endl;
    cout << "cfb=fbc" << endl;
    cout << "afc=fca" << endl;
    cout << "bfc=fcb" << endl;
    cout << "cfc=fcc" << endl;

    // Deposit uppercase markers at start
    cout << "^fa=^A<" << endl;
    cout << "^fb=^B<" << endl;
    cout << "^fc=^C<" << endl;

    // Leftward movement of <
    cout << "<a=a<" << endl;
    cout << "<b=b<" << endl;
    cout << "<c=c<" << endl;
    cout << "<R=R" << endl;

    // Phase 11: End reverse phase
    cout << "R=$" << endl;

    // Phase 12: Insert ? at boundaries
    for (char u : upper_chars) {
        for (char l : special_lower) {
            cout << u << l << "=" << u << "?" << l << endl;
        }
    }

    for (char l : lower_case) {
        cout << "^" << l << "=^?" << l << endl;
    }

    cout << "^$=(return)1" << endl;

    return 0;
}

