// Converts an unsigned 128-bit integer to a 32-bit IEEE 754 float
// Rounding is performed toward nearest, ties to even
// Assumptions: 
//   - float uses 32-bit IEEE 754 format (ssee eeee emmm mmmm ...)
//   - tu_int represents a 128-bit unsigned integer type
COMPILER_RT_ABI float __floatuntisf(tu_int value) {
    return __floatXiYf__(value);
