// Forward declaration assumed: GK_MKQSORT is defined elsewhere
template<typename T, typename Compare>
void gk_mksort(size_t n, T* base, Compare comp);

// Helper template to wrap comparison logic generically
template<typename T>
void sort_array_increasing(size_t n, T* base) {
    auto comp = [](const T& a, const T& b) { return a < b; };
    gk_mksort(n, base, comp);
}

template<typename T>
void sort_array_decreasing(size_t n, T* base) {
    auto comp = [](const T& a, const T& b) { return a > b; };
    gk_mksort(n, base, comp);
}

// Specializations for key-value structs where comparison is on .key or ->key
template<typename K, typename V>
void sort_kv_increasing(size_t n, struct gk_kv<K,V>* base) {
    auto comp = [](const struct gk_kv<K,V>& a, const struct gk_kv<K,V>& b) {
        return a.key < b.key;
    };
    gk_mksort(n, base, comp);
}

template<typename K, typename V>
void sort_kv_decreasing(size_t n, struct gk_kv<K,V>* base) {
    auto comp = [](const struct gk_kv<K,V>& a, const struct gk_kv<K,V>& b) {
        return a.key > b.key;
    };
    gk_mksort(n, base, comp);
}

// String-keyed key-value sorters
void sort_skv_increasing(size_t n, gk_skv_t* base) {
    auto comp = [](const gk_skv_t& a, const gk_skv_t& b) {
        return std::strcmp(a.key, b.key) < 0;
    };
    gk_mksort(n, base, comp);
}

void sort_skv_decreasing(size_t n, gk_skv_t* base) {
    auto comp = [](const gk_skv_t& a, const gk_skv_t& b) {
        return std::strcmp(a.key, b.key) > 0;
    };
    gk_mksort(n, base, comp);
}

// Public API wrappers — now unified and concise
void gk_csorti(size_t n, char *base) { sort_array_increasing(n, base); }
void gk_csortd(size_t n, char *base) { sort_array_decreasing(n, base); }

void gk_isorti(size_t n, int *base) { sort_array_increasing(n, base); }
