#if defined(d_m3HasTracer)

static FILE* tracer_stream = nullptr;

// Helper to suppress lookup failures and initialize trace file on first success
static M3Result HandleLookupStatus(M3Result status)
{
    if (status == m3Err_none) {
        if (!tracer_stream) {
            tracer_stream = fopen("wasm3_trace.csv", "w");
        }
    } else if (status == m3Err_functionLookupFailed) {
        status = m3Err_none;
    }
    return status;
}

// Execution tracing functions
m3ApiRawFunction(m3_env_log_execution)
{
    m3ApiGetArg(uint32_t, event_id);
    fprintf(tracer_stream, "exec;%u\n", event_id);
    m3ApiSuccess();
}

m3ApiRawFunction(m3_env_log_exec_enter)
{
    m3ApiGetArg(uint32_t, event_id);
    m3ApiGetArg(uint32_t, func_idx);
    fprintf(tracer_stream, "enter;%u;%u\n", event_id, func_idx);
    m3ApiSuccess();
}

m3ApiRawFunction(m3_env_log_exec_exit)
{
    m3ApiGetArg(uint32_t, event_id);
    m3ApiGetArg(uint32_t, func_idx);
    fprintf(tracer_stream, "exit;%u;%u\n", event_id, func_idx);
    m3ApiSuccess();
}

m3ApiRawFunction(m3_env_log_exec_loop)
{
    m3ApiGetArg(uint32_t, event_id);
    fprintf(tracer_stream, "loop;%u\n", event_id);
    m3ApiSuccess();
}

// Memory access tracing: pointer operations
m3ApiRawFunction(m3_env_load_ptr)
{
    m3ApiReturnType(uint32_t)
    m3ApiGetArg(uint32_t, event_id);
    m3ApiGetArg(uint32_t, align_val);
    m3ApiGetArg(uint32_t, offset_val);
    m3ApiGetArg(uint32_t, addr_val);
    fprintf(tracer_stream, "load ptr;%u;%u;%u;%u\n", event_id, align_val, offset_val, addr_val);
    m3ApiReturn(addr_val);
}

m3ApiRawFunction(m3_env_store_ptr)
{
    m3ApiReturnType(uint32_t)
    m3ApiGetArg(uint32_t, event_id);
    m3ApiGetArg(uint32_t, align_val);
    m3ApiGetArg(uint32_t, offset_val);
    m3ApiGetArg(uint32_t, addr_val);
    fprintf(tracer_stream, "store ptr;%u;%u;%u;%u\n", event_id, align_val, offset_val, addr_val);
    m3ApiReturn(addr_val);
}

// Generic memory value tracing macros (restructured with renamed parameters)
#define TRACE_MEMORY_OP(OP_NAME, FUNC_NAME, TYPE, FORMAT_SPEC) \
m3ApiRawFunction(FUNC_NAME)                                    \
{                                                              \
    m3ApiReturnType(TYPE)                                      \
    m3ApiGetArg(uint32_t, event_id);                           \
    m3ApiGetArg(TYPE,     data_val);                           \
    fprintf(tracer_stream, OP_NAME ";%u;" FORMAT_SPEC "\n", event_id, data_val); \
    m3ApiReturn(data_val);                                     \
}

TRACE_MEMORY_OP("load i32",  m3_env_load_val_i32, int32_t, "%" PRIi32)
TRACE_MEMORY_OP("store i32", m3_env_store_val_i32, int32_t, "%" PRIi32)
TRACE_MEMORY_OP("load i64",  m3_env_load_val_i64, int64_t, "%" PRIi64)
TRACE_MEMORY_OP("store i64", m3_env_store_val_i64, int64_t, "%" PRIi64)
TRACE_MEMORY_OP("load f32",  m3_env_load_val_f32, float,   "%" PRIf32)
TRACE_MEMORY_OP("store f32", m3_env_store_val_f32, float,   "%" PRIf32)
TRACE_MEMORY_OP("load f64",  m3_env_load_val_f64, double,  "%" PRIf64)
TRACE_MEMORY_OP("store f64", m3_env_store_val_f64, double,  "%" PRIf64)

// Local variable tracing macros (renamed locals & reordered args)
#define TRACE_LOCAL_OP(OP_NAME, FUNC_NAME, TYPE, FORMAT_SPEC)  \
m3ApiRawFunction(FUNC_NAME)                                    \
{                                                              \
    m3ApiReturnType(TYPE)                                      \
    m3ApiGetArg(uint32_t, event_id);                           \
    m3ApiGetArg(uint32_t, local_idx);                          \
    m3ApiGetArg(TYPE,     val);                                \
    fprintf(tracer_stream, OP_NAME ";%u;%u;" FORMAT_SPEC "\n", event_id, local_idx, val); \
    m3ApiReturn(val);                                          \
}

TRACE_LOCAL_OP("get i32", m3_env_get_i32, int32_t, "%" PRIi32)
TRACE_LOCAL_OP("set i32", m3_env_set_i32, int32_t, "%" PRIi32)
