// Linker function for tracer functions
M3Result m3_LinkTracer(IM3Module mod)
{
    M3Result res = m3Err_none;
    const char* ns = "env";

    #define LINK_TRACE_FUNC(name, sig, fn) \
        _ (HandleLookupStatus(m3_LinkRawFunction(mod, ns, name, sig, &fn)))

    LINK_TRACE_FUNC("log_execution",       "v(i)",     m3_env_log_execution);
    LINK_TRACE_FUNC("log_exec_enter",      "v(ii)",    m3_env_log_exec_enter);
    LINK_TRACE_FUNC("log_exec_exit",       "v(ii)",    m3_env_log_exec_exit);
    LINK_TRACE_FUNC("log_exec_loop",       "v(i)",     m3_env_log_exec_loop);
    LINK_TRACE_FUNC("load_ptr",            "i(iiii)",  m3_env_load_ptr);
    LINK_TRACE_FUNC("store_ptr",           "i(iiii)",  m3_env_store_ptr);
    LINK_TRACE_FUNC("load_val_i32",        "i(ii)",    m3_env_load_val_i32);
    LINK_TRACE_FUNC("load_val_i64",        "I(iI)",    m3_env_load_val_i64);
    LINK_TRACE_FUNC("load_val_f32",        "f(if)",    m3_env_load_val_f32);
    LINK_TRACE_FUNC("load_val_f64",        "F(iF)",    m3_env_load_val_f64);
    LINK_TRACE_FUNC("store_val_i32",       "i(ii)",    m3_env_store_val_i32);
    LINK_TRACE_FUNC("store_val_i64",       "I(iI)",    m3_env_store_val_i64);
    LINK_TRACE_FUNC("store_val_f32",       "f(if)",    m3_env_store_val_f32);
    LINK_TRACE_FUNC("store_val_f64",       "F(iF)",    m3_env_store_val_f64);
    LINK_TRACE_FUNC("get_i32",             "i(iii)",   m3_env_get_i32);
    LINK_TRACE_FUNC("get_i64",             "I(iiI)",   m3_env_get_i64);
    LINK_TRACE_FUNC("get_f32",             "f(iif)",   m3_env_get_f32);
    LINK_TRACE_FUNC("get_f64",             "F(iiF)",   m3_env_get_f64);
