#include <dolphin.h>
#include <dolphin/os.h>
#include "__os.h"

// Function prototypes
void __OSSystemCallVectorStart(void);
void __OSSystemCallVectorEnd(void);

#ifdef __GEKKO__
static asm void SystemCallHandler(void) {
entry __OSSystemCallVectorStart
    nofralloc
    mfspr r9, HID0
    ori r10, r9, 0x8
    mtspr HID0, r10
    isync
    sync
    mtspr HID0, r9
    rfi
entry __OSSystemCallVectorEnd
    nop
}
#endif

void __OSInitializeSystemCall(void) {
    void* targetAddress = (void*)OSPhysicalToCached(0xC00);
    u32 vectorSize = (u32)&__OSSystemCallVectorEnd - (u32)&__OSSystemCallVectorStart;

    memcpy(targetAddress, __OSSystemCallVectorStart, vectorSize);
    DCFlushRangeNoSync(targetAddress, 0x100);
    __sync();
    ICInvalidateRange(targetAddress, 0x100);
}

