// Draw method: queues each soft particle into the global particle buffer if available
void RndSoftParticles::DrawShowing() {
    RndSoftParticleBuffer *buffer = TheNgRnd.ParticleBuffer();
    if (buffer != nullptr) {
        // Use explicit iterator instead of FOREACH macro for clarity and variation
        for (auto iter = mParticles.begin(); iter != mParticles.end(); ++iter) {
            buffer->Queue(*iter, mBlend);
        }
    }
}

// List all child drawables (particles) for rendering hierarchy traversal
void RndSoftParticles::ListDrawChildren(std::list<RndDrawable *> &draws) {
    // Replace FOREACH with standard iterator loop
    for (auto iter = mParticles.begin(); iter != mParticles.end(); ++iter) {
        draws.push_back(*iter);
    }
}

