std::string generateTestName(sen::ConstTypeHandle<> srcType, Var value, sen::ConstTypeHandle<> dstType)
{
  std::ostringstream oss;
  oss << srcType->getName() << "_" << value.getCopyAs<std::string>() << "_to_" << dstType->getName();
  std::string result = oss.str();

  // Replace hyphens with 'n'
  std::replace(result.begin(), result.end(), '-', 'n');

  // Replace non-alphanumeric characters with underscores
  std::replace_if(result.begin(), result.end(), 
                  [](char c) { return !std::isalnum(static_cast<unsigned char>(c)); }, '_');

  return result;
}

template <typename T>
struct VariantConversionFixture : public testing::TestWithParam<std::tuple<sen::ConstTypeHandle<>, Var, sen::ConstTypeHandle<>, T>>
{
protected:
  void executeTest()
  {
    Var originalValue = std::get<1>(GetParam());
    std::ignore = sen::impl::adaptVariant(*std::get<2>(GetParam()), originalValue, std::get<0>(GetParam()));

    ASSERT_TRUE(originalValue.holds<T>());
    EXPECT_EQ(originalValue.get<T>(), std::get<3>(GetParam()));
  }
};

