#include <iostream>

// Apply transformation by multiplication factor
void scaleValue(int& value, int factor) {
    value *= factor;
}

// Apply transformation by adding increment
void incrementValue(int& value, int increment) {
    value += increment;
}

// Display current value followed by space
void displayValue(const int& value) {
    std::cout << value << ' ';
}

// Map function for unary operations
void applyOperation(int* data, int length, void (*operation)(int&)) {
    for (int index = 0; index < length; ++index) {
        operation(data[index]);
    }
}

// Map function for binary operations with additional parameter
void applyOperation(int* data, int length, void (*operation)(int&, int), int param) {
    for (int index = 0; index < length; ++index) {
        operation(data[index], param);
    }
}

int main() {
    int numbers[] = {1, 2, 3, 4, 5};

    // First pass: multiply each element by 10
    applyOperation(numbers, 5, scaleValue, 10);

    // Second pass: add 1 to each element
    applyOperation(numbers, 5, incrementValue, 1);

    // Third pass: multiply each element by 10 using lambda
    applyOperation(numbers, 5, [](int& x) { x *= 10; });

    // Final pass: print all values
    applyOperation(numbers, 5, displayValue);

    return 0;
}

