using namespace MOBase;

DisableProxyPluginDialog::DisableProxyPluginDialog(
    IPlugin* proxyPlugin, 
    const std::vector<IPlugin*>& requiredPlugins,
    QWidget* parent)
    : QDialog(parent)
    , ui(new Ui::DisableProxyPluginDialog)
{
    ui->setupUi(this);

    // Construct warning message dynamically based on count
    QString msgTemplate = QObject::tr("Disabling the '%1' plugin will prevent the "
                                      "following %2 plugin(s) from working:");
    QString localizedProxyName = proxyPlugin->localizedName();
    int count = static_cast<int>(requiredPlugins.size());
    ui->topLabel->setText(msgTemplate.arg(localizedProxyName).arg(count));

    // Connect buttons to dialog outcomes
    connect(ui->noBtn, &QPushButton::clicked, this, &QDialog::reject);
    connect(ui->yesBtn, &QPushButton::clicked, this, &QDialog::accept);

    // Configure table view for displaying dependencies
    ui->requiredPlugins->setSelectionMode(QAbstractItemView::NoSelection);

    // Populate table rows using index-based loop (refactored for clarity)
    const int rowCount = static_cast<int>(requiredPlugins.size());
    ui->requiredPlugins->setRowCount(rowCount);

    for (int idx = 0; idx < rowCount; ++idx) {
        IPlugin* plugin = requiredPlugins[idx];
        QTableWidgetItem* nameItem = new QTableWidgetItem(plugin->localizedName());
        QTableWidgetItem* descItem = new QTableWidgetItem(plugin->description());

        ui->requiredPlugins->setItem(idx, 0, nameItem);
        ui->requiredPlugins->setItem(idx, 1, descItem);
        ui->requiredPlugins->setRowHeight(idx, 9);
    }

    // Hide row headers and sort alphabetically by name
    ui->requiredPlugins->verticalHeader()->setVisible(false);
    ui->requiredPlugins->sortByColumn(0, Qt::AscendingOrder);
}

