void IUIScene_CommandBlockMenu::Initialise(CommandBlockEntity* cmdBlock)
{
    m_commandBlock = cmdBlock;
    std::string currentCmd = m_commandBlock->getCommand();
    SetCommand(currentCmd);
}

void IUIScene_CommandBlockMenu::ConfirmButtonClicked()
{
    // Prepare payload data for sending command update
    std::vector<unsigned char> buffer;
    buffer.reserve(64); // Pre-allocate space to avoid frequent reallocations

    // Write coordinates and command into buffer manually (simulating DataOutputStream behavior)
    int x = m_commandBlock->x;
    int y = m_commandBlock->y;
    int z = m_commandBlock->z;

    // Simulate writing integers as 4-byte big-endian values
    for (int val : {x, y, z}) {
        buffer.push_back(static_cast<unsigned char>((val >> 24) & 0xFF));
        buffer.push_back(static_cast<unsigned char>((val >> 16) & 0xFF));
        buffer.push_back(static_cast<unsigned char>((val >> 8) & 0xFF));
        buffer.push_back(static_cast<unsigned char>(val & 0xFF));
    }

    // Write UTF string: length-prefixed (2 bytes for length, then UTF-8 bytes)
    std::string cmd = GetCommand();
    size_t len = cmd.length();
    if (len > 0xFFFF) len = 0xFFFF; // Clamp to max allowed by short
    buffer.push_back(static_cast<unsigned char>((len >> 8) & 0xFF));
    buffer.push_back(static_cast<unsigned char>(len & 0xFF));
    for (size_t i = 0; i < len; ++i) {
        buffer.push_back(static_cast<unsigned char>(cmd[i]));
    }

    // Construct and send packet
    auto payloadPacket = std::make_shared<CustomPayloadPacket>(
        CustomPayloadPacket::SET_ADVENTURE_COMMAND_PACKET,
        buffer
    );

    LocalPlayer* player = Minecraft::GetInstance()->localplayers[GetPad()];
    player->connection->send(payloadPacket);
}

