  loadData::printValue(stream, settings.tol_stat, "tol_stat", settings.tol_stat != referenceSettings.tol_stat);
  loadData::printValue(stream, settings.tol_eq, "tol_eq", settings.tol_eq != referenceSettings.tol_eq);
  loadData::printValue(stream, settings.tol_ineq, "tol_ineq", settings.tol_ineq != referenceSettings.tol_ineq);
  loadData::printValue(stream, settings.tol_comp, "tol_comp", settings.tol_comp != referenceSettings.tol_comp);
  loadData::printValue(stream, settings.reg_prim, "reg_prim", settings.reg_prim != referenceSettings.reg_prim);
