// Convert wide string to UTF-8 encoded std::string (const reference overload)
auto ToBytes(const std::wstring& wstr) -> std::string {
  std::string result;
  utf8::utf16to8(wstr.cbegin(), wstr.cend(), std::back_inserter(result));
  return result;
}

// Convert wide string to UTF-8 encoded std::string (rvalue reference overload)
auto ToBytes(std::wstring&& wstr) -> std::string {
  std::string result;
  utf8::utf16to8(wstr.begin(), wstr.end(), std::back_inserter(result));
  return result;
}

// Convert UTF-8 encoded std::string to wide string (const reference overload)
auto FromBytes(const std::string& str) -> std::wstring {
  std::wstring result;
  utf8::utf8to16(str.cbegin(), str.cend(), std::back_inserter(result));
  return result;
}

// Convert UTF-8 encoded std::string to wide string (rvalue reference overload)
auto FromBytes(std::string&& str) -> std::wstring {
  std::wstring result;
  utf8::utf8to16(str.begin(), str.end(), std::back_inserter(result));
  return result;
}

