// Print Bark scale information for various sampling rates and block sizes
int main() {
    int blockSize;
    double sampleRate;

    // Iterate through powers of two from 64 up to (but not including) 32000
    for (blockSize = 64; blockSize < 32000; blockSize *= 2) {
        // Test with different standard audio sample rates
        sampleRate = 48000.0;
        fprintf(stderr, "rate=%gHz, block=%d, f(1)=%.2gHz bark(1)=%.2g (of %.2g)\n",
                sampleRate, blockSize, sampleRate/2 / (blockSize/2), 
                toBARK(sampleRate/2 / (blockSize/2)), toBARK(sampleRate/2));

        sampleRate = 44100.0;
        fprintf(stderr, "rate=%gHz, block=%d, f(1)=%.2gHz bark(1)=%.2g (of %.2g)\n",
                sampleRate, blockSize, sampleRate/2 / (blockSize/2), 
                toBARK(sampleRate/2 / (blockSize/2)), toBARK(sampleRate/2));

        sampleRate = 32000.0;
        fprintf(stderr, "rate=%gHz, block=%d, f(1)=%.2gHz bark(1)=%.2g (of %.2g)\n",
                sampleRate, blockSize, sampleRate/2 / (blockSize/2), 
                toBARK(sampleRate/2 / (blockSize/2)), toBARK(sampleRate/2));

        sampleRate = 22050.0;
        fprintf(stderr, "rate=%gHz, block=%d, f(1)=%.2gHz bark(1)=%.2g (of %.2g)\n",
                sampleRate, blockSize, sampleRate/2 / (blockSize/2), 
                toBARK(sampleRate/2 / (blockSize/2)), toBARK(sampleRate/2));

        sampleRate = 16000.0;
        fprintf(stderr, "rate=%gHz, block=%d, f(1)=%.2gHz bark(1)=%.2g (of %.2g)\n",
                sampleRate, blockSize, sampleRate/2 / (blockSize/2), 
                toBARK(sampleRate/2 / (blockSize/2)), toBARK(sampleRate/2));

        sampleRate = 11025.0;
        fprintf(stderr, "rate=%gHz, block=%d, f(1)=%.2gHz bark(1)=%.2g (of %.2g)\n",
                sampleRate, blockSize, sampleRate/2 / (blockSize/2), 
                toBARK(sampleRate/2 / (blockSize/2)), toBARK(sampleRate/2));

        sampleRate = 8000.0;
        fprintf(stderr, "rate=%gHz, block=%d, f(1)=%.2gHz bark(1)=%.2g (of %.2g)\n\n",
                sampleRate, blockSize, sampleRate/2 / (blockSize/2), 
                toBARK(sampleRate/2 / (blockSize/2)), toBARK(sampleRate/2));
    }

    // Second loop: print Bark values and corresponding frequencies
    {
        float barkValue = 0.0f;
        int index = 0;
        while (barkValue < 28.0f) {
            fprintf(stderr, "(%d) bark=%f %gHz (%d of 128)\n",
                    index, barkValue, fromBARK(barkValue),
                    (int)(fromBARK(barkValue)/22050.0*128.0));
            barkValue += 1.0f;
            index++;
        }
    }

    return 0;
}

