void AXARTLfo(AXART_LFO* lfo) {
    // Accumulate phase increment
    float accumulated = lfo->counter + lfo->delta;

    // Handle wraparound when phase exceeds 1.0
    if (accumulated >= 1.0f) {
        // Calculate how many full cycles we've completed
        u32 fullSteps = (u32)accumulated;
        lfo->counter = accumulated - fullSteps;

        // Advance sample index and wrap within buffer bounds
        lfo->sampleIndex += fullSteps;
        lfo->sampleIndex %= lfo->length;

        // Update interpolation samples
        lfo->sample1 = lfo->sample;
        lfo->sample = lfo->lfo[lfo->sampleIndex];
    } else {
        // No wraparound, just update counter
        lfo->counter = accumulated;
    }

    // Linear interpolation: sample1 + t * (sample - sample1)
    // Rearranged as: sample1 - t * (sample1 - sample)
    lfo->output = lfo->sample1 - lfo->counter * (lfo->sample1 - lfo->sample);
}
